GO
CREATE PROCEDURE [upd_alq_detallealquiler_itemdocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detallealquiler_itemdocumento varchar(300) = null,
		@p_id_detallealquiler int = null,
		@p_id_itemdocumento int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [alq_detallealquiler_itemdocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detallealquiler_itemdocumento] = isnull(@p_detallealquiler_itemdocumento,[detallealquiler_itemdocumento]),
			[id_detallealquiler] = isnull(@p_id_detallealquiler,[id_detallealquiler]),
			[id_itemdocumento] = isnull(@p_id_itemdocumento,[id_itemdocumento]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
