IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_alq_detallealquiler_itemdocumento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_alq_detallealquiler_itemdocumento]
GO
CREATE PROCEDURE [ins_alq_detallealquiler_itemdocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detallealquiler_itemdocumento varchar(300),
		@p_id_detallealquiler int,
		@p_id_itemdocumento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [alq_detallealquiler_itemdocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detallealquiler_itemdocumento],
			[id_detallealquiler],
			[id_itemdocumento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detallealquiler_itemdocumento,
			@p_id_detallealquiler,
			@p_id_itemdocumento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [alq_detallealquiler_itemdocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
