GO
CREATE PROCEDURE [aud_alq_detallealquiler_itemdocumento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [alq_detallealquiler_itemdocumento].id as id_tabla,
	[alq_detallealquiler_itemdocumento].id_usuario_modifico as id_usuario_modifico,
	[alq_detallealquiler_itemdocumento].id_usuario_creo as id_usuario_creo,
	[alq_detallealquiler_itemdocumento].fechaModificacion as fechaModificacion,
	[alq_detallealquiler_itemdocumento].fechaCreacion as fechaCreacion,
	[alq_detallealquiler_itemdocumento].active as active,
	[alq_detallealquiler_itemdocumento].[detallealquiler_itemdocumento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [alq_detallealquiler_itemdocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[alq_detallealquiler_itemdocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[alq_detallealquiler_itemdocumento].[id_usuario_creo]
	where ' + @p_filtro)
END
