	INNER JOIN [doc_documento] AS [doc_documento_movimiento] ON [doc_documento_movimiento].id=[alq_detalleLiquidacion].[id_documento_movimiento]

	INNER JOIN [dis_evento] ON [dis_evento].id=[alq_detalleLiquidacion].[id_evento]
