CREATE PROCEDURE [upd_alq_detalleLiquidacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detalleLiquidacion varchar(300) = null,
		@p_detalleLiquidacion_codigo varchar(100) = null,
		@p_cantidad int = null,
		@p_dias int = null,
		@p_fechaInicio_fh smalldatetime = null,
		@p_fechaFin_fh smalldatetime = null,
		@p_id_itemDocumento int = null,
		@p_id_detalleAlquiler int = null,
		@p_saldo int = null,
		@p_id_documento_movimiento int = null,
		@p_horometro float = null,
		@p_id_tarifa int = null,
		@p_id_evento int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [alq_detalleLiquidacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detalleLiquidacion] = isnull(@p_detalleLiquidacion,[detalleLiquidacion]),
			[detalleLiquidacion_codigo] = isnull(@p_detalleLiquidacion_codigo,[detalleLiquidacion_codigo]),
			[cantidad] = isnull(@p_cantidad,[cantidad]),
			[dias] = isnull(@p_dias,[dias]),
			[fechaInicio_fh] = isnull(@p_fechaInicio_fh,[fechaInicio_fh]),
			[fechaFin_fh] = isnull(@p_fechaFin_fh,[fechaFin_fh]),
			[id_itemDocumento] = isnull(@p_id_itemDocumento,[id_itemDocumento]),
			[id_detalleAlquiler] = isnull(@p_id_detalleAlquiler,[id_detalleAlquiler]),
			[saldo] = isnull(@p_saldo,[saldo]),
			[id_documento_movimiento] = isnull(@p_id_documento_movimiento,[id_documento_movimiento]),
			[horometro] = isnull(@p_horometro,[horometro]),
			[id_tarifa] = isnull(@p_id_tarifa,[id_tarifa]),
			[id_evento] = isnull(@p_id_evento,[id_evento]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
