GO
CREATE PROCEDURE [ins_alq_detalleLiquidacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detalleLiquidacion varchar(300),
		@p_detalleLiquidacion_codigo varchar(100),
		@p_cantidad int,
		@p_dias int,
		@p_fechaInicio_fh smalldatetime,
		@p_fechaFin_fh smalldatetime,
		@p_id_itemDocumento int,
		@p_id_detalleAlquiler int,
		@p_saldo int,
		@p_id_documento_movimiento int,
		@p_horometro float,
		@p_id_tarifa int,
		@p_id_evento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [alq_detalleLiquidacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detalleLiquidacion],
			[detalleLiquidacion_codigo],
			[cantidad],
			[dias],
			[fechaInicio_fh],
			[fechaFin_fh],
			[id_itemDocumento],
			[id_detalleAlquiler],
			[saldo],
			[id_documento_movimiento],
			[horometro],
			[id_tarifa],
			[id_evento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detalleLiquidacion,
			@p_detalleLiquidacion_codigo,
			@p_cantidad,
			@p_dias,
			@p_fechaInicio_fh,
			@p_fechaFin_fh,
			@p_id_itemDocumento,
			@p_id_detalleAlquiler,
			@p_saldo,
			@p_id_documento_movimiento,
			@p_horometro,
			@p_id_tarifa,
			@p_id_evento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [alq_detalleLiquidacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
