CREATE PROCEDURE [aud_alq_detalleLiquidacion]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [alq_detalleLiquidacion].id as id_tabla,
	[alq_detalleLiquidacion].id_usuario_modifico as id_usuario_modifico,
	[alq_detalleLiquidacion].id_usuario_creo as id_usuario_creo,
	[alq_detalleLiquidacion].fechaModificacion as fechaModificacion,
	[alq_detalleLiquidacion].fechaCreacion as fechaCreacion,
	[alq_detalleLiquidacion].active as active,
	[alq_detalleLiquidacion].[detalleLiquidacion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [alq_detalleLiquidacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[alq_detalleLiquidacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[alq_detalleLiquidacion].[id_usuario_creo]
	where ' + @p_filtro)
END
