IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_alq_historicoAlquiler]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_alq_historicoAlquiler]
GO
CREATE PROCEDURE [ins_alq_historicoAlquiler]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_historicoAlquiler varchar(300),
		@p_historicoAlquiler_codigo varchar(100),
		@p_fechaEstado smalldatetime,
		@p_id_equipo int,
		@p_id_estadoEquipo int,
		@p_id_documento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [alq_historicoAlquiler]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[historicoAlquiler],
			[historicoAlquiler_codigo],
			[fechaEstado],
			[id_equipo],
			[id_estadoEquipo],
			[id_documento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_historicoAlquiler,
			@p_historicoAlquiler_codigo,
			@p_fechaEstado,
			@p_id_equipo,
			@p_id_estadoEquipo,
			@p_id_documento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [alq_historicoAlquiler] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
