GO
CREATE PROCEDURE [aud_alq_historicoAlquiler]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [alq_historicoAlquiler].id as id_tabla,
	[alq_historicoAlquiler].id_usuario_modifico as id_usuario_modifico,
	[alq_historicoAlquiler].id_usuario_creo as id_usuario_creo,
	[alq_historicoAlquiler].fechaModificacion as fechaModificacion,
	[alq_historicoAlquiler].fechaCreacion as fechaCreacion,
	[alq_historicoAlquiler].active as active,
	[alq_historicoAlquiler].[historicoAlquiler] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [alq_historicoAlquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[alq_historicoAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[alq_historicoAlquiler].[id_usuario_creo]
	where ' + @p_filtro)
END
