IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_alq_periodoAlquiler]')) DROP VIEW [dbo].[view_alq_periodoAlquiler]
GO
CREATE  VIEW [view_alq_periodoAlquiler] AS
SELECT 	[alq_periodoAlquiler].[id] AS [id],
		[alq_periodoAlquiler].[uid] AS [uid],
		[alq_periodoAlquiler].[eid] AS [eid],
		[alq_periodoAlquiler].[id_usuario_modifico] AS [id_usuario_modifico],
		[alq_periodoAlquiler].[id_usuario_creo] AS [id_usuario_creo],
		[alq_periodoAlquiler].[fechaModificacion] AS [fechaModificacion],
		[alq_periodoAlquiler].[fechaCreacion] AS [fechaCreacion],
		[alq_periodoAlquiler].[active] AS [active],
		[alq_periodoAlquiler].[periodoAlquiler] AS [periodoAlquiler],
		[alq_periodoAlquiler].[periodoAlquiler_codigo] AS [periodoAlquiler_codigo],
		[alq_periodoAlquiler].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [alq_periodoAlquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[alq_periodoAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[alq_periodoAlquiler].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [alq_periodoAlquiler].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [alq_periodoAlquiler].active=1
GO
