CREATE PROCEDURE [aud_alq_periodoAlquiler]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [alq_periodoAlquiler].id as id_tabla,
	[alq_periodoAlquiler].id_usuario_modifico as id_usuario_modifico,
	[alq_periodoAlquiler].id_usuario_creo as id_usuario_creo,
	[alq_periodoAlquiler].fechaModificacion as fechaModificacion,
	[alq_periodoAlquiler].fechaCreacion as fechaCreacion,
	[alq_periodoAlquiler].active as active,
	[alq_periodoAlquiler].[periodoAlquiler] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [alq_periodoAlquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[alq_periodoAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[alq_periodoAlquiler].[id_usuario_creo]
	where ' + @p_filtro)
END
