[equ_detalleAlquiler].[id_tercero] as [equ_detalleAlquiler_id_tercero],
[equ_detalleAlquiler].[fechaUltimaFactura_fh] as [equ_detalleAlquiler_fechaUltimaFactura_fh],
[equ_detalleAlquiler].[valorMes] as [equ_detalleAlquiler_valorMes],
[equ_detalleAlquiler].[fechaInicioFactura_fh] as [equ_detalleAlquiler_fechaInicioFactura_fh],
[equ_detalleAlquiler].[cantidadSolicitada] as [equ_detalleAlquiler_cantidadSolicitada],
[equ_detalleAlquiler].[cantidadAlquilada] as [equ_detalleAlquiler_cantidadAlquilada],
[equ_detalleAlquiler].[id_catalogo] as [equ_detalleAlquiler_id_catalogo],
[equ_detalleAlquiler].[estadoalquiler] as [equ_detalleAlquiler_estadoalquiler],
[equ_detalleAlquiler].[esSerializado] as [equ_detalleAlquiler_esSerializado],
[equ_detalleAlquiler].[bloquearDespacho] as [equ_detalleAlquiler_bloquearDespacho],
[equ_detalleAlquiler].[cmm] as [equ_detalleAlquiler_cmm],
		[alq_tarifa].[id_tipoTarifa] AS [id_tipoTarifa],
[alq_tipoTarifa].[tipoTarifa] as [alq_tipoTarifa_tipoTarifa],
[alq_tipoTarifa].[tipoTarifa_codigo] as [alq_tipoTarifa_tipoTarifa_codigo],
[alq_tipoTarifa].[valor] as [alq_tipoTarifa_valor],
[alq_tipoTarifa].[cmm] as [alq_tipoTarifa_cmm],
		[alq_tarifa].[horasIncluidas] AS [horasIncluidas],
		[alq_tarifa].[cantidadIncluida] AS [cantidadIncluida],
		[alq_tarifa].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [alq_tarifa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[alq_tarifa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[alq_tarifa].[id_usuario_creo]
	INNER JOIN [doc_itemDocumento] ON [doc_itemDocumento].id=[alq_tarifa].[id_itemDocumento]
	INNER JOIN [equ_detalleAlquiler] ON [equ_detalleAlquiler].id=[alq_tarifa].[id_detalleAlquiler]
	INNER JOIN [alq_tipoTarifa] ON [alq_tipoTarifa].id=[alq_tarifa].[id_tipoTarifa]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [alq_tarifa].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [alq_tarifa].active=1
GO
