IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_alq_tarifa]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_alq_tarifa]
GO
CREATE PROCEDURE [ins_alq_tarifa]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tarifa varchar(300),
		@p_tarifa_codigo varchar(100),
		@p_id_itemDocumento int,
		@p_id_detalleAlquiler int,
		@p_id_tipoTarifa int,
		@p_horasIncluidas float,
		@p_cantidadIncluida int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [alq_tarifa]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tarifa],
			[tarifa_codigo],
			[id_itemDocumento],
			[id_detalleAlquiler],
			[id_tipoTarifa],
			[horasIncluidas],
			[cantidadIncluida],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tarifa,
			@p_tarifa_codigo,
			@p_id_itemDocumento,
			@p_id_detalleAlquiler,
			@p_id_tipoTarifa,
			@p_horasIncluidas,
			@p_cantidadIncluida,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [alq_tarifa] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
