CREATE PROCEDURE [aud_alq_tarifa]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [alq_tarifa].id as id_tabla,
	[alq_tarifa].id_usuario_modifico as id_usuario_modifico,
	[alq_tarifa].id_usuario_creo as id_usuario_creo,
	[alq_tarifa].fechaModificacion as fechaModificacion,
	[alq_tarifa].fechaCreacion as fechaCreacion,
	[alq_tarifa].active as active,
	[alq_tarifa].[tarifa] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [alq_tarifa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[alq_tarifa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[alq_tarifa].[id_usuario_creo]
	where ' + @p_filtro)
END
