IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_alq_tipoTarifa]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_alq_tipoTarifa]
GO
CREATE PROCEDURE [ins_alq_tipoTarifa]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoTarifa varchar(300),
		@p_tipoTarifa_codigo varchar(100),
		@p_valor decimal,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [alq_tipoTarifa]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoTarifa],
			[tipoTarifa_codigo],
			[valor],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoTarifa,
			@p_tipoTarifa_codigo,
			@p_valor,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [alq_tipoTarifa] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
