GO
CREATE  VIEW [view_cat_atributo] AS
SELECT 	[cat_atributo].[id] AS [id],
		[cat_atributo].[uid] AS [uid],
		[cat_atributo].[eid] AS [eid],
		[cat_atributo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_atributo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_atributo].[fechaModificacion] AS [fechaModificacion],
		[cat_atributo].[fechaCreacion] AS [fechaCreacion],
		[cat_atributo].[active] AS [active],
		[cat_atributo].[atributo] AS [atributo],
		[cat_atributo].[atributo_codigo] AS [atributo_codigo],
		[cat_atributo].[id_unidad] AS [id_unidad],
[gen_unidad].[unidad] as [gen_unidad_unidad],
[gen_unidad].[unidad_codigo] as [gen_unidad_unidad_codigo],
[gen_unidad].[cmm] as [gen_unidad_cmm],
		[cat_atributo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_atributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_atributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_atributo].[id_usuario_creo]
	INNER JOIN [gen_unidad] ON [gen_unidad].id=[cat_atributo].[id_unidad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_atributo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_atributo].active=1
GO
