CREATE PROCEDURE [aud_cat_atributo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_atributo].id as id_tabla,
	[cat_atributo].id_usuario_modifico as id_usuario_modifico,
	[cat_atributo].id_usuario_creo as id_usuario_creo,
	[cat_atributo].fechaModificacion as fechaModificacion,
	[cat_atributo].fechaCreacion as fechaCreacion,
	[cat_atributo].active as active,
	[cat_atributo].[atributo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_atributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_atributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_atributo].[id_usuario_creo]
	where ' + @p_filtro)
END
