GO
CREATE  VIEW [view_cat_atributo_opcionAtributo] AS
SELECT 	[cat_atributo_opcionAtributo].[id] AS [id],
		[cat_atributo_opcionAtributo].[uid] AS [uid],
		[cat_atributo_opcionAtributo].[eid] AS [eid],
		[cat_atributo_opcionAtributo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_atributo_opcionAtributo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_atributo_opcionAtributo].[fechaModificacion] AS [fechaModificacion],
		[cat_atributo_opcionAtributo].[fechaCreacion] AS [fechaCreacion],
		[cat_atributo_opcionAtributo].[active] AS [active],
		[cat_atributo_opcionAtributo].[atributo_opcionAtributo] AS [atributo_opcionAtributo],
		[cat_atributo_opcionAtributo].[id_atributo] AS [id_atributo],
[cat_atributo].[atributo] as [cat_atributo_atributo],
[cat_atributo].[atributo_codigo] as [cat_atributo_atributo_codigo],
[cat_atributo].[id_unidad] as [cat_atributo_id_unidad],
[cat_atributo].[cmm] as [cat_atributo_cmm],
		[cat_atributo_opcionAtributo].[id_opcionAtributo] AS [id_opcionAtributo],
[equ_opcionAtributo].[opcionAtributo] as [equ_opcionAtributo_opcionAtributo],
[equ_opcionAtributo].[opcionAtributo_codigo] as [equ_opcionAtributo_opcionAtributo_codigo],
[equ_opcionAtributo].[orden] as [equ_opcionAtributo_orden],
[equ_opcionAtributo].[id_atributo] as [equ_opcionAtributo_id_atributo],
[equ_opcionAtributo].[cmm] as [equ_opcionAtributo_cmm],
		[cat_atributo_opcionAtributo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_atributo_opcionAtributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_atributo_opcionAtributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_atributo_opcionAtributo].[id_usuario_creo]
	INNER JOIN [cat_atributo] ON [cat_atributo].id=[cat_atributo_opcionAtributo].[id_atributo]
	INNER JOIN [equ_opcionAtributo] ON [equ_opcionAtributo].id=[cat_atributo_opcionAtributo].[id_opcionAtributo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_atributo_opcionAtributo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
