IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_atributo_opcionAtributo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_atributo_opcionAtributo]
GO
CREATE PROCEDURE [ins_cat_atributo_opcionAtributo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_atributo_opcionAtributo varchar(300),
		@p_id_atributo int,
		@p_id_opcionAtributo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_atributo_opcionAtributo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[atributo_opcionAtributo],
			[id_atributo],
			[id_opcionAtributo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_atributo_opcionAtributo,
			@p_id_atributo,
			@p_id_opcionAtributo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_atributo_opcionAtributo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
