IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_catalogo]')) DROP VIEW [dbo].[view_cat_catalogo]
GO
CREATE  VIEW [view_cat_catalogo] AS
SELECT 	[cat_catalogo].[id] AS [id],
		[cat_catalogo].[uid] AS [uid],
		[cat_catalogo].[eid] AS [eid],
		[cat_catalogo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo].[active] AS [active],
		[cat_catalogo].[catalogo] AS [catalogo],
		[cat_catalogo].[catalogo_codigo] AS [catalogo_codigo],
		[cat_catalogo].[codigoInventario] AS [codigoInventario],
		[cat_catalogo].[precioVenta] AS [precioVenta],
		[cat_catalogo].[tiempoConsecucion] AS [tiempoConsecucion],
		[cat_catalogo].[esNacional] AS [esNacional],
		[cat_catalogo].[id_familia] AS [id_familia],
[gen_familia].[familia] as [gen_familia_familia],
[gen_familia].[familia_codigo] as [gen_familia_familia_codigo],
[gen_familia].[id_familia] as [gen_familia_id_familia],
[gen_familia].[cmm] as [gen_familia_cmm],
		[cat_catalogo].[id_subtipoCatalogo] AS [id_subtipoCatalogo],
[cat_subtipoCatalogo].[subtipoCatalogo] as [cat_subtipoCatalogo_subtipoCatalogo],
[cat_subtipoCatalogo].[subtipoCatalogo_codigo] as [cat_subtipoCatalogo_subtipoCatalogo_codigo],
[cat_subtipoCatalogo].[id_tipoCatalogo] as [cat_subtipoCatalogo_id_tipoCatalogo],
[cat_subtipoCatalogo].[cmm] as [cat_subtipoCatalogo_cmm],
		[cat_catalogo].[id_unidad] AS [id_unidad],
[gen_unidad].[unidad] as [gen_unidad_unidad],
[gen_unidad].[unidad_codigo] as [gen_unidad_unidad_codigo],
[gen_unidad].[cmm] as [gen_unidad_cmm],
		[cat_catalogo].[id_impuesto] AS [id_impuesto],
[gen_impuesto].[impuesto] as [gen_impuesto_impuesto],
[gen_impuesto].[impuesto_codigo] as [gen_impuesto_impuesto_codigo],
[gen_impuesto].[valor] as [gen_impuesto_valor],
[gen_impuesto].[cmm] as [gen_impuesto_cmm],
		[cat_catalogo].[descripcion] AS [descripcion],
		[cat_catalogo].[bloquearCostear] AS [bloquearCostear],
		[cat_catalogo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo].[id_usuario_creo]
	INNER JOIN [gen_familia] ON [gen_familia].id=[cat_catalogo].[id_familia]
	INNER JOIN [cat_subtipoCatalogo] ON [cat_subtipoCatalogo].id=[cat_catalogo].[id_subtipoCatalogo]
	INNER JOIN [gen_unidad] ON [gen_unidad].id=[cat_catalogo].[id_unidad]
	INNER JOIN [gen_impuesto] ON [gen_impuesto].id=[cat_catalogo].[id_impuesto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_catalogo].active=1
GO
