IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_cat_catalogo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_cat_catalogo]
GO
CREATE PROCEDURE [upd_cat_catalogo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_catalogo varchar(300) = null,
		@p_catalogo_codigo varchar(100) = null,
		@p_codigoInventario varchar(50) = null,
		@p_precioVenta money = null,
		@p_tiempoConsecucion int = null,
		@p_esNacional bit = null,
		@p_id_familia int = null,
		@p_id_subtipoCatalogo int = null,
		@p_id_unidad int = null,
		@p_id_impuesto int = null,
		@p_descripcion varchar(8000) = null,
		@p_bloquearCostear bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_catalogo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[catalogo] = isnull(@p_catalogo,[catalogo]),
			[catalogo_codigo] = isnull(@p_catalogo_codigo,[catalogo_codigo]),
			[codigoInventario] = isnull(@p_codigoInventario,[codigoInventario]),
			[precioVenta] = isnull(@p_precioVenta,[precioVenta]),
			[tiempoConsecucion] = isnull(@p_tiempoConsecucion,[tiempoConsecucion]),
			[esNacional] = isnull(@p_esNacional,[esNacional]),
			[id_familia] = isnull(@p_id_familia,[id_familia]),
			[id_subtipoCatalogo] = isnull(@p_id_subtipoCatalogo,[id_subtipoCatalogo]),
