		[esNacional] AS [esNacional],
		[id_familia] AS [id_familia],
		[id_subtipoCatalogo] AS [id_subtipoCatalogo],
		[id_unidad] AS [id_unidad],
		[id_impuesto] AS [id_impuesto],
		[descripcion] AS [descripcion],
		[bloquearCostear] AS [bloquearCostear],
