CREATE PROCEDURE [ins_dis_obra_catalogo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_obra_catalogo varchar(300),
		@p_cantidad float,
		@p_valorUnitario float,
		@p_total float,
		@p_promedioDia float,
		@p_id_obra int,
		@p_id_catalogo int,
		@p_valorMaximo float,
		@p_valorMinimo float,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_obra_catalogo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[obra_catalogo],
			[cantidad],
			[valorUnitario],
			[total],
			[promedioDia],
			[id_obra],
			[id_catalogo],
			[valorMaximo],
			[valorMinimo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_obra_catalogo,
			@p_cantidad,
			@p_valorUnitario,
			@p_total,
			@p_promedioDia,
			@p_id_obra,
			@p_id_catalogo,
			@p_valorMaximo,
			@p_valorMinimo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_obra_catalogo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
