CREATE  VIEW [view_cat_catalogo_actividad] AS
SELECT 	[cat_catalogo.actividad].[id] AS [id],
		[cat_catalogo.actividad].[uid] AS [uid],
		[cat_catalogo.actividad].[eid] AS [eid],
		[cat_catalogo.actividad].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo.actividad].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo.actividad].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo.actividad].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo.actividad].[active] AS [active],
		[cat_catalogo.actividad].[catalogo.actividad] AS [catalogo.actividad],
		[cat_catalogo.actividad].[esProductiva] AS [esProductiva],
		[cat_catalogo.actividad].[duracionEstimada] AS [duracionEstimada],
		[cat_catalogo.actividad].[procedimiento] AS [procedimiento],
		[cat_catalogo.actividad].[dias_garantia] AS [dias_garantia],
		[cat_catalogo.actividad].[cmm] AS [cmm],
[cat_catalogo_actividad].[catalogo_codigo] AS [cat_catalogo_actividad_catalogo_codigo],
[cat_catalogo_actividad].[codigoInventario] AS [cat_catalogo_actividad_codigoInventario],
[cat_catalogo_actividad].[precioVenta] AS [cat_catalogo_actividad_precioVenta],
[cat_catalogo_actividad].[tiempoConsecucion] AS [cat_catalogo_actividad_tiempoConsecucion],
[cat_catalogo_actividad].[esNacional] AS [cat_catalogo_actividad_esNacional],
[cat_catalogo_actividad].[id_familia] AS [cat_catalogo_actividad_id_familia],
[cat_catalogo_actividad_gen_familia].[familia] as [cat_catalogo_actividad_gen_familia_familia],
[cat_catalogo_actividad_gen_familia].[familia_codigo] as [cat_catalogo_actividad_gen_familia_familia_codigo],
[cat_catalogo_actividad_gen_familia].[id_familia] as [cat_catalogo_actividad_gen_familia_id_familia],
[cat_catalogo_actividad_gen_familia].[cmm] as [cat_catalogo_actividad_gen_familia_cmm],
[cat_catalogo_actividad].[id_subtipoCatalogo] AS [cat_catalogo_actividad_id_subtipoCatalogo],
[cat_catalogo_actividad_cat_subtipoCatalogo].[subtipoCatalogo] as [cat_catalogo_actividad_cat_subtipoCatalogo_subtipoCatalogo],
[cat_catalogo_actividad_cat_subtipoCatalogo].[subtipoCatalogo_codigo] as [cat_catalogo_actividad_cat_subtipoCatalogo_subtipoCatalogo_codigo],
[cat_catalogo_actividad_cat_subtipoCatalogo].[id_tipoCatalogo] as [cat_catalogo_actividad_cat_subtipoCatalogo_id_tipoCatalogo],
[cat_catalogo_actividad_cat_subtipoCatalogo].[cmm] as [cat_catalogo_actividad_cat_subtipoCatalogo_cmm],
[cat_catalogo_actividad].[id_unidad] AS [cat_catalogo_actividad_id_unidad],
[cat_catalogo_actividad_gen_unidad].[unidad] as [cat_catalogo_actividad_gen_unidad_unidad],
[cat_catalogo_actividad_gen_unidad].[unidad_codigo] as [cat_catalogo_actividad_gen_unidad_unidad_codigo],
[cat_catalogo_actividad_gen_unidad].[cmm] as [cat_catalogo_actividad_gen_unidad_cmm],
[cat_catalogo_actividad].[id_impuesto] AS [cat_catalogo_actividad_id_impuesto],
[cat_catalogo_actividad_gen_impuesto].[impuesto] as [cat_catalogo_actividad_gen_impuesto_impuesto],
[cat_catalogo_actividad_gen_impuesto].[impuesto_codigo] as [cat_catalogo_actividad_gen_impuesto_impuesto_codigo],
[cat_catalogo_actividad_gen_impuesto].[valor] as [cat_catalogo_actividad_gen_impuesto_valor],
[cat_catalogo_actividad_gen_impuesto].[cmm] as [cat_catalogo_actividad_gen_impuesto_cmm],
[cat_catalogo_actividad].[descripcion] AS [cat_catalogo_actividad_descripcion],
[cat_catalogo_actividad].[bloquearCostear] AS [cat_catalogo_actividad_bloquearCostear],
[cat_catalogo_actividad].[cmm] AS [cat_catalogo_actividad_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo.actividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.actividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.actividad].[id_usuario_creo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_actividad] ON [cat_catalogo.actividad].id = [cat_catalogo_actividad].id
	INNER JOIN [gen_familia]as [cat_catalogo_actividad_gen_familia] ON [cat_catalogo_actividad_gen_familia].id=[cat_catalogo_actividad].[id_familia]
	INNER JOIN [cat_subtipoCatalogo]as [cat_catalogo_actividad_cat_subtipoCatalogo] ON [cat_catalogo_actividad_cat_subtipoCatalogo].id=[cat_catalogo_actividad].[id_subtipoCatalogo]
	INNER JOIN [gen_unidad]as [cat_catalogo_actividad_gen_unidad] ON [cat_catalogo_actividad_gen_unidad].id=[cat_catalogo_actividad].[id_unidad]
	INNER JOIN [gen_impuesto]as [cat_catalogo_actividad_gen_impuesto] ON [cat_catalogo_actividad_gen_impuesto].id=[cat_catalogo_actividad].[id_impuesto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo.actividad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_catalogo.actividad].active=1
