			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_actividad,
			@p_esProductiva,
			@p_duracionEstimada,
			@p_procedimiento,
			@p_dias_garantia,
			@p_cmm)
UPDATE [cat_catalogo.actividad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
END
