	[cat_catalogo.actividad].fechaCreacion as fechaCreacion,
	[cat_catalogo.actividad].active as active,
	[cat_catalogo.actividad].[catalogo.actividad] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
