CREATE  VIEW [view_cat_catalogo_equipo] AS
SELECT 	[cat_catalogo.equipo].[id] AS [id],
		[cat_catalogo.equipo].[uid] AS [uid],
		[cat_catalogo.equipo].[eid] AS [eid],
		[cat_catalogo.equipo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo.equipo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo.equipo].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo.equipo].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo.equipo].[active] AS [active],
		[cat_catalogo.equipo].[catalogo.equipo] AS [catalogo.equipo],
		[cat_catalogo.equipo].[garantiaMeses] AS [garantiaMeses],
		[cat_catalogo.equipo].[garantiaHoras] AS [garantiaHoras],
		[cat_catalogo.equipo].[manejaHorometro] AS [manejaHorometro],
		[cat_catalogo.equipo].[id_marca] AS [id_marca],
[cat_marca].[marca] as [cat_marca_marca],
[cat_marca].[marca_codigo] as [cat_marca_marca_codigo],
[cat_marca].[id_tercero_fabricante] as [cat_marca_id_tercero_fabricante],
[cat_marca].[cmm] as [cat_marca_cmm],
		[cat_catalogo.equipo].[cmm] AS [cmm],
[cat_catalogo_equipo].[catalogo_codigo] AS [cat_catalogo_equipo_catalogo_codigo],
[cat_catalogo_equipo].[codigoInventario] AS [cat_catalogo_equipo_codigoInventario],
[cat_catalogo_equipo].[precioVenta] AS [cat_catalogo_equipo_precioVenta],
[cat_catalogo_equipo].[tiempoConsecucion] AS [cat_catalogo_equipo_tiempoConsecucion],
[cat_catalogo_equipo].[esNacional] AS [cat_catalogo_equipo_esNacional],
[cat_catalogo_equipo].[id_familia] AS [cat_catalogo_equipo_id_familia],
[cat_catalogo_equipo_gen_familia].[familia] as [cat_catalogo_equipo_gen_familia_familia],
[cat_catalogo_equipo_gen_familia].[familia_codigo] as [cat_catalogo_equipo_gen_familia_familia_codigo],
[cat_catalogo_equipo_gen_familia].[id_familia] as [cat_catalogo_equipo_gen_familia_id_familia],
[cat_catalogo_equipo_gen_familia].[cmm] as [cat_catalogo_equipo_gen_familia_cmm],
[cat_catalogo_equipo].[id_subtipoCatalogo] AS [cat_catalogo_equipo_id_subtipoCatalogo],
[cat_catalogo_equipo_cat_subtipoCatalogo].[subtipoCatalogo] as [cat_catalogo_equipo_cat_subtipoCatalogo_subtipoCatalogo],
[cat_catalogo_equipo_cat_subtipoCatalogo].[subtipoCatalogo_codigo] as [cat_catalogo_equipo_cat_subtipoCatalogo_subtipoCatalogo_codigo],
[cat_catalogo_equipo_cat_subtipoCatalogo].[id_tipoCatalogo] as [cat_catalogo_equipo_cat_subtipoCatalogo_id_tipoCatalogo],
[cat_catalogo_equipo_cat_subtipoCatalogo].[cmm] as [cat_catalogo_equipo_cat_subtipoCatalogo_cmm],
[cat_catalogo_equipo].[id_unidad] AS [cat_catalogo_equipo_id_unidad],
[cat_catalogo_equipo_gen_unidad].[unidad] as [cat_catalogo_equipo_gen_unidad_unidad],
[cat_catalogo_equipo_gen_unidad].[unidad_codigo] as [cat_catalogo_equipo_gen_unidad_unidad_codigo],
[cat_catalogo_equipo_gen_unidad].[cmm] as [cat_catalogo_equipo_gen_unidad_cmm],
[cat_catalogo_equipo].[id_impuesto] AS [cat_catalogo_equipo_id_impuesto],
[cat_catalogo_equipo_gen_impuesto].[impuesto] as [cat_catalogo_equipo_gen_impuesto_impuesto],
[cat_catalogo_equipo_gen_impuesto].[impuesto_codigo] as [cat_catalogo_equipo_gen_impuesto_impuesto_codigo],
[cat_catalogo_equipo_gen_impuesto].[valor] as [cat_catalogo_equipo_gen_impuesto_valor],
[cat_catalogo_equipo_gen_impuesto].[cmm] as [cat_catalogo_equipo_gen_impuesto_cmm],
[cat_catalogo_equipo].[descripcion] AS [cat_catalogo_equipo_descripcion],
[cat_catalogo_equipo].[bloquearCostear] AS [cat_catalogo_equipo_bloquearCostear],
[cat_catalogo_equipo].[cmm] AS [cat_catalogo_equipo_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo.equipo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.equipo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.equipo].[id_usuario_creo]
	INNER JOIN [cat_marca] ON [cat_marca].id=[cat_catalogo.equipo].[id_marca]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_equipo] ON [cat_catalogo.equipo].id = [cat_catalogo_equipo].id
	INNER JOIN [gen_familia]as [cat_catalogo_equipo_gen_familia] ON [cat_catalogo_equipo_gen_familia].id=[cat_catalogo_equipo].[id_familia]
	INNER JOIN [cat_subtipoCatalogo]as [cat_catalogo_equipo_cat_subtipoCatalogo] ON [cat_catalogo_equipo_cat_subtipoCatalogo].id=[cat_catalogo_equipo].[id_subtipoCatalogo]
	INNER JOIN [gen_unidad]as [cat_catalogo_equipo_gen_unidad] ON [cat_catalogo_equipo_gen_unidad].id=[cat_catalogo_equipo].[id_unidad]
	INNER JOIN [gen_impuesto]as [cat_catalogo_equipo_gen_impuesto] ON [cat_catalogo_equipo_gen_impuesto].id=[cat_catalogo_equipo].[id_impuesto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo.equipo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_catalogo.equipo].active=1
GO
