		@p_id_impuesto int,
		@p_descripcion varchar(8000),
		@p_bloquearCostear bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
exec @v_id = [ins_cat_catalogo]
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_catalogo_equipo,
			@p_catalogo_codigo,
			@p_codigoInventario,
			@p_precioVenta,
			@p_tiempoConsecucion,
			@p_esNacional,
			@p_id_familia,
			@p_id_subtipoCatalogo,
			@p_id_unidad,
			@p_id_impuesto,
			@p_descripcion,
			@p_bloquearCostear,
			@p_cmm		
INSERT INTO [cat_catalogo.equipo]
			([id],
			[uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo.equipo],
			[garantiaMeses],
			[garantiaHoras],
			[manejaHorometro],
			[id_marca],
			[cmm])
		VALUES( @v_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_equipo,
			@p_garantiaMeses,
			@p_garantiaHoras,
			@p_manejaHorometro,
			@p_id_marca,
			@p_cmm)
UPDATE [cat_catalogo.equipo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
END
