			[catalogo.equipo_catalogo.tempario] = isnull(@p_catalogo_equipo_catalogo_tempario,[catalogo.equipo_catalogo.tempario]),
			[id_catalogo.equipo] = isnull(@p_id_catalogo_equipo,[id_catalogo.equipo]),
			[id_catalogo.tempario] = isnull(@p_id_catalogo_tempario,[id_catalogo.tempario]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
