IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_catalogo_equipo_catalogo_tempario]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_catalogo_equipo_catalogo_tempario]
GO
CREATE PROCEDURE [ins_cat_catalogo_equipo_catalogo_tempario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_catalogo_equipo_catalogo_tempario varchar(300),
		@p_id_catalogo_equipo int,
		@p_id_catalogo_tempario int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_catalogo.equipo_catalogo.tempario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo.equipo_catalogo.tempario],
			[id_catalogo.equipo],
			[id_catalogo.tempario],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_equipo_catalogo_tempario,
			@p_id_catalogo_equipo,
			@p_id_catalogo_tempario,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_catalogo.equipo_catalogo.tempario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
