GO
CREATE  VIEW [view_cat_catalogo_equipo_pruebaCheckList] AS
SELECT 	[cat_catalogo.equipo_pruebaCheckList].[id] AS [id],
		[cat_catalogo.equipo_pruebaCheckList].[uid] AS [uid],
		[cat_catalogo.equipo_pruebaCheckList].[eid] AS [eid],
		[cat_catalogo.equipo_pruebaCheckList].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo.equipo_pruebaCheckList].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo.equipo_pruebaCheckList].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo.equipo_pruebaCheckList].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo.equipo_pruebaCheckList].[active] AS [active],
		[cat_catalogo.equipo_pruebaCheckList].[catalogo.equipo_pruebaCheckList] AS [catalogo.equipo_pruebaCheckList],
		[cat_catalogo.equipo_pruebaCheckList].[id_pruebaCheckList] AS [id_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList] as [cat_pruebaCheckList_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList_codigo] as [cat_pruebaCheckList_pruebaCheckList_codigo],
[cat_pruebaCheckList].[activo] as [cat_pruebaCheckList_activo],
[cat_pruebaCheckList].[cmm] as [cat_pruebaCheckList_cmm],
		[cat_catalogo.equipo_pruebaCheckList].[id_catalogo.equipo] AS [id_catalogo.equipo],
[cat_catalogo.equipo].[catalogo.equipo] as [cat_catalogo.equipo_catalogo.equipo],
[cat_catalogo.equipo].[garantiaMeses] as [cat_catalogo.equipo_garantiaMeses],
[cat_catalogo.equipo].[garantiaHoras] as [cat_catalogo.equipo_garantiaHoras],
[cat_catalogo.equipo].[manejaHorometro] as [cat_catalogo.equipo_manejaHorometro],
[cat_catalogo.equipo].[id_marca] as [cat_catalogo.equipo_id_marca],
[cat_catalogo.equipo].[cmm] as [cat_catalogo.equipo_cmm],
		[cat_catalogo_equipo].[catalogo_codigo] AS [cat_catalogo_equipo_catalogo_codigo],
		[cat_catalogo_equipo].[codigoInventario] AS [cat_catalogo_equipo_codigoInventario],
		[cat_catalogo_equipo].[precioVenta] AS [cat_catalogo_equipo_precioVenta],
		[cat_catalogo_equipo].[tiempoConsecucion] AS [cat_catalogo_equipo_tiempoConsecucion],
		[cat_catalogo_equipo].[esNacional] AS [cat_catalogo_equipo_esNacional],
		[cat_catalogo_equipo].[id_familia] AS [cat_catalogo_equipo_id_familia],
		[cat_catalogo_equipo].[id_subtipoCatalogo] AS [cat_catalogo_equipo_id_subtipoCatalogo],
		[cat_catalogo_equipo].[id_unidad] AS [cat_catalogo_equipo_id_unidad],
		[cat_catalogo_equipo].[id_impuesto] AS [cat_catalogo_equipo_id_impuesto],
		[cat_catalogo_equipo].[descripcion] AS [cat_catalogo_equipo_descripcion],
		[cat_catalogo_equipo].[bloquearCostear] AS [cat_catalogo_equipo_bloquearCostear],
		[cat_catalogo_equipo].[cmm] AS [cat_catalogo_equipo_cmm],
		[cat_catalogo.equipo_pruebaCheckList].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo.equipo_pruebaCheckList]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.equipo_pruebaCheckList].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.equipo_pruebaCheckList].[id_usuario_creo]
	INNER JOIN [cat_pruebaCheckList] ON [cat_pruebaCheckList].id=[cat_catalogo.equipo_pruebaCheckList].[id_pruebaCheckList]
	INNER JOIN [cat_catalogo.equipo] ON [cat_catalogo.equipo].id=[cat_catalogo.equipo_pruebaCheckList].[id_catalogo.equipo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_equipo] ON [cat_catalogo.equipo].id = [cat_catalogo_equipo].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo.equipo_pruebaCheckList].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
