CREATE PROCEDURE [upd_cat_catalogo_equipo_pruebaCheckList]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_catalogo_equipo_pruebaCheckList varchar(300) = null,
		@p_id_pruebaCheckList int = null,
		@p_id_catalogo_equipo int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_catalogo.equipo_pruebaCheckList]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[catalogo.equipo_pruebaCheckList] = isnull(@p_catalogo_equipo_pruebaCheckList,[catalogo.equipo_pruebaCheckList]),
			[id_pruebaCheckList] = isnull(@p_id_pruebaCheckList,[id_pruebaCheckList]),
			[id_catalogo.equipo] = isnull(@p_id_catalogo_equipo,[id_catalogo.equipo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
