GO
CREATE PROCEDURE [ins_cat_catalogo_equipo_pruebaCheckList]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_catalogo_equipo_pruebaCheckList varchar(300),
		@p_id_pruebaCheckList int,
		@p_id_catalogo_equipo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_catalogo.equipo_pruebaCheckList]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo.equipo_pruebaCheckList],
			[id_pruebaCheckList],
			[id_catalogo.equipo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_equipo_pruebaCheckList,
			@p_id_pruebaCheckList,
			@p_id_catalogo_equipo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_catalogo.equipo_pruebaCheckList] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
