IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_catalogo_otro]')) DROP VIEW [dbo].[view_cat_catalogo_otro]
GO
CREATE  VIEW [view_cat_catalogo_otro] AS
SELECT 	[cat_catalogo.otro].[id] AS [id],
		[cat_catalogo.otro].[uid] AS [uid],
		[cat_catalogo.otro].[eid] AS [eid],
		[cat_catalogo.otro].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo.otro].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo.otro].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo.otro].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo.otro].[active] AS [active],
		[cat_catalogo.otro].[catalogo.otro] AS [catalogo.otro],
		[cat_catalogo.otro].[costo] AS [costo],
		[cat_catalogo.otro].[periodoAlquiler] AS [periodoAlquiler],
		[cat_catalogo.otro].[cmm] AS [cmm],
[cat_catalogo_otro].[catalogo_codigo] AS [cat_catalogo_otro_catalogo_codigo],
[cat_catalogo_otro].[codigoInventario] AS [cat_catalogo_otro_codigoInventario],
[cat_catalogo_otro].[precioVenta] AS [cat_catalogo_otro_precioVenta],
[cat_catalogo_otro].[tiempoConsecucion] AS [cat_catalogo_otro_tiempoConsecucion],
[cat_catalogo_otro].[esNacional] AS [cat_catalogo_otro_esNacional],
[cat_catalogo_otro].[id_familia] AS [cat_catalogo_otro_id_familia],
[cat_catalogo_otro_gen_familia].[familia] as [cat_catalogo_otro_gen_familia_familia],
[cat_catalogo_otro_gen_familia].[familia_codigo] as [cat_catalogo_otro_gen_familia_familia_codigo],
[cat_catalogo_otro_gen_familia].[id_familia] as [cat_catalogo_otro_gen_familia_id_familia],
[cat_catalogo_otro_gen_familia].[cmm] as [cat_catalogo_otro_gen_familia_cmm],
[cat_catalogo_otro].[id_subtipoCatalogo] AS [cat_catalogo_otro_id_subtipoCatalogo],
[cat_catalogo_otro_cat_subtipoCatalogo].[subtipoCatalogo] as [cat_catalogo_otro_cat_subtipoCatalogo_subtipoCatalogo],
[cat_catalogo_otro_cat_subtipoCatalogo].[subtipoCatalogo_codigo] as [cat_catalogo_otro_cat_subtipoCatalogo_subtipoCatalogo_codigo],
[cat_catalogo_otro_cat_subtipoCatalogo].[id_tipoCatalogo] as [cat_catalogo_otro_cat_subtipoCatalogo_id_tipoCatalogo],
[cat_catalogo_otro_cat_subtipoCatalogo].[cmm] as [cat_catalogo_otro_cat_subtipoCatalogo_cmm],
[cat_catalogo_otro].[id_unidad] AS [cat_catalogo_otro_id_unidad],
[cat_catalogo_otro_gen_unidad].[unidad] as [cat_catalogo_otro_gen_unidad_unidad],
[cat_catalogo_otro_gen_unidad].[unidad_codigo] as [cat_catalogo_otro_gen_unidad_unidad_codigo],
[cat_catalogo_otro_gen_unidad].[cmm] as [cat_catalogo_otro_gen_unidad_cmm],
[cat_catalogo_otro].[id_impuesto] AS [cat_catalogo_otro_id_impuesto],
[cat_catalogo_otro_gen_impuesto].[impuesto] as [cat_catalogo_otro_gen_impuesto_impuesto],
[cat_catalogo_otro_gen_impuesto].[impuesto_codigo] as [cat_catalogo_otro_gen_impuesto_impuesto_codigo],
[cat_catalogo_otro_gen_impuesto].[valor] as [cat_catalogo_otro_gen_impuesto_valor],
[cat_catalogo_otro_gen_impuesto].[cmm] as [cat_catalogo_otro_gen_impuesto_cmm],
[cat_catalogo_otro].[descripcion] AS [cat_catalogo_otro_descripcion],
[cat_catalogo_otro].[bloquearCostear] AS [cat_catalogo_otro_bloquearCostear],
[cat_catalogo_otro].[cmm] AS [cat_catalogo_otro_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo.otro]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.otro].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.otro].[id_usuario_creo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_otro] ON [cat_catalogo.otro].id = [cat_catalogo_otro].id
	INNER JOIN [gen_familia]as [cat_catalogo_otro_gen_familia] ON [cat_catalogo_otro_gen_familia].id=[cat_catalogo_otro].[id_familia]
	INNER JOIN [cat_subtipoCatalogo]as [cat_catalogo_otro_cat_subtipoCatalogo] ON [cat_catalogo_otro_cat_subtipoCatalogo].id=[cat_catalogo_otro].[id_subtipoCatalogo]
	INNER JOIN [gen_unidad]as [cat_catalogo_otro_gen_unidad] ON [cat_catalogo_otro_gen_unidad].id=[cat_catalogo_otro].[id_unidad]
	INNER JOIN [gen_impuesto]as [cat_catalogo_otro_gen_impuesto] ON [cat_catalogo_otro_gen_impuesto].id=[cat_catalogo_otro].[id_impuesto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo.otro].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_catalogo.otro].active=1
GO
