CREATE  VIEW [view_cat_catalogo_producto] AS
SELECT 	[cat_catalogo.producto].[id] AS [id],
		[cat_catalogo.producto].[uid] AS [uid],
		[cat_catalogo.producto].[eid] AS [eid],
		[cat_catalogo.producto].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo.producto].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo.producto].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo.producto].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo.producto].[active] AS [active],
		[cat_catalogo.producto].[catalogo.producto] AS [catalogo.producto],
		[cat_catalogo.producto].[cmm] AS [cmm],
[cat_catalogo_producto].[catalogo_codigo] AS [cat_catalogo_producto_catalogo_codigo],
[cat_catalogo_producto].[codigoInventario] AS [cat_catalogo_producto_codigoInventario],
[cat_catalogo_producto].[precioVenta] AS [cat_catalogo_producto_precioVenta],
[cat_catalogo_producto].[tiempoConsecucion] AS [cat_catalogo_producto_tiempoConsecucion],
[cat_catalogo_producto].[esNacional] AS [cat_catalogo_producto_esNacional],
[cat_catalogo_producto].[id_familia] AS [cat_catalogo_producto_id_familia],
[cat_catalogo_producto_gen_familia].[familia] as [cat_catalogo_producto_gen_familia_familia],
[cat_catalogo_producto_gen_familia].[familia_codigo] as [cat_catalogo_producto_gen_familia_familia_codigo],
[cat_catalogo_producto_gen_familia].[id_familia] as [cat_catalogo_producto_gen_familia_id_familia],
[cat_catalogo_producto_gen_familia].[cmm] as [cat_catalogo_producto_gen_familia_cmm],
[cat_catalogo_producto].[id_subtipoCatalogo] AS [cat_catalogo_producto_id_subtipoCatalogo],
[cat_catalogo_producto_cat_subtipoCatalogo].[subtipoCatalogo] as [cat_catalogo_producto_cat_subtipoCatalogo_subtipoCatalogo],
[cat_catalogo_producto_cat_subtipoCatalogo].[subtipoCatalogo_codigo] as [cat_catalogo_producto_cat_subtipoCatalogo_subtipoCatalogo_codigo],
[cat_catalogo_producto_cat_subtipoCatalogo].[id_tipoCatalogo] as [cat_catalogo_producto_cat_subtipoCatalogo_id_tipoCatalogo],
[cat_catalogo_producto_cat_subtipoCatalogo].[cmm] as [cat_catalogo_producto_cat_subtipoCatalogo_cmm],
[cat_catalogo_producto].[id_unidad] AS [cat_catalogo_producto_id_unidad],
[cat_catalogo_producto_gen_unidad].[unidad] as [cat_catalogo_producto_gen_unidad_unidad],
[cat_catalogo_producto_gen_unidad].[unidad_codigo] as [cat_catalogo_producto_gen_unidad_unidad_codigo],
[cat_catalogo_producto_gen_unidad].[cmm] as [cat_catalogo_producto_gen_unidad_cmm],
[cat_catalogo_producto].[id_impuesto] AS [cat_catalogo_producto_id_impuesto],
[cat_catalogo_producto_gen_impuesto].[impuesto] as [cat_catalogo_producto_gen_impuesto_impuesto],
[cat_catalogo_producto_gen_impuesto].[impuesto_codigo] as [cat_catalogo_producto_gen_impuesto_impuesto_codigo],
[cat_catalogo_producto_gen_impuesto].[valor] as [cat_catalogo_producto_gen_impuesto_valor],
[cat_catalogo_producto_gen_impuesto].[cmm] as [cat_catalogo_producto_gen_impuesto_cmm],
[cat_catalogo_producto].[descripcion] AS [cat_catalogo_producto_descripcion],
[cat_catalogo_producto].[bloquearCostear] AS [cat_catalogo_producto_bloquearCostear],
[cat_catalogo_producto].[cmm] AS [cat_catalogo_producto_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo.producto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.producto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.producto].[id_usuario_creo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_producto] ON [cat_catalogo.producto].id = [cat_catalogo_producto].id
	INNER JOIN [gen_familia]as [cat_catalogo_producto_gen_familia] ON [cat_catalogo_producto_gen_familia].id=[cat_catalogo_producto].[id_familia]
	INNER JOIN [cat_subtipoCatalogo]as [cat_catalogo_producto_cat_subtipoCatalogo] ON [cat_catalogo_producto_cat_subtipoCatalogo].id=[cat_catalogo_producto].[id_subtipoCatalogo]
	INNER JOIN [gen_unidad]as [cat_catalogo_producto_gen_unidad] ON [cat_catalogo_producto_gen_unidad].id=[cat_catalogo_producto].[id_unidad]
	INNER JOIN [gen_impuesto]as [cat_catalogo_producto_gen_impuesto] ON [cat_catalogo_producto_gen_impuesto].id=[cat_catalogo_producto].[id_impuesto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo.producto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_catalogo.producto].active=1
GO
