GO
CREATE PROCEDURE [ins_cat_catalogo_producto]
		@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_catalogo_producto varchar(300),
		@p_cmm varchar(300),
		@p_catalogo_codigo varchar(100),
		@p_codigoInventario varchar(50),
		@p_precioVenta money,
		@p_tiempoConsecucion int,
		@p_esNacional bit,
		@p_id_familia int,
		@p_id_subtipoCatalogo int,
		@p_id_unidad int,
		@p_id_impuesto int,
		@p_descripcion varchar(8000),
		@p_bloquearCostear bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
exec @v_id = [ins_cat_catalogo]
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_catalogo_producto,
			@p_catalogo_codigo,
			@p_codigoInventario,
			@p_precioVenta,
			@p_tiempoConsecucion,
			@p_esNacional,
			@p_id_familia,
			@p_id_subtipoCatalogo,
			@p_id_unidad,
			@p_id_impuesto,
			@p_descripcion,
			@p_bloquearCostear,
			@p_cmm		
INSERT INTO [cat_catalogo.producto]
			([id],
			[uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo.producto],
			[cmm])
		VALUES( @v_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_producto,
			@p_cmm)
UPDATE [cat_catalogo.producto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
END
GO
