BEGIN
exec(	'SELECT [cat_catalogo.producto].id as id_tabla,
	[cat_catalogo.producto].id_usuario_modifico as id_usuario_modifico,
	[cat_catalogo.producto].id_usuario_creo as id_usuario_creo,
	[cat_catalogo.producto].fechaModificacion as fechaModificacion,
	[cat_catalogo.producto].fechaCreacion as fechaCreacion,
	[cat_catalogo.producto].active as active,
	[cat_catalogo.producto].[catalogo.producto] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_catalogo.producto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.producto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.producto].[id_usuario_creo]
	where ' + @p_filtro)
END
