CREATE  VIEW [view_cat_catalogo_repuesto] AS
SELECT 	[cat_catalogo.repuesto].[id] AS [id],
		[cat_catalogo.repuesto].[uid] AS [uid],
		[cat_catalogo.repuesto].[eid] AS [eid],
		[cat_catalogo.repuesto].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo.repuesto].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo.repuesto].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo.repuesto].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo.repuesto].[active] AS [active],
		[cat_catalogo.repuesto].[catalogo.repuesto] AS [catalogo.repuesto],
		[cat_catalogo.repuesto].[garantiaDias] AS [garantiaDias],
		[cat_catalogo.repuesto].[garantiaHoras] AS [garantiaHoras],
		[cat_catalogo.repuesto].[vigente] AS [vigente],
		[cat_catalogo.repuesto].[id_marca] AS [id_marca],
[cat_marca].[marca] as [cat_marca_marca],
[cat_marca].[marca_codigo] as [cat_marca_marca_codigo],
[cat_marca].[id_tercero_fabricante] as [cat_marca_id_tercero_fabricante],
[cat_marca].[cmm] as [cat_marca_cmm],
		[cat_catalogo.repuesto].[peso] AS [peso],
		[cat_catalogo.repuesto].[cmm] AS [cmm],
[cat_catalogo_repuesto].[catalogo_codigo] AS [cat_catalogo_repuesto_catalogo_codigo],
[cat_catalogo_repuesto].[codigoInventario] AS [cat_catalogo_repuesto_codigoInventario],
[cat_catalogo_repuesto].[precioVenta] AS [cat_catalogo_repuesto_precioVenta],
[cat_catalogo_repuesto].[tiempoConsecucion] AS [cat_catalogo_repuesto_tiempoConsecucion],
[cat_catalogo_repuesto].[esNacional] AS [cat_catalogo_repuesto_esNacional],
[cat_catalogo_repuesto].[id_familia] AS [cat_catalogo_repuesto_id_familia],
[cat_catalogo_repuesto_gen_familia].[familia] as [cat_catalogo_repuesto_gen_familia_familia],
[cat_catalogo_repuesto_gen_familia].[familia_codigo] as [cat_catalogo_repuesto_gen_familia_familia_codigo],
[cat_catalogo_repuesto_gen_familia].[id_familia] as [cat_catalogo_repuesto_gen_familia_id_familia],
[cat_catalogo_repuesto_gen_familia].[cmm] as [cat_catalogo_repuesto_gen_familia_cmm],
[cat_catalogo_repuesto].[id_subtipoCatalogo] AS [cat_catalogo_repuesto_id_subtipoCatalogo],
[cat_catalogo_repuesto_cat_subtipoCatalogo].[subtipoCatalogo] as [cat_catalogo_repuesto_cat_subtipoCatalogo_subtipoCatalogo],
[cat_catalogo_repuesto_cat_subtipoCatalogo].[subtipoCatalogo_codigo] as [cat_catalogo_repuesto_cat_subtipoCatalogo_subtipoCatalogo_codigo],
[cat_catalogo_repuesto_cat_subtipoCatalogo].[id_tipoCatalogo] as [cat_catalogo_repuesto_cat_subtipoCatalogo_id_tipoCatalogo],
[cat_catalogo_repuesto_cat_subtipoCatalogo].[cmm] as [cat_catalogo_repuesto_cat_subtipoCatalogo_cmm],
[cat_catalogo_repuesto].[id_unidad] AS [cat_catalogo_repuesto_id_unidad],
[cat_catalogo_repuesto_gen_unidad].[unidad] as [cat_catalogo_repuesto_gen_unidad_unidad],
[cat_catalogo_repuesto_gen_unidad].[unidad_codigo] as [cat_catalogo_repuesto_gen_unidad_unidad_codigo],
[cat_catalogo_repuesto_gen_unidad].[cmm] as [cat_catalogo_repuesto_gen_unidad_cmm],
[cat_catalogo_repuesto].[id_impuesto] AS [cat_catalogo_repuesto_id_impuesto],
[cat_catalogo_repuesto_gen_impuesto].[impuesto] as [cat_catalogo_repuesto_gen_impuesto_impuesto],
[cat_catalogo_repuesto_gen_impuesto].[impuesto_codigo] as [cat_catalogo_repuesto_gen_impuesto_impuesto_codigo],
[cat_catalogo_repuesto_gen_impuesto].[valor] as [cat_catalogo_repuesto_gen_impuesto_valor],
[cat_catalogo_repuesto_gen_impuesto].[cmm] as [cat_catalogo_repuesto_gen_impuesto_cmm],
[cat_catalogo_repuesto].[descripcion] AS [cat_catalogo_repuesto_descripcion],
[cat_catalogo_repuesto].[bloquearCostear] AS [cat_catalogo_repuesto_bloquearCostear],
[cat_catalogo_repuesto].[cmm] AS [cat_catalogo_repuesto_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo.repuesto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.repuesto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.repuesto].[id_usuario_creo]
	INNER JOIN [cat_marca] ON [cat_marca].id=[cat_catalogo.repuesto].[id_marca]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_repuesto] ON [cat_catalogo.repuesto].id = [cat_catalogo_repuesto].id
	INNER JOIN [gen_familia]as [cat_catalogo_repuesto_gen_familia] ON [cat_catalogo_repuesto_gen_familia].id=[cat_catalogo_repuesto].[id_familia]
	INNER JOIN [cat_subtipoCatalogo]as [cat_catalogo_repuesto_cat_subtipoCatalogo] ON [cat_catalogo_repuesto_cat_subtipoCatalogo].id=[cat_catalogo_repuesto].[id_subtipoCatalogo]
	INNER JOIN [gen_unidad]as [cat_catalogo_repuesto_gen_unidad] ON [cat_catalogo_repuesto_gen_unidad].id=[cat_catalogo_repuesto].[id_unidad]
	INNER JOIN [gen_impuesto]as [cat_catalogo_repuesto_gen_impuesto] ON [cat_catalogo_repuesto_gen_impuesto].id=[cat_catalogo_repuesto].[id_impuesto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo.repuesto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_catalogo.repuesto].active=1
GO
