GO
CREATE PROCEDURE [upd_cat_catalogo_repuesto]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_active bit = null,
		@p_catalogo_repuesto varchar(300) = null,
		@p_garantiaDias int = null,
		@p_garantiaHoras int = null,
		@p_vigente bit = null,
		@p_id_marca int = null,
		@p_peso float = null,
		@p_cmm varchar(300) = null,
		@p_catalogo_codigo varchar(100),
		@p_codigoInventario varchar(50),
		@p_precioVenta money,
		@p_tiempoConsecucion int,
		@p_esNacional bit,
		@p_id_familia int,
		@p_id_subtipoCatalogo int,
		@p_id_unidad int,
		@p_id_impuesto int,
		@p_descripcion varchar(8000),
		@p_bloquearCostear bit,
		@p_cmm varchar(300)
AS
BEGIN
exec [upd_cat_catalogo]
			@p_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_fechaCreacion,
			@p_catalogo_repuesto,
			@p_catalogo_codigo,
			@p_codigoInventario,
			@p_precioVenta,
			@p_tiempoConsecucion,
			@p_esNacional,
			@p_id_familia,
			@p_id_subtipoCatalogo,
			@p_id_unidad,
			@p_id_impuesto,
			@p_descripcion,
			@p_bloquearCostear,
			@p_cmm
	UPDATE [cat_catalogo.repuesto]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[fechaCreacion] = isnull(@p_fechaCreacion,[fechaCreacion]),
			[catalogo.repuesto] = isnull(@p_catalogo_repuesto,[catalogo.repuesto]),
			[garantiaDias] = isnull(@p_garantiaDias,[garantiaDias]),
