			[vigente] = isnull(@p_vigente,[vigente]),
			[id_marca] = isnull(@p_id_marca,[id_marca]),
			[peso] = isnull(@p_peso,[peso]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
