		[cat_catalogo.tempario].[modoAjuste] AS [modoAjuste],
		[cat_catalogo.tempario].[cmm] AS [cmm],
[cat_catalogo_tempario].[catalogo_codigo] AS [cat_catalogo_tempario_catalogo_codigo],
[cat_catalogo_tempario].[codigoInventario] AS [cat_catalogo_tempario_codigoInventario],
[cat_catalogo_tempario].[precioVenta] AS [cat_catalogo_tempario_precioVenta],
[cat_catalogo_tempario].[tiempoConsecucion] AS [cat_catalogo_tempario_tiempoConsecucion],
[cat_catalogo_tempario].[esNacional] AS [cat_catalogo_tempario_esNacional],
[cat_catalogo_tempario].[id_familia] AS [cat_catalogo_tempario_id_familia],
[cat_catalogo_tempario_gen_familia].[familia] as [cat_catalogo_tempario_gen_familia_familia],
[cat_catalogo_tempario_gen_familia].[familia_codigo] as [cat_catalogo_tempario_gen_familia_familia_codigo],
[cat_catalogo_tempario_gen_familia].[id_familia] as [cat_catalogo_tempario_gen_familia_id_familia],
[cat_catalogo_tempario_gen_familia].[cmm] as [cat_catalogo_tempario_gen_familia_cmm],
[cat_catalogo_tempario].[id_subtipoCatalogo] AS [cat_catalogo_tempario_id_subtipoCatalogo],
[cat_catalogo_tempario_cat_subtipoCatalogo].[subtipoCatalogo] as [cat_catalogo_tempario_cat_subtipoCatalogo_subtipoCatalogo],
[cat_catalogo_tempario_cat_subtipoCatalogo].[subtipoCatalogo_codigo] as [cat_catalogo_tempario_cat_subtipoCatalogo_subtipoCatalogo_codigo],
[cat_catalogo_tempario_cat_subtipoCatalogo].[id_tipoCatalogo] as [cat_catalogo_tempario_cat_subtipoCatalogo_id_tipoCatalogo],
[cat_catalogo_tempario_cat_subtipoCatalogo].[cmm] as [cat_catalogo_tempario_cat_subtipoCatalogo_cmm],
[cat_catalogo_tempario].[id_unidad] AS [cat_catalogo_tempario_id_unidad],
[cat_catalogo_tempario_gen_unidad].[unidad] as [cat_catalogo_tempario_gen_unidad_unidad],
[cat_catalogo_tempario_gen_unidad].[unidad_codigo] as [cat_catalogo_tempario_gen_unidad_unidad_codigo],
[cat_catalogo_tempario_gen_unidad].[cmm] as [cat_catalogo_tempario_gen_unidad_cmm],
[cat_catalogo_tempario].[id_impuesto] AS [cat_catalogo_tempario_id_impuesto],
[cat_catalogo_tempario_gen_impuesto].[impuesto] as [cat_catalogo_tempario_gen_impuesto_impuesto],
[cat_catalogo_tempario_gen_impuesto].[impuesto_codigo] as [cat_catalogo_tempario_gen_impuesto_impuesto_codigo],
[cat_catalogo_tempario_gen_impuesto].[valor] as [cat_catalogo_tempario_gen_impuesto_valor],
[cat_catalogo_tempario_gen_impuesto].[cmm] as [cat_catalogo_tempario_gen_impuesto_cmm],
[cat_catalogo_tempario].[descripcion] AS [cat_catalogo_tempario_descripcion],
[cat_catalogo_tempario].[bloquearCostear] AS [cat_catalogo_tempario_bloquearCostear],
[cat_catalogo_tempario].[cmm] AS [cat_catalogo_tempario_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo.tempario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.tempario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.tempario].[id_usuario_creo]
	INNER JOIN [gen_tipoServicio] ON [gen_tipoServicio].id=[cat_catalogo.tempario].[id_tipoServicio]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_tempario] ON [cat_catalogo.tempario].id = [cat_catalogo_tempario].id
	INNER JOIN [gen_familia]as [cat_catalogo_tempario_gen_familia] ON [cat_catalogo_tempario_gen_familia].id=[cat_catalogo_tempario].[id_familia]
	INNER JOIN [cat_subtipoCatalogo]as [cat_catalogo_tempario_cat_subtipoCatalogo] ON [cat_catalogo_tempario_cat_subtipoCatalogo].id=[cat_catalogo_tempario].[id_subtipoCatalogo]
	INNER JOIN [gen_unidad]as [cat_catalogo_tempario_gen_unidad] ON [cat_catalogo_tempario_gen_unidad].id=[cat_catalogo_tempario].[id_unidad]
	INNER JOIN [gen_impuesto]as [cat_catalogo_tempario_gen_impuesto] ON [cat_catalogo_tempario_gen_impuesto].id=[cat_catalogo_tempario].[id_impuesto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo.tempario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_catalogo.tempario].active=1
