GO
CREATE PROCEDURE [upd_cat_catalogo_tempario]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_active bit = null,
		@p_catalogo_tempario varchar(300) = null,
		@p_duracionEstimada float = null,
		@p_enTaller bit = null,
		@p_esCiclico bit = null,
		@p_detieneEquipos bit = null,
		@p_horasDetencion float = null,
		@p_periodoHoras int = null,
		@p_facturaTodo bit = null,
		@p_periodoDias int = null,
		@p_porcGarantia float = null,
		@p_porcTropicalizacion float = null,
		@p_id_tipoServicio int = null,
		@p_proyectar bit = null,
		@p_incluirMenores bit = null,
		@p_modoAjuste int = null,
		@p_cmm varchar(300) = null,
		@p_catalogo_codigo varchar(100),
		@p_codigoInventario varchar(50),
		@p_precioVenta money,
		@p_tiempoConsecucion int,
		@p_esNacional bit,
		@p_id_familia int,
		@p_id_subtipoCatalogo int,
		@p_id_unidad int,
		@p_id_impuesto int,
		@p_descripcion varchar(8000),
		@p_bloquearCostear bit,
		@p_cmm varchar(300)
AS
BEGIN
exec [upd_cat_catalogo]
			@p_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_fechaCreacion,
			@p_catalogo_tempario,
			@p_catalogo_codigo,
			@p_codigoInventario,
			@p_precioVenta,
			@p_tiempoConsecucion,
			@p_esNacional,
			@p_id_familia,
			@p_id_subtipoCatalogo,
			@p_id_unidad,
			@p_id_impuesto,
			@p_descripcion,
			@p_bloquearCostear,
			@p_cmm
	UPDATE [cat_catalogo.tempario]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[fechaCreacion] = isnull(@p_fechaCreacion,[fechaCreacion]),
			[catalogo.tempario] = isnull(@p_catalogo_tempario,[catalogo.tempario]),
			[duracionEstimada] = isnull(@p_duracionEstimada,[duracionEstimada]),
			[enTaller] = isnull(@p_enTaller,[enTaller]),
			[esCiclico] = isnull(@p_esCiclico,[esCiclico]),
			[detieneEquipos] = isnull(@p_detieneEquipos,[detieneEquipos]),
			[horasDetencion] = isnull(@p_horasDetencion,[horasDetencion]),
			[periodoHoras] = isnull(@p_periodoHoras,[periodoHoras]),
			[facturaTodo] = isnull(@p_facturaTodo,[facturaTodo]),
			[periodoDias] = isnull(@p_periodoDias,[periodoDias]),
			[porcGarantia] = isnull(@p_porcGarantia,[porcGarantia]),
			[porcTropicalizacion] = isnull(@p_porcTropicalizacion,[porcTropicalizacion]),
			[id_tipoServicio] = isnull(@p_id_tipoServicio,[id_tipoServicio]),
			[proyectar] = isnull(@p_proyectar,[proyectar]),
			[incluirMenores] = isnull(@p_incluirMenores,[incluirMenores]),
			[modoAjuste] = isnull(@p_modoAjuste,[modoAjuste]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
