CREATE PROCEDURE [ins_cat_catalogo_tempario]
		@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_catalogo_tempario varchar(300),
		@p_duracionEstimada float,
		@p_enTaller bit,
		@p_esCiclico bit,
		@p_detieneEquipos bit,
		@p_horasDetencion float,
		@p_periodoHoras int,
		@p_facturaTodo bit,
		@p_periodoDias int,
		@p_porcGarantia float,
		@p_porcTropicalizacion float,
		@p_id_tipoServicio int,
		@p_proyectar bit,
		@p_incluirMenores bit,
		@p_modoAjuste int,
		@p_cmm varchar(300),
		@p_catalogo_codigo varchar(100),
		@p_codigoInventario varchar(50),
		@p_precioVenta money,
		@p_tiempoConsecucion int,
		@p_esNacional bit,
		@p_id_familia int,
		@p_id_subtipoCatalogo int,
		@p_id_unidad int,
		@p_id_impuesto int,
		@p_descripcion varchar(8000),
		@p_bloquearCostear bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
exec @v_id = [ins_cat_catalogo]
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_catalogo_tempario,
			@p_catalogo_codigo,
			@p_codigoInventario,
			@p_precioVenta,
			@p_tiempoConsecucion,
			@p_esNacional,
			@p_id_familia,
			@p_id_subtipoCatalogo,
			@p_id_unidad,
			@p_id_impuesto,
			@p_descripcion,
			@p_bloquearCostear,
			@p_cmm		
INSERT INTO [cat_catalogo.tempario]
			([id],
			[uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo.tempario],
			[duracionEstimada],
			[enTaller],
			[esCiclico],
			[detieneEquipos],
			[horasDetencion],
			[periodoHoras],
			[facturaTodo],
			[periodoDias],
			[porcGarantia],
			[porcTropicalizacion],
			[id_tipoServicio],
			[proyectar],
			[incluirMenores],
			[modoAjuste],
			[cmm])
		VALUES( @v_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_tempario,
			@p_duracionEstimada,
			@p_enTaller,
			@p_esCiclico,
			@p_detieneEquipos,
			@p_horasDetencion,
			@p_periodoHoras,
			@p_facturaTodo,
			@p_periodoDias,
			@p_porcGarantia,
			@p_porcTropicalizacion,
			@p_id_tipoServicio,
			@p_proyectar,
			@p_incluirMenores,
			@p_modoAjuste,
			@p_cmm)
UPDATE [cat_catalogo.tempario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
END
