CREATE PROCEDURE [aud_cat_catalogo_tempario]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_catalogo.tempario].id as id_tabla,
	[cat_catalogo.tempario].id_usuario_modifico as id_usuario_modifico,
	[cat_catalogo.tempario].id_usuario_creo as id_usuario_creo,
	[cat_catalogo.tempario].fechaModificacion as fechaModificacion,
	[cat_catalogo.tempario].fechaCreacion as fechaCreacion,
	[cat_catalogo.tempario].active as active,
	[cat_catalogo.tempario].[catalogo.tempario] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_catalogo.tempario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo.tempario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo.tempario].[id_usuario_creo]
	where ' + @p_filtro)
END
