	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_catalogo_bodega].id as id_tabla,
	[cat_catalogo_bodega].id_usuario_modifico as id_usuario_modifico,
	[cat_catalogo_bodega].id_usuario_creo as id_usuario_creo,
	[cat_catalogo_bodega].fechaModificacion as fechaModificacion,
	[cat_catalogo_bodega].fechaCreacion as fechaCreacion,
	[cat_catalogo_bodega].active as active,
	[cat_catalogo_bodega].[catalogo_bodega] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_catalogo_bodega]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo_bodega].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo_bodega].[id_usuario_creo]
	where ' + @p_filtro)
END
