CREATE  VIEW [view_cat_catalogo_listaPrecio] AS
SELECT 	[cat_catalogo_listaPrecio].[id] AS [id],
		[cat_catalogo_listaPrecio].[uid] AS [uid],
		[cat_catalogo_listaPrecio].[eid] AS [eid],
		[cat_catalogo_listaPrecio].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_catalogo_listaPrecio].[id_usuario_creo] AS [id_usuario_creo],
		[cat_catalogo_listaPrecio].[fechaModificacion] AS [fechaModificacion],
		[cat_catalogo_listaPrecio].[fechaCreacion] AS [fechaCreacion],
		[cat_catalogo_listaPrecio].[active] AS [active],
		[cat_catalogo_listaPrecio].[catalogo_listaPrecio] AS [catalogo_listaPrecio],
		[cat_catalogo_listaPrecio].[PrecioVenta] AS [PrecioVenta],
		[cat_catalogo_listaPrecio].[id_catalogo] AS [id_catalogo],
[cat_catalogo].[catalogo] as [cat_catalogo_catalogo],
[cat_catalogo].[catalogo_codigo] as [cat_catalogo_catalogo_codigo],
[cat_catalogo].[codigoInventario] as [cat_catalogo_codigoInventario],
[cat_catalogo].[precioVenta] as [cat_catalogo_precioVenta],
[cat_catalogo].[tiempoConsecucion] as [cat_catalogo_tiempoConsecucion],
[cat_catalogo].[esNacional] as [cat_catalogo_esNacional],
[cat_catalogo].[id_familia] as [cat_catalogo_id_familia],
[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[cat_catalogo_listaPrecio].[id_listaPrecio] AS [id_listaPrecio],
[cat_listaPrecio].[listaPrecio] as [cat_listaPrecio_listaPrecio],
[cat_listaPrecio].[listaPrecio_codigo] as [cat_listaPrecio_listaPrecio_codigo],
[cat_listaPrecio].[porcentajeDescuento] as [cat_listaPrecio_porcentajeDescuento],
[cat_listaPrecio].[esPrivado] as [cat_listaPrecio_esPrivado],
[cat_listaPrecio].[id_moneda] as [cat_listaPrecio_id_moneda],
[cat_listaPrecio].[paraCompra] as [cat_listaPrecio_paraCompra],
[cat_listaPrecio].[cmm] as [cat_listaPrecio_cmm],
		[cat_catalogo_listaPrecio].[porcDto] AS [porcDto],
		[cat_catalogo_listaPrecio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_catalogo_listaPrecio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo_listaPrecio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo_listaPrecio].[id_usuario_creo]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[cat_catalogo_listaPrecio].[id_catalogo]
	INNER JOIN [cat_listaPrecio] ON [cat_listaPrecio].id=[cat_catalogo_listaPrecio].[id_listaPrecio]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_catalogo_listaPrecio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
