IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_catalogo_listaPrecio]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_catalogo_listaPrecio]
GO
CREATE PROCEDURE [ins_cat_catalogo_listaPrecio]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_catalogo_listaPrecio varchar(300),
		@p_PrecioVenta money,
		@p_id_catalogo int,
		@p_id_listaPrecio int,
		@p_porcDto float,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_catalogo_listaPrecio]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo_listaPrecio],
			[PrecioVenta],
			[id_catalogo],
			[id_listaPrecio],
			[porcDto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_listaPrecio,
			@p_PrecioVenta,
			@p_id_catalogo,
			@p_id_listaPrecio,
			@p_porcDto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_catalogo_listaPrecio] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
