BEGIN
exec(	'SELECT [cat_catalogo_listaPrecio].id as id_tabla,
	[cat_catalogo_listaPrecio].id_usuario_modifico as id_usuario_modifico,
	[cat_catalogo_listaPrecio].id_usuario_creo as id_usuario_creo,
	[cat_catalogo_listaPrecio].fechaModificacion as fechaModificacion,
	[cat_catalogo_listaPrecio].fechaCreacion as fechaCreacion,
	[cat_catalogo_listaPrecio].active as active,
	[cat_catalogo_listaPrecio].[catalogo_listaPrecio] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_catalogo_listaPrecio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_catalogo_listaPrecio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_catalogo_listaPrecio].[id_usuario_creo]
	where ' + @p_filtro)
END
