		[cat_detalleRepuesto].[fechaCreacion] AS [fechaCreacion],
		[cat_detalleRepuesto].[active] AS [active],
		[cat_detalleRepuesto].[detalleRepuesto] AS [detalleRepuesto],
		[cat_detalleRepuesto].[detalleRepuesto_codigo] AS [detalleRepuesto_codigo],
		[cat_detalleRepuesto].[cantidad] AS [cantidad],
		[cat_detalleRepuesto].[id_catalogo.repuesto] AS [id_catalogo.repuesto],
[cat_catalogo.repuesto].[catalogo.repuesto] as [cat_catalogo.repuesto_catalogo.repuesto],
[cat_catalogo.repuesto].[garantiaDias] as [cat_catalogo.repuesto_garantiaDias],
[cat_catalogo.repuesto].[garantiaHoras] as [cat_catalogo.repuesto_garantiaHoras],
[cat_catalogo.repuesto].[vigente] as [cat_catalogo.repuesto_vigente],
[cat_catalogo.repuesto].[id_marca] as [cat_catalogo.repuesto_id_marca],
[cat_catalogo.repuesto].[peso] as [cat_catalogo.repuesto_peso],
[cat_catalogo.repuesto].[cmm] as [cat_catalogo.repuesto_cmm],
		[cat_catalogo_repuesto].[catalogo_codigo] AS [cat_catalogo_repuesto_catalogo_codigo],
		[cat_catalogo_repuesto].[codigoInventario] AS [cat_catalogo_repuesto_codigoInventario],
		[cat_catalogo_repuesto].[precioVenta] AS [cat_catalogo_repuesto_precioVenta],
		[cat_catalogo_repuesto].[tiempoConsecucion] AS [cat_catalogo_repuesto_tiempoConsecucion],
		[cat_catalogo_repuesto].[esNacional] AS [cat_catalogo_repuesto_esNacional],
		[cat_catalogo_repuesto].[id_familia] AS [cat_catalogo_repuesto_id_familia],
		[cat_catalogo_repuesto].[id_subtipoCatalogo] AS [cat_catalogo_repuesto_id_subtipoCatalogo],
		[cat_catalogo_repuesto].[id_unidad] AS [cat_catalogo_repuesto_id_unidad],
		[cat_catalogo_repuesto].[id_impuesto] AS [cat_catalogo_repuesto_id_impuesto],
		[cat_catalogo_repuesto].[descripcion] AS [cat_catalogo_repuesto_descripcion],
		[cat_catalogo_repuesto].[bloquearCostear] AS [cat_catalogo_repuesto_bloquearCostear],
		[cat_catalogo_repuesto].[cmm] AS [cat_catalogo_repuesto_cmm],
		[cat_detalleRepuesto].[id_catalogo.repuesto_hijo] AS [id_catalogo.repuesto_hijo],
[cat_catalogo.repuesto_hijo].[catalogo.repuesto] as [cat_catalogo.repuesto_hijo_catalogo.repuesto],
[cat_catalogo.repuesto_hijo].[garantiaDias] as [cat_catalogo.repuesto_hijo_garantiaDias],
[cat_catalogo.repuesto_hijo].[garantiaHoras] as [cat_catalogo.repuesto_hijo_garantiaHoras],
[cat_catalogo.repuesto_hijo].[vigente] as [cat_catalogo.repuesto_hijo_vigente],
[cat_catalogo.repuesto_hijo].[id_marca] as [cat_catalogo.repuesto_hijo_id_marca],
[cat_catalogo.repuesto_hijo].[peso] as [cat_catalogo.repuesto_hijo_peso],
[cat_catalogo.repuesto_hijo].[cmm] as [cat_catalogo.repuesto_hijo_cmm],
		[cat_catalogo_repuesto_hijo].[catalogo_codigo] AS [cat_catalogo_repuesto_hijo_catalogo_codigo],
		[cat_catalogo_repuesto_hijo].[codigoInventario] AS [cat_catalogo_repuesto_hijo_codigoInventario],
		[cat_catalogo_repuesto_hijo].[precioVenta] AS [cat_catalogo_repuesto_hijo_precioVenta],
		[cat_catalogo_repuesto_hijo].[tiempoConsecucion] AS [cat_catalogo_repuesto_hijo_tiempoConsecucion],
		[cat_catalogo_repuesto_hijo].[esNacional] AS [cat_catalogo_repuesto_hijo_esNacional],
		[cat_catalogo_repuesto_hijo].[id_familia] AS [cat_catalogo_repuesto_hijo_id_familia],
		[cat_catalogo_repuesto_hijo].[id_subtipoCatalogo] AS [cat_catalogo_repuesto_hijo_id_subtipoCatalogo],
		[cat_catalogo_repuesto_hijo].[id_unidad] AS [cat_catalogo_repuesto_hijo_id_unidad],
		[cat_catalogo_repuesto_hijo].[id_impuesto] AS [cat_catalogo_repuesto_hijo_id_impuesto],
		[cat_catalogo_repuesto_hijo].[descripcion] AS [cat_catalogo_repuesto_hijo_descripcion],
		[cat_catalogo_repuesto_hijo].[bloquearCostear] AS [cat_catalogo_repuesto_hijo_bloquearCostear],
		[cat_catalogo_repuesto_hijo].[cmm] AS [cat_catalogo_repuesto_hijo_cmm],
		[cat_detalleRepuesto].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_detalleRepuesto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_detalleRepuesto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_detalleRepuesto].[id_usuario_creo]
	INNER JOIN [cat_catalogo.repuesto] ON [cat_catalogo.repuesto].id=[cat_detalleRepuesto].[id_catalogo.repuesto]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_repuesto] ON [cat_catalogo.repuesto].id = [cat_catalogo_repuesto].id
	INNER JOIN [cat_catalogo.repuesto] AS [cat_catalogo.repuesto_hijo] ON [cat_catalogo.repuesto_hijo].id=[cat_detalleRepuesto].[id_catalogo.repuesto_hijo]
	INNER JOIN [cat_catalogo] aS  [cat_catalogo_repuesto_hijo] ON [cat_catalogo.repuesto_hijo].id = [cat_catalogo_repuesto_hijo].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_detalleRepuesto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_detalleRepuesto].active=1
