GO
CREATE PROCEDURE [upd_cat_detalleRepuesto]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detalleRepuesto varchar(300) = null,
		@p_detalleRepuesto_codigo varchar(100) = null,
		@p_cantidad float = null,
		@p_id_catalogo_repuesto int = null,
		@p_id_catalogo_repuesto_hijo int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_detalleRepuesto]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detalleRepuesto] = isnull(@p_detalleRepuesto,[detalleRepuesto]),
			[detalleRepuesto_codigo] = isnull(@p_detalleRepuesto_codigo,[detalleRepuesto_codigo]),
			[cantidad] = isnull(@p_cantidad,[cantidad]),
			[id_catalogo.repuesto] = isnull(@p_id_catalogo_repuesto,[id_catalogo.repuesto]),
			[id_catalogo.repuesto_hijo] = isnull(@p_id_catalogo_repuesto_hijo,[id_catalogo.repuesto_hijo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
