IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_detalleRepuesto]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_detalleRepuesto]
GO
CREATE PROCEDURE [ins_cat_detalleRepuesto]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detalleRepuesto varchar(300),
		@p_detalleRepuesto_codigo varchar(100),
		@p_cantidad float,
		@p_id_catalogo_repuesto int,
		@p_id_catalogo_repuesto_hijo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_detalleRepuesto]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detalleRepuesto],
			[detalleRepuesto_codigo],
			[cantidad],
			[id_catalogo.repuesto],
			[id_catalogo.repuesto_hijo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detalleRepuesto,
			@p_detalleRepuesto_codigo,
			@p_cantidad,
			@p_id_catalogo_repuesto,
			@p_id_catalogo_repuesto_hijo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_detalleRepuesto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
