CREATE PROCEDURE [aud_cat_detalleRepuesto]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_detalleRepuesto].id as id_tabla,
	[cat_detalleRepuesto].id_usuario_modifico as id_usuario_modifico,
	[cat_detalleRepuesto].id_usuario_creo as id_usuario_creo,
	[cat_detalleRepuesto].fechaModificacion as fechaModificacion,
	[cat_detalleRepuesto].fechaCreacion as fechaCreacion,
	[cat_detalleRepuesto].active as active,
	[cat_detalleRepuesto].[detalleRepuesto] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_detalleRepuesto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_detalleRepuesto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_detalleRepuesto].[id_usuario_creo]
	where ' + @p_filtro)
END
