[cat_catalogo.tempario].[detieneEquipos] as [cat_catalogo.tempario_detieneEquipos],
[cat_catalogo.tempario].[horasDetencion] as [cat_catalogo.tempario_horasDetencion],
[cat_catalogo.tempario].[periodoHoras] as [cat_catalogo.tempario_periodoHoras],
[cat_catalogo.tempario].[facturaTodo] as [cat_catalogo.tempario_facturaTodo],
[cat_catalogo.tempario].[periodoDias] as [cat_catalogo.tempario_periodoDias],
[cat_catalogo.tempario].[porcGarantia] as [cat_catalogo.tempario_porcGarantia],
[cat_catalogo.tempario].[porcTropicalizacion] as [cat_catalogo.tempario_porcTropicalizacion],
[cat_catalogo.tempario].[id_tipoServicio] as [cat_catalogo.tempario_id_tipoServicio],
[cat_catalogo.tempario].[proyectar] as [cat_catalogo.tempario_proyectar],
[cat_catalogo.tempario].[incluirMenores] as [cat_catalogo.tempario_incluirMenores],
[cat_catalogo.tempario].[modoAjuste] as [cat_catalogo.tempario_modoAjuste],
[cat_catalogo.tempario].[cmm] as [cat_catalogo.tempario_cmm],
		[cat_catalogo_tempario].[catalogo_codigo] AS [cat_catalogo_tempario_catalogo_codigo],
		[cat_catalogo_tempario].[codigoInventario] AS [cat_catalogo_tempario_codigoInventario],
		[cat_catalogo_tempario].[precioVenta] AS [cat_catalogo_tempario_precioVenta],
		[cat_catalogo_tempario].[tiempoConsecucion] AS [cat_catalogo_tempario_tiempoConsecucion],
		[cat_catalogo_tempario].[esNacional] AS [cat_catalogo_tempario_esNacional],
		[cat_catalogo_tempario].[id_familia] AS [cat_catalogo_tempario_id_familia],
		[cat_catalogo_tempario].[id_subtipoCatalogo] AS [cat_catalogo_tempario_id_subtipoCatalogo],
		[cat_catalogo_tempario].[id_unidad] AS [cat_catalogo_tempario_id_unidad],
		[cat_catalogo_tempario].[id_impuesto] AS [cat_catalogo_tempario_id_impuesto],
		[cat_catalogo_tempario].[descripcion] AS [cat_catalogo_tempario_descripcion],
		[cat_catalogo_tempario].[bloquearCostear] AS [cat_catalogo_tempario_bloquearCostear],
		[cat_catalogo_tempario].[cmm] AS [cat_catalogo_tempario_cmm],
		[cat_detalleTempario].[id_pruebaCheckList] AS [id_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList] as [cat_pruebaCheckList_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList_codigo] as [cat_pruebaCheckList_pruebaCheckList_codigo],
[cat_pruebaCheckList].[activo] as [cat_pruebaCheckList_activo],
[cat_pruebaCheckList].[cmm] as [cat_pruebaCheckList_cmm],
		[cat_detalleTempario].[id_sistema] AS [id_sistema],
[cat_sistema].[sistema] as [cat_sistema_sistema],
[cat_sistema].[sistema_codigo] as [cat_sistema_sistema_codigo],
[cat_sistema].[id_sistema] as [cat_sistema_id_sistema],
[cat_sistema].[cmm] as [cat_sistema_cmm],
		[cat_detalleTempario].[id_detalleTempario_padre] AS [id_detalleTempario_padre],
[cat_detalleTempario_padre].[detalleTempario] as [cat_detalleTempario_padre_detalleTempario],
[cat_detalleTempario_padre].[detalleTempario_codigo] as [cat_detalleTempario_padre_detalleTempario_codigo],
[cat_detalleTempario_padre].[cantidadEstandar] as [cat_detalleTempario_padre_cantidadEstandar],
[cat_detalleTempario_padre].[orden] as [cat_detalleTempario_padre_orden],
[cat_detalleTempario_padre].[cantidadTropicalizada] as [cat_detalleTempario_padre_cantidadTropicalizada],
[cat_detalleTempario_padre].[id_catalogo] as [cat_detalleTempario_padre_id_catalogo],
[cat_detalleTempario_padre].[id_catalogo.tempario] as [cat_detalleTempario_padre_id_catalogo.tempario],
[cat_detalleTempario_padre].[id_pruebaCheckList] as [cat_detalleTempario_padre_id_pruebaCheckList],
[cat_detalleTempario_padre].[id_sistema] as [cat_detalleTempario_padre_id_sistema],
[cat_detalleTempario_padre].[id_detalleTempario_padre] as [cat_detalleTempario_padre_id_detalleTempario_padre],
[cat_detalleTempario_padre].[cmm] as [cat_detalleTempario_padre_cmm],
		[cat_detalleTempario].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_detalleTempario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_detalleTempario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_detalleTempario].[id_usuario_creo]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[cat_detalleTempario].[id_catalogo]
	INNER JOIN [cat_catalogo.tempario] ON [cat_catalogo.tempario].id=[cat_detalleTempario].[id_catalogo.tempario]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_tempario] ON [cat_catalogo.tempario].id = [cat_catalogo_tempario].id
	INNER JOIN [cat_pruebaCheckList] ON [cat_pruebaCheckList].id=[cat_detalleTempario].[id_pruebaCheckList]
	INNER JOIN [cat_sistema] ON [cat_sistema].id=[cat_detalleTempario].[id_sistema]
	INNER JOIN [cat_detalleTempario] AS [cat_detalleTempario_padre] ON [cat_detalleTempario_padre].id=[cat_detalleTempario].[id_detalleTempario_padre]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_detalleTempario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_detalleTempario].active=1
GO
