CREATE PROCEDURE [aud_cat_detalleTempario]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_detalleTempario].id as id_tabla,
	[cat_detalleTempario].id_usuario_modifico as id_usuario_modifico,
	[cat_detalleTempario].id_usuario_creo as id_usuario_creo,
	[cat_detalleTempario].fechaModificacion as fechaModificacion,
	[cat_detalleTempario].fechaCreacion as fechaCreacion,
	[cat_detalleTempario].active as active,
	[cat_detalleTempario].[detalleTempario] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_detalleTempario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_detalleTempario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_detalleTempario].[id_usuario_creo]
	where ' + @p_filtro)
END
