IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_dimension]')) DROP VIEW [dbo].[view_cat_dimension]
GO
CREATE  VIEW [view_cat_dimension] AS
SELECT 	[cat_dimension].[id] AS [id],
		[cat_dimension].[uid] AS [uid],
		[cat_dimension].[eid] AS [eid],
		[cat_dimension].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_dimension].[id_usuario_creo] AS [id_usuario_creo],
		[cat_dimension].[fechaModificacion] AS [fechaModificacion],
		[cat_dimension].[fechaCreacion] AS [fechaCreacion],
		[cat_dimension].[active] AS [active],
		[cat_dimension].[dimension] AS [dimension],
		[cat_dimension].[dimension_codigo] AS [dimension_codigo],
		[cat_dimension].[aplicaEnX] AS [aplicaEnX],
		[cat_dimension].[aplicaEnY] AS [aplicaEnY],
		[cat_dimension].[aplicaEnZ] AS [aplicaEnZ],
		[cat_dimension].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_dimension]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_dimension].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_dimension].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_dimension].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_dimension].active=1
GO
