GO
CREATE PROCEDURE [upd_cat_dimension]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_dimension varchar(300) = null,
		@p_dimension_codigo varchar(100) = null,
		@p_aplicaEnX bit = null,
		@p_aplicaEnY bit = null,
		@p_aplicaEnZ bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_dimension]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[dimension] = isnull(@p_dimension,[dimension]),
			[dimension_codigo] = isnull(@p_dimension_codigo,[dimension_codigo]),
			[aplicaEnX] = isnull(@p_aplicaEnX,[aplicaEnX]),
			[aplicaEnY] = isnull(@p_aplicaEnY,[aplicaEnY]),
			[aplicaEnZ] = isnull(@p_aplicaEnZ,[aplicaEnZ]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
