IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_dimension]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_dimension]
GO
CREATE PROCEDURE [ins_cat_dimension]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_dimension varchar(300),
		@p_dimension_codigo varchar(100),
		@p_aplicaEnX bit,
		@p_aplicaEnY bit,
		@p_aplicaEnZ bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_dimension]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[dimension],
			[dimension_codigo],
			[aplicaEnX],
			[aplicaEnY],
			[aplicaEnZ],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_dimension,
			@p_dimension_codigo,
			@p_aplicaEnX,
			@p_aplicaEnY,
			@p_aplicaEnZ,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_dimension] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
