		[cat_listaPrecio].[fechaModificacion] AS [fechaModificacion],
		[cat_listaPrecio].[fechaCreacion] AS [fechaCreacion],
		[cat_listaPrecio].[active] AS [active],
		[cat_listaPrecio].[listaPrecio] AS [listaPrecio],
		[cat_listaPrecio].[listaPrecio_codigo] AS [listaPrecio_codigo],
