		[cat_listaPrecio].[esPrivado] AS [esPrivado],
		[cat_listaPrecio].[id_moneda] AS [id_moneda],
[gen_moneda].[moneda] as [gen_moneda_moneda],
[gen_moneda].[moneda_codigo] as [gen_moneda_moneda_codigo],
[gen_moneda].[abreviatura] as [gen_moneda_abreviatura],
[gen_moneda].[cambio] as [gen_moneda_cambio],
[gen_moneda].[cmm] as [gen_moneda_cmm],
		[cat_listaPrecio].[paraCompra] AS [paraCompra],
		[cat_listaPrecio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_listaPrecio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_listaPrecio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_listaPrecio].[id_usuario_creo]
	INNER JOIN [gen_moneda] ON [gen_moneda].id=[cat_listaPrecio].[id_moneda]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_listaPrecio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_listaPrecio].active=1
