CREATE PROCEDURE [ins_cat_listaPrecio]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_listaPrecio varchar(300),
		@p_listaPrecio_codigo varchar(100),
		@p_porcentajeDescuento float,
		@p_esPrivado bit,
		@p_id_moneda int,
		@p_paraCompra bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_listaPrecio]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[listaPrecio],
			[listaPrecio_codigo],
			[porcentajeDescuento],
			[esPrivado],
			[id_moneda],
			[paraCompra],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_listaPrecio,
			@p_listaPrecio_codigo,
			@p_porcentajeDescuento,
			@p_esPrivado,
			@p_id_moneda,
			@p_paraCompra,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_listaPrecio] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
