GO
CREATE PROCEDURE [aud_cat_listaPrecio]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_listaPrecio].id as id_tabla,
	[cat_listaPrecio].id_usuario_modifico as id_usuario_modifico,
	[cat_listaPrecio].id_usuario_creo as id_usuario_creo,
	[cat_listaPrecio].fechaModificacion as fechaModificacion,
	[cat_listaPrecio].fechaCreacion as fechaCreacion,
	[cat_listaPrecio].active as active,
	[cat_listaPrecio].[listaPrecio] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_listaPrecio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_listaPrecio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_listaPrecio].[id_usuario_creo]
	where ' + @p_filtro)
END
