IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_marca]')) DROP VIEW [dbo].[view_cat_marca]
GO
CREATE  VIEW [view_cat_marca] AS
SELECT 	[cat_marca].[id] AS [id],
		[cat_marca].[uid] AS [uid],
		[cat_marca].[eid] AS [eid],
		[cat_marca].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_marca].[id_usuario_creo] AS [id_usuario_creo],
		[cat_marca].[fechaModificacion] AS [fechaModificacion],
		[cat_marca].[fechaCreacion] AS [fechaCreacion],
		[cat_marca].[active] AS [active],
		[cat_marca].[marca] AS [marca],
		[cat_marca].[marca_codigo] AS [marca_codigo],
		[cat_marca].[id_tercero_fabricante] AS [id_tercero_fabricante],
[ter_tercero_fabricante].[tercero] as [ter_tercero_fabricante_tercero],
[ter_tercero_fabricante].[tercero_codigo] as [ter_tercero_fabricante_tercero_codigo],
[ter_tercero_fabricante].[tercero_nit] as [ter_tercero_fabricante_tercero_nit],
[ter_tercero_fabricante].[direccion] as [ter_tercero_fabricante_direccion],
[ter_tercero_fabricante].[contacto] as [ter_tercero_fabricante_contacto],
[ter_tercero_fabricante].[telefono] as [ter_tercero_fabricante_telefono],
[ter_tercero_fabricante].[fax] as [ter_tercero_fabricante_fax],
[ter_tercero_fabricante].[email] as [ter_tercero_fabricante_email],
[ter_tercero_fabricante].[website] as [ter_tercero_fabricante_website],
[ter_tercero_fabricante].[representante] as [ter_tercero_fabricante_representante],
[ter_tercero_fabricante].[notas] as [ter_tercero_fabricante_notas],
[ter_tercero_fabricante].[tercero_nombreCorto] as [ter_tercero_fabricante_tercero_nombreCorto],
[ter_tercero_fabricante].[esCliente] as [ter_tercero_fabricante_esCliente],
[ter_tercero_fabricante].[esProveedor] as [ter_tercero_fabricante_esProveedor],
[ter_tercero_fabricante].[esTransportador] as [ter_tercero_fabricante_esTransportador],
[ter_tercero_fabricante].[esFabricante] as [ter_tercero_fabricante_esFabricante],
[ter_tercero_fabricante].[esEmpresaPropia] as [ter_tercero_fabricante_esEmpresaPropia],
[ter_tercero_fabricante].[clasificacion] as [ter_tercero_fabricante_clasificacion],
[ter_tercero_fabricante].[id_zona] as [ter_tercero_fabricante_id_zona],
[ter_tercero_fabricante].[id_estadoTercero] as [ter_tercero_fabricante_id_estadoTercero],
[ter_tercero_fabricante].[id_naturalezaTercero] as [ter_tercero_fabricante_id_naturalezaTercero],
[ter_tercero_fabricante].[esProspecto] as [ter_tercero_fabricante_esProspecto],
[ter_tercero_fabricante].[id_formaPago] as [ter_tercero_fabricante_id_formaPago],
[ter_tercero_fabricante].[tiempoEntrega] as [ter_tercero_fabricante_tiempoEntrega],
[ter_tercero_fabricante].[cmm] as [ter_tercero_fabricante_cmm],
		[cat_marca].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_marca]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_marca].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_marca].[id_usuario_creo]
	INNER JOIN [ter_tercero] AS [ter_tercero_fabricante] ON [ter_tercero_fabricante].id=[cat_marca].[id_tercero_fabricante]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_marca].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_marca].active=1
GO
