		[cat_posicion].[posicion_codigo] AS [posicion_codigo],
		[cat_posicion].[id_catalogo.equipo_equipo] AS [id_catalogo.equipo_equipo],
[cat_catalogo.equipo_equipo].[catalogo.equipo] as [cat_catalogo.equipo_equipo_catalogo.equipo],
[cat_catalogo.equipo_equipo].[garantiaMeses] as [cat_catalogo.equipo_equipo_garantiaMeses],
[cat_catalogo.equipo_equipo].[garantiaHoras] as [cat_catalogo.equipo_equipo_garantiaHoras],
[cat_catalogo.equipo_equipo].[manejaHorometro] as [cat_catalogo.equipo_equipo_manejaHorometro],
[cat_catalogo.equipo_equipo].[id_marca] as [cat_catalogo.equipo_equipo_id_marca],
[cat_catalogo.equipo_equipo].[cmm] as [cat_catalogo.equipo_equipo_cmm],
		[cat_catalogo_equipo_equipo].[catalogo_codigo] AS [cat_catalogo_equipo_equipo_catalogo_codigo],
		[cat_catalogo_equipo_equipo].[codigoInventario] AS [cat_catalogo_equipo_equipo_codigoInventario],
		[cat_catalogo_equipo_equipo].[precioVenta] AS [cat_catalogo_equipo_equipo_precioVenta],
		[cat_catalogo_equipo_equipo].[tiempoConsecucion] AS [cat_catalogo_equipo_equipo_tiempoConsecucion],
		[cat_catalogo_equipo_equipo].[esNacional] AS [cat_catalogo_equipo_equipo_esNacional],
		[cat_catalogo_equipo_equipo].[id_familia] AS [cat_catalogo_equipo_equipo_id_familia],
		[cat_catalogo_equipo_equipo].[id_subtipoCatalogo] AS [cat_catalogo_equipo_equipo_id_subtipoCatalogo],
		[cat_catalogo_equipo_equipo].[id_unidad] AS [cat_catalogo_equipo_equipo_id_unidad],
		[cat_catalogo_equipo_equipo].[id_impuesto] AS [cat_catalogo_equipo_equipo_id_impuesto],
		[cat_catalogo_equipo_equipo].[descripcion] AS [cat_catalogo_equipo_equipo_descripcion],
		[cat_catalogo_equipo_equipo].[bloquearCostear] AS [cat_catalogo_equipo_equipo_bloquearCostear],
		[cat_catalogo_equipo_equipo].[cmm] AS [cat_catalogo_equipo_equipo_cmm],
		[cat_posicion].[id_catalogo.equipo_componente] AS [id_catalogo.equipo_componente],
[cat_catalogo.equipo_componente].[catalogo.equipo] as [cat_catalogo.equipo_componente_catalogo.equipo],
[cat_catalogo.equipo_componente].[garantiaMeses] as [cat_catalogo.equipo_componente_garantiaMeses],
[cat_catalogo.equipo_componente].[garantiaHoras] as [cat_catalogo.equipo_componente_garantiaHoras],
[cat_catalogo.equipo_componente].[manejaHorometro] as [cat_catalogo.equipo_componente_manejaHorometro],
[cat_catalogo.equipo_componente].[id_marca] as [cat_catalogo.equipo_componente_id_marca],
[cat_catalogo.equipo_componente].[cmm] as [cat_catalogo.equipo_componente_cmm],
		[cat_catalogo_equipo_componente].[catalogo_codigo] AS [cat_catalogo_equipo_componente_catalogo_codigo],
		[cat_catalogo_equipo_componente].[codigoInventario] AS [cat_catalogo_equipo_componente_codigoInventario],
		[cat_catalogo_equipo_componente].[precioVenta] AS [cat_catalogo_equipo_componente_precioVenta],
		[cat_catalogo_equipo_componente].[tiempoConsecucion] AS [cat_catalogo_equipo_componente_tiempoConsecucion],
		[cat_catalogo_equipo_componente].[esNacional] AS [cat_catalogo_equipo_componente_esNacional],
		[cat_catalogo_equipo_componente].[id_familia] AS [cat_catalogo_equipo_componente_id_familia],
		[cat_catalogo_equipo_componente].[id_subtipoCatalogo] AS [cat_catalogo_equipo_componente_id_subtipoCatalogo],
		[cat_catalogo_equipo_componente].[id_unidad] AS [cat_catalogo_equipo_componente_id_unidad],
		[cat_catalogo_equipo_componente].[id_impuesto] AS [cat_catalogo_equipo_componente_id_impuesto],
		[cat_catalogo_equipo_componente].[descripcion] AS [cat_catalogo_equipo_componente_descripcion],
		[cat_catalogo_equipo_componente].[bloquearCostear] AS [cat_catalogo_equipo_componente_bloquearCostear],
		[cat_catalogo_equipo_componente].[cmm] AS [cat_catalogo_equipo_componente_cmm],
		[cat_posicion].[id_dimension_x] AS [id_dimension_x],
[cat_dimension_x].[dimension] as [cat_dimension_x_dimension],
[cat_dimension_x].[dimension_codigo] as [cat_dimension_x_dimension_codigo],
[cat_dimension_x].[aplicaEnX] as [cat_dimension_x_aplicaEnX],
[cat_dimension_x].[aplicaEnY] as [cat_dimension_x_aplicaEnY],
[cat_dimension_x].[aplicaEnZ] as [cat_dimension_x_aplicaEnZ],
[cat_dimension_x].[cmm] as [cat_dimension_x_cmm],
		[cat_posicion].[id_dimension_y] AS [id_dimension_y],
[cat_dimension_y].[dimension] as [cat_dimension_y_dimension],
[cat_dimension_y].[dimension_codigo] as [cat_dimension_y_dimension_codigo],
[cat_dimension_y].[aplicaEnX] as [cat_dimension_y_aplicaEnX],
[cat_dimension_y].[aplicaEnY] as [cat_dimension_y_aplicaEnY],
[cat_dimension_y].[aplicaEnZ] as [cat_dimension_y_aplicaEnZ],
[cat_dimension_y].[cmm] as [cat_dimension_y_cmm],
		[cat_posicion].[id_dimension_z] AS [id_dimension_z],
[cat_dimension_z].[dimension] as [cat_dimension_z_dimension],
[cat_dimension_z].[dimension_codigo] as [cat_dimension_z_dimension_codigo],
[cat_dimension_z].[aplicaEnX] as [cat_dimension_z_aplicaEnX],
[cat_dimension_z].[aplicaEnY] as [cat_dimension_z_aplicaEnY],
[cat_dimension_z].[aplicaEnZ] as [cat_dimension_z_aplicaEnZ],
[cat_dimension_z].[cmm] as [cat_dimension_z_cmm],
		[cat_posicion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_posicion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_posicion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_posicion].[id_usuario_creo]
	INNER JOIN [cat_catalogo.equipo] AS [cat_catalogo.equipo_equipo] ON [cat_catalogo.equipo_equipo].id=[cat_posicion].[id_catalogo.equipo_equipo]
	INNER JOIN [cat_catalogo] aS  [cat_catalogo_equipo_equipo] ON [cat_catalogo.equipo_equipo].id = [cat_catalogo_equipo_equipo].id
	INNER JOIN [cat_catalogo.equipo] AS [cat_catalogo.equipo_componente] ON [cat_catalogo.equipo_componente].id=[cat_posicion].[id_catalogo.equipo_componente]
	INNER JOIN [cat_catalogo] aS  [cat_catalogo_equipo_componente] ON [cat_catalogo.equipo_componente].id = [cat_catalogo_equipo_componente].id
	INNER JOIN [cat_dimension] AS [cat_dimension_x] ON [cat_dimension_x].id=[cat_posicion].[id_dimension_x]
	INNER JOIN [cat_dimension] AS [cat_dimension_y] ON [cat_dimension_y].id=[cat_posicion].[id_dimension_y]
	INNER JOIN [cat_dimension] AS [cat_dimension_z] ON [cat_dimension_z].id=[cat_posicion].[id_dimension_z]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_posicion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_posicion].active=1
GO
