IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_cat_posicion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_cat_posicion]
GO
CREATE PROCEDURE [upd_cat_posicion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_posicion varchar(300) = null,
		@p_posicion_codigo varchar(100) = null,
		@p_id_catalogo_equipo_equipo int = null,
		@p_id_catalogo_equipo_componente int = null,
		@p_id_dimension_x int = null,
		@p_id_dimension_y int = null,
		@p_id_dimension_z int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_posicion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[posicion] = isnull(@p_posicion,[posicion]),
			[posicion_codigo] = isnull(@p_posicion_codigo,[posicion_codigo]),
			[id_catalogo.equipo_equipo] = isnull(@p_id_catalogo_equipo_equipo,[id_catalogo.equipo_equipo]),
			[id_catalogo.equipo_componente] = isnull(@p_id_catalogo_equipo_componente,[id_catalogo.equipo_componente]),
			[id_dimension_x] = isnull(@p_id_dimension_x,[id_dimension_x]),
			[id_dimension_y] = isnull(@p_id_dimension_y,[id_dimension_y]),
			[id_dimension_z] = isnull(@p_id_dimension_z,[id_dimension_z]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
