IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_posicion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_posicion]
GO
CREATE PROCEDURE [ins_cat_posicion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_posicion varchar(300),
		@p_posicion_codigo varchar(100),
		@p_id_catalogo_equipo_equipo int,
		@p_id_catalogo_equipo_componente int,
		@p_id_dimension_x int,
		@p_id_dimension_y int,
		@p_id_dimension_z int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_posicion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[posicion],
			[posicion_codigo],
			[id_catalogo.equipo_equipo],
			[id_catalogo.equipo_componente],
			[id_dimension_x],
			[id_dimension_y],
			[id_dimension_z],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_posicion,
			@p_posicion_codigo,
			@p_id_catalogo_equipo_equipo,
			@p_id_catalogo_equipo_componente,
			@p_id_dimension_x,
			@p_id_dimension_y,
			@p_id_dimension_z,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_posicion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
