CREATE PROCEDURE [aud_cat_posicion]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_posicion].id as id_tabla,
	[cat_posicion].id_usuario_modifico as id_usuario_modifico,
	[cat_posicion].id_usuario_creo as id_usuario_creo,
	[cat_posicion].fechaModificacion as fechaModificacion,
	[cat_posicion].fechaCreacion as fechaCreacion,
	[cat_posicion].active as active,
	[cat_posicion].[posicion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_posicion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_posicion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_posicion].[id_usuario_creo]
	where ' + @p_filtro)
END
