IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_pruebaCheckList]')) DROP VIEW [dbo].[view_cat_pruebaCheckList]
GO
CREATE  VIEW [view_cat_pruebaCheckList] AS
SELECT 	[cat_pruebaCheckList].[id] AS [id],
		[cat_pruebaCheckList].[uid] AS [uid],
		[cat_pruebaCheckList].[eid] AS [eid],
		[cat_pruebaCheckList].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_pruebaCheckList].[id_usuario_creo] AS [id_usuario_creo],
		[cat_pruebaCheckList].[fechaModificacion] AS [fechaModificacion],
		[cat_pruebaCheckList].[fechaCreacion] AS [fechaCreacion],
		[cat_pruebaCheckList].[active] AS [active],
		[cat_pruebaCheckList].[pruebaCheckList] AS [pruebaCheckList],
		[cat_pruebaCheckList].[pruebaCheckList_codigo] AS [pruebaCheckList_codigo],
		[cat_pruebaCheckList].[activo] AS [activo],
		[cat_pruebaCheckList].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_pruebaCheckList]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_pruebaCheckList].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_pruebaCheckList].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_pruebaCheckList].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_pruebaCheckList].active=1
GO
