			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[pruebaCheckList] = isnull(@p_pruebaCheckList,[pruebaCheckList]),
			[pruebaCheckList_codigo] = isnull(@p_pruebaCheckList_codigo,[pruebaCheckList_codigo]),
			[activo] = isnull(@p_activo,[activo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
