IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_pruebaCheckList]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_pruebaCheckList]
