IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_pruebaCheckList_atributo]')) DROP VIEW [dbo].[view_cat_pruebaCheckList_atributo]
GO
CREATE  VIEW [view_cat_pruebaCheckList_atributo] AS
SELECT 	[cat_pruebaCheckList_atributo].[id] AS [id],
		[cat_pruebaCheckList_atributo].[uid] AS [uid],
		[cat_pruebaCheckList_atributo].[eid] AS [eid],
		[cat_pruebaCheckList_atributo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_pruebaCheckList_atributo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_pruebaCheckList_atributo].[fechaModificacion] AS [fechaModificacion],
		[cat_pruebaCheckList_atributo].[fechaCreacion] AS [fechaCreacion],
		[cat_pruebaCheckList_atributo].[active] AS [active],
		[cat_pruebaCheckList_atributo].[pruebaCheckList_atributo] AS [pruebaCheckList_atributo],
		[cat_pruebaCheckList_atributo].[id_pruebaCheckList] AS [id_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList] as [cat_pruebaCheckList_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList_codigo] as [cat_pruebaCheckList_pruebaCheckList_codigo],
[cat_pruebaCheckList].[activo] as [cat_pruebaCheckList_activo],
[cat_pruebaCheckList].[cmm] as [cat_pruebaCheckList_cmm],
		[cat_pruebaCheckList_atributo].[id_atributo] AS [id_atributo],
[cat_atributo].[atributo] as [cat_atributo_atributo],
[cat_atributo].[atributo_codigo] as [cat_atributo_atributo_codigo],
[cat_atributo].[id_unidad] as [cat_atributo_id_unidad],
[cat_atributo].[cmm] as [cat_atributo_cmm],
		[cat_pruebaCheckList_atributo].[orden] AS [orden],
		[cat_pruebaCheckList_atributo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_pruebaCheckList_atributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_pruebaCheckList_atributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_pruebaCheckList_atributo].[id_usuario_creo]
	INNER JOIN [cat_pruebaCheckList] ON [cat_pruebaCheckList].id=[cat_pruebaCheckList_atributo].[id_pruebaCheckList]
	INNER JOIN [cat_atributo] ON [cat_atributo].id=[cat_pruebaCheckList_atributo].[id_atributo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_pruebaCheckList_atributo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
