GO
CREATE PROCEDURE [ins_cat_pruebaCheckList_atributo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_pruebaCheckList_atributo varchar(300),
		@p_id_pruebaCheckList int,
		@p_id_atributo int,
		@p_orden int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_pruebaCheckList_atributo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[pruebaCheckList_atributo],
			[id_pruebaCheckList],
			[id_atributo],
			[orden],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_pruebaCheckList_atributo,
			@p_id_pruebaCheckList,
			@p_id_atributo,
			@p_orden,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_pruebaCheckList_atributo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
