IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_reemplazo]')) DROP VIEW [dbo].[view_cat_reemplazo]
GO
CREATE  VIEW [view_cat_reemplazo] AS
SELECT 	[cat_reemplazo].[id] AS [id],
		[cat_reemplazo].[uid] AS [uid],
		[cat_reemplazo].[eid] AS [eid],
		[cat_reemplazo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_reemplazo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_reemplazo].[fechaModificacion] AS [fechaModificacion],
		[cat_reemplazo].[fechaCreacion] AS [fechaCreacion],
		[cat_reemplazo].[active] AS [active],
		[cat_reemplazo].[reemplazo] AS [reemplazo],
		[cat_reemplazo].[reemplazo_codigo] AS [reemplazo_codigo],
		[cat_reemplazo].[id_tipoReemplazo] AS [id_tipoReemplazo],
[cat_tipoReemplazo].[tipoReemplazo] as [cat_tipoReemplazo_tipoReemplazo],
[cat_tipoReemplazo].[tipoReemplazo_codigo] as [cat_tipoReemplazo_tipoReemplazo_codigo],
[cat_tipoReemplazo].[cmm] as [cat_tipoReemplazo_cmm],
		[cat_reemplazo].[id_catalogo.repuesto] AS [id_catalogo.repuesto],
[cat_catalogo.repuesto].[catalogo.repuesto] as [cat_catalogo.repuesto_catalogo.repuesto],
[cat_catalogo.repuesto].[garantiaDias] as [cat_catalogo.repuesto_garantiaDias],
[cat_catalogo.repuesto].[garantiaHoras] as [cat_catalogo.repuesto_garantiaHoras],
[cat_catalogo.repuesto].[vigente] as [cat_catalogo.repuesto_vigente],
[cat_catalogo.repuesto].[id_marca] as [cat_catalogo.repuesto_id_marca],
[cat_catalogo.repuesto].[peso] as [cat_catalogo.repuesto_peso],
[cat_catalogo.repuesto].[cmm] as [cat_catalogo.repuesto_cmm],
		[cat_catalogo_repuesto].[catalogo_codigo] AS [cat_catalogo_repuesto_catalogo_codigo],
		[cat_catalogo_repuesto].[codigoInventario] AS [cat_catalogo_repuesto_codigoInventario],
		[cat_catalogo_repuesto].[precioVenta] AS [cat_catalogo_repuesto_precioVenta],
		[cat_catalogo_repuesto].[tiempoConsecucion] AS [cat_catalogo_repuesto_tiempoConsecucion],
		[cat_catalogo_repuesto].[esNacional] AS [cat_catalogo_repuesto_esNacional],
		[cat_catalogo_repuesto].[id_familia] AS [cat_catalogo_repuesto_id_familia],
		[cat_catalogo_repuesto].[id_subtipoCatalogo] AS [cat_catalogo_repuesto_id_subtipoCatalogo],
		[cat_catalogo_repuesto].[id_unidad] AS [cat_catalogo_repuesto_id_unidad],
		[cat_catalogo_repuesto].[id_impuesto] AS [cat_catalogo_repuesto_id_impuesto],
		[cat_catalogo_repuesto].[descripcion] AS [cat_catalogo_repuesto_descripcion],
		[cat_catalogo_repuesto].[bloquearCostear] AS [cat_catalogo_repuesto_bloquearCostear],
		[cat_catalogo_repuesto].[cmm] AS [cat_catalogo_repuesto_cmm],
		[cat_reemplazo].[id_catalogo.repuesto_1] AS [id_catalogo.repuesto_1],
[cat_catalogo.repuesto_1].[catalogo.repuesto] as [cat_catalogo.repuesto_1_catalogo.repuesto],
[cat_catalogo.repuesto_1].[garantiaDias] as [cat_catalogo.repuesto_1_garantiaDias],
[cat_catalogo.repuesto_1].[garantiaHoras] as [cat_catalogo.repuesto_1_garantiaHoras],
[cat_catalogo.repuesto_1].[vigente] as [cat_catalogo.repuesto_1_vigente],
[cat_catalogo.repuesto_1].[id_marca] as [cat_catalogo.repuesto_1_id_marca],
[cat_catalogo.repuesto_1].[peso] as [cat_catalogo.repuesto_1_peso],
[cat_catalogo.repuesto_1].[cmm] as [cat_catalogo.repuesto_1_cmm],
		[cat_catalogo_repuesto_1].[catalogo_codigo] AS [cat_catalogo_repuesto_1_catalogo_codigo],
		[cat_catalogo_repuesto_1].[codigoInventario] AS [cat_catalogo_repuesto_1_codigoInventario],
		[cat_catalogo_repuesto_1].[precioVenta] AS [cat_catalogo_repuesto_1_precioVenta],
		[cat_catalogo_repuesto_1].[tiempoConsecucion] AS [cat_catalogo_repuesto_1_tiempoConsecucion],
		[cat_catalogo_repuesto_1].[esNacional] AS [cat_catalogo_repuesto_1_esNacional],
		[cat_catalogo_repuesto_1].[id_familia] AS [cat_catalogo_repuesto_1_id_familia],
		[cat_catalogo_repuesto_1].[id_subtipoCatalogo] AS [cat_catalogo_repuesto_1_id_subtipoCatalogo],
		[cat_catalogo_repuesto_1].[id_unidad] AS [cat_catalogo_repuesto_1_id_unidad],
		[cat_catalogo_repuesto_1].[id_impuesto] AS [cat_catalogo_repuesto_1_id_impuesto],
		[cat_catalogo_repuesto_1].[descripcion] AS [cat_catalogo_repuesto_1_descripcion],
		[cat_catalogo_repuesto_1].[bloquearCostear] AS [cat_catalogo_repuesto_1_bloquearCostear],
		[cat_catalogo_repuesto_1].[cmm] AS [cat_catalogo_repuesto_1_cmm],
		[cat_reemplazo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_reemplazo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_reemplazo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_reemplazo].[id_usuario_creo]
	INNER JOIN [cat_tipoReemplazo] ON [cat_tipoReemplazo].id=[cat_reemplazo].[id_tipoReemplazo]
	INNER JOIN [cat_catalogo.repuesto] ON [cat_catalogo.repuesto].id=[cat_reemplazo].[id_catalogo.repuesto]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_repuesto] ON [cat_catalogo.repuesto].id = [cat_catalogo_repuesto].id
	INNER JOIN [cat_catalogo.repuesto] AS [cat_catalogo.repuesto_1] ON [cat_catalogo.repuesto_1].id=[cat_reemplazo].[id_catalogo.repuesto_1]
	INNER JOIN [cat_catalogo] aS  [cat_catalogo_repuesto_1] ON [cat_catalogo.repuesto_1].id = [cat_catalogo_repuesto_1].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_reemplazo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_reemplazo].active=1
GO
