IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_reemplazo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_reemplazo]
GO
CREATE PROCEDURE [ins_cat_reemplazo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_reemplazo varchar(300),
		@p_reemplazo_codigo varchar(100),
		@p_id_tipoReemplazo int,
		@p_id_catalogo_repuesto int,
		@p_id_catalogo_repuesto_1 int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_reemplazo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[reemplazo],
			[reemplazo_codigo],
			[id_tipoReemplazo],
			[id_catalogo.repuesto],
			[id_catalogo.repuesto_1],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_reemplazo,
			@p_reemplazo_codigo,
			@p_id_tipoReemplazo,
			@p_id_catalogo_repuesto,
			@p_id_catalogo_repuesto_1,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_reemplazo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
