	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_reemplazo].id as id_tabla,
	[cat_reemplazo].id_usuario_modifico as id_usuario_modifico,
	[cat_reemplazo].id_usuario_creo as id_usuario_creo,
	[cat_reemplazo].fechaModificacion as fechaModificacion,
	[cat_reemplazo].fechaCreacion as fechaCreacion,
	[cat_reemplazo].active as active,
	[cat_reemplazo].[reemplazo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_reemplazo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_reemplazo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_reemplazo].[id_usuario_creo]
	where ' + @p_filtro)
END
