GO
CREATE  VIEW [view_cat_reemplazo_catalogo_equipo] AS
SELECT 	[cat_reemplazo_catalogo.equipo].[id] AS [id],
		[cat_reemplazo_catalogo.equipo].[uid] AS [uid],
		[cat_reemplazo_catalogo.equipo].[eid] AS [eid],
		[cat_reemplazo_catalogo.equipo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_reemplazo_catalogo.equipo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_reemplazo_catalogo.equipo].[fechaModificacion] AS [fechaModificacion],
		[cat_reemplazo_catalogo.equipo].[fechaCreacion] AS [fechaCreacion],
		[cat_reemplazo_catalogo.equipo].[active] AS [active],
		[cat_reemplazo_catalogo.equipo].[reemplazo_catalogo.equipo] AS [reemplazo_catalogo.equipo],
		[cat_reemplazo_catalogo.equipo].[id_reemplazo] AS [id_reemplazo],
[cat_reemplazo].[reemplazo] as [cat_reemplazo_reemplazo],
[cat_reemplazo].[reemplazo_codigo] as [cat_reemplazo_reemplazo_codigo],
[cat_reemplazo].[id_tipoReemplazo] as [cat_reemplazo_id_tipoReemplazo],
[cat_reemplazo].[id_catalogo.repuesto] as [cat_reemplazo_id_catalogo.repuesto],
[cat_reemplazo].[id_catalogo.repuesto_1] as [cat_reemplazo_id_catalogo.repuesto_1],
[cat_reemplazo].[cmm] as [cat_reemplazo_cmm],
		[cat_reemplazo_catalogo.equipo].[id_versionEquipo] AS [id_versionEquipo],
[cat_versionEquipo].[versionEquipo] as [cat_versionEquipo_versionEquipo],
[cat_versionEquipo].[versionEquipo_codigo] as [cat_versionEquipo_versionEquipo_codigo],
[cat_versionEquipo].[id_catalogo.equipo] as [cat_versionEquipo_id_catalogo.equipo],
[cat_versionEquipo].[cmm] as [cat_versionEquipo_cmm],
		[cat_reemplazo_catalogo.equipo].[id_catalogo.equipo] AS [id_catalogo.equipo],
[cat_catalogo.equipo].[catalogo.equipo] as [cat_catalogo.equipo_catalogo.equipo],
[cat_catalogo.equipo].[garantiaMeses] as [cat_catalogo.equipo_garantiaMeses],
[cat_catalogo.equipo].[garantiaHoras] as [cat_catalogo.equipo_garantiaHoras],
[cat_catalogo.equipo].[manejaHorometro] as [cat_catalogo.equipo_manejaHorometro],
[cat_catalogo.equipo].[id_marca] as [cat_catalogo.equipo_id_marca],
[cat_catalogo.equipo].[cmm] as [cat_catalogo.equipo_cmm],
		[cat_catalogo_equipo].[catalogo_codigo] AS [cat_catalogo_equipo_catalogo_codigo],
		[cat_catalogo_equipo].[codigoInventario] AS [cat_catalogo_equipo_codigoInventario],
		[cat_catalogo_equipo].[precioVenta] AS [cat_catalogo_equipo_precioVenta],
		[cat_catalogo_equipo].[tiempoConsecucion] AS [cat_catalogo_equipo_tiempoConsecucion],
		[cat_catalogo_equipo].[esNacional] AS [cat_catalogo_equipo_esNacional],
		[cat_catalogo_equipo].[id_familia] AS [cat_catalogo_equipo_id_familia],
		[cat_catalogo_equipo].[id_subtipoCatalogo] AS [cat_catalogo_equipo_id_subtipoCatalogo],
		[cat_catalogo_equipo].[id_unidad] AS [cat_catalogo_equipo_id_unidad],
		[cat_catalogo_equipo].[id_impuesto] AS [cat_catalogo_equipo_id_impuesto],
		[cat_catalogo_equipo].[descripcion] AS [cat_catalogo_equipo_descripcion],
		[cat_catalogo_equipo].[bloquearCostear] AS [cat_catalogo_equipo_bloquearCostear],
		[cat_catalogo_equipo].[cmm] AS [cat_catalogo_equipo_cmm],
		[cat_reemplazo_catalogo.equipo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_reemplazo_catalogo.equipo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_reemplazo_catalogo.equipo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_reemplazo_catalogo.equipo].[id_usuario_creo]
	INNER JOIN [cat_reemplazo] ON [cat_reemplazo].id=[cat_reemplazo_catalogo.equipo].[id_reemplazo]
	INNER JOIN [cat_versionEquipo] ON [cat_versionEquipo].id=[cat_reemplazo_catalogo.equipo].[id_versionEquipo]
	INNER JOIN [cat_catalogo.equipo] ON [cat_catalogo.equipo].id=[cat_reemplazo_catalogo.equipo].[id_catalogo.equipo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_equipo] ON [cat_catalogo.equipo].id = [cat_catalogo_equipo].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_reemplazo_catalogo.equipo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
