GO
CREATE PROCEDURE [ins_cat_reemplazo_catalogo_equipo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_reemplazo_catalogo_equipo varchar(300),
		@p_id_reemplazo int,
		@p_id_versionEquipo int,
		@p_id_catalogo_equipo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_reemplazo_catalogo.equipo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[reemplazo_catalogo.equipo],
			[id_reemplazo],
			[id_versionEquipo],
			[id_catalogo.equipo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_reemplazo_catalogo_equipo,
			@p_id_reemplazo,
			@p_id_versionEquipo,
			@p_id_catalogo_equipo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_reemplazo_catalogo.equipo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
