IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_sistema]')) DROP VIEW [dbo].[view_cat_sistema]
GO
CREATE  VIEW [view_cat_sistema] AS
SELECT 	[cat_sistema].[id] AS [id],
		[cat_sistema].[uid] AS [uid],
		[cat_sistema].[eid] AS [eid],
		[cat_sistema].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_sistema].[id_usuario_creo] AS [id_usuario_creo],
		[cat_sistema].[fechaModificacion] AS [fechaModificacion],
		[cat_sistema].[fechaCreacion] AS [fechaCreacion],
		[cat_sistema].[active] AS [active],
		[cat_sistema].[sistema] AS [sistema],
		[cat_sistema].[sistema_codigo] AS [sistema_codigo],
		[cat_sistema].[id_sistema] AS [id_sistema],
[cat_sistema_padre].[sistema] as [cat_sistema_padre_sistema],
[cat_sistema_padre].[sistema_codigo] as [cat_sistema_padre_sistema_codigo],
[cat_sistema_padre].[id_sistema] as [cat_sistema_padre_id_sistema],
[cat_sistema_padre].[cmm] as [cat_sistema_padre_cmm],
		[cat_sistema].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_sistema]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_sistema].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_sistema].[id_usuario_creo]
	INNER JOIN [cat_sistema] AS [cat_sistema_padre] ON [cat_sistema_padre].id=[cat_sistema].[id_sistema]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_sistema].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_sistema].active=1
GO
