IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_sistema]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_sistema]
GO
CREATE PROCEDURE [ins_cat_sistema]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_sistema varchar(300),
		@p_sistema_codigo varchar(100),
		@p_id_sistema int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_sistema]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[sistema],
			[sistema_codigo],
			[id_sistema],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_sistema,
			@p_sistema_codigo,
			@p_id_sistema,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_sistema] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
