IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_soporteActividad]')) DROP VIEW [dbo].[view_cat_soporteActividad]
GO
CREATE  VIEW [view_cat_soporteActividad] AS
SELECT 	[cat_soporteActividad].[id] AS [id],
		[cat_soporteActividad].[uid] AS [uid],
		[cat_soporteActividad].[eid] AS [eid],
		[cat_soporteActividad].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_soporteActividad].[id_usuario_creo] AS [id_usuario_creo],
		[cat_soporteActividad].[fechaModificacion] AS [fechaModificacion],
		[cat_soporteActividad].[fechaCreacion] AS [fechaCreacion],
		[cat_soporteActividad].[active] AS [active],
		[cat_soporteActividad].[soporteActividad] AS [soporteActividad],
		[cat_soporteActividad].[soporteActividad_codigo] AS [soporteActividad_codigo],
		[cat_soporteActividad].[duracion] AS [duracion],
		[cat_soporteActividad].[id_detalleTempario] AS [id_detalleTempario],
[cat_detalleTempario].[detalleTempario] as [cat_detalleTempario_detalleTempario],
[cat_detalleTempario].[detalleTempario_codigo] as [cat_detalleTempario_detalleTempario_codigo],
[cat_detalleTempario].[cantidadEstandar] as [cat_detalleTempario_cantidadEstandar],
[cat_detalleTempario].[orden] as [cat_detalleTempario_orden],
[cat_detalleTempario].[cantidadTropicalizada] as [cat_detalleTempario_cantidadTropicalizada],
[cat_detalleTempario].[id_catalogo] as [cat_detalleTempario_id_catalogo],
[cat_detalleTempario].[id_catalogo.tempario] as [cat_detalleTempario_id_catalogo.tempario],
[cat_detalleTempario].[id_pruebaCheckList] as [cat_detalleTempario_id_pruebaCheckList],
[cat_detalleTempario].[id_sistema] as [cat_detalleTempario_id_sistema],
[cat_detalleTempario].[id_detalleTempario_padre] as [cat_detalleTempario_id_detalleTempario_padre],
[cat_detalleTempario].[cmm] as [cat_detalleTempario_cmm],
		[cat_soporteActividad].[id_cargo] AS [id_cargo],
[seg_cargo].[cargo] as [seg_cargo_cargo],
[seg_cargo].[cargo_codigo] as [seg_cargo_cargo_codigo],
[seg_cargo].[esTecnico] as [seg_cargo_esTecnico],
[seg_cargo].[esComercial] as [seg_cargo_esComercial],
[seg_cargo].[esCoordinador] as [seg_cargo_esCoordinador],
[seg_cargo].[valorHora] as [seg_cargo_valorHora],
[seg_cargo].[esAdministrativo] as [seg_cargo_esAdministrativo],
[seg_cargo].[cmm] as [seg_cargo_cmm],
		[cat_soporteActividad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_soporteActividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_soporteActividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_soporteActividad].[id_usuario_creo]
	INNER JOIN [cat_detalleTempario] ON [cat_detalleTempario].id=[cat_soporteActividad].[id_detalleTempario]
	INNER JOIN [seg_cargo] ON [seg_cargo].id=[cat_soporteActividad].[id_cargo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_soporteActividad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_soporteActividad].active=1
GO
