IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_subtipoCatalogo]')) DROP VIEW [dbo].[view_cat_subtipoCatalogo]
GO
CREATE  VIEW [view_cat_subtipoCatalogo] AS
SELECT 	[cat_subtipoCatalogo].[id] AS [id],
		[cat_subtipoCatalogo].[uid] AS [uid],
		[cat_subtipoCatalogo].[eid] AS [eid],
		[cat_subtipoCatalogo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_subtipoCatalogo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_subtipoCatalogo].[fechaModificacion] AS [fechaModificacion],
		[cat_subtipoCatalogo].[fechaCreacion] AS [fechaCreacion],
		[cat_subtipoCatalogo].[active] AS [active],
		[cat_subtipoCatalogo].[subtipoCatalogo] AS [subtipoCatalogo],
		[cat_subtipoCatalogo].[subtipoCatalogo_codigo] AS [subtipoCatalogo_codigo],
		[cat_subtipoCatalogo].[id_tipoCatalogo] AS [id_tipoCatalogo],
[cat_tipoCatalogo].[tipoCatalogo] as [cat_tipoCatalogo_tipoCatalogo],
[cat_tipoCatalogo].[tipoCatalogo_codigo] as [cat_tipoCatalogo_tipoCatalogo_codigo],
[cat_tipoCatalogo].[afectaInventario] as [cat_tipoCatalogo_afectaInventario],
[cat_tipoCatalogo].[afectaProduccion] as [cat_tipoCatalogo_afectaProduccion],
[cat_tipoCatalogo].[cmm] as [cat_tipoCatalogo_cmm],
		[cat_subtipoCatalogo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_subtipoCatalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_subtipoCatalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_subtipoCatalogo].[id_usuario_creo]
	INNER JOIN [cat_tipoCatalogo] ON [cat_tipoCatalogo].id=[cat_subtipoCatalogo].[id_tipoCatalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_subtipoCatalogo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_subtipoCatalogo].active=1
GO
