GO
CREATE  VIEW [view_cat_tarifa] AS
SELECT 	[cat_tarifa].[id] AS [id],
		[cat_tarifa].[uid] AS [uid],
		[cat_tarifa].[eid] AS [eid],
		[cat_tarifa].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_tarifa].[id_usuario_creo] AS [id_usuario_creo],
		[cat_tarifa].[fechaModificacion] AS [fechaModificacion],
		[cat_tarifa].[fechaCreacion] AS [fechaCreacion],
		[cat_tarifa].[active] AS [active],
		[cat_tarifa].[tarifa] AS [tarifa],
		[cat_tarifa].[tarifa_codigo] AS [tarifa_codigo],
		[cat_tarifa].[incluyeRepuestos] AS [incluyeRepuestos],
		[cat_tarifa].[externo] AS [externo],
		[cat_tarifa].[taller] AS [taller],
		[cat_tarifa].[precio] AS [precio],
		[cat_tarifa].[valorPorUnidad] AS [valorPorUnidad],
		[cat_tarifa].[minimo] AS [minimo],
		[cat_tarifa].[estrategia] AS [estrategia],
		[cat_tarifa].[prioridad] AS [prioridad],
		[cat_tarifa].[id_marca] AS [id_marca],
[cat_marca].[marca] as [cat_marca_marca],
[cat_marca].[marca_codigo] as [cat_marca_marca_codigo],
[cat_marca].[id_tercero_fabricante] as [cat_marca_id_tercero_fabricante],
[cat_marca].[cmm] as [cat_marca_cmm],
		[cat_tarifa].[id_cargo] AS [id_cargo],
[seg_cargo].[cargo] as [seg_cargo_cargo],
[seg_cargo].[cargo_codigo] as [seg_cargo_cargo_codigo],
[seg_cargo].[esTecnico] as [seg_cargo_esTecnico],
[seg_cargo].[esComercial] as [seg_cargo_esComercial],
[seg_cargo].[esCoordinador] as [seg_cargo_esCoordinador],
[seg_cargo].[valorHora] as [seg_cargo_valorHora],
[seg_cargo].[esAdministrativo] as [seg_cargo_esAdministrativo],
[seg_cargo].[cmm] as [seg_cargo_cmm],
		[cat_tarifa].[id_tipoServicio] AS [id_tipoServicio],
[gen_tipoServicio].[tipoServicio] as [gen_tipoServicio_tipoServicio],
[gen_tipoServicio].[tipoServicio_codigo] as [gen_tipoServicio_tipoServicio_codigo],
[gen_tipoServicio].[tieneGarantia] as [gen_tipoServicio_tieneGarantia],
[gen_tipoServicio].[diasGarantia] as [gen_tipoServicio_diasGarantia],
[gen_tipoServicio].[cmm] as [gen_tipoServicio_cmm],
		[cat_tarifa].[id_familia] AS [id_familia],
[gen_familia].[familia] as [gen_familia_familia],
[gen_familia].[familia_codigo] as [gen_familia_familia_codigo],
[gen_familia].[id_familia] as [gen_familia_id_familia],
[gen_familia].[cmm] as [gen_familia_cmm],
		[cat_tarifa].[id_atributo] AS [id_atributo],
[cat_atributo].[atributo] as [cat_atributo_atributo],
[cat_atributo].[atributo_codigo] as [cat_atributo_atributo_codigo],
[cat_atributo].[id_unidad] as [cat_atributo_id_unidad],
[cat_atributo].[cmm] as [cat_atributo_cmm],
		[cat_tarifa].[id_zona] AS [id_zona],
[gen_zona].[zona] as [gen_zona_zona],
[gen_zona].[zona_codigo] as [gen_zona_zona_codigo],
[gen_zona].[tiempoDesplazamiento] as [gen_zona_tiempoDesplazamiento],
[gen_zona].[nivel] as [gen_zona_nivel],
[gen_zona].[id_zona] as [gen_zona_id_zona],
[gen_zona].[codigoExterno] as [gen_zona_codigoExterno],
[gen_zona].[cmm] as [gen_zona_cmm],
		[cat_tarifa].[id_catalogo.equipo] AS [id_catalogo.equipo],
[cat_catalogo.equipo].[catalogo.equipo] as [cat_catalogo.equipo_catalogo.equipo],
[cat_catalogo.equipo].[garantiaMeses] as [cat_catalogo.equipo_garantiaMeses],
[cat_catalogo.equipo].[garantiaHoras] as [cat_catalogo.equipo_garantiaHoras],
[cat_catalogo.equipo].[manejaHorometro] as [cat_catalogo.equipo_manejaHorometro],
[cat_catalogo.equipo].[id_marca] as [cat_catalogo.equipo_id_marca],
[cat_catalogo.equipo].[cmm] as [cat_catalogo.equipo_cmm],
		[cat_catalogo_equipo].[catalogo_codigo] AS [cat_catalogo_equipo_catalogo_codigo],
		[cat_catalogo_equipo].[codigoInventario] AS [cat_catalogo_equipo_codigoInventario],
		[cat_catalogo_equipo].[precioVenta] AS [cat_catalogo_equipo_precioVenta],
		[cat_catalogo_equipo].[tiempoConsecucion] AS [cat_catalogo_equipo_tiempoConsecucion],
		[cat_catalogo_equipo].[esNacional] AS [cat_catalogo_equipo_esNacional],
		[cat_catalogo_equipo].[id_familia] AS [cat_catalogo_equipo_id_familia],
		[cat_catalogo_equipo].[id_subtipoCatalogo] AS [cat_catalogo_equipo_id_subtipoCatalogo],
		[cat_catalogo_equipo].[id_unidad] AS [cat_catalogo_equipo_id_unidad],
		[cat_catalogo_equipo].[id_impuesto] AS [cat_catalogo_equipo_id_impuesto],
		[cat_catalogo_equipo].[descripcion] AS [cat_catalogo_equipo_descripcion],
		[cat_catalogo_equipo].[bloquearCostear] AS [cat_catalogo_equipo_bloquearCostear],
		[cat_catalogo_equipo].[cmm] AS [cat_catalogo_equipo_cmm],
		[cat_tarifa].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_tarifa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_tarifa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_tarifa].[id_usuario_creo]
	INNER JOIN [cat_marca] ON [cat_marca].id=[cat_tarifa].[id_marca]
	INNER JOIN [seg_cargo] ON [seg_cargo].id=[cat_tarifa].[id_cargo]
	INNER JOIN [gen_tipoServicio] ON [gen_tipoServicio].id=[cat_tarifa].[id_tipoServicio]
	INNER JOIN [gen_familia] ON [gen_familia].id=[cat_tarifa].[id_familia]
	INNER JOIN [cat_atributo] ON [cat_atributo].id=[cat_tarifa].[id_atributo]
	INNER JOIN [gen_zona] ON [gen_zona].id=[cat_tarifa].[id_zona]
	INNER JOIN [cat_catalogo.equipo] ON [cat_catalogo.equipo].id=[cat_tarifa].[id_catalogo.equipo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_equipo] ON [cat_catalogo.equipo].id = [cat_catalogo_equipo].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_tarifa].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_tarifa].active=1
GO
