GO
CREATE PROCEDURE [upd_cat_tarifa]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_tarifa varchar(300) = null,
		@p_tarifa_codigo varchar(100) = null,
		@p_incluyeRepuestos bit = null,
		@p_externo bit = null,
		@p_taller bit = null,
		@p_precio money = null,
		@p_valorPorUnidad bit = null,
		@p_minimo float = null,
		@p_estrategia int = null,
		@p_prioridad int = null,
		@p_id_marca int = null,
		@p_id_cargo int = null,
		@p_id_tipoServicio int = null,
		@p_id_familia int = null,
		@p_id_atributo int = null,
		@p_id_zona int = null,
		@p_id_catalogo_equipo int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_tarifa]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tarifa] = isnull(@p_tarifa,[tarifa]),
			[tarifa_codigo] = isnull(@p_tarifa_codigo,[tarifa_codigo]),
			[incluyeRepuestos] = isnull(@p_incluyeRepuestos,[incluyeRepuestos]),
			[externo] = isnull(@p_externo,[externo]),
			[taller] = isnull(@p_taller,[taller]),
			[precio] = isnull(@p_precio,[precio]),
			[valorPorUnidad] = isnull(@p_valorPorUnidad,[valorPorUnidad]),
			[minimo] = isnull(@p_minimo,[minimo]),
			[estrategia] = isnull(@p_estrategia,[estrategia]),
			[prioridad] = isnull(@p_prioridad,[prioridad]),
			[id_marca] = isnull(@p_id_marca,[id_marca]),
			[id_cargo] = isnull(@p_id_cargo,[id_cargo]),
			[id_tipoServicio] = isnull(@p_id_tipoServicio,[id_tipoServicio]),
			[id_familia] = isnull(@p_id_familia,[id_familia]),
			[id_atributo] = isnull(@p_id_atributo,[id_atributo]),
			[id_zona] = isnull(@p_id_zona,[id_zona]),
			[id_catalogo.equipo] = isnull(@p_id_catalogo_equipo,[id_catalogo.equipo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
