IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_tarifa]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_tarifa]
GO
CREATE PROCEDURE [ins_cat_tarifa]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tarifa varchar(300),
		@p_tarifa_codigo varchar(100),
		@p_incluyeRepuestos bit,
		@p_externo bit,
		@p_taller bit,
		@p_precio money,
		@p_valorPorUnidad bit,
		@p_minimo float,
		@p_estrategia int,
		@p_prioridad int,
		@p_id_marca int,
		@p_id_cargo int,
		@p_id_tipoServicio int,
		@p_id_familia int,
		@p_id_atributo int,
		@p_id_zona int,
		@p_id_catalogo_equipo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_tarifa]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tarifa],
			[tarifa_codigo],
			[incluyeRepuestos],
			[externo],
			[taller],
			[precio],
			[valorPorUnidad],
			[minimo],
			[estrategia],
			[prioridad],
			[id_marca],
			[id_cargo],
			[id_tipoServicio],
			[id_familia],
			[id_atributo],
			[id_zona],
			[id_catalogo.equipo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tarifa,
			@p_tarifa_codigo,
			@p_incluyeRepuestos,
			@p_externo,
			@p_taller,
			@p_precio,
			@p_valorPorUnidad,
			@p_minimo,
			@p_estrategia,
			@p_prioridad,
			@p_id_marca,
			@p_id_cargo,
			@p_id_tipoServicio,
			@p_id_familia,
			@p_id_atributo,
			@p_id_zona,
			@p_id_catalogo_equipo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_tarifa] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
