[cat_catalogo_elemento].[esNacional] as [cat_catalogo_elemento_esNacional],
[cat_catalogo_elemento].[id_familia] as [cat_catalogo_elemento_id_familia],
[cat_catalogo_elemento].[id_subtipoCatalogo] as [cat_catalogo_elemento_id_subtipoCatalogo],
[cat_catalogo_elemento].[id_unidad] as [cat_catalogo_elemento_id_unidad],
[cat_catalogo_elemento].[id_impuesto] as [cat_catalogo_elemento_id_impuesto],
[cat_catalogo_elemento].[descripcion] as [cat_catalogo_elemento_descripcion],
[cat_catalogo_elemento].[bloquearCostear] as [cat_catalogo_elemento_bloquearCostear],
[cat_catalogo_elemento].[cmm] as [cat_catalogo_elemento_cmm],
		[cat_tarifaCatalogo].[id_tipotarifa] AS [id_tipotarifa],
[alq_tipoTarifa].[tipoTarifa] as [alq_tipoTarifa_tipoTarifa],
[alq_tipoTarifa].[tipoTarifa_codigo] as [alq_tipoTarifa_tipoTarifa_codigo],
[alq_tipoTarifa].[valor] as [alq_tipoTarifa_valor],
[alq_tipoTarifa].[cmm] as [alq_tipoTarifa_cmm],
		[cat_tarifaCatalogo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_tarifaCatalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_tarifaCatalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_tarifaCatalogo].[id_usuario_creo]
	INNER JOIN [cat_catalogo] AS [cat_catalogo_tarifa] ON [cat_catalogo_tarifa].id=[cat_tarifaCatalogo].[id_catalogo_tarifa]
	INNER JOIN [cat_catalogo] AS [cat_catalogo_elemento] ON [cat_catalogo_elemento].id=[cat_tarifaCatalogo].[id_catalogo_elemento]
	INNER JOIN [alq_tipoTarifa] ON [alq_tipoTarifa].id=[cat_tarifaCatalogo].[id_tipotarifa]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_tarifaCatalogo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_tarifaCatalogo].active=1
GO
