GO
CREATE PROCEDURE [upd_cat_tarifaCatalogo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_tarifaCatalogo varchar(300) = null,
		@p_tarifaCatalogo_codigo varchar(100) = null,
		@p_id_catalogo_tarifa int = null,
		@p_id_catalogo_elemento int = null,
		@p_id_tipotarifa int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_tarifaCatalogo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tarifaCatalogo] = isnull(@p_tarifaCatalogo,[tarifaCatalogo]),
			[tarifaCatalogo_codigo] = isnull(@p_tarifaCatalogo_codigo,[tarifaCatalogo_codigo]),
			[id_catalogo_tarifa] = isnull(@p_id_catalogo_tarifa,[id_catalogo_tarifa]),
			[id_catalogo_elemento] = isnull(@p_id_catalogo_elemento,[id_catalogo_elemento]),
			[id_tipotarifa] = isnull(@p_id_tipotarifa,[id_tipotarifa]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
