IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_tarifaCatalogo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_tarifaCatalogo]
GO
CREATE PROCEDURE [ins_cat_tarifaCatalogo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tarifaCatalogo varchar(300),
		@p_tarifaCatalogo_codigo varchar(100),
		@p_id_catalogo_tarifa int,
		@p_id_catalogo_elemento int,
		@p_id_tipotarifa int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_tarifaCatalogo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tarifaCatalogo],
			[tarifaCatalogo_codigo],
			[id_catalogo_tarifa],
			[id_catalogo_elemento],
			[id_tipotarifa],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tarifaCatalogo,
			@p_tarifaCatalogo_codigo,
			@p_id_catalogo_tarifa,
			@p_id_catalogo_elemento,
			@p_id_tipotarifa,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_tarifaCatalogo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
