CREATE PROCEDURE [aud_cat_tarifaCatalogo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cat_tarifaCatalogo].id as id_tabla,
	[cat_tarifaCatalogo].id_usuario_modifico as id_usuario_modifico,
	[cat_tarifaCatalogo].id_usuario_creo as id_usuario_creo,
	[cat_tarifaCatalogo].fechaModificacion as fechaModificacion,
	[cat_tarifaCatalogo].fechaCreacion as fechaCreacion,
	[cat_tarifaCatalogo].active as active,
	[cat_tarifaCatalogo].[tarifaCatalogo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cat_tarifaCatalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_tarifaCatalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_tarifaCatalogo].[id_usuario_creo]
	where ' + @p_filtro)
END
