[cat_tarifa].[prioridad] as [cat_tarifa_prioridad],
[cat_tarifa].[id_marca] as [cat_tarifa_id_marca],
[cat_tarifa].[id_cargo] as [cat_tarifa_id_cargo],
[cat_tarifa].[id_tipoServicio] as [cat_tarifa_id_tipoServicio],
[cat_tarifa].[id_familia] as [cat_tarifa_id_familia],
[cat_tarifa].[id_atributo] as [cat_tarifa_id_atributo],
[cat_tarifa].[id_zona] as [cat_tarifa_id_zona],
[cat_tarifa].[id_catalogo.equipo] as [cat_tarifa_id_catalogo.equipo],
[cat_tarifa].[cmm] as [cat_tarifa_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_tarifaRango]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_tarifaRango].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_tarifaRango].[id_usuario_creo]
	INNER JOIN [cat_tarifa] ON [cat_tarifa].id=[cat_tarifaRango].[id_tarifa]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_tarifaRango].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_tarifaRango].active=1
