CREATE PROCEDURE [upd_cat_tarifaRango]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_tarifaRango varchar(300) = null,
		@p_tarifaRango_codigo varchar(100) = null,
		@p_rangoInicio float = null,
		@p_rangoFin float = null,
		@p_precio float = null,
		@p_id_tarifa int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cat_tarifaRango]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tarifaRango] = isnull(@p_tarifaRango,[tarifaRango]),
			[tarifaRango_codigo] = isnull(@p_tarifaRango_codigo,[tarifaRango_codigo]),
			[rangoInicio] = isnull(@p_rangoInicio,[rangoInicio]),
			[rangoFin] = isnull(@p_rangoFin,[rangoFin]),
			[precio] = isnull(@p_precio,[precio]),
			[id_tarifa] = isnull(@p_id_tarifa,[id_tarifa]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
