IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cat_tarifaRango]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cat_tarifaRango]
GO
CREATE PROCEDURE [ins_cat_tarifaRango]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tarifaRango varchar(300),
		@p_tarifaRango_codigo varchar(100),
		@p_rangoInicio float,
		@p_rangoFin float,
		@p_precio float,
		@p_id_tarifa int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_tarifaRango]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tarifaRango],
			[tarifaRango_codigo],
			[rangoInicio],
			[rangoFin],
			[precio],
			[id_tarifa],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tarifaRango,
			@p_tarifaRango_codigo,
			@p_rangoInicio,
			@p_rangoFin,
			@p_precio,
			@p_id_tarifa,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_tarifaRango] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
