CREATE  VIEW [view_cat_tipoCatalogo] AS
SELECT 	[cat_tipoCatalogo].[id] AS [id],
		[cat_tipoCatalogo].[uid] AS [uid],
		[cat_tipoCatalogo].[eid] AS [eid],
		[cat_tipoCatalogo].[id_usuario_modifico] AS [id_usuario_modifico],
