		[cat_tipoCatalogo].[fechaCreacion] AS [fechaCreacion],
		[cat_tipoCatalogo].[active] AS [active],
		[cat_tipoCatalogo].[tipoCatalogo] AS [tipoCatalogo],
		[cat_tipoCatalogo].[tipoCatalogo_codigo] AS [tipoCatalogo_codigo],
		[cat_tipoCatalogo].[afectaInventario] AS [afectaInventario],
		[cat_tipoCatalogo].[afectaProduccion] AS [afectaProduccion],
		[cat_tipoCatalogo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_tipoCatalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_tipoCatalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_tipoCatalogo].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_tipoCatalogo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_tipoCatalogo].active=1
