CREATE PROCEDURE [ins_cat_tipoCatalogo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoCatalogo varchar(300),
		@p_tipoCatalogo_codigo varchar(100),
		@p_afectaInventario bit,
		@p_afectaProduccion bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_tipoCatalogo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoCatalogo],
			[tipoCatalogo_codigo],
			[afectaInventario],
			[afectaProduccion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoCatalogo,
			@p_tipoCatalogo_codigo,
			@p_afectaInventario,
			@p_afectaProduccion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_tipoCatalogo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
