GO
CREATE  VIEW [view_cat_tipoCatalogo_listaPrecio] AS
SELECT 	[cat_tipoCatalogo_listaPrecio].[id] AS [id],
		[cat_tipoCatalogo_listaPrecio].[uid] AS [uid],
		[cat_tipoCatalogo_listaPrecio].[eid] AS [eid],
		[cat_tipoCatalogo_listaPrecio].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_tipoCatalogo_listaPrecio].[id_usuario_creo] AS [id_usuario_creo],
		[cat_tipoCatalogo_listaPrecio].[fechaModificacion] AS [fechaModificacion],
		[cat_tipoCatalogo_listaPrecio].[fechaCreacion] AS [fechaCreacion],
		[cat_tipoCatalogo_listaPrecio].[active] AS [active],
		[cat_tipoCatalogo_listaPrecio].[tipoCatalogo_listaPrecio] AS [tipoCatalogo_listaPrecio],
		[cat_tipoCatalogo_listaPrecio].[porcentaje] AS [porcentaje],
		[cat_tipoCatalogo_listaPrecio].[id_tipoCatalogo] AS [id_tipoCatalogo],
[cat_tipoCatalogo].[tipoCatalogo] as [cat_tipoCatalogo_tipoCatalogo],
[cat_tipoCatalogo].[tipoCatalogo_codigo] as [cat_tipoCatalogo_tipoCatalogo_codigo],
[cat_tipoCatalogo].[afectaInventario] as [cat_tipoCatalogo_afectaInventario],
[cat_tipoCatalogo].[afectaProduccion] as [cat_tipoCatalogo_afectaProduccion],
[cat_tipoCatalogo].[cmm] as [cat_tipoCatalogo_cmm],
		[cat_tipoCatalogo_listaPrecio].[id_listaPrecio] AS [id_listaPrecio],
[cat_listaPrecio].[listaPrecio] as [cat_listaPrecio_listaPrecio],
[cat_listaPrecio].[listaPrecio_codigo] as [cat_listaPrecio_listaPrecio_codigo],
[cat_listaPrecio].[porcentajeDescuento] as [cat_listaPrecio_porcentajeDescuento],
[cat_listaPrecio].[esPrivado] as [cat_listaPrecio_esPrivado],
[cat_listaPrecio].[id_moneda] as [cat_listaPrecio_id_moneda],
[cat_listaPrecio].[paraCompra] as [cat_listaPrecio_paraCompra],
[cat_listaPrecio].[cmm] as [cat_listaPrecio_cmm],
		[cat_tipoCatalogo_listaPrecio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_tipoCatalogo_listaPrecio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_tipoCatalogo_listaPrecio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_tipoCatalogo_listaPrecio].[id_usuario_creo]
	INNER JOIN [cat_tipoCatalogo] ON [cat_tipoCatalogo].id=[cat_tipoCatalogo_listaPrecio].[id_tipoCatalogo]
	INNER JOIN [cat_listaPrecio] ON [cat_listaPrecio].id=[cat_tipoCatalogo_listaPrecio].[id_listaPrecio]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_tipoCatalogo_listaPrecio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
