IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cat_tipoReemplazo]')) DROP VIEW [dbo].[view_cat_tipoReemplazo]
GO
CREATE  VIEW [view_cat_tipoReemplazo] AS
SELECT 	[cat_tipoReemplazo].[id] AS [id],
		[cat_tipoReemplazo].[uid] AS [uid],
		[cat_tipoReemplazo].[eid] AS [eid],
		[cat_tipoReemplazo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_tipoReemplazo].[id_usuario_creo] AS [id_usuario_creo],
		[cat_tipoReemplazo].[fechaModificacion] AS [fechaModificacion],
		[cat_tipoReemplazo].[fechaCreacion] AS [fechaCreacion],
		[cat_tipoReemplazo].[active] AS [active],
		[cat_tipoReemplazo].[tipoReemplazo] AS [tipoReemplazo],
		[cat_tipoReemplazo].[tipoReemplazo_codigo] AS [tipoReemplazo_codigo],
		[cat_tipoReemplazo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_tipoReemplazo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_tipoReemplazo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_tipoReemplazo].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_tipoReemplazo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cat_tipoReemplazo].active=1
GO
