GO
CREATE  VIEW [view_cat_versionEquipo_detalleTempario] AS
SELECT 	[cat_versionEquipo_detalleTempario].[id] AS [id],
		[cat_versionEquipo_detalleTempario].[uid] AS [uid],
		[cat_versionEquipo_detalleTempario].[eid] AS [eid],
		[cat_versionEquipo_detalleTempario].[id_usuario_modifico] AS [id_usuario_modifico],
		[cat_versionEquipo_detalleTempario].[id_usuario_creo] AS [id_usuario_creo],
		[cat_versionEquipo_detalleTempario].[fechaModificacion] AS [fechaModificacion],
		[cat_versionEquipo_detalleTempario].[fechaCreacion] AS [fechaCreacion],
		[cat_versionEquipo_detalleTempario].[active] AS [active],
		[cat_versionEquipo_detalleTempario].[versionEquipo_detalleTempario] AS [versionEquipo_detalleTempario],
		[cat_versionEquipo_detalleTempario].[id_detalleTempario] AS [id_detalleTempario],
[cat_detalleTempario].[detalleTempario] as [cat_detalleTempario_detalleTempario],
[cat_detalleTempario].[detalleTempario_codigo] as [cat_detalleTempario_detalleTempario_codigo],
[cat_detalleTempario].[cantidadEstandar] as [cat_detalleTempario_cantidadEstandar],
[cat_detalleTempario].[orden] as [cat_detalleTempario_orden],
[cat_detalleTempario].[cantidadTropicalizada] as [cat_detalleTempario_cantidadTropicalizada],
[cat_detalleTempario].[id_catalogo] as [cat_detalleTempario_id_catalogo],
[cat_detalleTempario].[id_catalogo.tempario] as [cat_detalleTempario_id_catalogo.tempario],
[cat_detalleTempario].[id_pruebaCheckList] as [cat_detalleTempario_id_pruebaCheckList],
[cat_detalleTempario].[id_sistema] as [cat_detalleTempario_id_sistema],
[cat_detalleTempario].[id_detalleTempario_padre] as [cat_detalleTempario_id_detalleTempario_padre],
[cat_detalleTempario].[cmm] as [cat_detalleTempario_cmm],
		[cat_versionEquipo_detalleTempario].[id_versionEquipo] AS [id_versionEquipo],
[cat_versionEquipo].[versionEquipo] as [cat_versionEquipo_versionEquipo],
[cat_versionEquipo].[versionEquipo_codigo] as [cat_versionEquipo_versionEquipo_codigo],
[cat_versionEquipo].[id_catalogo.equipo] as [cat_versionEquipo_id_catalogo.equipo],
[cat_versionEquipo].[cmm] as [cat_versionEquipo_cmm],
		[cat_versionEquipo_detalleTempario].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cat_versionEquipo_detalleTempario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cat_versionEquipo_detalleTempario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cat_versionEquipo_detalleTempario].[id_usuario_creo]
	INNER JOIN [cat_detalleTempario] ON [cat_detalleTempario].id=[cat_versionEquipo_detalleTempario].[id_detalleTempario]
	INNER JOIN [cat_versionEquipo] ON [cat_versionEquipo].id=[cat_versionEquipo_detalleTempario].[id_versionEquipo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cat_versionEquipo_detalleTempario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
