GO
CREATE PROCEDURE [ins_cat_versionEquipo_detalleTempario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_versionEquipo_detalleTempario varchar(300),
		@p_id_detalleTempario int,
		@p_id_versionEquipo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_versionEquipo_detalleTempario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[versionEquipo_detalleTempario],
			[id_detalleTempario],
			[id_versionEquipo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_versionEquipo_detalleTempario,
			@p_id_detalleTempario,
			@p_id_versionEquipo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cat_versionEquipo_detalleTempario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
