	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_configuracionProyeccion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_configuracionProyeccion].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[cnt_configuracionProyeccion].[id_equipo]
	INNER JOIN [gen_tipoServicio] ON [gen_tipoServicio].id=[cnt_configuracionProyeccion].[id_tipoServicio]
	INNER JOIN [doc_subtipoDocumento] ON [doc_subtipoDocumento].id=[cnt_configuracionProyeccion].[id_subtipoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_coordinador] ON [seg_usuario_coordinador].id=[cnt_configuracionProyeccion].[id_usuario_coordinador]
	INNER JOIN [doc_estadoTipoDocumento] AS [doc_estadoTipoDocumento_inicial] ON [doc_estadoTipoDocumento_inicial].id=[cnt_configuracionProyeccion].[id_estadoTipoDocumento_inicial]
	INNER JOIN [doc_subtipoDocumento] AS [doc_subtipoDocumento_padre] ON [doc_subtipoDocumento_padre].id=[cnt_configuracionProyeccion].[id_subtipoDocumento_padre]
	INNER JOIN [doc_estadoTipoDocumento] AS [doc_estadoTipoDocumento_inicial_padre] ON [doc_estadoTipoDocumento_inicial_padre].id=[cnt_configuracionProyeccion].[id_estadoTipoDocumento_inicial_padre]
	INNER JOIN [doc_documento.contrato] ON [doc_documento.contrato].id=[cnt_configuracionProyeccion].[id_documento.contrato]
	INNER JOIN [doc_documento] aS [doc_documento_contrato] ON [doc_documento.contrato].id = [doc_documento_contrato].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cnt_configuracionProyeccion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cnt_configuracionProyeccion].active=1
