			[incluirMenores] = isnull(@p_incluirMenores,[incluirMenores]),
			[aproximarA] = isnull(@p_aproximarA,[aproximarA]),
			[precioVisita] = isnull(@p_precioVisita,[precioVisita]),
			[precioServicio] = isnull(@p_precioServicio,[precioServicio]),
			[promedio] = isnull(@p_promedio,[promedio]),
			[estrategia] = isnull(@p_estrategia,[estrategia]),
