IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cnt_configuracionProyeccion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cnt_configuracionProyeccion]
GO
CREATE PROCEDURE [ins_cnt_configuracionProyeccion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_configuracionProyeccion varchar(300),
		@p_configuracionProyeccion_codigo varchar(100),
		@p_id_equipo int,
		@p_id_documento_contrato int,
		@p_fecha_inicio_ff smalldatetime,
		@p_fecha_fin_ff smalldatetime,
		@p_frecuencia int,
		@p_intervalo int,
		@p_diaHabil int,
		@p_porTrabajo int,
		@p_incluirMenores int,
		@p_aproximarA int,
		@p_precioVisita float,
		@p_precioServicio float,
		@p_promedio float,
		@p_estrategia int,
		@p_id_tipoServicio int,
		@p_id_subtipoDocumento int,
		@p_id_usuario_coordinador int,
		@p_id_estadoTipoDocumento_inicial int,
		@p_id_subtipoDocumento_padre int,
		@p_id_estadoTipoDocumento_inicial_padre int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cnt_configuracionProyeccion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[configuracionProyeccion],
			[configuracionProyeccion_codigo],
			[id_equipo],
			[id_documento.contrato],
			[fecha_inicio_ff],
			[fecha_fin_ff],
			[frecuencia],
			[intervalo],
			[diaHabil],
			[porTrabajo],
			[incluirMenores],
			[aproximarA],
			[precioVisita],
			[precioServicio],
			[promedio],
			[estrategia],
			[id_tipoServicio],
			[id_subtipoDocumento],
			[id_usuario_coordinador],
			[id_estadoTipoDocumento_inicial],
			[id_subtipoDocumento_padre],
			[id_estadoTipoDocumento_inicial_padre],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_configuracionProyeccion,
			@p_configuracionProyeccion_codigo,
			@p_id_equipo,
			@p_id_documento_contrato,
			@p_fecha_inicio_ff,
			@p_fecha_fin_ff,
			@p_frecuencia,
			@p_intervalo,
			@p_diaHabil,
			@p_porTrabajo,
			@p_incluirMenores,
			@p_aproximarA,
			@p_precioVisita,
			@p_precioServicio,
			@p_promedio,
			@p_estrategia,
			@p_id_tipoServicio,
			@p_id_subtipoDocumento,
			@p_id_usuario_coordinador,
			@p_id_estadoTipoDocumento_inicial,
			@p_id_subtipoDocumento_padre,
			@p_id_estadoTipoDocumento_inicial_padre,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cnt_configuracionProyeccion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
