GO
CREATE PROCEDURE [aud_cnt_configuracionProyeccion]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cnt_configuracionProyeccion].id as id_tabla,
	[cnt_configuracionProyeccion].id_usuario_modifico as id_usuario_modifico,
	[cnt_configuracionProyeccion].id_usuario_creo as id_usuario_creo,
	[cnt_configuracionProyeccion].fechaModificacion as fechaModificacion,
	[cnt_configuracionProyeccion].fechaCreacion as fechaCreacion,
	[cnt_configuracionProyeccion].active as active,
	[cnt_configuracionProyeccion].[configuracionProyeccion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cnt_configuracionProyeccion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_configuracionProyeccion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_configuracionProyeccion].[id_usuario_creo]
	where ' + @p_filtro)
END
