IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_cnt_corrimientoVisitaFija]')) DROP VIEW [dbo].[view_cnt_corrimientoVisitaFija]
GO
CREATE  VIEW [view_cnt_corrimientoVisitaFija] AS
SELECT 	[cnt_corrimientoVisitaFija].[id] AS [id],
		[cnt_corrimientoVisitaFija].[uid] AS [uid],
		[cnt_corrimientoVisitaFija].[eid] AS [eid],
		[cnt_corrimientoVisitaFija].[id_usuario_modifico] AS [id_usuario_modifico],
		[cnt_corrimientoVisitaFija].[id_usuario_creo] AS [id_usuario_creo],
		[cnt_corrimientoVisitaFija].[fechaModificacion] AS [fechaModificacion],
		[cnt_corrimientoVisitaFija].[fechaCreacion] AS [fechaCreacion],
		[cnt_corrimientoVisitaFija].[active] AS [active],
		[cnt_corrimientoVisitaFija].[corrimientoVisitaFija] AS [corrimientoVisitaFija],
		[cnt_corrimientoVisitaFija].[corrimientoVisitaFija_codigo] AS [corrimientoVisitaFija_codigo],
		[cnt_corrimientoVisitaFija].[fechaOriginal_ff] AS [fechaOriginal_ff],
		[cnt_corrimientoVisitaFija].[id_visitaFija] AS [id_visitaFija],
[cnt_visitaFija].[visitaFija] as [cnt_visitaFija_visitaFija],
[cnt_visitaFija].[visitaFija_codigo] as [cnt_visitaFija_visitaFija_codigo],
[cnt_visitaFija].[fecha_ff] as [cnt_visitaFija_fecha_ff],
[cnt_visitaFija].[fechaCreada_ff] as [cnt_visitaFija_fechaCreada_ff],
[cnt_visitaFija].[horometro] as [cnt_visitaFija_horometro],
[cnt_visitaFija].[id_documento] as [cnt_visitaFija_id_documento],
[cnt_visitaFija].[id_catalogo.tempario] as [cnt_visitaFija_id_catalogo.tempario],
[cnt_visitaFija].[esPorTrabajo] as [cnt_visitaFija_esPorTrabajo],
[cnt_visitaFija].[correoRecordatorio] as [cnt_visitaFija_correoRecordatorio],
[cnt_visitaFija].[presupuesto] as [cnt_visitaFija_presupuesto],
[cnt_visitaFija].[id_configuracionProyeccion] as [cnt_visitaFija_id_configuracionProyeccion],
[cnt_visitaFija].[cmm] as [cnt_visitaFija_cmm],
		[cnt_corrimientoVisitaFija].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cnt_corrimientoVisitaFija]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_corrimientoVisitaFija].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_corrimientoVisitaFija].[id_usuario_creo]
	INNER JOIN [cnt_visitaFija] ON [cnt_visitaFija].id=[cnt_corrimientoVisitaFija].[id_visitaFija]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cnt_corrimientoVisitaFija].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cnt_corrimientoVisitaFija].active=1
