CREATE PROCEDURE [upd_cnt_corrimientoVisitaFija]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_corrimientoVisitaFija varchar(300) = null,
		@p_corrimientoVisitaFija_codigo varchar(100) = null,
		@p_fechaOriginal_ff smalldatetime = null,
		@p_id_visitaFija int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cnt_corrimientoVisitaFija]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[corrimientoVisitaFija] = isnull(@p_corrimientoVisitaFija,[corrimientoVisitaFija]),
			[corrimientoVisitaFija_codigo] = isnull(@p_corrimientoVisitaFija_codigo,[corrimientoVisitaFija_codigo]),
			[fechaOriginal_ff] = isnull(@p_fechaOriginal_ff,[fechaOriginal_ff]),
			[id_visitaFija] = isnull(@p_id_visitaFija,[id_visitaFija]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
