IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cnt_corrimientoVisitaFija]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cnt_corrimientoVisitaFija]
GO
CREATE PROCEDURE [ins_cnt_corrimientoVisitaFija]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_corrimientoVisitaFija varchar(300),
		@p_corrimientoVisitaFija_codigo varchar(100),
		@p_fechaOriginal_ff smalldatetime,
		@p_id_visitaFija int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cnt_corrimientoVisitaFija]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[corrimientoVisitaFija],
			[corrimientoVisitaFija_codigo],
			[fechaOriginal_ff],
			[id_visitaFija],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_corrimientoVisitaFija,
			@p_corrimientoVisitaFija_codigo,
			@p_fechaOriginal_ff,
			@p_id_visitaFija,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cnt_corrimientoVisitaFija] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
