IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cnt_pagosContrato]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cnt_pagosContrato]
GO
CREATE PROCEDURE [ins_cnt_pagosContrato]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_pagosContrato varchar(300),
		@p_pagosContrato_codigo varchar(100),
		@p_fecha_ff smalldatetime,
		@p_valor money,
		@p_id_documento_contrato int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cnt_pagosContrato]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[pagosContrato],
			[pagosContrato_codigo],
			[fecha_ff],
			[valor],
			[id_documento.contrato],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_pagosContrato,
			@p_pagosContrato_codigo,
			@p_fecha_ff,
			@p_valor,
			@p_id_documento_contrato,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cnt_pagosContrato] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
