CREATE PROCEDURE [aud_cnt_periodoContrato]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cnt_periodoContrato].id as id_tabla,
	[cnt_periodoContrato].id_usuario_modifico as id_usuario_modifico,
	[cnt_periodoContrato].id_usuario_creo as id_usuario_creo,
	[cnt_periodoContrato].fechaModificacion as fechaModificacion,
	[cnt_periodoContrato].fechaCreacion as fechaCreacion,
	[cnt_periodoContrato].active as active,
	[cnt_periodoContrato].[periodoContrato] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cnt_periodoContrato]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_periodoContrato].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_periodoContrato].[id_usuario_creo]
	where ' + @p_filtro)
END
