		[cnt_tiempoRespuesta].[id_documento.contrato] AS [id_documento.contrato],
[doc_documento.contrato].[documento.contrato] as [doc_documento.contrato_documento.contrato],
[doc_documento.contrato].[numero] as [doc_documento.contrato_numero],
[doc_documento.contrato].[totalContrato] as [doc_documento.contrato_totalContrato],
[doc_documento.contrato].[presupuesto] as [doc_documento.contrato_presupuesto],
[doc_documento.contrato].[fechaInicio_ff] as [doc_documento.contrato_fechaInicio_ff],
[doc_documento.contrato].[fechaFin_ff] as [doc_documento.contrato_fechaFin_ff],
[doc_documento.contrato].[diasCumplimiento] as [doc_documento.contrato_diasCumplimiento],
[doc_documento.contrato].[condiciones] as [doc_documento.contrato_condiciones],
[doc_documento.contrato].[id_periodoContrato] as [doc_documento.contrato_id_periodoContrato],
[doc_documento.contrato].[cmm] as [doc_documento.contrato_cmm],
		[doc_documento_contrato].[documento_codigo] AS [doc_documento_contrato_documento_codigo],
		[doc_documento_contrato].[documento_numero] AS [doc_documento_contrato_documento_numero],
		[doc_documento_contrato].[prefijo] AS [doc_documento_contrato_prefijo],
		[doc_documento_contrato].[subtotal] AS [doc_documento_contrato_subtotal],
		[doc_documento_contrato].[descuento] AS [doc_documento_contrato_descuento],
		[doc_documento_contrato].[iva] AS [doc_documento_contrato_iva],
		[doc_documento_contrato].[total] AS [doc_documento_contrato_total],
		[doc_documento_contrato].[costo] AS [doc_documento_contrato_costo],
		[doc_documento_contrato].[rentabilidad] AS [doc_documento_contrato_rentabilidad],
		[doc_documento_contrato].[trm] AS [doc_documento_contrato_trm],
		[doc_documento_contrato].[fecha_fh] AS [doc_documento_contrato_fecha_fh],
		[doc_documento_contrato].[fechaSugerida_fh] AS [doc_documento_contrato_fechaSugerida_fh],
		[doc_documento_contrato].[fechaCierre_ff] AS [doc_documento_contrato_fechaCierre_ff],
		[doc_documento_contrato].[fechaLimite_fh] AS [doc_documento_contrato_fechaLimite_fh],
		[doc_documento_contrato].[id_subtipoDocumento] AS [doc_documento_contrato_id_subtipoDocumento],
		[doc_documento_contrato].[id_tercero_cliente] AS [doc_documento_contrato_id_tercero_cliente],
		[doc_documento_contrato].[id_documento] AS [doc_documento_contrato_id_documento],
		[doc_documento_contrato].[id_tercero_proveedor] AS [doc_documento_contrato_id_tercero_proveedor],
		[doc_documento_contrato].[id_prioridadDocumento] AS [doc_documento_contrato_id_prioridadDocumento],
		[doc_documento_contrato].[id_moneda] AS [doc_documento_contrato_id_moneda],
		[doc_documento_contrato].[id_estadoTipoDocumento] AS [doc_documento_contrato_id_estadoTipoDocumento],
		[doc_documento_contrato].[id_motivoestado] AS [doc_documento_contrato_id_motivoestado],
		[doc_documento_contrato].[subtotalPlaneado] AS [doc_documento_contrato_subtotalPlaneado],
		[doc_documento_contrato].[descuentoPlaneado] AS [doc_documento_contrato_descuentoPlaneado],
		[doc_documento_contrato].[ivaPlaneado] AS [doc_documento_contrato_ivaPlaneado],
		[doc_documento_contrato].[totalPlaneado] AS [doc_documento_contrato_totalPlaneado],
		[doc_documento_contrato].[costoPlaneado] AS [doc_documento_contrato_costoPlaneado],
		[doc_documento_contrato].[id_usuario_asignado] AS [doc_documento_contrato_id_usuario_asignado],
		[doc_documento_contrato].[id_usuario_enUso] AS [doc_documento_contrato_id_usuario_enUso],
		[doc_documento_contrato].[identificador] AS [doc_documento_contrato_identificador],
		[doc_documento_contrato].[cmm] AS [doc_documento_contrato_cmm],
		[cnt_tiempoRespuesta].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cnt_tiempoRespuesta]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_tiempoRespuesta].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_tiempoRespuesta].[id_usuario_creo]
	INNER JOIN [doc_prioridadDocumento] ON [doc_prioridadDocumento].id=[cnt_tiempoRespuesta].[id_prioridadDocumento]
	INNER JOIN [doc_estrategiaPrioridad] ON [doc_estrategiaPrioridad].id=[cnt_tiempoRespuesta].[id_estrategiaPrioridad]
	INNER JOIN [doc_documento.contrato] ON [doc_documento.contrato].id=[cnt_tiempoRespuesta].[id_documento.contrato]
	INNER JOIN [doc_documento] aS [doc_documento_contrato] ON [doc_documento.contrato].id = [doc_documento_contrato].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cnt_tiempoRespuesta].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cnt_tiempoRespuesta].active=1
