IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cnt_tiempoRespuesta]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cnt_tiempoRespuesta]
GO
CREATE PROCEDURE [ins_cnt_tiempoRespuesta]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tiempoRespuesta varchar(300),
		@p_tiempoRespuesta_codigo varchar(100),
		@p_tiempoLimite int,
		@p_id_prioridadDocumento int,
		@p_id_estrategiaPrioridad int,
		@p_id_documento_contrato int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cnt_tiempoRespuesta]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tiempoRespuesta],
			[tiempoRespuesta_codigo],
			[tiempoLimite],
			[id_prioridadDocumento],
			[id_estrategiaPrioridad],
			[id_documento.contrato],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tiempoRespuesta,
			@p_tiempoRespuesta_codigo,
			@p_tiempoLimite,
			@p_id_prioridadDocumento,
			@p_id_estrategiaPrioridad,
			@p_id_documento_contrato,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cnt_tiempoRespuesta] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
