GO
CREATE PROCEDURE [aud_cnt_tiempoRespuesta]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [cnt_tiempoRespuesta].id as id_tabla,
	[cnt_tiempoRespuesta].id_usuario_modifico as id_usuario_modifico,
	[cnt_tiempoRespuesta].id_usuario_creo as id_usuario_creo,
	[cnt_tiempoRespuesta].fechaModificacion as fechaModificacion,
	[cnt_tiempoRespuesta].fechaCreacion as fechaCreacion,
	[cnt_tiempoRespuesta].active as active,
	[cnt_tiempoRespuesta].[tiempoRespuesta] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [cnt_tiempoRespuesta]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_tiempoRespuesta].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_tiempoRespuesta].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
