[cat_catalogo.tempario].[incluirMenores] as [cat_catalogo.tempario_incluirMenores],
[cat_catalogo.tempario].[modoAjuste] as [cat_catalogo.tempario_modoAjuste],
[cat_catalogo.tempario].[cmm] as [cat_catalogo.tempario_cmm],
		[cat_catalogo_tempario].[catalogo_codigo] AS [cat_catalogo_tempario_catalogo_codigo],
		[cat_catalogo_tempario].[codigoInventario] AS [cat_catalogo_tempario_codigoInventario],
		[cat_catalogo_tempario].[precioVenta] AS [cat_catalogo_tempario_precioVenta],
		[cat_catalogo_tempario].[tiempoConsecucion] AS [cat_catalogo_tempario_tiempoConsecucion],
		[cat_catalogo_tempario].[esNacional] AS [cat_catalogo_tempario_esNacional],
		[cat_catalogo_tempario].[id_familia] AS [cat_catalogo_tempario_id_familia],
		[cat_catalogo_tempario].[id_subtipoCatalogo] AS [cat_catalogo_tempario_id_subtipoCatalogo],
		[cat_catalogo_tempario].[id_unidad] AS [cat_catalogo_tempario_id_unidad],
		[cat_catalogo_tempario].[id_impuesto] AS [cat_catalogo_tempario_id_impuesto],
		[cat_catalogo_tempario].[descripcion] AS [cat_catalogo_tempario_descripcion],
		[cat_catalogo_tempario].[bloquearCostear] AS [cat_catalogo_tempario_bloquearCostear],
		[cat_catalogo_tempario].[cmm] AS [cat_catalogo_tempario_cmm],
		[cnt_visitaFija].[esPorTrabajo] AS [esPorTrabajo],
		[cnt_visitaFija].[correoRecordatorio] AS [correoRecordatorio],
		[cnt_visitaFija].[presupuesto] AS [presupuesto],
		[cnt_visitaFija].[id_configuracionProyeccion] AS [id_configuracionProyeccion],
[cnt_configuracionProyeccion].[configuracionProyeccion] as [cnt_configuracionProyeccion_configuracionProyeccion],
[cnt_configuracionProyeccion].[configuracionProyeccion_codigo] as [cnt_configuracionProyeccion_configuracionProyeccion_codigo],
[cnt_configuracionProyeccion].[id_equipo] as [cnt_configuracionProyeccion_id_equipo],
[cnt_configuracionProyeccion].[id_documento.contrato] as [cnt_configuracionProyeccion_id_documento.contrato],
[cnt_configuracionProyeccion].[fecha_inicio_ff] as [cnt_configuracionProyeccion_fecha_inicio_ff],
[cnt_configuracionProyeccion].[fecha_fin_ff] as [cnt_configuracionProyeccion_fecha_fin_ff],
[cnt_configuracionProyeccion].[frecuencia] as [cnt_configuracionProyeccion_frecuencia],
[cnt_configuracionProyeccion].[intervalo] as [cnt_configuracionProyeccion_intervalo],
[cnt_configuracionProyeccion].[diaHabil] as [cnt_configuracionProyeccion_diaHabil],
[cnt_configuracionProyeccion].[porTrabajo] as [cnt_configuracionProyeccion_porTrabajo],
[cnt_configuracionProyeccion].[incluirMenores] as [cnt_configuracionProyeccion_incluirMenores],
[cnt_configuracionProyeccion].[aproximarA] as [cnt_configuracionProyeccion_aproximarA],
[cnt_configuracionProyeccion].[precioVisita] as [cnt_configuracionProyeccion_precioVisita],
[cnt_configuracionProyeccion].[precioServicio] as [cnt_configuracionProyeccion_precioServicio],
[cnt_configuracionProyeccion].[promedio] as [cnt_configuracionProyeccion_promedio],
[cnt_configuracionProyeccion].[estrategia] as [cnt_configuracionProyeccion_estrategia],
[cnt_configuracionProyeccion].[id_tipoServicio] as [cnt_configuracionProyeccion_id_tipoServicio],
[cnt_configuracionProyeccion].[id_subtipoDocumento] as [cnt_configuracionProyeccion_id_subtipoDocumento],
[cnt_configuracionProyeccion].[id_usuario_coordinador] as [cnt_configuracionProyeccion_id_usuario_coordinador],
[cnt_configuracionProyeccion].[id_estadoTipoDocumento_inicial] as [cnt_configuracionProyeccion_id_estadoTipoDocumento_inicial],
[cnt_configuracionProyeccion].[id_subtipoDocumento_padre] as [cnt_configuracionProyeccion_id_subtipoDocumento_padre],
[cnt_configuracionProyeccion].[id_estadoTipoDocumento_inicial_padre] as [cnt_configuracionProyeccion_id_estadoTipoDocumento_inicial_padre],
[cnt_configuracionProyeccion].[cmm] as [cnt_configuracionProyeccion_cmm],
		[cnt_visitaFija].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cnt_visitaFija]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_visitaFija].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_visitaFija].[id_usuario_creo]
	INNER JOIN [doc_documento] ON [doc_documento].id=[cnt_visitaFija].[id_documento]
	INNER JOIN [cat_catalogo.tempario] ON [cat_catalogo.tempario].id=[cnt_visitaFija].[id_catalogo.tempario]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_tempario] ON [cat_catalogo.tempario].id = [cat_catalogo_tempario].id
	INNER JOIN [cnt_configuracionProyeccion] ON [cnt_configuracionProyeccion].id=[cnt_visitaFija].[id_configuracionProyeccion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cnt_visitaFija].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [cnt_visitaFija].active=1
