IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_cnt_visitaFija]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_cnt_visitaFija]
GO
CREATE PROCEDURE [upd_cnt_visitaFija]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_visitaFija varchar(300) = null,
		@p_visitaFija_codigo varchar(100) = null,
		@p_fecha_ff smalldatetime = null,
		@p_fechaCreada_ff smalldatetime = null,
		@p_horometro float = null,
		@p_id_documento int = null,
		@p_id_catalogo_tempario int = null,
		@p_esPorTrabajo bit = null,
		@p_correoRecordatorio varchar(500) = null,
		@p_presupuesto float = null,
		@p_id_configuracionProyeccion int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [cnt_visitaFija]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[visitaFija] = isnull(@p_visitaFija,[visitaFija]),
			[visitaFija_codigo] = isnull(@p_visitaFija_codigo,[visitaFija_codigo]),
			[fecha_ff] = isnull(@p_fecha_ff,[fecha_ff]),
			[fechaCreada_ff] = isnull(@p_fechaCreada_ff,[fechaCreada_ff]),
			[horometro] = isnull(@p_horometro,[horometro]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[id_catalogo.tempario] = isnull(@p_id_catalogo_tempario,[id_catalogo.tempario]),
			[esPorTrabajo] = isnull(@p_esPorTrabajo,[esPorTrabajo]),
			[correoRecordatorio] = isnull(@p_correoRecordatorio,[correoRecordatorio]),
			[presupuesto] = isnull(@p_presupuesto,[presupuesto]),
			[id_configuracionProyeccion] = isnull(@p_id_configuracionProyeccion,[id_configuracionProyeccion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
