IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cnt_visitaFija]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cnt_visitaFija]
GO
CREATE PROCEDURE [ins_cnt_visitaFija]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_visitaFija varchar(300),
		@p_visitaFija_codigo varchar(100),
		@p_fecha_ff smalldatetime,
		@p_fechaCreada_ff smalldatetime,
		@p_horometro float,
		@p_id_documento int,
		@p_id_catalogo_tempario int,
		@p_esPorTrabajo bit,
		@p_correoRecordatorio varchar(500),
		@p_presupuesto float,
		@p_id_configuracionProyeccion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cnt_visitaFija]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[visitaFija],
			[visitaFija_codigo],
			[fecha_ff],
			[fechaCreada_ff],
			[horometro],
			[id_documento],
			[id_catalogo.tempario],
			[esPorTrabajo],
			[correoRecordatorio],
			[presupuesto],
			[id_configuracionProyeccion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_visitaFija,
			@p_visitaFija_codigo,
			@p_fecha_ff,
			@p_fechaCreada_ff,
			@p_horometro,
			@p_id_documento,
			@p_id_catalogo_tempario,
			@p_esPorTrabajo,
			@p_correoRecordatorio,
			@p_presupuesto,
			@p_id_configuracionProyeccion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cnt_visitaFija] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
