CREATE PROCEDURE [reg_cnt_visitaFija_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[visitaFija] AS [visitaFija],
		[visitaFija_codigo] AS [visitaFija_codigo],
		[fecha_ff] AS [fecha_ff],
		[fechaCreada_ff] AS [fechaCreada_ff],
		[horometro] AS [horometro],
		[id_documento] AS [id_documento],
		[id_catalogo.tempario] AS [id_catalogo.tempario],
		[esPorTrabajo] AS [esPorTrabajo],
		[correoRecordatorio] AS [correoRecordatorio],
		[presupuesto] AS [presupuesto],
		[id_configuracionProyeccion] AS [id_configuracionProyeccion],
		[cmm] AS [cmm]
	FROM [cnt_visitaFija]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
