CREATE  VIEW [view_cnt_visitaFija_catalogo] AS
SELECT 	[cnt_visitaFija_catalogo].[id] AS [id],
		[cnt_visitaFija_catalogo].[uid] AS [uid],
		[cnt_visitaFija_catalogo].[eid] AS [eid],
		[cnt_visitaFija_catalogo].[id_usuario_modifico] AS [id_usuario_modifico],
		[cnt_visitaFija_catalogo].[id_usuario_creo] AS [id_usuario_creo],
		[cnt_visitaFija_catalogo].[fechaModificacion] AS [fechaModificacion],
		[cnt_visitaFija_catalogo].[fechaCreacion] AS [fechaCreacion],
		[cnt_visitaFija_catalogo].[active] AS [active],
		[cnt_visitaFija_catalogo].[visitaFija_catalogo] AS [visitaFija_catalogo],
		[cnt_visitaFija_catalogo].[cantidad] AS [cantidad],
		[cnt_visitaFija_catalogo].[precio] AS [precio],
		[cnt_visitaFija_catalogo].[id_visitaFija] AS [id_visitaFija],
[cnt_visitaFija].[visitaFija] as [cnt_visitaFija_visitaFija],
[cnt_visitaFija].[visitaFija_codigo] as [cnt_visitaFija_visitaFija_codigo],
[cnt_visitaFija].[fecha_ff] as [cnt_visitaFija_fecha_ff],
[cnt_visitaFija].[fechaCreada_ff] as [cnt_visitaFija_fechaCreada_ff],
[cnt_visitaFija].[horometro] as [cnt_visitaFija_horometro],
[cnt_visitaFija].[id_documento] as [cnt_visitaFija_id_documento],
[cnt_visitaFija].[id_catalogo.tempario] as [cnt_visitaFija_id_catalogo.tempario],
[cnt_visitaFija].[esPorTrabajo] as [cnt_visitaFija_esPorTrabajo],
[cnt_visitaFija].[correoRecordatorio] as [cnt_visitaFija_correoRecordatorio],
[cnt_visitaFija].[presupuesto] as [cnt_visitaFija_presupuesto],
[cnt_visitaFija].[id_configuracionProyeccion] as [cnt_visitaFija_id_configuracionProyeccion],
[cnt_visitaFija].[cmm] as [cnt_visitaFija_cmm],
		[cnt_visitaFija_catalogo].[id_catalogo] AS [id_catalogo],
[cat_catalogo].[catalogo] as [cat_catalogo_catalogo],
[cat_catalogo].[catalogo_codigo] as [cat_catalogo_catalogo_codigo],
[cat_catalogo].[codigoInventario] as [cat_catalogo_codigoInventario],
[cat_catalogo].[precioVenta] as [cat_catalogo_precioVenta],
[cat_catalogo].[tiempoConsecucion] as [cat_catalogo_tiempoConsecucion],
[cat_catalogo].[esNacional] as [cat_catalogo_esNacional],
[cat_catalogo].[id_familia] as [cat_catalogo_id_familia],
[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[cnt_visitaFija_catalogo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [cnt_visitaFija_catalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[cnt_visitaFija_catalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[cnt_visitaFija_catalogo].[id_usuario_creo]
	INNER JOIN [cnt_visitaFija] ON [cnt_visitaFija].id=[cnt_visitaFija_catalogo].[id_visitaFija]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[cnt_visitaFija_catalogo].[id_catalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [cnt_visitaFija_catalogo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
