IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_cnt_visitaFija_catalogo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_cnt_visitaFija_catalogo]
GO
CREATE PROCEDURE [ins_cnt_visitaFija_catalogo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_visitaFija_catalogo varchar(300),
		@p_cantidad float,
		@p_precio float,
		@p_id_visitaFija int,
		@p_id_catalogo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cnt_visitaFija_catalogo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[visitaFija_catalogo],
			[cantidad],
			[precio],
			[id_visitaFija],
			[id_catalogo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_visitaFija_catalogo,
			@p_cantidad,
			@p_precio,
			@p_id_visitaFija,
			@p_id_catalogo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [cnt_visitaFija_catalogo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
