CREATE PROCEDURE [reg_com_comision]
	@p_id INT
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[comision] AS [comision],
		[comision_codigo] AS [comision_codigo],
		[descuentoMaximo] AS [descuentoMaximo],
		[descuentoMinimo] AS [descuentoMinimo],
		[id_cargo] AS [id_cargo],
		[id_subtipoCatalogo] AS [id_subtipoCatalogo],
		[costear] AS [costear],
		[nivelnegocio] AS [nivelnegocio],
		[porc_comision] AS [porc_comision],
		[id_condicion] AS [id_condicion],
		[id_opcionCondicion] AS [id_opcionCondicion],
		[id_zona] AS [id_zona],
		[cmm] AS [cmm]
	FROM [com_comision]
	WHERE	(id = @p_id)

END
