IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_com_comision]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_com_comision]
GO
CREATE PROCEDURE [upd_com_comision]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_comision varchar(300) = null,
		@p_comision_codigo varchar(100) = null,
		@p_descuentoMaximo float = null,
		@p_descuentoMinimo float = null,
		@p_id_cargo int = null,
		@p_id_subtipoCatalogo int = null,
		@p_costear bit = null,
		@p_nivelnegocio int = null,
		@p_porc_comision float = null,
		@p_id_condicion int = null,
		@p_id_opcionCondicion int = null,
		@p_id_zona int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [com_comision]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[comision] = isnull(@p_comision,[comision]),
			[comision_codigo] = isnull(@p_comision_codigo,[comision_codigo]),
			[descuentoMaximo] = isnull(@p_descuentoMaximo,[descuentoMaximo]),
			[descuentoMinimo] = isnull(@p_descuentoMinimo,[descuentoMinimo]),
			[id_cargo] = isnull(@p_id_cargo,[id_cargo]),
			[id_subtipoCatalogo] = isnull(@p_id_subtipoCatalogo,[id_subtipoCatalogo]),
			[costear] = isnull(@p_costear,[costear]),
			[nivelnegocio] = isnull(@p_nivelnegocio,[nivelnegocio]),
			[porc_comision] = isnull(@p_porc_comision,[porc_comision]),
			[id_condicion] = isnull(@p_id_condicion,[id_condicion]),
			[id_opcionCondicion] = isnull(@p_id_opcionCondicion,[id_opcionCondicion]),
			[id_zona] = isnull(@p_id_zona,[id_zona]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
