IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_com_comision]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_com_comision]
GO
CREATE PROCEDURE [ins_com_comision]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_comision varchar(300),
		@p_comision_codigo varchar(100),
		@p_descuentoMaximo float,
		@p_descuentoMinimo float,
		@p_id_cargo int,
		@p_id_subtipoCatalogo int,
		@p_costear bit,
		@p_nivelnegocio int,
		@p_porc_comision float,
		@p_id_condicion int,
		@p_id_opcionCondicion int,
		@p_id_zona int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [com_comision]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[comision],
			[comision_codigo],
			[descuentoMaximo],
			[descuentoMinimo],
			[id_cargo],
			[id_subtipoCatalogo],
			[costear],
			[nivelnegocio],
			[porc_comision],
			[id_condicion],
			[id_opcionCondicion],
			[id_zona],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_comision,
			@p_comision_codigo,
			@p_descuentoMaximo,
			@p_descuentoMinimo,
			@p_id_cargo,
			@p_id_subtipoCatalogo,
			@p_costear,
			@p_nivelnegocio,
			@p_porc_comision,
			@p_id_condicion,
			@p_id_opcionCondicion,
			@p_id_zona,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [com_comision] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
