IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_dis_estadoEvento]')) DROP VIEW [dbo].[view_dis_estadoEvento]
GO
CREATE  VIEW [view_dis_estadoEvento] AS
SELECT 	[dis_estadoEvento].[id] AS [id],
		[dis_estadoEvento].[uid] AS [uid],
		[dis_estadoEvento].[eid] AS [eid],
		[dis_estadoEvento].[id_usuario_modifico] AS [id_usuario_modifico],
		[dis_estadoEvento].[id_usuario_creo] AS [id_usuario_creo],
		[dis_estadoEvento].[fechaModificacion] AS [fechaModificacion],
		[dis_estadoEvento].[fechaCreacion] AS [fechaCreacion],
		[dis_estadoEvento].[active] AS [active],
		[dis_estadoEvento].[estadoEvento] AS [estadoEvento],
		[dis_estadoEvento].[estadoEvento_codigo] AS [estadoEvento_codigo],
		[dis_estadoEvento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [dis_estadoEvento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_estadoEvento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_estadoEvento].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [dis_estadoEvento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [dis_estadoEvento].active=1
GO
