IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_dis_estadoEvento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_dis_estadoEvento]
GO
CREATE PROCEDURE [ins_dis_estadoEvento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_estadoEvento varchar(300),
		@p_estadoEvento_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_estadoEvento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[estadoEvento],
			[estadoEvento_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_estadoEvento,
			@p_estadoEvento_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_estadoEvento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
