AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_evento_estadoEvento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[evento_estadoEvento],
			[id_evento],
			[id_estadoEvento],
			[fechaHoraRegistro_fh],
			[afectaCliente],
			[id_sistema],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_evento_estadoEvento,
			@p_id_evento,
			@p_id_estadoEvento,
			@p_fechaHoraRegistro_fh,
			@p_afectaCliente,
			@p_id_sistema,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_evento_estadoEvento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
