IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_dis_evento_estadoEvento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_dis_evento_estadoEvento]
GO
CREATE PROCEDURE [upd_dis_evento_estadoEvento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_evento_estadoEvento varchar(300) = null,
		@p_id_evento int = null,
		@p_id_estadoEvento int = null,
		@p_fechaHoraRegistro_fh smalldatetime = null,
		@p_afectaCliente bit = null,
		@p_id_sistema int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [dis_evento_estadoEvento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[evento_estadoEvento] = isnull(@p_evento_estadoEvento,[evento_estadoEvento]),
			[id_evento] = isnull(@p_id_evento,[id_evento]),
			[id_estadoEvento] = isnull(@p_id_estadoEvento,[id_estadoEvento]),
			[fechaHoraRegistro_fh] = isnull(@p_fechaHoraRegistro_fh,[fechaHoraRegistro_fh]),
			[afectaCliente] = isnull(@p_afectaCliente,[afectaCliente]),
			[id_sistema] = isnull(@p_id_sistema,[id_sistema]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
