		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[evento] AS [evento],
		[evento_codigo] AS [evento_codigo],
		[fechaHoraInicio_ff] AS [fechaHoraInicio_ff],
		[duracion_hh] AS [duracion_hh],
		[afectaProduccion] AS [afectaProduccion],
		[notas] AS [notas],
		[id_equipo] AS [id_equipo],
		[id_motivoEvento] AS [id_motivoEvento],
		[id_usuario] AS [id_usuario],
		[id_estadoEquipo] AS [id_estadoEquipo],
		[id_falla] AS [id_falla],
		[id_falla_causa] AS [id_falla_causa],
		[id_metodoDeteccion] AS [id_metodoDeteccion],
