[equ_falla_causa].[cmm] as [equ_falla_causa_cmm],
		[dis_evento].[id_metodoDeteccion] AS [id_metodoDeteccion],
[dis_metodoDeteccion].[metodoDeteccion] as [dis_metodoDeteccion_metodoDeteccion],
[dis_metodoDeteccion].[metodoDeteccion_codigo] as [dis_metodoDeteccion_metodoDeteccion_codigo],
[dis_metodoDeteccion].[cmm] as [dis_metodoDeteccion_cmm],
		[dis_evento].[fechaHoraEstimada_fh] AS [fechaHoraEstimada_fh],
		[dis_evento].[eventoTipo] AS [eventoTipo],
		[dis_evento].[afectaCliente] AS [afectaCliente],
		[dis_evento].[id_estadoEvento] AS [id_estadoEvento],
[dis_estadoEvento].[estadoEvento] as [dis_estadoEvento_estadoEvento],
[dis_estadoEvento].[estadoEvento_codigo] as [dis_estadoEvento_estadoEvento_codigo],
[dis_estadoEvento].[cmm] as [dis_estadoEvento_cmm],
		[dis_evento].[codigo] AS [codigo],
		[dis_evento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [dis_evento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_evento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_evento].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[dis_evento].[id_equipo]
	INNER JOIN [dis_motivoEvento] ON [dis_motivoEvento].id=[dis_evento].[id_motivoEvento]
	INNER JOIN [seg_usuario] ON [seg_usuario].id=[dis_evento].[id_usuario]
	INNER JOIN [equ_estadoEquipo] ON [equ_estadoEquipo].id=[dis_evento].[id_estadoEquipo]
	INNER JOIN [equ_falla] ON [equ_falla].id=[dis_evento].[id_falla]
	INNER JOIN [equ_falla] AS [equ_falla_causa] ON [equ_falla_causa].id=[dis_evento].[id_falla_causa]
	INNER JOIN [dis_metodoDeteccion] ON [dis_metodoDeteccion].id=[dis_evento].[id_metodoDeteccion]
	INNER JOIN [dis_estadoEvento] ON [dis_estadoEvento].id=[dis_evento].[id_estadoEvento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [dis_evento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [dis_evento].active=1
