GO
CREATE PROCEDURE [upd_dis_evento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_evento varchar(300) = null,
		@p_evento_codigo varchar(100) = null,
		@p_fechaHoraInicio_ff smalldatetime = null,
		@p_duracion_hh smalldatetime = null,
		@p_afectaProduccion bit = null,
		@p_notas varchar(1000) = null,
		@p_id_equipo int = null,
		@p_id_motivoEvento int = null,
		@p_id_usuario int = null,
		@p_id_estadoEquipo int = null,
		@p_id_falla int = null,
		@p_id_falla_causa int = null,
		@p_id_metodoDeteccion int = null,
		@p_fechaHoraEstimada_fh smalldatetime = null,
		@p_eventoTipo int = null,
		@p_afectaCliente bit = null,
		@p_id_estadoEvento int = null,
		@p_codigo varchar(100) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [dis_evento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[evento] = isnull(@p_evento,[evento]),
			[evento_codigo] = isnull(@p_evento_codigo,[evento_codigo]),
			[fechaHoraInicio_ff] = isnull(@p_fechaHoraInicio_ff,[fechaHoraInicio_ff]),
			[duracion_hh] = isnull(@p_duracion_hh,[duracion_hh]),
			[afectaProduccion] = isnull(@p_afectaProduccion,[afectaProduccion]),
			[notas] = isnull(@p_notas,[notas]),
			[id_equipo] = isnull(@p_id_equipo,[id_equipo]),
			[id_motivoEvento] = isnull(@p_id_motivoEvento,[id_motivoEvento]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[id_estadoEquipo] = isnull(@p_id_estadoEquipo,[id_estadoEquipo]),
			[id_falla] = isnull(@p_id_falla,[id_falla]),
			[id_falla_causa] = isnull(@p_id_falla_causa,[id_falla_causa]),
			[id_metodoDeteccion] = isnull(@p_id_metodoDeteccion,[id_metodoDeteccion]),
			[fechaHoraEstimada_fh] = isnull(@p_fechaHoraEstimada_fh,[fechaHoraEstimada_fh]),
			[eventoTipo] = isnull(@p_eventoTipo,[eventoTipo]),
			[afectaCliente] = isnull(@p_afectaCliente,[afectaCliente]),
			[id_estadoEvento] = isnull(@p_id_estadoEvento,[id_estadoEvento]),
			[codigo] = isnull(@p_codigo,[codigo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
