IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_dis_evento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_dis_evento]
GO
CREATE PROCEDURE [ins_dis_evento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_evento varchar(300),
		@p_evento_codigo varchar(100),
		@p_fechaHoraInicio_ff smalldatetime,
		@p_duracion_hh smalldatetime,
		@p_afectaProduccion bit,
		@p_notas varchar(1000),
		@p_id_equipo int,
		@p_id_motivoEvento int,
		@p_id_usuario int,
		@p_id_estadoEquipo int,
		@p_id_falla int,
		@p_id_falla_causa int,
		@p_id_metodoDeteccion int,
		@p_fechaHoraEstimada_fh smalldatetime,
		@p_eventoTipo int,
		@p_afectaCliente bit,
		@p_id_estadoEvento int,
		@p_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_evento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[evento],
			[evento_codigo],
			[fechaHoraInicio_ff],
			[duracion_hh],
			[afectaProduccion],
			[notas],
			[id_equipo],
			[id_motivoEvento],
			[id_usuario],
			[id_estadoEquipo],
			[id_falla],
			[id_falla_causa],
			[id_metodoDeteccion],
			[fechaHoraEstimada_fh],
			[eventoTipo],
			[afectaCliente],
			[id_estadoEvento],
			[codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_evento,
			@p_evento_codigo,
			@p_fechaHoraInicio_ff,
			@p_duracion_hh,
			@p_afectaProduccion,
			@p_notas,
			@p_id_equipo,
			@p_id_motivoEvento,
			@p_id_usuario,
			@p_id_estadoEquipo,
			@p_id_falla,
			@p_id_falla_causa,
			@p_id_metodoDeteccion,
			@p_fechaHoraEstimada_fh,
			@p_eventoTipo,
			@p_afectaCliente,
			@p_id_estadoEvento,
			@p_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_evento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
