IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[aud_dis_evento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[aud_dis_evento]
GO
CREATE PROCEDURE [aud_dis_evento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [dis_evento].id as id_tabla,
	[dis_evento].id_usuario_modifico as id_usuario_modifico,
	[dis_evento].id_usuario_creo as id_usuario_creo,
	[dis_evento].fechaModificacion as fechaModificacion,
	[dis_evento].fechaCreacion as fechaCreacion,
	[dis_evento].active as active,
	[dis_evento].[evento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [dis_evento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_evento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_evento].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
