		[dis_evento_catalogo].[valorUnitario] AS [valorUnitario],
		[dis_evento_catalogo].[total] AS [total],
		[dis_evento_catalogo].[id_evento] AS [id_evento],
[dis_evento].[evento] as [dis_evento_evento],
[dis_evento].[evento_codigo] as [dis_evento_evento_codigo],
[dis_evento].[fechaHoraInicio_ff] as [dis_evento_fechaHoraInicio_ff],
[dis_evento].[duracion_hh] as [dis_evento_duracion_hh],
[dis_evento].[afectaProduccion] as [dis_evento_afectaProduccion],
[dis_evento].[notas] as [dis_evento_notas],
[dis_evento].[id_equipo] as [dis_evento_id_equipo],
[dis_evento].[id_motivoEvento] as [dis_evento_id_motivoEvento],
[dis_evento].[id_usuario] as [dis_evento_id_usuario],
[dis_evento].[id_estadoEquipo] as [dis_evento_id_estadoEquipo],
[dis_evento].[id_falla] as [dis_evento_id_falla],
[dis_evento].[id_falla_causa] as [dis_evento_id_falla_causa],
[dis_evento].[id_metodoDeteccion] as [dis_evento_id_metodoDeteccion],
[dis_evento].[fechaHoraEstimada_fh] as [dis_evento_fechaHoraEstimada_fh],
[dis_evento].[eventoTipo] as [dis_evento_eventoTipo],
[dis_evento].[afectaCliente] as [dis_evento_afectaCliente],
[dis_evento].[id_estadoEvento] as [dis_evento_id_estadoEvento],
[dis_evento].[codigo] as [dis_evento_codigo],
[dis_evento].[cmm] as [dis_evento_cmm],
		[dis_evento_catalogo].[id_catalogo] AS [id_catalogo],
[cat_catalogo].[catalogo] as [cat_catalogo_catalogo],
[cat_catalogo].[catalogo_codigo] as [cat_catalogo_catalogo_codigo],
[cat_catalogo].[codigoInventario] as [cat_catalogo_codigoInventario],
[cat_catalogo].[precioVenta] as [cat_catalogo_precioVenta],
[cat_catalogo].[tiempoConsecucion] as [cat_catalogo_tiempoConsecucion],
[cat_catalogo].[esNacional] as [cat_catalogo_esNacional],
[cat_catalogo].[id_familia] as [cat_catalogo_id_familia],
[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[dis_evento_catalogo].[observaciones] AS [observaciones],
		[dis_evento_catalogo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [dis_evento_catalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_evento_catalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_evento_catalogo].[id_usuario_creo]
	INNER JOIN [dis_evento] ON [dis_evento].id=[dis_evento_catalogo].[id_evento]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[dis_evento_catalogo].[id_catalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [dis_evento_catalogo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
