IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_dis_evento_catalogo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_dis_evento_catalogo]
GO
CREATE PROCEDURE [upd_dis_evento_catalogo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_evento_catalogo varchar(300) = null,
		@p_equipoAuxiliar bit = null,
		@p_cantidad float = null,
		@p_valorUnitario float = null,
		@p_total float = null,
		@p_id_evento int = null,
		@p_id_catalogo int = null,
		@p_observaciones varchar(400) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [dis_evento_catalogo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[evento_catalogo] = isnull(@p_evento_catalogo,[evento_catalogo]),
			[equipoAuxiliar] = isnull(@p_equipoAuxiliar,[equipoAuxiliar]),
			[cantidad] = isnull(@p_cantidad,[cantidad]),
			[valorUnitario] = isnull(@p_valorUnitario,[valorUnitario]),
			[total] = isnull(@p_total,[total]),
			[id_evento] = isnull(@p_id_evento,[id_evento]),
			[id_catalogo] = isnull(@p_id_catalogo,[id_catalogo]),
			[observaciones] = isnull(@p_observaciones,[observaciones]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
