IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_dis_evento_catalogo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_dis_evento_catalogo]
GO
CREATE PROCEDURE [ins_dis_evento_catalogo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_evento_catalogo varchar(300),
		@p_equipoAuxiliar bit,
		@p_cantidad float,
		@p_valorUnitario float,
		@p_total float,
		@p_id_evento int,
		@p_id_catalogo int,
		@p_observaciones varchar(400),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_evento_catalogo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[evento_catalogo],
			[equipoAuxiliar],
			[cantidad],
			[valorUnitario],
			[total],
			[id_evento],
			[id_catalogo],
			[observaciones],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_evento_catalogo,
			@p_equipoAuxiliar,
			@p_cantidad,
			@p_valorUnitario,
			@p_total,
			@p_id_evento,
			@p_id_catalogo,
			@p_observaciones,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_evento_catalogo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
