	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [dis_evento_catalogo].id as id_tabla,
	[dis_evento_catalogo].id_usuario_modifico as id_usuario_modifico,
	[dis_evento_catalogo].id_usuario_creo as id_usuario_creo,
	[dis_evento_catalogo].fechaModificacion as fechaModificacion,
	[dis_evento_catalogo].fechaCreacion as fechaCreacion,
	[dis_evento_catalogo].active as active,
	[dis_evento_catalogo].[evento_catalogo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [dis_evento_catalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_evento_catalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_evento_catalogo].[id_usuario_creo]
	where ' + @p_filtro)
END
