[dis_evento].[afectaProduccion] as [dis_evento_afectaProduccion],
[dis_evento].[notas] as [dis_evento_notas],
[dis_evento].[id_equipo] as [dis_evento_id_equipo],
[dis_evento].[id_motivoEvento] as [dis_evento_id_motivoEvento],
[dis_evento].[id_usuario] as [dis_evento_id_usuario],
[dis_evento].[id_estadoEquipo] as [dis_evento_id_estadoEquipo],
[dis_evento].[id_falla] as [dis_evento_id_falla],
[dis_evento].[id_falla_causa] as [dis_evento_id_falla_causa],
[dis_evento].[id_metodoDeteccion] as [dis_evento_id_metodoDeteccion],
[dis_evento].[fechaHoraEstimada_fh] as [dis_evento_fechaHoraEstimada_fh],
[dis_evento].[eventoTipo] as [dis_evento_eventoTipo],
[dis_evento].[afectaCliente] as [dis_evento_afectaCliente],
[dis_evento].[id_estadoEvento] as [dis_evento_id_estadoEvento],
[dis_evento].[codigo] as [dis_evento_codigo],
[dis_evento].[cmm] as [dis_evento_cmm],
		[dis_evento_estadoEvento].[id_estadoEvento] AS [id_estadoEvento],
[dis_estadoEvento].[estadoEvento] as [dis_estadoEvento_estadoEvento],
[dis_estadoEvento].[estadoEvento_codigo] as [dis_estadoEvento_estadoEvento_codigo],
[dis_estadoEvento].[cmm] as [dis_estadoEvento_cmm],
		[dis_evento_estadoEvento].[fechaHoraRegistro_fh] AS [fechaHoraRegistro_fh],
		[dis_evento_estadoEvento].[afectaCliente] AS [afectaCliente],
		[dis_evento_estadoEvento].[id_sistema] AS [id_sistema],
[cat_sistema].[sistema] as [cat_sistema_sistema],
[cat_sistema].[sistema_codigo] as [cat_sistema_sistema_codigo],
[cat_sistema].[id_sistema] as [cat_sistema_id_sistema],
[cat_sistema].[cmm] as [cat_sistema_cmm],
		[dis_evento_estadoEvento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [dis_evento_estadoEvento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_evento_estadoEvento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_evento_estadoEvento].[id_usuario_creo]
	INNER JOIN [dis_evento] ON [dis_evento].id=[dis_evento_estadoEvento].[id_evento]
	INNER JOIN [dis_estadoEvento] ON [dis_estadoEvento].id=[dis_evento_estadoEvento].[id_estadoEvento]
	INNER JOIN [cat_sistema] ON [cat_sistema].id=[dis_evento_estadoEvento].[id_sistema]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [dis_evento_estadoEvento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
