IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_dis_evento_estadoEvento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_dis_evento_estadoEvento]
GO
CREATE PROCEDURE [ins_dis_evento_estadoEvento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_evento_estadoEvento varchar(300),
		@p_id_evento int,
		@p_id_estadoEvento int,
		@p_fechaHoraRegistro_fh smalldatetime,
		@p_afectaCliente bit,
		@p_id_sistema int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_evento_estadoEvento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[evento_estadoEvento],
			[id_evento],
			[id_estadoEvento],
			[fechaHoraRegistro_fh],
			[afectaCliente],
			[id_sistema],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_evento_estadoEvento,
			@p_id_evento,
			@p_id_estadoEvento,
			@p_fechaHoraRegistro_fh,
			@p_afectaCliente,
			@p_id_sistema,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_evento_estadoEvento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
