CREATE PROCEDURE [aud_dis_evento_estadoEvento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [dis_evento_estadoEvento].id as id_tabla,
	[dis_evento_estadoEvento].id_usuario_modifico as id_usuario_modifico,
	[dis_evento_estadoEvento].id_usuario_creo as id_usuario_creo,
	[dis_evento_estadoEvento].fechaModificacion as fechaModificacion,
	[dis_evento_estadoEvento].fechaCreacion as fechaCreacion,
	[dis_evento_estadoEvento].active as active,
	[dis_evento_estadoEvento].[evento_estadoEvento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [dis_evento_estadoEvento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_evento_estadoEvento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_evento_estadoEvento].[id_usuario_creo]
	where ' + @p_filtro)
END
