		[dis_metodoDeteccion].[eid] AS [eid],
		[dis_metodoDeteccion].[id_usuario_modifico] AS [id_usuario_modifico],
		[dis_metodoDeteccion].[id_usuario_creo] AS [id_usuario_creo],
		[dis_metodoDeteccion].[fechaModificacion] AS [fechaModificacion],
		[dis_metodoDeteccion].[fechaCreacion] AS [fechaCreacion],
		[dis_metodoDeteccion].[active] AS [active],
		[dis_metodoDeteccion].[metodoDeteccion] AS [metodoDeteccion],
		[dis_metodoDeteccion].[metodoDeteccion_codigo] AS [metodoDeteccion_codigo],
		[dis_metodoDeteccion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [dis_metodoDeteccion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_metodoDeteccion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_metodoDeteccion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [dis_metodoDeteccion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [dis_metodoDeteccion].active=1
