IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_dis_metodoDeteccion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_dis_metodoDeteccion]
GO
CREATE PROCEDURE [ins_dis_metodoDeteccion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_metodoDeteccion varchar(300),
		@p_metodoDeteccion_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_metodoDeteccion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[metodoDeteccion],
			[metodoDeteccion_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_metodoDeteccion,
			@p_metodoDeteccion_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_metodoDeteccion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
