CREATE  VIEW [view_dis_motivoEvento] AS
SELECT 	[dis_motivoEvento].[id] AS [id],
		[dis_motivoEvento].[uid] AS [uid],
		[dis_motivoEvento].[eid] AS [eid],
		[dis_motivoEvento].[id_usuario_modifico] AS [id_usuario_modifico],
