		[dis_motivoEvento].[fechaModificacion] AS [fechaModificacion],
		[dis_motivoEvento].[fechaCreacion] AS [fechaCreacion],
		[dis_motivoEvento].[active] AS [active],
		[dis_motivoEvento].[motivoEvento] AS [motivoEvento],
		[dis_motivoEvento].[motivoEvento_codigo] AS [motivoEvento_codigo],
		[dis_motivoEvento].[responsableServicio] AS [responsableServicio],
		[dis_motivoEvento].[VaradaProduccion] AS [VaradaProduccion],
		[dis_motivoEvento].[esFalla] AS [esFalla],
		[dis_motivoEvento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [dis_motivoEvento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_motivoEvento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_motivoEvento].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [dis_motivoEvento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [dis_motivoEvento].active=1
