	[dis_motivoEvento].id_usuario_modifico as id_usuario_modifico,
	[dis_motivoEvento].id_usuario_creo as id_usuario_creo,
	[dis_motivoEvento].fechaModificacion as fechaModificacion,
	[dis_motivoEvento].fechaCreacion as fechaCreacion,
