CREATE PROCEDURE [ins_dis_obra]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_obra varchar(300),
		@p_obra_codigo varchar(100),
		@p_fechaInicial_ff smalldatetime,
		@p_fechaFinal_ff smalldatetime,
		@p_id_sucursal int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_obra]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[obra],
			[obra_codigo],
			[fechaInicial_ff],
			[fechaFinal_ff],
			[id_sucursal],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_obra,
			@p_obra_codigo,
			@p_fechaInicial_ff,
			@p_fechaFinal_ff,
			@p_id_sucursal,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_obra] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
