CREATE  VIEW [view_dis_obra_catalogo] AS
SELECT 	[dis_obra_catalogo].[id] AS [id],
		[dis_obra_catalogo].[uid] AS [uid],
		[dis_obra_catalogo].[eid] AS [eid],
		[dis_obra_catalogo].[id_usuario_modifico] AS [id_usuario_modifico],
		[dis_obra_catalogo].[id_usuario_creo] AS [id_usuario_creo],
		[dis_obra_catalogo].[fechaModificacion] AS [fechaModificacion],
		[dis_obra_catalogo].[fechaCreacion] AS [fechaCreacion],
		[dis_obra_catalogo].[active] AS [active],
		[dis_obra_catalogo].[obra_catalogo] AS [obra_catalogo],
		[dis_obra_catalogo].[cantidad] AS [cantidad],
		[dis_obra_catalogo].[valorUnitario] AS [valorUnitario],
		[dis_obra_catalogo].[total] AS [total],
		[dis_obra_catalogo].[promedioDia] AS [promedioDia],
		[dis_obra_catalogo].[id_obra] AS [id_obra],
[dis_obra].[obra] as [dis_obra_obra],
[dis_obra].[obra_codigo] as [dis_obra_obra_codigo],
[dis_obra].[fechaInicial_ff] as [dis_obra_fechaInicial_ff],
[dis_obra].[fechaFinal_ff] as [dis_obra_fechaFinal_ff],
[dis_obra].[id_sucursal] as [dis_obra_id_sucursal],
[dis_obra].[cmm] as [dis_obra_cmm],
		[dis_obra_catalogo].[id_catalogo] AS [id_catalogo],
[cat_catalogo].[catalogo] as [cat_catalogo_catalogo],
[cat_catalogo].[catalogo_codigo] as [cat_catalogo_catalogo_codigo],
[cat_catalogo].[codigoInventario] as [cat_catalogo_codigoInventario],
[cat_catalogo].[precioVenta] as [cat_catalogo_precioVenta],
[cat_catalogo].[tiempoConsecucion] as [cat_catalogo_tiempoConsecucion],
[cat_catalogo].[esNacional] as [cat_catalogo_esNacional],
[cat_catalogo].[id_familia] as [cat_catalogo_id_familia],
[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[dis_obra_catalogo].[valorMaximo] AS [valorMaximo],
		[dis_obra_catalogo].[valorMinimo] AS [valorMinimo],
		[dis_obra_catalogo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [dis_obra_catalogo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[dis_obra_catalogo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[dis_obra_catalogo].[id_usuario_creo]
	INNER JOIN [dis_obra] ON [dis_obra].id=[dis_obra_catalogo].[id_obra]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[dis_obra_catalogo].[id_catalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [dis_obra_catalogo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
