CREATE PROCEDURE [aud_dis_obra_equipo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [dis_obra_equipo].id as id_tabla,
	[dis_obra_equipo].id_usuario_modifico as id_usuario_modifico,
	[dis_obra_equipo].id_usuario_creo as id_usuario_creo,
	[dis_obra_equipo].fechaModificacion as fechaModificacion,
	[dis_obra_equipo].fechaCreacion as fechaCreacion,
	[dis_obra_equipo].active as active,
	[dis_obra_equipo].[obra_equipo] as campoPrincipal,
