IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_centroCosto]')) DROP VIEW [dbo].[view_doc_centroCosto]
GO
CREATE  VIEW [view_doc_centroCosto] AS
SELECT 	[doc_centroCosto].[id] AS [id],
		[doc_centroCosto].[uid] AS [uid],
		[doc_centroCosto].[eid] AS [eid],
		[doc_centroCosto].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_centroCosto].[id_usuario_creo] AS [id_usuario_creo],
		[doc_centroCosto].[fechaModificacion] AS [fechaModificacion],
		[doc_centroCosto].[fechaCreacion] AS [fechaCreacion],
		[doc_centroCosto].[active] AS [active],
		[doc_centroCosto].[centroCosto] AS [centroCosto],
		[doc_centroCosto].[centroCosto_codigo] AS [centroCosto_codigo],
		[doc_centroCosto].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_centroCosto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_centroCosto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_centroCosto].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_centroCosto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_centroCosto].active=1
