IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_centroCosto]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_centroCosto]
GO
CREATE PROCEDURE [ins_doc_centroCosto]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_centroCosto varchar(300),
		@p_centroCosto_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_centroCosto]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[centroCosto],
			[centroCosto_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_centroCosto,
			@p_centroCosto_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_centroCosto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
