IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_condicion]')) DROP VIEW [dbo].[view_doc_condicion]
GO
CREATE  VIEW [view_doc_condicion] AS
SELECT 	[doc_condicion].[id] AS [id],
		[doc_condicion].[uid] AS [uid],
		[doc_condicion].[eid] AS [eid],
		[doc_condicion].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_condicion].[id_usuario_creo] AS [id_usuario_creo],
		[doc_condicion].[fechaModificacion] AS [fechaModificacion],
		[doc_condicion].[fechaCreacion] AS [fechaCreacion],
		[doc_condicion].[active] AS [active],
		[doc_condicion].[condicion] AS [condicion],
		[doc_condicion].[condicion_codigo] AS [condicion_codigo],
		[doc_condicion].[textoLibre] AS [textoLibre],
		[doc_condicion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_condicion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_condicion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_condicion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_condicion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_condicion].active=1
GO
