IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_condicion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_condicion]
GO
CREATE PROCEDURE [ins_doc_condicion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_condicion varchar(300),
		@p_condicion_codigo varchar(100),
		@p_textoLibre bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_condicion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[condicion],
			[condicion_codigo],
			[textoLibre],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_condicion,
			@p_condicion_codigo,
			@p_textoLibre,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_condicion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
