	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_costeo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_costeo].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_costeo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
