GO
CREATE PROCEDURE [aud_doc_costeo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_costeo].id as id_tabla,
	[doc_costeo].id_usuario_modifico as id_usuario_modifico,
	[doc_costeo].id_usuario_creo as id_usuario_creo,
	[doc_costeo].fechaModificacion as fechaModificacion,
	[doc_costeo].fechaCreacion as fechaCreacion,
	[doc_costeo].active as active,
	[doc_costeo].[costeo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_costeo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_costeo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_costeo].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
