		[doc_documento].[identificador] AS [identificador],
		[doc_documento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento].[id_usuario_creo]
	INNER JOIN [doc_subtipoDocumento] ON [doc_subtipoDocumento].id=[doc_documento].[id_subtipoDocumento]
	INNER JOIN [ter_tercero] AS [ter_tercero_cliente] ON [ter_tercero_cliente].id=[doc_documento].[id_tercero_cliente]
	INNER JOIN [doc_documento] AS [doc_documento_padre] ON [doc_documento_padre].id=[doc_documento].[id_documento]
	INNER JOIN [ter_tercero] AS [ter_tercero_proveedor] ON [ter_tercero_proveedor].id=[doc_documento].[id_tercero_proveedor]
	INNER JOIN [doc_prioridadDocumento] ON [doc_prioridadDocumento].id=[doc_documento].[id_prioridadDocumento]
	INNER JOIN [gen_moneda] ON [gen_moneda].id=[doc_documento].[id_moneda]
	INNER JOIN [doc_estadoTipoDocumento] ON [doc_estadoTipoDocumento].id=[doc_documento].[id_estadoTipoDocumento]
	INNER JOIN [doc_motivoestado] ON [doc_motivoestado].id=[doc_documento].[id_motivoestado]
	INNER JOIN [seg_usuario] AS [seg_usuario_asignado] ON [seg_usuario_asignado].id=[doc_documento].[id_usuario_asignado]
	INNER JOIN [seg_usuario] AS [seg_usuario_enUso] ON [seg_usuario_enUso].id=[doc_documento].[id_usuario_enUso]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documento].active=1
GO
