		@p_fecha_fh smalldatetime = null,
		@p_fechaSugerida_fh smalldatetime = null,
		@p_fechaCierre_ff smalldatetime = null,
		@p_fechaLimite_fh smalldatetime = null,
		@p_id_subtipoDocumento int = null,
		@p_id_tercero_cliente int = null,
		@p_id_documento int = null,
		@p_id_tercero_proveedor int = null,
		@p_id_prioridadDocumento int = null,
		@p_id_moneda int = null,
		@p_id_estadoTipoDocumento int = null,
		@p_id_motivoestado int = null,
		@p_subtotalPlaneado float = null,
		@p_descuentoPlaneado float = null,
		@p_ivaPlaneado float = null,
		@p_totalPlaneado float = null,
		@p_costoPlaneado float = null,
		@p_id_usuario_asignado int = null,
		@p_id_usuario_enUso int = null,
		@p_identificador varchar(25) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_documento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[documento] = isnull(@p_documento,[documento]),
			[documento_codigo] = isnull(@p_documento_codigo,[documento_codigo]),
			[documento_numero] = isnull(@p_documento_numero,[documento_numero]),
			[prefijo] = isnull(@p_prefijo,[prefijo]),
			[subtotal] = isnull(@p_subtotal,[subtotal]),
			[descuento] = isnull(@p_descuento,[descuento]),
			[iva] = isnull(@p_iva,[iva]),
			[total] = isnull(@p_total,[total]),
			[costo] = isnull(@p_costo,[costo]),
			[rentabilidad] = isnull(@p_rentabilidad,[rentabilidad]),
			[trm] = isnull(@p_trm,[trm]),
			[fecha_fh] = isnull(@p_fecha_fh,[fecha_fh]),
			[fechaSugerida_fh] = isnull(@p_fechaSugerida_fh,[fechaSugerida_fh]),
			[fechaCierre_ff] = isnull(@p_fechaCierre_ff,[fechaCierre_ff]),
			[fechaLimite_fh] = isnull(@p_fechaLimite_fh,[fechaLimite_fh]),
			[id_subtipoDocumento] = isnull(@p_id_subtipoDocumento,[id_subtipoDocumento]),
			[id_tercero_cliente] = isnull(@p_id_tercero_cliente,[id_tercero_cliente]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[id_tercero_proveedor] = isnull(@p_id_tercero_proveedor,[id_tercero_proveedor]),
			[id_prioridadDocumento] = isnull(@p_id_prioridadDocumento,[id_prioridadDocumento]),
			[id_moneda] = isnull(@p_id_moneda,[id_moneda]),
			[id_estadoTipoDocumento] = isnull(@p_id_estadoTipoDocumento,[id_estadoTipoDocumento]),
			[id_motivoestado] = isnull(@p_id_motivoestado,[id_motivoestado]),
			[subtotalPlaneado] = isnull(@p_subtotalPlaneado,[subtotalPlaneado]),
			[descuentoPlaneado] = isnull(@p_descuentoPlaneado,[descuentoPlaneado]),
			[ivaPlaneado] = isnull(@p_ivaPlaneado,[ivaPlaneado]),
			[totalPlaneado] = isnull(@p_totalPlaneado,[totalPlaneado]),
			[costoPlaneado] = isnull(@p_costoPlaneado,[costoPlaneado]),
			[id_usuario_asignado] = isnull(@p_id_usuario_asignado,[id_usuario_asignado]),
			[id_usuario_enUso] = isnull(@p_id_usuario_enUso,[id_usuario_enUso]),
			[identificador] = isnull(@p_identificador,[identificador]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
