		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[documento] AS [documento],
		[documento_codigo] AS [documento_codigo],
		[documento_numero] AS [documento_numero],
		[prefijo] AS [prefijo],
		[subtotal] AS [subtotal],
		[descuento] AS [descuento],
		[iva] AS [iva],
		[total] AS [total],
		[costo] AS [costo],
		[rentabilidad] AS [rentabilidad],
		[trm] AS [trm],
		[fecha_fh] AS [fecha_fh],
		[fechaSugerida_fh] AS [fechaSugerida_fh],
		[fechaCierre_ff] AS [fechaCierre_ff],
		[fechaLimite_fh] AS [fechaLimite_fh],
		[id_subtipoDocumento] AS [id_subtipoDocumento],
		[id_tercero_cliente] AS [id_tercero_cliente],
		[id_documento] AS [id_documento],
		[id_tercero_proveedor] AS [id_tercero_proveedor],
		[id_prioridadDocumento] AS [id_prioridadDocumento],
		[id_moneda] AS [id_moneda],
		[id_estadoTipoDocumento] AS [id_estadoTipoDocumento],
		[id_motivoestado] AS [id_motivoestado],
		[subtotalPlaneado] AS [subtotalPlaneado],
		[descuentoPlaneado] AS [descuentoPlaneado],
		[ivaPlaneado] AS [ivaPlaneado],
		[totalPlaneado] AS [totalPlaneado],
		[costoPlaneado] AS [costoPlaneado],
		[id_usuario_asignado] AS [id_usuario_asignado],
		[id_usuario_enUso] AS [id_usuario_enUso],
		[identificador] AS [identificador],
		[cmm] AS [cmm]
	FROM [doc_documento]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
