CREATE PROCEDURE [aud_doc_documento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento].id as id_tabla,
	[doc_documento].id_usuario_modifico as id_usuario_modifico,
	[doc_documento].id_usuario_creo as id_usuario_creo,
	[doc_documento].fechaModificacion as fechaModificacion,
	[doc_documento].fechaCreacion as fechaCreacion,
	[doc_documento].active as active,
	[doc_documento].[documento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento].[id_usuario_creo]
	where ' + @p_filtro)
END
