IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[reg_doc_documento_alquiler]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[reg_doc_documento_alquiler]
GO
CREATE PROCEDURE [reg_doc_documento_alquiler]
	@p_id INT
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[documento.alquiler] AS [documento.alquiler],
		[fechaFin_ff] AS [fechaFin_ff],
		[mesVencido] AS [mesVencido],
		[observaciones] AS [observaciones],
		[ejecutaDevolucion] AS [ejecutaDevolucion],
		[cmm] AS [cmm]
	FROM [doc_documento.alquiler]
	WHERE	(id = @p_id)

END
