[doc_documento_alquiler].[cmm] AS [doc_documento_alquiler_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.alquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.alquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.alquiler].[id_usuario_creo]
	INNER JOIN [doc_documento] aS [doc_documento_alquiler] ON [doc_documento.alquiler].id = [doc_documento_alquiler].id
	INNER JOIN [doc_subtipoDocumento]as [doc_documento_alquiler_doc_subtipoDocumento] ON [doc_documento_alquiler_doc_subtipoDocumento].id=[doc_documento_alquiler].[id_subtipoDocumento]
	INNER JOIN [ter_tercero]as [doc_documento_alquiler_ter_tercero_cliente] ON [doc_documento_alquiler_ter_tercero_cliente].id=[doc_documento_alquiler].[id_tercero_cliente]
	INNER JOIN [doc_documento]as [doc_documento_alquiler_doc_documento_padre] ON [doc_documento_alquiler_doc_documento_padre].id=[doc_documento_alquiler].[id_documento]
	INNER JOIN [ter_tercero]as [doc_documento_alquiler_ter_tercero_proveedor] ON [doc_documento_alquiler_ter_tercero_proveedor].id=[doc_documento_alquiler].[id_tercero_proveedor]
	INNER JOIN [doc_prioridadDocumento]as [doc_documento_alquiler_doc_prioridadDocumento] ON [doc_documento_alquiler_doc_prioridadDocumento].id=[doc_documento_alquiler].[id_prioridadDocumento]
	INNER JOIN [gen_moneda]as [doc_documento_alquiler_gen_moneda] ON [doc_documento_alquiler_gen_moneda].id=[doc_documento_alquiler].[id_moneda]
	INNER JOIN [doc_estadoTipoDocumento]as [doc_documento_alquiler_doc_estadoTipoDocumento] ON [doc_documento_alquiler_doc_estadoTipoDocumento].id=[doc_documento_alquiler].[id_estadoTipoDocumento]
	INNER JOIN [doc_motivoestado]as [doc_documento_alquiler_doc_motivoestado] ON [doc_documento_alquiler_doc_motivoestado].id=[doc_documento_alquiler].[id_motivoestado]
	INNER JOIN [seg_usuario]as [doc_documento_alquiler_seg_usuario_asignado] ON [doc_documento_alquiler_seg_usuario_asignado].id=[doc_documento_alquiler].[id_usuario_asignado]
	INNER JOIN [seg_usuario]as [doc_documento_alquiler_seg_usuario_enUso] ON [doc_documento_alquiler_seg_usuario_enUso].id=[doc_documento_alquiler].[id_usuario_enUso]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.alquiler].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documento.alquiler].active=1
