IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[sel_doc_documento_contratosXusuario_modifico]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[sel_doc_documento_contratosXusuario_modifico]
GO
CREATE PROCEDURE [sel_doc_documento_contratosXusuario_modifico]
	@p_id_usuario_modifico INT
AS
BEGIN
	SELECT * 
	FROM [view_doc_documento.contrato]
	WHERE ([id_usuario_modifico]= @p_id_usuario_modifico)
END
GO
