GO
CREATE PROCEDURE [upd_doc_documento_contrato]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_active bit = null,
		@p_documento_contrato varchar(300) = null,
		@p_numero varchar(50) = null,
		@p_totalContrato money = null,
		@p_presupuesto money = null,
		@p_fechaInicio_ff smalldatetime = null,
		@p_fechaFin_ff smalldatetime = null,
		@p_diasCumplimiento int = null,
		@p_condiciones varchar(8000) = null,
		@p_id_periodoContrato int = null,
		@p_cmm varchar(300) = null,
		@p_documento_codigo varchar(100),
		@p_documento_numero int,
		@p_prefijo varchar(10),
		@p_subtotal float,
		@p_descuento float,
		@p_iva float,
		@p_total float,
		@p_costo float,
		@p_rentabilidad float,
		@p_trm float,
		@p_fecha_fh smalldatetime,
		@p_fechaSugerida_fh smalldatetime,
		@p_fechaCierre_ff smalldatetime,
		@p_fechaLimite_fh smalldatetime,
		@p_id_subtipoDocumento int,
		@p_id_tercero_cliente int,
		@p_id_documento int,
		@p_id_tercero_proveedor int,
		@p_id_prioridadDocumento int,
		@p_id_moneda int,
		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_subtotalPlaneado float,
		@p_descuentoPlaneado float,
		@p_ivaPlaneado float,
		@p_totalPlaneado float,
		@p_costoPlaneado float,
		@p_id_usuario_asignado int,
		@p_id_usuario_enUso int,
		@p_identificador varchar(25),
		@p_cmm varchar(300)
AS
BEGIN
exec [upd_doc_documento]
			@p_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_fechaCreacion,
			@p_documento_contrato,
			@p_documento_codigo,
			@p_documento_numero,
			@p_prefijo,
			@p_subtotal,
			@p_descuento,
			@p_iva,
			@p_total,
			@p_costo,
			@p_rentabilidad,
			@p_trm,
			@p_fecha_fh,
			@p_fechaSugerida_fh,
			@p_fechaCierre_ff,
			@p_fechaLimite_fh,
			@p_id_subtipoDocumento,
			@p_id_tercero_cliente,
			@p_id_documento,
			@p_id_tercero_proveedor,
			@p_id_prioridadDocumento,
			@p_id_moneda,
			@p_id_estadoTipoDocumento,
			@p_id_motivoestado,
			@p_subtotalPlaneado,
			@p_descuentoPlaneado,
			@p_ivaPlaneado,
			@p_totalPlaneado,
			@p_costoPlaneado,
			@p_id_usuario_asignado,
			@p_id_usuario_enUso,
			@p_identificador,
			@p_cmm
	UPDATE [doc_documento.contrato]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[fechaCreacion] = isnull(@p_fechaCreacion,[fechaCreacion]),
			[documento.contrato] = isnull(@p_documento_contrato,[documento.contrato]),
			[numero] = isnull(@p_numero,[numero]),
			[totalContrato] = isnull(@p_totalContrato,[totalContrato]),
			[presupuesto] = isnull(@p_presupuesto,[presupuesto]),
			[fechaInicio_ff] = isnull(@p_fechaInicio_ff,[fechaInicio_ff]),
			[fechaFin_ff] = isnull(@p_fechaFin_ff,[fechaFin_ff]),
			[diasCumplimiento] = isnull(@p_diasCumplimiento,[diasCumplimiento]),
			[condiciones] = isnull(@p_condiciones,[condiciones]),
			[id_periodoContrato] = isnull(@p_id_periodoContrato,[id_periodoContrato]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
