CREATE PROCEDURE [aud_doc_documento_contrato]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento.contrato].id as id_tabla,
	[doc_documento.contrato].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.contrato].id_usuario_creo as id_usuario_creo,
	[doc_documento.contrato].fechaModificacion as fechaModificacion,
	[doc_documento.contrato].fechaCreacion as fechaCreacion,
	[doc_documento.contrato].active as active,
	[doc_documento.contrato].[documento.contrato] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento.contrato]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.contrato].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.contrato].[id_usuario_creo]
	where ' + @p_filtro)
END
