GO
CREATE PROCEDURE [ins_doc_documento_cotizacion]
		@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_cotizacion varchar(300),
		@p_version int,
		@p_validez int,
		@p_contacto varchar(100),
		@p_cargo varchar(100),
		@p_encabezado varchar(8000),
		@p_condiciones varchar(8000),
		@p_notas varchar(8000),
		@p_esAIU bit,
		@p_procentajeA float,
		@p_procentajeI float,
		@p_procentajeU float,
		@p_valorA float,
		@p_valorI float,
		@p_valorU float,
		@p_id_sucursal int,
		@p_id_equipo int,
		@p_id_usuario_asesor int,
		@p_email varchar(100),
		@p_telefono varchar(100),
		@p_cmm varchar(300),
		@p_documento_codigo varchar(100),
		@p_documento_numero int,
		@p_prefijo varchar(10),
		@p_subtotal float,
		@p_descuento float,
		@p_iva float,
		@p_total float,
		@p_costo float,
		@p_rentabilidad float,
		@p_trm float,
		@p_fecha_fh smalldatetime,
		@p_fechaSugerida_fh smalldatetime,
		@p_fechaCierre_ff smalldatetime,
		@p_fechaLimite_fh smalldatetime,
		@p_id_subtipoDocumento int,
		@p_id_tercero_cliente int,
		@p_id_documento int,
		@p_id_tercero_proveedor int,
		@p_id_prioridadDocumento int,
		@p_id_moneda int,
		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_subtotalPlaneado float,
		@p_descuentoPlaneado float,
		@p_ivaPlaneado float,
		@p_totalPlaneado float,
		@p_costoPlaneado float,
		@p_id_usuario_asignado int,
		@p_id_usuario_enUso int,
		@p_identificador varchar(25),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
exec @v_id = [ins_doc_documento]
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_documento_cotizacion,
			@p_documento_codigo,
			@p_documento_numero,
			@p_prefijo,
			@p_subtotal,
			@p_descuento,
			@p_iva,
			@p_total,
			@p_costo,
			@p_rentabilidad,
			@p_trm,
			@p_fecha_fh,
			@p_fechaSugerida_fh,
			@p_fechaCierre_ff,
			@p_fechaLimite_fh,
			@p_id_subtipoDocumento,
			@p_id_tercero_cliente,
			@p_id_documento,
			@p_id_tercero_proveedor,
			@p_id_prioridadDocumento,
			@p_id_moneda,
			@p_id_estadoTipoDocumento,
			@p_id_motivoestado,
			@p_subtotalPlaneado,
			@p_descuentoPlaneado,
			@p_ivaPlaneado,
			@p_totalPlaneado,
			@p_costoPlaneado,
			@p_id_usuario_asignado,
			@p_id_usuario_enUso,
			@p_identificador,
			@p_cmm		
INSERT INTO [doc_documento.cotizacion]
			([id],
			[uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.cotizacion],
			[version],
			[validez],
			[contacto],
			[cargo],
			[encabezado],
			[condiciones],
			[notas],
			[esAIU],
			[procentajeA],
			[procentajeI],
			[procentajeU],
			[valorA],
			[valorI],
			[valorU],
			[id_sucursal],
			[id_equipo],
			[id_usuario_asesor],
			[email],
			[telefono],
			[cmm])
		VALUES( @v_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_cotizacion,
			@p_version,
			@p_validez,
			@p_contacto,
			@p_cargo,
			@p_encabezado,
			@p_condiciones,
			@p_notas,
			@p_esAIU,
			@p_procentajeA,
			@p_procentajeI,
			@p_procentajeU,
			@p_valorA,
			@p_valorI,
			@p_valorU,
			@p_id_sucursal,
			@p_id_equipo,
			@p_id_usuario_asesor,
			@p_email,
			@p_telefono,
			@p_cmm)
UPDATE [doc_documento.cotizacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
END
GO
