CREATE PROCEDURE [reg_doc_documento_cotizacion_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[documento.cotizacion] AS [documento.cotizacion],
		[version] AS [version],
		[validez] AS [validez],
		[contacto] AS [contacto],
		[cargo] AS [cargo],
		[encabezado] AS [encabezado],
		[condiciones] AS [condiciones],
		[notas] AS [notas],
		[esAIU] AS [esAIU],
		[procentajeA] AS [procentajeA],
		[procentajeI] AS [procentajeI],
		[procentajeU] AS [procentajeU],
		[valorA] AS [valorA],
		[valorI] AS [valorI],
		[valorU] AS [valorU],
		[id_sucursal] AS [id_sucursal],
		[id_equipo] AS [id_equipo],
		[id_usuario_asesor] AS [id_usuario_asesor],
		[email] AS [email],
		[telefono] AS [telefono],
		[cmm] AS [cmm]
	FROM [doc_documento.cotizacion]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
