IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[aud_doc_documento_cotizacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[aud_doc_documento_cotizacion]
GO
CREATE PROCEDURE [aud_doc_documento_cotizacion]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento.cotizacion].id as id_tabla,
	[doc_documento.cotizacion].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.cotizacion].id_usuario_creo as id_usuario_creo,
	[doc_documento.cotizacion].fechaModificacion as fechaModificacion,
	[doc_documento.cotizacion].fechaCreacion as fechaCreacion,
	[doc_documento.cotizacion].active as active,
	[doc_documento.cotizacion].[documento.cotizacion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento.cotizacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.cotizacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.cotizacion].[id_usuario_creo]
	where ' + @p_filtro)
END
