	INNER JOIN [doc_documento.cotizacion] ON [doc_documento.cotizacion].id=[doc_documento.cotizacion_condicion].[id_documento.cotizacion]
	INNER JOIN [doc_documento] aS [doc_documento_cotizacion] ON [doc_documento.cotizacion].id = [doc_documento_cotizacion].id
	INNER JOIN [doc_condicion] ON [doc_condicion].id=[doc_documento.cotizacion_condicion].[id_condicion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.cotizacion_condicion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
