GO
CREATE PROCEDURE [upd_doc_documento_cotizacion_condicion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_documento_cotizacion_condicion varchar(300) = null,
		@p_imprimir bit = null,
		@p_id_opcionCondicion int = null,
		@p_id_documento_cotizacion int = null,
		@p_id_condicion int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_documento.cotizacion_condicion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[documento.cotizacion_condicion] = isnull(@p_documento_cotizacion_condicion,[documento.cotizacion_condicion]),
			[imprimir] = isnull(@p_imprimir,[imprimir]),
			[id_opcionCondicion] = isnull(@p_id_opcionCondicion,[id_opcionCondicion]),
			[id_documento.cotizacion] = isnull(@p_id_documento_cotizacion,[id_documento.cotizacion]),
			[id_condicion] = isnull(@p_id_condicion,[id_condicion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
