IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_documento_cotizacion_condicion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_documento_cotizacion_condicion]
GO
CREATE PROCEDURE [ins_doc_documento_cotizacion_condicion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_cotizacion_condicion varchar(300),
		@p_imprimir bit,
		@p_id_opcionCondicion int,
		@p_id_documento_cotizacion int,
		@p_id_condicion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento.cotizacion_condicion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.cotizacion_condicion],
			[imprimir],
			[id_opcionCondicion],
			[id_documento.cotizacion],
			[id_condicion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_cotizacion_condicion,
			@p_imprimir,
			@p_id_opcionCondicion,
			@p_id_documento_cotizacion,
			@p_id_condicion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento.cotizacion_condicion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
