IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[aud_doc_documento_cotizacion_condicion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[aud_doc_documento_cotizacion_condicion]
GO
CREATE PROCEDURE [aud_doc_documento_cotizacion_condicion]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento.cotizacion_condicion].id as id_tabla,
	[doc_documento.cotizacion_condicion].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.cotizacion_condicion].id_usuario_creo as id_usuario_creo,
	[doc_documento.cotizacion_condicion].fechaModificacion as fechaModificacion,
	[doc_documento.cotizacion_condicion].fechaCreacion as fechaCreacion,
	[doc_documento.cotizacion_condicion].active as active,
	[doc_documento.cotizacion_condicion].[documento.cotizacion_condicion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento.cotizacion_condicion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.cotizacion_condicion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.cotizacion_condicion].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
