GO
CREATE PROCEDURE [upd_doc_documento_entrada]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_active bit = null,
		@p_documento_entrada varchar(300) = null,
		@p_telefonoEntrega varchar(100) = null,
		@p_direccionEntrega varchar(300) = null,
		@p_asunto varchar(300) = null,
		@p_observaciones varchar(8000) = null,
		@p_solicitante varchar(300) = null,
		@p_id_usuario_recibe int = null,
		@p_id_tercero_transportador int = null,
		@p_id_sucursal int = null,
		@p_esPorAjuste bit = null,
		@p_cmm varchar(300) = null,
		@p_documento_codigo varchar(100),
		@p_documento_numero int,
		@p_prefijo varchar(10),
		@p_subtotal float,
		@p_descuento float,
		@p_iva float,
		@p_total float,
		@p_costo float,
		@p_rentabilidad float,
		@p_trm float,
		@p_fecha_fh smalldatetime,
		@p_fechaSugerida_fh smalldatetime,
		@p_fechaCierre_ff smalldatetime,
		@p_fechaLimite_fh smalldatetime,
		@p_id_subtipoDocumento int,
		@p_id_tercero_cliente int,
		@p_id_documento int,
		@p_id_tercero_proveedor int,
		@p_id_prioridadDocumento int,
		@p_id_moneda int,
		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_subtotalPlaneado float,
		@p_descuentoPlaneado float,
		@p_ivaPlaneado float,
		@p_totalPlaneado float,
		@p_costoPlaneado float,
		@p_id_usuario_asignado int,
		@p_id_usuario_enUso int,
		@p_identificador varchar(25),
		@p_cmm varchar(300)
AS
BEGIN
exec [upd_doc_documento]
			@p_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_fechaCreacion,
			@p_documento_entrada,
			@p_documento_codigo,
			@p_documento_numero,
			@p_prefijo,
			@p_subtotal,
			@p_descuento,
			@p_iva,
			@p_total,
			@p_costo,
			@p_rentabilidad,
			@p_trm,
			@p_fecha_fh,
			@p_fechaSugerida_fh,
			@p_fechaCierre_ff,
			@p_fechaLimite_fh,
			@p_id_subtipoDocumento,
			@p_id_tercero_cliente,
			@p_id_documento,
			@p_id_tercero_proveedor,
			@p_id_prioridadDocumento,
			@p_id_moneda,
			@p_id_estadoTipoDocumento,
			@p_id_motivoestado,
			@p_subtotalPlaneado,
			@p_descuentoPlaneado,
			@p_ivaPlaneado,
			@p_totalPlaneado,
			@p_costoPlaneado,
			@p_id_usuario_asignado,
			@p_id_usuario_enUso,
			@p_identificador,
			@p_cmm
	UPDATE [doc_documento.entrada]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[fechaCreacion] = isnull(@p_fechaCreacion,[fechaCreacion]),
			[documento.entrada] = isnull(@p_documento_entrada,[documento.entrada]),
			[telefonoEntrega] = isnull(@p_telefonoEntrega,[telefonoEntrega]),
			[direccionEntrega] = isnull(@p_direccionEntrega,[direccionEntrega]),
			[asunto] = isnull(@p_asunto,[asunto]),
			[observaciones] = isnull(@p_observaciones,[observaciones]),
			[solicitante] = isnull(@p_solicitante,[solicitante]),
			[id_usuario_recibe] = isnull(@p_id_usuario_recibe,[id_usuario_recibe]),
			[id_tercero_transportador] = isnull(@p_id_tercero_transportador,[id_tercero_transportador]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[esPorAjuste] = isnull(@p_esPorAjuste,[esPorAjuste]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
