CREATE PROCEDURE [reg_doc_documento_entrada_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[documento.entrada] AS [documento.entrada],
		[telefonoEntrega] AS [telefonoEntrega],
		[direccionEntrega] AS [direccionEntrega],
		[asunto] AS [asunto],
		[observaciones] AS [observaciones],
		[solicitante] AS [solicitante],
		[id_usuario_recibe] AS [id_usuario_recibe],
		[id_tercero_transportador] AS [id_tercero_transportador],
		[id_sucursal] AS [id_sucursal],
		[esPorAjuste] AS [esPorAjuste],
		[cmm] AS [cmm]
	FROM [doc_documento.entrada]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
