CREATE PROCEDURE [aud_doc_documento_gasto]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento.gasto].id as id_tabla,
	[doc_documento.gasto].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.gasto].id_usuario_creo as id_usuario_creo,
	[doc_documento.gasto].fechaModificacion as fechaModificacion,
	[doc_documento.gasto].fechaCreacion as fechaCreacion,
	[doc_documento.gasto].active as active,
	[doc_documento.gasto].[documento.gasto] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento.gasto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.gasto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.gasto].[id_usuario_creo]
	where ' + @p_filtro)
END
