[doc_documento_ordenCompra_seg_usuario_enUso].[id_usuario] as [doc_documento_ordenCompra_seg_usuario_enUso_id_usuario],
[doc_documento_ordenCompra_seg_usuario_enUso].[habilitado] as [doc_documento_ordenCompra_seg_usuario_enUso_habilitado],
