[doc_documento_ot].[cmm] AS [doc_documento_ot_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.ot]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.ot].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.ot].[id_usuario_creo]
	INNER JOIN [gen_tipoServicio] ON [gen_tipoServicio].id=[doc_documento.ot].[id_tipoServicio]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[doc_documento.ot].[id_equipo]
	INNER JOIN [seg_usuario] AS [seg_usuario_coordinador] ON [seg_usuario_coordinador].id=[doc_documento.ot].[id_usuario_coordinador]
	INNER JOIN [ort_motivoCancelacion] ON [ort_motivoCancelacion].id=[doc_documento.ot].[id_motivoCancelacion]
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[doc_documento.ot].[id_sucursal]
	INNER JOIN [cat_sistema] ON [cat_sistema].id=[doc_documento.ot].[id_sistema]
	INNER JOIN [ort_departamentoSolicitud] ON [ort_departamentoSolicitud].id=[doc_documento.ot].[id_departamentoSolicitud]
	INNER JOIN [gen_zona] ON [gen_zona].id=[doc_documento.ot].[id_zona]
	INNER JOIN [doc_documento.contrato] ON [doc_documento.contrato].id=[doc_documento.ot].[id_documento.contrato]
	INNER JOIN [doc_documento] aS [doc_documento_contrato] ON [doc_documento.contrato].id = [doc_documento_contrato].id
	INNER JOIN [doc_documento] aS [doc_documento_ot] ON [doc_documento.ot].id = [doc_documento_ot].id
	INNER JOIN [doc_subtipoDocumento]as [doc_documento_ot_doc_subtipoDocumento] ON [doc_documento_ot_doc_subtipoDocumento].id=[doc_documento_ot].[id_subtipoDocumento]
	INNER JOIN [ter_tercero]as [doc_documento_ot_ter_tercero_cliente] ON [doc_documento_ot_ter_tercero_cliente].id=[doc_documento_ot].[id_tercero_cliente]
	INNER JOIN [doc_documento]as [doc_documento_ot_doc_documento_padre] ON [doc_documento_ot_doc_documento_padre].id=[doc_documento_ot].[id_documento]
	INNER JOIN [ter_tercero]as [doc_documento_ot_ter_tercero_proveedor] ON [doc_documento_ot_ter_tercero_proveedor].id=[doc_documento_ot].[id_tercero_proveedor]
	INNER JOIN [doc_prioridadDocumento]as [doc_documento_ot_doc_prioridadDocumento] ON [doc_documento_ot_doc_prioridadDocumento].id=[doc_documento_ot].[id_prioridadDocumento]
	INNER JOIN [gen_moneda]as [doc_documento_ot_gen_moneda] ON [doc_documento_ot_gen_moneda].id=[doc_documento_ot].[id_moneda]
	INNER JOIN [doc_estadoTipoDocumento]as [doc_documento_ot_doc_estadoTipoDocumento] ON [doc_documento_ot_doc_estadoTipoDocumento].id=[doc_documento_ot].[id_estadoTipoDocumento]
	INNER JOIN [doc_motivoestado]as [doc_documento_ot_doc_motivoestado] ON [doc_documento_ot_doc_motivoestado].id=[doc_documento_ot].[id_motivoestado]
	INNER JOIN [seg_usuario]as [doc_documento_ot_seg_usuario_asignado] ON [doc_documento_ot_seg_usuario_asignado].id=[doc_documento_ot].[id_usuario_asignado]
	INNER JOIN [seg_usuario]as [doc_documento_ot_seg_usuario_enUso] ON [doc_documento_ot_seg_usuario_enUso].id=[doc_documento_ot].[id_usuario_enUso]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.ot].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documento.ot].active=1
