CREATE PROCEDURE [upd_doc_documento_ot]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_active bit = null,
		@p_documento_ot varchar(300) = null,
		@p_motivoServicio varchar(8000) = null,
		@p_enTaller bit = null,
		@p_diagnosticoInicial varchar(8000) = null,
		@p_contacto varchar(100) = null,
		@p_cargo varchar(100) = null,
		@p_telefono varchar(100) = null,
		@p_fax varchar(100) = null,
		@p_email varchar(100) = null,
		@p_direccionUbicacion varchar(300) = null,
		@p_duracionEstimada float = null,
		@p_fechaGarantia_ff smalldatetime = null,
		@p_fechaCompromiso_fh smalldatetime = null,
		@p_trabajos varchar(8000) = null,
		@p_recomendaciones varchar(8000) = null,
		@p_compromisos varchar(8000) = null,
		@p_reclamacionFabrica varchar(100) = null,
		@p_porcentajeCliente float = null,
		@p_porcentajeDistribuidor float = null,
		@p_porcentajeFabricante float = null,
		@p_segunTempario bit = null,
		@p_distribuyeCentros bit = null,
		@p_id_tipoServicio int = null,
		@p_id_equipo int = null,
		@p_id_usuario_coordinador int = null,
		@p_id_motivoCancelacion int = null,
		@p_id_sucursal int = null,
		@p_id_sistema int = null,
		@p_id_departamentoSolicitud int = null,
		@p_id_zona int = null,
		@p_id_documento_contrato int = null,
		@p_cmm varchar(300) = null,
		@p_documento_codigo varchar(100),
		@p_documento_numero int,
		@p_prefijo varchar(10),
		@p_subtotal float,
		@p_descuento float,
		@p_iva float,
		@p_total float,
		@p_costo float,
		@p_rentabilidad float,
		@p_trm float,
		@p_fecha_fh smalldatetime,
		@p_fechaSugerida_fh smalldatetime,
		@p_fechaCierre_ff smalldatetime,
		@p_fechaLimite_fh smalldatetime,
		@p_id_subtipoDocumento int,
		@p_id_tercero_cliente int,
		@p_id_documento int,
		@p_id_tercero_proveedor int,
		@p_id_prioridadDocumento int,
		@p_id_moneda int,
		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_subtotalPlaneado float,
		@p_descuentoPlaneado float,
		@p_ivaPlaneado float,
		@p_totalPlaneado float,
		@p_costoPlaneado float,
		@p_id_usuario_asignado int,
		@p_id_usuario_enUso int,
		@p_identificador varchar(25),
		@p_cmm varchar(300)
AS
BEGIN
exec [upd_doc_documento]
			@p_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_fechaCreacion,
			@p_documento_ot,
			@p_documento_codigo,
			@p_documento_numero,
			@p_prefijo,
			@p_subtotal,
			@p_descuento,
			@p_iva,
			@p_total,
			@p_costo,
			@p_rentabilidad,
			@p_trm,
			@p_fecha_fh,
			@p_fechaSugerida_fh,
			@p_fechaCierre_ff,
			@p_fechaLimite_fh,
			@p_id_subtipoDocumento,
			@p_id_tercero_cliente,
			@p_id_documento,
			@p_id_tercero_proveedor,
			@p_id_prioridadDocumento,
			@p_id_moneda,
			@p_id_estadoTipoDocumento,
			@p_id_motivoestado,
			@p_subtotalPlaneado,
			@p_descuentoPlaneado,
			@p_ivaPlaneado,
			@p_totalPlaneado,
			@p_costoPlaneado,
			@p_id_usuario_asignado,
			@p_id_usuario_enUso,
			@p_identificador,
			@p_cmm
	UPDATE [doc_documento.ot]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[fechaCreacion] = isnull(@p_fechaCreacion,[fechaCreacion]),
			[documento.ot] = isnull(@p_documento_ot,[documento.ot]),
			[motivoServicio] = isnull(@p_motivoServicio,[motivoServicio]),
			[enTaller] = isnull(@p_enTaller,[enTaller]),
			[diagnosticoInicial] = isnull(@p_diagnosticoInicial,[diagnosticoInicial]),
			[contacto] = isnull(@p_contacto,[contacto]),
			[cargo] = isnull(@p_cargo,[cargo]),
			[telefono] = isnull(@p_telefono,[telefono]),
			[fax] = isnull(@p_fax,[fax]),
			[email] = isnull(@p_email,[email]),
			[direccionUbicacion] = isnull(@p_direccionUbicacion,[direccionUbicacion]),
			[duracionEstimada] = isnull(@p_duracionEstimada,[duracionEstimada]),
			[fechaGarantia_ff] = isnull(@p_fechaGarantia_ff,[fechaGarantia_ff]),
			[fechaCompromiso_fh] = isnull(@p_fechaCompromiso_fh,[fechaCompromiso_fh]),
			[trabajos] = isnull(@p_trabajos,[trabajos]),
			[recomendaciones] = isnull(@p_recomendaciones,[recomendaciones]),
			[compromisos] = isnull(@p_compromisos,[compromisos]),
			[reclamacionFabrica] = isnull(@p_reclamacionFabrica,[reclamacionFabrica]),
			[porcentajeCliente] = isnull(@p_porcentajeCliente,[porcentajeCliente]),
			[porcentajeDistribuidor] = isnull(@p_porcentajeDistribuidor,[porcentajeDistribuidor]),
			[porcentajeFabricante] = isnull(@p_porcentajeFabricante,[porcentajeFabricante]),
			[segunTempario] = isnull(@p_segunTempario,[segunTempario]),
			[distribuyeCentros] = isnull(@p_distribuyeCentros,[distribuyeCentros]),
			[id_tipoServicio] = isnull(@p_id_tipoServicio,[id_tipoServicio]),
			[id_equipo] = isnull(@p_id_equipo,[id_equipo]),
			[id_usuario_coordinador] = isnull(@p_id_usuario_coordinador,[id_usuario_coordinador]),
			[id_motivoCancelacion] = isnull(@p_id_motivoCancelacion,[id_motivoCancelacion]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[id_sistema] = isnull(@p_id_sistema,[id_sistema]),
			[id_departamentoSolicitud] = isnull(@p_id_departamentoSolicitud,[id_departamentoSolicitud]),
			[id_zona] = isnull(@p_id_zona,[id_zona]),
			[id_documento.contrato] = isnull(@p_id_documento_contrato,[id_documento.contrato]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
