GO
CREATE PROCEDURE [ins_doc_documento_ot]
		@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_ot varchar(300),
		@p_motivoServicio varchar(8000),
		@p_enTaller bit,
		@p_diagnosticoInicial varchar(8000),
		@p_contacto varchar(100),
		@p_cargo varchar(100),
		@p_telefono varchar(100),
		@p_fax varchar(100),
		@p_email varchar(100),
		@p_direccionUbicacion varchar(300),
		@p_duracionEstimada float,
		@p_fechaGarantia_ff smalldatetime,
		@p_fechaCompromiso_fh smalldatetime,
		@p_trabajos varchar(8000),
		@p_recomendaciones varchar(8000),
		@p_compromisos varchar(8000),
		@p_reclamacionFabrica varchar(100),
		@p_porcentajeCliente float,
		@p_porcentajeDistribuidor float,
		@p_porcentajeFabricante float,
		@p_segunTempario bit,
		@p_distribuyeCentros bit,
		@p_id_tipoServicio int,
		@p_id_equipo int,
		@p_id_usuario_coordinador int,
		@p_id_motivoCancelacion int,
		@p_id_sucursal int,
		@p_id_sistema int,
		@p_id_departamentoSolicitud int,
		@p_id_zona int,
		@p_id_documento_contrato int,
		@p_cmm varchar(300),
		@p_documento_codigo varchar(100),
		@p_documento_numero int,
		@p_prefijo varchar(10),
		@p_subtotal float,
		@p_descuento float,
		@p_iva float,
		@p_total float,
		@p_costo float,
		@p_rentabilidad float,
		@p_trm float,
		@p_fecha_fh smalldatetime,
		@p_fechaSugerida_fh smalldatetime,
		@p_fechaCierre_ff smalldatetime,
		@p_fechaLimite_fh smalldatetime,
		@p_id_subtipoDocumento int,
		@p_id_tercero_cliente int,
		@p_id_documento int,
		@p_id_tercero_proveedor int,
		@p_id_prioridadDocumento int,
		@p_id_moneda int,
		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_subtotalPlaneado float,
		@p_descuentoPlaneado float,
		@p_ivaPlaneado float,
		@p_totalPlaneado float,
		@p_costoPlaneado float,
		@p_id_usuario_asignado int,
		@p_id_usuario_enUso int,
		@p_identificador varchar(25),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
exec @v_id = [ins_doc_documento]
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_documento_ot,
			@p_documento_codigo,
			@p_documento_numero,
			@p_prefijo,
			@p_subtotal,
			@p_descuento,
			@p_iva,
			@p_total,
			@p_costo,
			@p_rentabilidad,
			@p_trm,
			@p_fecha_fh,
			@p_fechaSugerida_fh,
			@p_fechaCierre_ff,
			@p_fechaLimite_fh,
			@p_id_subtipoDocumento,
			@p_id_tercero_cliente,
			@p_id_documento,
			@p_id_tercero_proveedor,
			@p_id_prioridadDocumento,
			@p_id_moneda,
			@p_id_estadoTipoDocumento,
			@p_id_motivoestado,
			@p_subtotalPlaneado,
			@p_descuentoPlaneado,
			@p_ivaPlaneado,
			@p_totalPlaneado,
			@p_costoPlaneado,
			@p_id_usuario_asignado,
			@p_id_usuario_enUso,
			@p_identificador,
			@p_cmm		
INSERT INTO [doc_documento.ot]
			([id],
			[uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.ot],
			[motivoServicio],
			[enTaller],
			[diagnosticoInicial],
			[contacto],
			[cargo],
			[telefono],
			[fax],
			[email],
			[direccionUbicacion],
			[duracionEstimada],
			[fechaGarantia_ff],
			[fechaCompromiso_fh],
			[trabajos],
			[recomendaciones],
			[compromisos],
			[reclamacionFabrica],
			[porcentajeCliente],
			[porcentajeDistribuidor],
			[porcentajeFabricante],
			[segunTempario],
			[distribuyeCentros],
			[id_tipoServicio],
			[id_equipo],
			[id_usuario_coordinador],
			[id_motivoCancelacion],
			[id_sucursal],
			[id_sistema],
			[id_departamentoSolicitud],
			[id_zona],
			[id_documento.contrato],
			[cmm])
		VALUES( @v_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_ot,
			@p_motivoServicio,
			@p_enTaller,
			@p_diagnosticoInicial,
			@p_contacto,
			@p_cargo,
			@p_telefono,
			@p_fax,
			@p_email,
			@p_direccionUbicacion,
			@p_duracionEstimada,
			@p_fechaGarantia_ff,
			@p_fechaCompromiso_fh,
			@p_trabajos,
			@p_recomendaciones,
			@p_compromisos,
			@p_reclamacionFabrica,
			@p_porcentajeCliente,
			@p_porcentajeDistribuidor,
			@p_porcentajeFabricante,
			@p_segunTempario,
			@p_distribuyeCentros,
			@p_id_tipoServicio,
			@p_id_equipo,
			@p_id_usuario_coordinador,
			@p_id_motivoCancelacion,
			@p_id_sucursal,
			@p_id_sistema,
			@p_id_departamentoSolicitud,
			@p_id_zona,
			@p_id_documento_contrato,
			@p_cmm)
UPDATE [doc_documento.ot] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
END
GO
