AS
BEGIN
exec(	'SELECT [doc_documento.ot].id as id_tabla,
	[doc_documento.ot].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.ot].id_usuario_creo as id_usuario_creo,
	[doc_documento.ot].fechaModificacion as fechaModificacion,
	[doc_documento.ot].fechaCreacion as fechaCreacion,
	[doc_documento.ot].active as active,
	[doc_documento.ot].[documento.ot] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento.ot]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.ot].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.ot].[id_usuario_creo]
	where ' + @p_filtro)
END
