	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.ot_centroCosto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.ot_centroCosto].[id_usuario_creo]
	INNER JOIN [doc_centroCosto] ON [doc_centroCosto].id=[doc_documento.ot_centroCosto].[id_centroCosto]
	INNER JOIN [doc_documento.ot] ON [doc_documento.ot].id=[doc_documento.ot_centroCosto].[id_documento.ot]
	INNER JOIN [doc_documento] aS [doc_documento_ot] ON [doc_documento.ot].id = [doc_documento_ot].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.ot_centroCosto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
