IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_documento_ot_centroCosto]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_documento_ot_centroCosto]
GO
CREATE PROCEDURE [ins_doc_documento_ot_centroCosto]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_ot_centroCosto varchar(300),
		@p_porcentaje float,
		@p_id_centroCosto int,
		@p_id_documento_ot int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento.ot_centroCosto]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.ot_centroCosto],
			[porcentaje],
			[id_centroCosto],
			[id_documento.ot],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_ot_centroCosto,
			@p_porcentaje,
			@p_id_centroCosto,
			@p_id_documento_ot,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento.ot_centroCosto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
