		[doc_documento_ot].[documento_codigo] AS [doc_documento_ot_documento_codigo],
		[doc_documento_ot].[documento_numero] AS [doc_documento_ot_documento_numero],
		[doc_documento_ot].[prefijo] AS [doc_documento_ot_prefijo],
		[doc_documento_ot].[subtotal] AS [doc_documento_ot_subtotal],
		[doc_documento_ot].[descuento] AS [doc_documento_ot_descuento],
		[doc_documento_ot].[iva] AS [doc_documento_ot_iva],
		[doc_documento_ot].[total] AS [doc_documento_ot_total],
		[doc_documento_ot].[costo] AS [doc_documento_ot_costo],
		[doc_documento_ot].[rentabilidad] AS [doc_documento_ot_rentabilidad],
		[doc_documento_ot].[trm] AS [doc_documento_ot_trm],
		[doc_documento_ot].[fecha_fh] AS [doc_documento_ot_fecha_fh],
		[doc_documento_ot].[fechaSugerida_fh] AS [doc_documento_ot_fechaSugerida_fh],
		[doc_documento_ot].[fechaCierre_ff] AS [doc_documento_ot_fechaCierre_ff],
		[doc_documento_ot].[fechaLimite_fh] AS [doc_documento_ot_fechaLimite_fh],
		[doc_documento_ot].[id_subtipoDocumento] AS [doc_documento_ot_id_subtipoDocumento],
		[doc_documento_ot].[id_tercero_cliente] AS [doc_documento_ot_id_tercero_cliente],
		[doc_documento_ot].[id_documento] AS [doc_documento_ot_id_documento],
		[doc_documento_ot].[id_tercero_proveedor] AS [doc_documento_ot_id_tercero_proveedor],
		[doc_documento_ot].[id_prioridadDocumento] AS [doc_documento_ot_id_prioridadDocumento],
		[doc_documento_ot].[id_moneda] AS [doc_documento_ot_id_moneda],
		[doc_documento_ot].[id_estadoTipoDocumento] AS [doc_documento_ot_id_estadoTipoDocumento],
		[doc_documento_ot].[id_motivoestado] AS [doc_documento_ot_id_motivoestado],
		[doc_documento_ot].[subtotalPlaneado] AS [doc_documento_ot_subtotalPlaneado],
		[doc_documento_ot].[descuentoPlaneado] AS [doc_documento_ot_descuentoPlaneado],
		[doc_documento_ot].[ivaPlaneado] AS [doc_documento_ot_ivaPlaneado],
		[doc_documento_ot].[totalPlaneado] AS [doc_documento_ot_totalPlaneado],
		[doc_documento_ot].[costoPlaneado] AS [doc_documento_ot_costoPlaneado],
		[doc_documento_ot].[id_usuario_asignado] AS [doc_documento_ot_id_usuario_asignado],
		[doc_documento_ot].[id_usuario_enUso] AS [doc_documento_ot_id_usuario_enUso],
		[doc_documento_ot].[identificador] AS [doc_documento_ot_identificador],
		[doc_documento_ot].[cmm] AS [doc_documento_ot_cmm],
		[doc_documento.ot_pruebaCheckList].[id_pruebaCheckList] AS [id_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList] as [cat_pruebaCheckList_pruebaCheckList],
[cat_pruebaCheckList].[pruebaCheckList_codigo] as [cat_pruebaCheckList_pruebaCheckList_codigo],
[cat_pruebaCheckList].[activo] as [cat_pruebaCheckList_activo],
[cat_pruebaCheckList].[cmm] as [cat_pruebaCheckList_cmm],
		[doc_documento.ot_pruebaCheckList].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.ot_pruebaCheckList]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.ot_pruebaCheckList].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.ot_pruebaCheckList].[id_usuario_creo]
	INNER JOIN [doc_documento.ot] ON [doc_documento.ot].id=[doc_documento.ot_pruebaCheckList].[id_documento.ot]
	INNER JOIN [doc_documento] aS [doc_documento_ot] ON [doc_documento.ot].id = [doc_documento_ot].id
	INNER JOIN [cat_pruebaCheckList] ON [cat_pruebaCheckList].id=[doc_documento.ot_pruebaCheckList].[id_pruebaCheckList]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.ot_pruebaCheckList].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
