IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_documento_ot_pruebaCheckList]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_documento_ot_pruebaCheckList]
GO
CREATE PROCEDURE [ins_doc_documento_ot_pruebaCheckList]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_ot_pruebaCheckList varchar(300),
		@p_id_documento_ot int,
		@p_id_pruebaCheckList int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento.ot_pruebaCheckList]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.ot_pruebaCheckList],
			[id_documento.ot],
			[id_pruebaCheckList],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_ot_pruebaCheckList,
			@p_id_documento_ot,
			@p_id_pruebaCheckList,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento.ot_pruebaCheckList] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
