[doc_documento_prestamo].[cmm] AS [doc_documento_prestamo_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.prestamo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.prestamo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.prestamo].[id_usuario_creo]
	INNER JOIN [seg_usuario] AS [seg_usuario_entrego] ON [seg_usuario_entrego].id=[doc_documento.prestamo].[id_usuario_entrego]
	INNER JOIN [doc_documento] aS [doc_documento_prestamo] ON [doc_documento.prestamo].id = [doc_documento_prestamo].id
	INNER JOIN [doc_subtipoDocumento]as [doc_documento_prestamo_doc_subtipoDocumento] ON [doc_documento_prestamo_doc_subtipoDocumento].id=[doc_documento_prestamo].[id_subtipoDocumento]
	INNER JOIN [ter_tercero]as [doc_documento_prestamo_ter_tercero_cliente] ON [doc_documento_prestamo_ter_tercero_cliente].id=[doc_documento_prestamo].[id_tercero_cliente]
	INNER JOIN [doc_documento]as [doc_documento_prestamo_doc_documento_padre] ON [doc_documento_prestamo_doc_documento_padre].id=[doc_documento_prestamo].[id_documento]
	INNER JOIN [ter_tercero]as [doc_documento_prestamo_ter_tercero_proveedor] ON [doc_documento_prestamo_ter_tercero_proveedor].id=[doc_documento_prestamo].[id_tercero_proveedor]
	INNER JOIN [doc_prioridadDocumento]as [doc_documento_prestamo_doc_prioridadDocumento] ON [doc_documento_prestamo_doc_prioridadDocumento].id=[doc_documento_prestamo].[id_prioridadDocumento]
	INNER JOIN [gen_moneda]as [doc_documento_prestamo_gen_moneda] ON [doc_documento_prestamo_gen_moneda].id=[doc_documento_prestamo].[id_moneda]
	INNER JOIN [doc_estadoTipoDocumento]as [doc_documento_prestamo_doc_estadoTipoDocumento] ON [doc_documento_prestamo_doc_estadoTipoDocumento].id=[doc_documento_prestamo].[id_estadoTipoDocumento]
	INNER JOIN [doc_motivoestado]as [doc_documento_prestamo_doc_motivoestado] ON [doc_documento_prestamo_doc_motivoestado].id=[doc_documento_prestamo].[id_motivoestado]
	INNER JOIN [seg_usuario]as [doc_documento_prestamo_seg_usuario_asignado] ON [doc_documento_prestamo_seg_usuario_asignado].id=[doc_documento_prestamo].[id_usuario_asignado]
	INNER JOIN [seg_usuario]as [doc_documento_prestamo_seg_usuario_enUso] ON [doc_documento_prestamo_seg_usuario_enUso].id=[doc_documento_prestamo].[id_usuario_enUso]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.prestamo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documento.prestamo].active=1
