[doc_documento_proyecto_seg_usuario_enUso].[identificacion] as [doc_documento_proyecto_seg_usuario_enUso_identificacion],
[doc_documento_proyecto_seg_usuario_enUso].[id_usuario] as [doc_documento_proyecto_seg_usuario_enUso_id_usuario],
[doc_documento_proyecto_seg_usuario_enUso].[habilitado] as [doc_documento_proyecto_seg_usuario_enUso_habilitado],
[doc_documento_proyecto_seg_usuario_enUso].[idDispositivo] as [doc_documento_proyecto_seg_usuario_enUso_idDispositivo],
[doc_documento_proyecto_seg_usuario_enUso].[cmm] as [doc_documento_proyecto_seg_usuario_enUso_cmm],
[doc_documento_proyecto].[identificador] AS [doc_documento_proyecto_identificador],
[doc_documento_proyecto].[cmm] AS [doc_documento_proyecto_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.proyecto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.proyecto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.proyecto].[id_usuario_creo]
	INNER JOIN [doc_documento] aS [doc_documento_proyecto] ON [doc_documento.proyecto].id = [doc_documento_proyecto].id
	INNER JOIN [doc_subtipoDocumento]as [doc_documento_proyecto_doc_subtipoDocumento] ON [doc_documento_proyecto_doc_subtipoDocumento].id=[doc_documento_proyecto].[id_subtipoDocumento]
	INNER JOIN [ter_tercero]as [doc_documento_proyecto_ter_tercero_cliente] ON [doc_documento_proyecto_ter_tercero_cliente].id=[doc_documento_proyecto].[id_tercero_cliente]
	INNER JOIN [doc_documento]as [doc_documento_proyecto_doc_documento_padre] ON [doc_documento_proyecto_doc_documento_padre].id=[doc_documento_proyecto].[id_documento]
	INNER JOIN [ter_tercero]as [doc_documento_proyecto_ter_tercero_proveedor] ON [doc_documento_proyecto_ter_tercero_proveedor].id=[doc_documento_proyecto].[id_tercero_proveedor]
	INNER JOIN [doc_prioridadDocumento]as [doc_documento_proyecto_doc_prioridadDocumento] ON [doc_documento_proyecto_doc_prioridadDocumento].id=[doc_documento_proyecto].[id_prioridadDocumento]
	INNER JOIN [gen_moneda]as [doc_documento_proyecto_gen_moneda] ON [doc_documento_proyecto_gen_moneda].id=[doc_documento_proyecto].[id_moneda]
	INNER JOIN [doc_estadoTipoDocumento]as [doc_documento_proyecto_doc_estadoTipoDocumento] ON [doc_documento_proyecto_doc_estadoTipoDocumento].id=[doc_documento_proyecto].[id_estadoTipoDocumento]
	INNER JOIN [doc_motivoestado]as [doc_documento_proyecto_doc_motivoestado] ON [doc_documento_proyecto_doc_motivoestado].id=[doc_documento_proyecto].[id_motivoestado]
	INNER JOIN [seg_usuario]as [doc_documento_proyecto_seg_usuario_asignado] ON [doc_documento_proyecto_seg_usuario_asignado].id=[doc_documento_proyecto].[id_usuario_asignado]
	INNER JOIN [seg_usuario]as [doc_documento_proyecto_seg_usuario_enUso] ON [doc_documento_proyecto_seg_usuario_enUso].id=[doc_documento_proyecto].[id_usuario_enUso]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.proyecto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documento.proyecto].active=1
GO
