GO
CREATE PROCEDURE [ins_doc_documento_proyecto]
		@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_proyecto varchar(300),
		@p_nombre varchar(500),
		@p_fechaInicioEstimada smalldatetime,
		@p_fechaFinEstimada smalldatetime,
		@p_descripcion varchar(2000),
		@p_presupuesto money,
		@p_cmm varchar(300),
		@p_documento_codigo varchar(100),
		@p_documento_numero int,
		@p_prefijo varchar(10),
		@p_subtotal float,
		@p_descuento float,
		@p_iva float,
		@p_total float,
		@p_costo float,
		@p_rentabilidad float,
		@p_trm float,
		@p_fecha_fh smalldatetime,
		@p_fechaSugerida_fh smalldatetime,
		@p_fechaCierre_ff smalldatetime,
		@p_fechaLimite_fh smalldatetime,
		@p_id_subtipoDocumento int,
		@p_id_tercero_cliente int,
		@p_id_documento int,
		@p_id_tercero_proveedor int,
		@p_id_prioridadDocumento int,
		@p_id_moneda int,
		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_subtotalPlaneado float,
		@p_descuentoPlaneado float,
		@p_ivaPlaneado float,
		@p_totalPlaneado float,
		@p_costoPlaneado float,
		@p_id_usuario_asignado int,
		@p_id_usuario_enUso int,
		@p_identificador varchar(25),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
exec @v_id = [ins_doc_documento]
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			@p_documento_proyecto,
			@p_documento_codigo,
			@p_documento_numero,
			@p_prefijo,
			@p_subtotal,
			@p_descuento,
			@p_iva,
			@p_total,
			@p_costo,
			@p_rentabilidad,
			@p_trm,
			@p_fecha_fh,
			@p_fechaSugerida_fh,
			@p_fechaCierre_ff,
			@p_fechaLimite_fh,
			@p_id_subtipoDocumento,
			@p_id_tercero_cliente,
			@p_id_documento,
			@p_id_tercero_proveedor,
			@p_id_prioridadDocumento,
			@p_id_moneda,
			@p_id_estadoTipoDocumento,
			@p_id_motivoestado,
			@p_subtotalPlaneado,
			@p_descuentoPlaneado,
			@p_ivaPlaneado,
			@p_totalPlaneado,
			@p_costoPlaneado,
			@p_id_usuario_asignado,
			@p_id_usuario_enUso,
			@p_identificador,
			@p_cmm		
INSERT INTO [doc_documento.proyecto]
			([id],
			[uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.proyecto],
			[nombre],
			[fechaInicioEstimada],
			[fechaFinEstimada],
			[descripcion],
			[presupuesto],
			[cmm])
		VALUES( @v_id,
			@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_proyecto,
			@p_nombre,
			@p_fechaInicioEstimada,
			@p_fechaFinEstimada,
			@p_descripcion,
			@p_presupuesto,
			@p_cmm)
UPDATE [doc_documento.proyecto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
END
