CREATE PROCEDURE [aud_doc_documento_proyecto]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento.proyecto].id as id_tabla,
	[doc_documento.proyecto].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.proyecto].id_usuario_creo as id_usuario_creo,
	[doc_documento.proyecto].fechaModificacion as fechaModificacion,
	[doc_documento.proyecto].fechaCreacion as fechaCreacion,
	[doc_documento.proyecto].active as active,
	[doc_documento.proyecto].[documento.proyecto] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

