GO
CREATE PROCEDURE [ins_doc_documento_proyecto_calidad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_proyecto_calidad varchar(300),
		@p_id_calidad int,
		@p_id_documento_proyecto int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento.proyecto_calidad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.proyecto_calidad],
			[id_calidad],
			[id_documento.proyecto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_proyecto_calidad,
			@p_id_calidad,
			@p_id_documento_proyecto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento.proyecto_calidad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
