IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_documento_proyecto_ejecutores]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_documento_proyecto_ejecutores]
GO
CREATE PROCEDURE [ins_doc_documento_proyecto_ejecutores]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_proyecto_ejecutores varchar(300),
		@p_id_ejecutores int,
		@p_id_documento_proyecto int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento.proyecto_ejecutores]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.proyecto_ejecutores],
			[id_ejecutores],
			[id_documento.proyecto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_proyecto_ejecutores,
			@p_id_ejecutores,
			@p_id_documento_proyecto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento.proyecto_ejecutores] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
