IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_documento_proyecto_entregable]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_documento_proyecto_entregable]
GO
CREATE PROCEDURE [ins_doc_documento_proyecto_entregable]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_proyecto_entregable varchar(300),
		@p_id_documento_proyecto int,
		@p_id_entregable int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento.proyecto_entregable]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.proyecto_entregable],
			[id_documento.proyecto],
			[id_entregable],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_proyecto_entregable,
			@p_id_documento_proyecto,
			@p_id_entregable,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento.proyecto_entregable] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
