		[doc_documento.proyecto_etapa].[eid] AS [eid],
		[doc_documento.proyecto_etapa].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_documento.proyecto_etapa].[id_usuario_creo] AS [id_usuario_creo],
		[doc_documento.proyecto_etapa].[fechaModificacion] AS [fechaModificacion],
		[doc_documento.proyecto_etapa].[fechaCreacion] AS [fechaCreacion],
		[doc_documento.proyecto_etapa].[active] AS [active],
		[doc_documento.proyecto_etapa].[documento.proyecto_etapa] AS [documento.proyecto_etapa],
		[doc_documento.proyecto_etapa].[id_etapa] AS [id_etapa],
[pro_etapa].[etapa] as [pro_etapa_etapa],
[pro_etapa].[etapa_codigo] as [pro_etapa_etapa_codigo],
[pro_etapa].[descripcion] as [pro_etapa_descripcion],
[pro_etapa].[fechaInicioPlaneada_ff] as [pro_etapa_fechaInicioPlaneada_ff],
[pro_etapa].[fechaInicioProyectada_ff] as [pro_etapa_fechaInicioProyectada_ff],
[pro_etapa].[fechaInicioReal_ff] as [pro_etapa_fechaInicioReal_ff],
[pro_etapa].[fechaFinPlaneada_ff] as [pro_etapa_fechaFinPlaneada_ff],
[pro_etapa].[fechaFinProyectada_ff] as [pro_etapa_fechaFinProyectada_ff],
[pro_etapa].[fechaFinReal_ff] as [pro_etapa_fechaFinReal_ff],
[pro_etapa].[orden] as [pro_etapa_orden],
[pro_etapa].[completado] as [pro_etapa_completado],
[pro_etapa].[porcentajePresupuesto] as [pro_etapa_porcentajePresupuesto],
[pro_etapa].[valorPresupuesto] as [pro_etapa_valorPresupuesto],
