[pro_etapa].[fechaInicioProyectada] as [pro_etapa_fechaInicioProyectada],
[pro_etapa].[fechaInicioReal] as [pro_etapa_fechaInicioReal],
[pro_etapa].[fechaFinPlaneada] as [pro_etapa_fechaFinPlaneada],
[pro_etapa].[fechaFinProyectada] as [pro_etapa_fechaFinProyectada],
[pro_etapa].[fechaFinReal] as [pro_etapa_fechaFinReal],
[pro_etapa].[cmm] as [pro_etapa_cmm],
		[doc_documento.proyecto_etapa].[id_documento.proyecto] AS [id_documento.proyecto],
[doc_documento.proyecto].[documento.proyecto] as [doc_documento.proyecto_documento.proyecto],
[doc_documento.proyecto].[nombre] as [doc_documento.proyecto_nombre],
[doc_documento.proyecto].[fechaInicioEstimada] as [doc_documento.proyecto_fechaInicioEstimada],
[doc_documento.proyecto].[fechaFinEstimada] as [doc_documento.proyecto_fechaFinEstimada],
[doc_documento.proyecto].[descripcion] as [doc_documento.proyecto_descripcion],
[doc_documento.proyecto].[presupuesto] as [doc_documento.proyecto_presupuesto],
[doc_documento.proyecto].[cmm] as [doc_documento.proyecto_cmm],
		[doc_documento_proyecto].[documento_codigo] AS [doc_documento_proyecto_documento_codigo],
		[doc_documento_proyecto].[documento_numero] AS [doc_documento_proyecto_documento_numero],
		[doc_documento_proyecto].[prefijo] AS [doc_documento_proyecto_prefijo],
		[doc_documento_proyecto].[subtotal] AS [doc_documento_proyecto_subtotal],
		[doc_documento_proyecto].[descuento] AS [doc_documento_proyecto_descuento],
		[doc_documento_proyecto].[iva] AS [doc_documento_proyecto_iva],
		[doc_documento_proyecto].[total] AS [doc_documento_proyecto_total],
		[doc_documento_proyecto].[costo] AS [doc_documento_proyecto_costo],
		[doc_documento_proyecto].[rentabilidad] AS [doc_documento_proyecto_rentabilidad],
		[doc_documento_proyecto].[trm] AS [doc_documento_proyecto_trm],
		[doc_documento_proyecto].[fecha_fh] AS [doc_documento_proyecto_fecha_fh],
		[doc_documento_proyecto].[fechaSugerida_fh] AS [doc_documento_proyecto_fechaSugerida_fh],
		[doc_documento_proyecto].[fechaCierre_ff] AS [doc_documento_proyecto_fechaCierre_ff],
		[doc_documento_proyecto].[fechaLimite_fh] AS [doc_documento_proyecto_fechaLimite_fh],
		[doc_documento_proyecto].[id_subtipoDocumento] AS [doc_documento_proyecto_id_subtipoDocumento],
		[doc_documento_proyecto].[id_tercero_cliente] AS [doc_documento_proyecto_id_tercero_cliente],
		[doc_documento_proyecto].[id_documento] AS [doc_documento_proyecto_id_documento],
		[doc_documento_proyecto].[id_tercero_proveedor] AS [doc_documento_proyecto_id_tercero_proveedor],
		[doc_documento_proyecto].[id_prioridadDocumento] AS [doc_documento_proyecto_id_prioridadDocumento],
		[doc_documento_proyecto].[id_moneda] AS [doc_documento_proyecto_id_moneda],
		[doc_documento_proyecto].[id_estadoTipoDocumento] AS [doc_documento_proyecto_id_estadoTipoDocumento],
		[doc_documento_proyecto].[id_motivoestado] AS [doc_documento_proyecto_id_motivoestado],
		[doc_documento_proyecto].[subtotalPlaneado] AS [doc_documento_proyecto_subtotalPlaneado],
		[doc_documento_proyecto].[descuentoPlaneado] AS [doc_documento_proyecto_descuentoPlaneado],
		[doc_documento_proyecto].[ivaPlaneado] AS [doc_documento_proyecto_ivaPlaneado],
		[doc_documento_proyecto].[totalPlaneado] AS [doc_documento_proyecto_totalPlaneado],
		[doc_documento_proyecto].[costoPlaneado] AS [doc_documento_proyecto_costoPlaneado],
		[doc_documento_proyecto].[id_usuario_asignado] AS [doc_documento_proyecto_id_usuario_asignado],
		[doc_documento_proyecto].[id_usuario_enUso] AS [doc_documento_proyecto_id_usuario_enUso],
		[doc_documento_proyecto].[identificador] AS [doc_documento_proyecto_identificador],
		[doc_documento_proyecto].[cmm] AS [doc_documento_proyecto_cmm],
		[doc_documento.proyecto_etapa].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.proyecto_etapa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.proyecto_etapa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.proyecto_etapa].[id_usuario_creo]
	INNER JOIN [pro_etapa] ON [pro_etapa].id=[doc_documento.proyecto_etapa].[id_etapa]
	INNER JOIN [doc_documento.proyecto] ON [doc_documento.proyecto].id=[doc_documento.proyecto_etapa].[id_documento.proyecto]
	INNER JOIN [doc_documento] aS [doc_documento_proyecto] ON [doc_documento.proyecto].id = [doc_documento_proyecto].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.proyecto_etapa].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
