CREATE PROCEDURE [upd_doc_documento_proyecto_etapa]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_documento_proyecto_etapa varchar(300) = null,
		@p_id_etapa int = null,
		@p_id_documento_proyecto int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
