	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento.proyecto_etapa].id as id_tabla,
	[doc_documento.proyecto_etapa].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.proyecto_etapa].id_usuario_creo as id_usuario_creo,
	[doc_documento.proyecto_etapa].fechaModificacion as fechaModificacion,
	[doc_documento.proyecto_etapa].fechaCreacion as fechaCreacion,
	[doc_documento.proyecto_etapa].active as active,
	[doc_documento.proyecto_etapa].[documento.proyecto_etapa] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento.proyecto_etapa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.proyecto_etapa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.proyecto_etapa].[id_usuario_creo]
	where ' + @p_filtro)
END
