		[doc_documento_proyecto].[costoPlaneado] AS [doc_documento_proyecto_costoPlaneado],
		[doc_documento_proyecto].[id_usuario_asignado] AS [doc_documento_proyecto_id_usuario_asignado],
		[doc_documento_proyecto].[id_usuario_enUso] AS [doc_documento_proyecto_id_usuario_enUso],
		[doc_documento_proyecto].[identificador] AS [doc_documento_proyecto_identificador],
		[doc_documento_proyecto].[cmm] AS [doc_documento_proyecto_cmm],
		[doc_documento.proyecto_sucursal].[id_sucursal] AS [id_sucursal],
[ter_sucursal].[sucursal] as [ter_sucursal_sucursal],
[ter_sucursal].[sucursal_codigo] as [ter_sucursal_sucursal_codigo],
[ter_sucursal].[contacto] as [ter_sucursal_contacto],
[ter_sucursal].[telefono] as [ter_sucursal_telefono],
[ter_sucursal].[Fax] as [ter_sucursal_Fax],
[ter_sucursal].[Email] as [ter_sucursal_Email],
[ter_sucursal].[Direccion] as [ter_sucursal_Direccion],
[ter_sucursal].[paraVenta] as [ter_sucursal_paraVenta],
[ter_sucursal].[paraSoporte] as [ter_sucursal_paraSoporte],
[ter_sucursal].[paraAlquiler] as [ter_sucursal_paraAlquiler],
[ter_sucursal].[id_tercero] as [ter_sucursal_id_tercero],
[ter_sucursal].[id_zona] as [ter_sucursal_id_zona],
[ter_sucursal].[id_usuario_asesor] as [ter_sucursal_id_usuario_asesor],
[ter_sucursal].[id_usuario_tecnico] as [ter_sucursal_id_usuario_tecnico],
[ter_sucursal].[id_sucursal] as [ter_sucursal_id_sucursal],
[ter_sucursal].[id_estadoTercero] as [ter_sucursal_id_estadoTercero],
[ter_sucursal].[codigorecursiva] as [ter_sucursal_codigorecursiva],
[ter_sucursal].[cargo] as [ter_sucursal_cargo],
[ter_sucursal].[cmm] as [ter_sucursal_cmm],
		[doc_documento.proyecto_sucursal].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.proyecto_sucursal]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.proyecto_sucursal].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.proyecto_sucursal].[id_usuario_creo]
	INNER JOIN [doc_documento.proyecto] ON [doc_documento.proyecto].id=[doc_documento.proyecto_sucursal].[id_documento.proyecto]
	INNER JOIN [doc_documento] aS [doc_documento_proyecto] ON [doc_documento.proyecto].id = [doc_documento_proyecto].id
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[doc_documento.proyecto_sucursal].[id_sucursal]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.proyecto_sucursal].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
