	INNER JOIN [seg_usuario] AS [seg_usuario_recibe] ON [seg_usuario_recibe].id=[doc_documento.salida].[id_usuario_recibe]
	INNER JOIN [ter_tercero] AS [ter_tercero_transportador] ON [ter_tercero_transportador].id=[doc_documento.salida].[id_tercero_transportador]
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[doc_documento.salida].[id_sucursal]
	INNER JOIN [doc_documento] aS [doc_documento_salida] ON [doc_documento.salida].id = [doc_documento_salida].id
	INNER JOIN [doc_subtipoDocumento]as [doc_documento_salida_doc_subtipoDocumento] ON [doc_documento_salida_doc_subtipoDocumento].id=[doc_documento_salida].[id_subtipoDocumento]
	INNER JOIN [ter_tercero]as [doc_documento_salida_ter_tercero_cliente] ON [doc_documento_salida_ter_tercero_cliente].id=[doc_documento_salida].[id_tercero_cliente]
	INNER JOIN [doc_documento]as [doc_documento_salida_doc_documento_padre] ON [doc_documento_salida_doc_documento_padre].id=[doc_documento_salida].[id_documento]
	INNER JOIN [ter_tercero]as [doc_documento_salida_ter_tercero_proveedor] ON [doc_documento_salida_ter_tercero_proveedor].id=[doc_documento_salida].[id_tercero_proveedor]
	INNER JOIN [doc_prioridadDocumento]as [doc_documento_salida_doc_prioridadDocumento] ON [doc_documento_salida_doc_prioridadDocumento].id=[doc_documento_salida].[id_prioridadDocumento]
	INNER JOIN [gen_moneda]as [doc_documento_salida_gen_moneda] ON [doc_documento_salida_gen_moneda].id=[doc_documento_salida].[id_moneda]
	INNER JOIN [doc_estadoTipoDocumento]as [doc_documento_salida_doc_estadoTipoDocumento] ON [doc_documento_salida_doc_estadoTipoDocumento].id=[doc_documento_salida].[id_estadoTipoDocumento]
	INNER JOIN [doc_motivoestado]as [doc_documento_salida_doc_motivoestado] ON [doc_documento_salida_doc_motivoestado].id=[doc_documento_salida].[id_motivoestado]
	INNER JOIN [seg_usuario]as [doc_documento_salida_seg_usuario_asignado] ON [doc_documento_salida_seg_usuario_asignado].id=[doc_documento_salida].[id_usuario_asignado]
	INNER JOIN [seg_usuario]as [doc_documento_salida_seg_usuario_enUso] ON [doc_documento_salida_seg_usuario_enUso].id=[doc_documento_salida].[id_usuario_enUso]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.salida].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documento.salida].active=1
GO
