		[active] AS [active],
		[documento.solicitud] AS [documento.solicitud],
		[email] AS [email],
		[fax] AS [fax],
		[telefono] AS [telefono],
		[solicitante] AS [solicitante],
		[motivoServicio] AS [motivoServicio],
		[solucionTelefonica] AS [solucionTelefonica],
		[id_departamentoSolicitud] AS [id_departamentoSolicitud],
		[id_medioSolicitud] AS [id_medioSolicitud],
		[id_equipo] AS [id_equipo],
		[id_sucursal] AS [id_sucursal],
		[id_zona] AS [id_zona],
		[cargo] AS [cargo],
		[direccion] AS [direccion],
		[cmm] AS [cmm]
	FROM [doc_documento.solicitud]
