CREATE PROCEDURE [lis_doc_documento_solicitudes_m]
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT id AS id,
[documento.solicitud] AS [doc_documento.solicitud]
	FROM [doc_documento.solicitud]
	WHERE active = 1
	AND	(eid LIKE @p_eid+'%')
END
