IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[aud_doc_documento_solicitud]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[aud_doc_documento_solicitud]
GO
CREATE PROCEDURE [aud_doc_documento_solicitud]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento.solicitud].id as id_tabla,
	[doc_documento.solicitud].id_usuario_modifico as id_usuario_modifico,
	[doc_documento.solicitud].id_usuario_creo as id_usuario_creo,
	[doc_documento.solicitud].fechaModificacion as fechaModificacion,
	[doc_documento.solicitud].fechaCreacion as fechaCreacion,
	[doc_documento.solicitud].active as active,
	[doc_documento.solicitud].[documento.solicitud] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento.solicitud]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.solicitud].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.solicitud].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
SET QUOTED_IDENTIFIER OFF 
GO
SET ANSI_NULLS ON
GO
