		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[documento.traslado] AS [documento.traslado],
		[id_bodega_origen] AS [id_bodega_origen],
		[id_bodega_destino] AS [id_bodega_destino],
		[cmm] AS [cmm]
	FROM [doc_documento.traslado]
	WHERE	(id = @p_id)

END
