[doc_documento_traslado].[cmm] AS [doc_documento_traslado_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento.traslado]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento.traslado].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento.traslado].[id_usuario_creo]
	INNER JOIN [gen_bodega] AS [gen_bodega_origen] ON [gen_bodega_origen].id=[doc_documento.traslado].[id_bodega_origen]
	INNER JOIN [gen_bodega] AS [gen_bodega_destino] ON [gen_bodega_destino].id=[doc_documento.traslado].[id_bodega_destino]
	INNER JOIN [doc_documento] aS [doc_documento_traslado] ON [doc_documento.traslado].id = [doc_documento_traslado].id
	INNER JOIN [doc_subtipoDocumento]as [doc_documento_traslado_doc_subtipoDocumento] ON [doc_documento_traslado_doc_subtipoDocumento].id=[doc_documento_traslado].[id_subtipoDocumento]
	INNER JOIN [ter_tercero]as [doc_documento_traslado_ter_tercero_cliente] ON [doc_documento_traslado_ter_tercero_cliente].id=[doc_documento_traslado].[id_tercero_cliente]
	INNER JOIN [doc_documento]as [doc_documento_traslado_doc_documento_padre] ON [doc_documento_traslado_doc_documento_padre].id=[doc_documento_traslado].[id_documento]
	INNER JOIN [ter_tercero]as [doc_documento_traslado_ter_tercero_proveedor] ON [doc_documento_traslado_ter_tercero_proveedor].id=[doc_documento_traslado].[id_tercero_proveedor]
	INNER JOIN [doc_prioridadDocumento]as [doc_documento_traslado_doc_prioridadDocumento] ON [doc_documento_traslado_doc_prioridadDocumento].id=[doc_documento_traslado].[id_prioridadDocumento]
	INNER JOIN [gen_moneda]as [doc_documento_traslado_gen_moneda] ON [doc_documento_traslado_gen_moneda].id=[doc_documento_traslado].[id_moneda]
	INNER JOIN [doc_estadoTipoDocumento]as [doc_documento_traslado_doc_estadoTipoDocumento] ON [doc_documento_traslado_doc_estadoTipoDocumento].id=[doc_documento_traslado].[id_estadoTipoDocumento]
	INNER JOIN [doc_motivoestado]as [doc_documento_traslado_doc_motivoestado] ON [doc_documento_traslado_doc_motivoestado].id=[doc_documento_traslado].[id_motivoestado]
	INNER JOIN [seg_usuario]as [doc_documento_traslado_seg_usuario_asignado] ON [doc_documento_traslado_seg_usuario_asignado].id=[doc_documento_traslado].[id_usuario_asignado]
	INNER JOIN [seg_usuario]as [doc_documento_traslado_seg_usuario_enUso] ON [doc_documento_traslado_seg_usuario_enUso].id=[doc_documento_traslado].[id_usuario_enUso]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento.traslado].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documento.traslado].active=1
