FROM [doc_documento_catalogo.tempario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento_catalogo.tempario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento_catalogo.tempario].[id_usuario_creo]
	INNER JOIN [cat_catalogo.tempario] ON [cat_catalogo.tempario].id=[doc_documento_catalogo.tempario].[id_catalogo.tempario]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_tempario] ON [cat_catalogo.tempario].id = [cat_catalogo_tempario].id
	INNER JOIN [doc_documento] ON [doc_documento].id=[doc_documento_catalogo.tempario].[id_documento]
	INNER JOIN [doc_itemDocumento] ON [doc_itemDocumento].id=[doc_documento_catalogo.tempario].[id_itemDocumento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento_catalogo.tempario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
