		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[documento_catalogo.tempario] AS [documento_catalogo.tempario],
		[id_catalogo.tempario] AS [id_catalogo.tempario],
		[id_documento] AS [id_documento],
		[id_itemDocumento] AS [id_itemDocumento],
		[cmm] AS [cmm]
	FROM [doc_documento_catalogo.tempario]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
