GO
CREATE PROCEDURE [upd_doc_documento_estadoTipoDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_documento_estadoTipoDocumento varchar(300) = null,
		@p_notas varchar(300) = null,
		@p_id_documento int = null,
		@p_id_estadoTipoDocumento int = null,
		@p_id_motivoestado int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_documento_estadoTipoDocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[documento_estadoTipoDocumento] = isnull(@p_documento_estadoTipoDocumento,[documento_estadoTipoDocumento]),
			[notas] = isnull(@p_notas,[notas]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[id_estadoTipoDocumento] = isnull(@p_id_estadoTipoDocumento,[id_estadoTipoDocumento]),
			[id_motivoestado] = isnull(@p_id_motivoestado,[id_motivoestado]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
