IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_documento_estadoTipoDocumento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_documento_estadoTipoDocumento]
GO
CREATE PROCEDURE [ins_doc_documento_estadoTipoDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_estadoTipoDocumento varchar(300),
		@p_notas varchar(300),
		@p_id_documento int,
		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento_estadoTipoDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento_estadoTipoDocumento],
			[notas],
			[id_documento],
			[id_estadoTipoDocumento],
			[id_motivoestado],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_estadoTipoDocumento,
			@p_notas,
			@p_id_documento,
			@p_id_estadoTipoDocumento,
			@p_id_motivoestado,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento_estadoTipoDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
