		[doc_documento_opcionRespuesta].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documento_opcionRespuesta]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento_opcionRespuesta].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento_opcionRespuesta].[id_usuario_creo]
	INNER JOIN [doc_documento] ON [doc_documento].id=[doc_documento_opcionRespuesta].[id_documento]
	INNER JOIN [doc_opcionRespuesta] ON [doc_opcionRespuesta].id=[doc_documento_opcionRespuesta].[id_opcionRespuesta]
	INNER JOIN [doc_pregunta] ON [doc_pregunta].id=[doc_documento_opcionRespuesta].[id_pregunta]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documento_opcionRespuesta].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
