		@p_id_opcionRespuesta int,
		@p_id_pregunta int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento_opcionRespuesta]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento_opcionRespuesta],
			[id_documento],
			[id_opcionRespuesta],
			[id_pregunta],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_opcionRespuesta,
			@p_id_documento,
			@p_id_opcionRespuesta,
			@p_id_pregunta,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento_opcionRespuesta] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
