	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documento_opcionRespuesta].id as id_tabla,
	[doc_documento_opcionRespuesta].id_usuario_modifico as id_usuario_modifico,
	[doc_documento_opcionRespuesta].id_usuario_creo as id_usuario_creo,
	[doc_documento_opcionRespuesta].fechaModificacion as fechaModificacion,
	[doc_documento_opcionRespuesta].fechaCreacion as fechaCreacion,
	[doc_documento_opcionRespuesta].active as active,
	[doc_documento_opcionRespuesta].[documento_opcionRespuesta] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documento_opcionRespuesta]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documento_opcionRespuesta].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documento_opcionRespuesta].[id_usuario_creo]
	where ' + @p_filtro)
END
