CREATE PROCEDURE [aud_doc_documentoAtributo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documentoAtributo].id as id_tabla,
	[doc_documentoAtributo].id_usuario_modifico as id_usuario_modifico,
	[doc_documentoAtributo].id_usuario_creo as id_usuario_creo,
	[doc_documentoAtributo].fechaModificacion as fechaModificacion,
	[doc_documentoAtributo].fechaCreacion as fechaCreacion,
	[doc_documentoAtributo].active as active,
	[doc_documentoAtributo].[documentoAtributo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documentoAtributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documentoAtributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documentoAtributo].[id_usuario_creo]
	where ' + @p_filtro)
END
