[ter_contacto].[cargo] as [ter_contacto_cargo],
[ter_contacto].[codigoAcceso] as [ter_contacto_codigoAcceso],
[ter_contacto].[id_cargoContacto] as [ter_contacto_id_cargoContacto],
[ter_contacto].[accesoActivo] as [ter_contacto_accesoActivo],
[ter_contacto].[ter_cargoContacto_id_usuario_Modifico] as [ter_contacto_ter_cargoContacto_id_usuario_Modifico],
[ter_contacto].[ter_cargoContacto_id_usuario_Creo] as [ter_contacto_ter_cargoContacto_id_usuario_Creo],
[ter_contacto].[cmm] as [ter_contacto_cmm],
		[doc_documentoComentario].[fechaOrden] AS [fechaOrden],
		[doc_documentoComentario].[fechaOriginal] AS [fechaOriginal],
		[doc_documentoComentario].[id_usuarioOriginal] AS [id_usuarioOriginal],
		[doc_documentoComentario].[conRespuesta] AS [conRespuesta],
		[doc_documentoComentario].[relevante] AS [relevante],
		[doc_documentoComentario].[id_reporteTecnico] AS [id_reporteTecnico],
[ort_reporteTecnico].[reporteTecnico] as [ort_reporteTecnico_reporteTecnico],
[ort_reporteTecnico].[reporteTecnico_codigo] as [ort_reporteTecnico_reporteTecnico_codigo],
[ort_reporteTecnico].[numero] as [ort_reporteTecnico_numero],
[ort_reporteTecnico].[trabajos] as [ort_reporteTecnico_trabajos],
[ort_reporteTecnico].[recomendaciones] as [ort_reporteTecnico_recomendaciones],
[ort_reporteTecnico].[compromisos] as [ort_reporteTecnico_compromisos],
[ort_reporteTecnico].[id_canalAtencion] as [ort_reporteTecnico_id_canalAtencion],
[ort_reporteTecnico].[diagnostico] as [ort_reporteTecnico_diagnostico],
[ort_reporteTecnico].[id_documento.gasto] as [ort_reporteTecnico_id_documento.gasto],
[ort_reporteTecnico].[cmm] as [ort_reporteTecnico_cmm],
[ort_reporteTecnico].[desde_fh] as [ort_reporteTecnico_desde_fh],
[ort_reporteTecnico].[duracion] as [ort_reporteTecnico_duracion],
[ort_reporteTecnico].[id_reporteTecnico] as [ort_reporteTecnico_id_reporteTecnico],
		[doc_documentoComentario].[finalizado] AS [finalizado],
		[doc_documentoComentario].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_documentoComentario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documentoComentario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documentoComentario].[id_usuario_creo]
	INNER JOIN [doc_documento] ON [doc_documento].id=[doc_documentoComentario].[id_documento]
	INNER JOIN [seg_usuario] ON [seg_usuario].id=[doc_documentoComentario].[id_usuario]
	INNER JOIN [doc_tarea] ON [doc_tarea].id=[doc_documentoComentario].[id_tarea]
	INNER JOIN [doc_documentoComentario] AS [doc_documentoComentario_padre] ON [doc_documentoComentario_padre].id=[doc_documentoComentario].[id_documentoComentario]
	INNER JOIN [ter_contacto] ON [ter_contacto].id=[doc_documentoComentario].[id_contacto]
	INNER JOIN [ort_reporteTecnico] ON [ort_reporteTecnico].id=[doc_documentoComentario].[id_reporteTecnico]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_documentoComentario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_documentoComentario].active=1
GO
