GO
CREATE PROCEDURE [upd_doc_documentoComentario]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_documentoComentario varchar(300) = null,
		@p_documentoComentario_codigo varchar(100) = null,
		@p_comentario varchar(8000) = null,
		@p_recordar bit = null,
		@p_id_documento int = null,
		@p_id_usuario int = null,
		@p_id_tarea int = null,
		@p_fechaRecordar_fh smalldatetime = null,
		@p_cerrada bit = null,
		@p_id_documentoComentario int = null,
		@p_id_contacto int = null,
		@p_fechaOrden smalldatetime = null,
		@p_fechaOriginal smalldatetime = null,
		@p_id_usuarioOriginal int = null,
		@p_conRespuesta int = null,
		@p_relevante int = null,
		@p_id_reporteTecnico int = null,
		@p_finalizado int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_documentoComentario]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[documentoComentario] = isnull(@p_documentoComentario,[documentoComentario]),
			[documentoComentario_codigo] = isnull(@p_documentoComentario_codigo,[documentoComentario_codigo]),
			[comentario] = isnull(@p_comentario,[comentario]),
			[recordar] = isnull(@p_recordar,[recordar]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[id_tarea] = isnull(@p_id_tarea,[id_tarea]),
			[fechaRecordar_fh] = isnull(@p_fechaRecordar_fh,[fechaRecordar_fh]),
			[cerrada] = isnull(@p_cerrada,[cerrada]),
			[id_documentoComentario] = isnull(@p_id_documentoComentario,[id_documentoComentario]),
			[id_contacto] = isnull(@p_id_contacto,[id_contacto]),
			[fechaOrden] = isnull(@p_fechaOrden,[fechaOrden]),
			[fechaOriginal] = isnull(@p_fechaOriginal,[fechaOriginal]),
			[id_usuarioOriginal] = isnull(@p_id_usuarioOriginal,[id_usuarioOriginal]),
			[conRespuesta] = isnull(@p_conRespuesta,[conRespuesta]),
			[relevante] = isnull(@p_relevante,[relevante]),
			[id_reporteTecnico] = isnull(@p_id_reporteTecnico,[id_reporteTecnico]),
			[finalizado] = isnull(@p_finalizado,[finalizado]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
