IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_documentoComentario]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_documentoComentario]
GO
CREATE PROCEDURE [ins_doc_documentoComentario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documentoComentario varchar(300),
		@p_documentoComentario_codigo varchar(100),
		@p_comentario varchar(8000),
		@p_recordar bit,
		@p_id_documento int,
		@p_id_usuario int,
		@p_id_tarea int,
		@p_fechaRecordar_fh smalldatetime,
		@p_cerrada bit,
		@p_id_documentoComentario int,
		@p_id_contacto int,
		@p_fechaOrden smalldatetime,
		@p_fechaOriginal smalldatetime,
		@p_id_usuarioOriginal int,
		@p_conRespuesta int,
		@p_relevante int,
		@p_id_reporteTecnico int,
		@p_finalizado int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documentoComentario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documentoComentario],
			[documentoComentario_codigo],
			[comentario],
			[recordar],
			[id_documento],
			[id_usuario],
			[id_tarea],
			[fechaRecordar_fh],
			[cerrada],
			[id_documentoComentario],
			[id_contacto],
			[fechaOrden],
			[fechaOriginal],
			[id_usuarioOriginal],
			[conRespuesta],
			[relevante],
			[id_reporteTecnico],
			[finalizado],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documentoComentario,
			@p_documentoComentario_codigo,
			@p_comentario,
			@p_recordar,
			@p_id_documento,
			@p_id_usuario,
			@p_id_tarea,
			@p_fechaRecordar_fh,
			@p_cerrada,
			@p_id_documentoComentario,
			@p_id_contacto,
			@p_fechaOrden,
			@p_fechaOriginal,
			@p_id_usuarioOriginal,
			@p_conRespuesta,
			@p_relevante,
			@p_id_reporteTecnico,
			@p_finalizado,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documentoComentario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
