CREATE PROCEDURE [reg_doc_documentoComentario_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[documentoComentario] AS [documentoComentario],
		[documentoComentario_codigo] AS [documentoComentario_codigo],
		[comentario] AS [comentario],
		[recordar] AS [recordar],
		[id_documento] AS [id_documento],
		[id_usuario] AS [id_usuario],
		[id_tarea] AS [id_tarea],
		[fechaRecordar_fh] AS [fechaRecordar_fh],
		[cerrada] AS [cerrada],
		[id_documentoComentario] AS [id_documentoComentario],
		[id_contacto] AS [id_contacto],
		[fechaOrden] AS [fechaOrden],
		[fechaOriginal] AS [fechaOriginal],
		[id_usuarioOriginal] AS [id_usuarioOriginal],
		[conRespuesta] AS [conRespuesta],
		[relevante] AS [relevante],
		[id_reporteTecnico] AS [id_reporteTecnico],
		[finalizado] AS [finalizado],
		[cmm] AS [cmm]
	FROM [doc_documentoComentario]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
