CREATE PROCEDURE [aud_doc_documentoComentario]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_documentoComentario].id as id_tabla,
	[doc_documentoComentario].id_usuario_modifico as id_usuario_modifico,
	[doc_documentoComentario].id_usuario_creo as id_usuario_creo,
	[doc_documentoComentario].fechaModificacion as fechaModificacion,
	[doc_documentoComentario].fechaCreacion as fechaCreacion,
	[doc_documentoComentario].active as active,
	[doc_documentoComentario].[documentoComentario] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_documentoComentario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_documentoComentario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_documentoComentario].[id_usuario_creo]
	where ' + @p_filtro)
END
