CREATE  VIEW [view_doc_estadoTipoDocumento] AS
SELECT 	[doc_estadoTipoDocumento].[id] AS [id],
		[doc_estadoTipoDocumento].[uid] AS [uid],
		[doc_estadoTipoDocumento].[eid] AS [eid],
		[doc_estadoTipoDocumento].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_estadoTipoDocumento].[id_usuario_creo] AS [id_usuario_creo],
		[doc_estadoTipoDocumento].[fechaModificacion] AS [fechaModificacion],
		[doc_estadoTipoDocumento].[fechaCreacion] AS [fechaCreacion],
		[doc_estadoTipoDocumento].[active] AS [active],
		[doc_estadoTipoDocumento].[estadoTipoDocumento] AS [estadoTipoDocumento],
		[doc_estadoTipoDocumento].[estadoTipoDocumento_codigo] AS [estadoTipoDocumento_codigo],
		[doc_estadoTipoDocumento].[afectaIndicador] AS [afectaIndicador],
		[doc_estadoTipoDocumento].[editaDocumento] AS [editaDocumento],
		[doc_estadoTipoDocumento].[orden] AS [orden],
		[doc_estadoTipoDocumento].[puedeRegresar] AS [puedeRegresar],
		[doc_estadoTipoDocumento].[color] AS [color],
		[doc_estadoTipoDocumento].[afectaInventario] AS [afectaInventario],
		[doc_estadoTipoDocumento].[id_tipoDocumento] AS [id_tipoDocumento],
[doc_tipoDocumento].[tipoDocumento] as [doc_tipoDocumento_tipoDocumento],
[doc_tipoDocumento].[tipoDocumento_codigo] as [doc_tipoDocumento_tipoDocumento_codigo],
[doc_tipoDocumento].[esSalida] as [doc_tipoDocumento_esSalida],
[doc_tipoDocumento].[mostrarBodega] as [doc_tipoDocumento_mostrarBodega],
[doc_tipoDocumento].[mostrarCentroCosto] as [doc_tipoDocumento_mostrarCentroCosto],
[doc_tipoDocumento].[mostrarIncoterm] as [doc_tipoDocumento_mostrarIncoterm],
[doc_tipoDocumento].[puedeSerMayor] as [doc_tipoDocumento_puedeSerMayor],
[doc_tipoDocumento].[puedeSerMenor] as [doc_tipoDocumento_puedeSerMenor],
[doc_tipoDocumento].[esUrgente] as [doc_tipoDocumento_esUrgente],
[doc_tipoDocumento].[cmm] as [doc_tipoDocumento_cmm],
		[doc_estadoTipoDocumento].[descripcion] AS [descripcion],
		[doc_estadoTipoDocumento].[observacionesObligatorio] AS [observacionesObligatorio],
		[doc_estadoTipoDocumento].[motivoObligatorio] AS [motivoObligatorio],
		[doc_estadoTipoDocumento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_estadoTipoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_estadoTipoDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_estadoTipoDocumento].[id_usuario_creo]
	INNER JOIN [doc_tipoDocumento] ON [doc_tipoDocumento].id=[doc_estadoTipoDocumento].[id_tipoDocumento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_estadoTipoDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_estadoTipoDocumento].active=1
