		@p_id_estadoTipoDocumento int,
		@p_id_motivoestado int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento_estadoTipoDocumento]
			([uid],
