GO
CREATE  VIEW [view_doc_estadoTipoDocumento_perfil] AS
SELECT 	[doc_estadoTipoDocumento_perfil].[id] AS [id],
		[doc_estadoTipoDocumento_perfil].[uid] AS [uid],
		[doc_estadoTipoDocumento_perfil].[eid] AS [eid],
		[doc_estadoTipoDocumento_perfil].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_estadoTipoDocumento_perfil].[id_usuario_creo] AS [id_usuario_creo],
		[doc_estadoTipoDocumento_perfil].[fechaModificacion] AS [fechaModificacion],
		[doc_estadoTipoDocumento_perfil].[fechaCreacion] AS [fechaCreacion],
		[doc_estadoTipoDocumento_perfil].[active] AS [active],
		[doc_estadoTipoDocumento_perfil].[estadoTipoDocumento_perfil] AS [estadoTipoDocumento_perfil],
		[doc_estadoTipoDocumento_perfil].[id_estadoTipoDocumento] AS [id_estadoTipoDocumento],
[doc_estadoTipoDocumento].[estadoTipoDocumento] as [doc_estadoTipoDocumento_estadoTipoDocumento],
[doc_estadoTipoDocumento].[estadoTipoDocumento_codigo] as [doc_estadoTipoDocumento_estadoTipoDocumento_codigo],
[doc_estadoTipoDocumento].[afectaIndicador] as [doc_estadoTipoDocumento_afectaIndicador],
[doc_estadoTipoDocumento].[editaDocumento] as [doc_estadoTipoDocumento_editaDocumento],
[doc_estadoTipoDocumento].[orden] as [doc_estadoTipoDocumento_orden],
[doc_estadoTipoDocumento].[puedeRegresar] as [doc_estadoTipoDocumento_puedeRegresar],
[doc_estadoTipoDocumento].[color] as [doc_estadoTipoDocumento_color],
[doc_estadoTipoDocumento].[afectaInventario] as [doc_estadoTipoDocumento_afectaInventario],
[doc_estadoTipoDocumento].[id_tipoDocumento] as [doc_estadoTipoDocumento_id_tipoDocumento],
[doc_estadoTipoDocumento].[descripcion] as [doc_estadoTipoDocumento_descripcion],
[doc_estadoTipoDocumento].[observacionesObligatorio] as [doc_estadoTipoDocumento_observacionesObligatorio],
[doc_estadoTipoDocumento].[motivoObligatorio] as [doc_estadoTipoDocumento_motivoObligatorio],
[doc_estadoTipoDocumento].[cmm] as [doc_estadoTipoDocumento_cmm],
		[doc_estadoTipoDocumento_perfil].[id_perfil] AS [id_perfil],
[seg_perfil].[perfil] as [seg_perfil_perfil],
[seg_perfil].[perfil_codigo] as [seg_perfil_perfil_codigo],
[seg_perfil].[descripcion] as [seg_perfil_descripcion],
[seg_perfil].[mostrarBotones] as [seg_perfil_mostrarBotones],
[seg_perfil].[paraCliente] as [seg_perfil_paraCliente],
[seg_perfil].[paraProveedor] as [seg_perfil_paraProveedor],
[seg_perfil].[cmm] as [seg_perfil_cmm],
		[doc_estadoTipoDocumento_perfil].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_estadoTipoDocumento_perfil]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_estadoTipoDocumento_perfil].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_estadoTipoDocumento_perfil].[id_usuario_creo]
	INNER JOIN [doc_estadoTipoDocumento] ON [doc_estadoTipoDocumento].id=[doc_estadoTipoDocumento_perfil].[id_estadoTipoDocumento]
	INNER JOIN [seg_perfil] ON [seg_perfil].id=[doc_estadoTipoDocumento_perfil].[id_perfil]
