CREATE PROCEDURE [upd_doc_estadoTipoDocumento_perfil]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_estadoTipoDocumento_perfil varchar(300) = null,
		@p_id_estadoTipoDocumento int = null,
		@p_id_perfil int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_estadoTipoDocumento_perfil]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[estadoTipoDocumento_perfil] = isnull(@p_estadoTipoDocumento_perfil,[estadoTipoDocumento_perfil]),
			[id_estadoTipoDocumento] = isnull(@p_id_estadoTipoDocumento,[id_estadoTipoDocumento]),
			[id_perfil] = isnull(@p_id_perfil,[id_perfil]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
