IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_estadoTipoDocumento_perfil]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_estadoTipoDocumento_perfil]
GO
CREATE PROCEDURE [ins_doc_estadoTipoDocumento_perfil]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_estadoTipoDocumento_perfil varchar(300),
		@p_id_estadoTipoDocumento int,
		@p_id_perfil int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_estadoTipoDocumento_perfil]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[estadoTipoDocumento_perfil],
			[id_estadoTipoDocumento],
			[id_perfil],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_estadoTipoDocumento_perfil,
			@p_id_estadoTipoDocumento,
			@p_id_perfil,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_estadoTipoDocumento_perfil] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
