CREATE PROCEDURE [aud_doc_estadoTipoDocumento_perfil]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_estadoTipoDocumento_perfil].id as id_tabla,
	[doc_estadoTipoDocumento_perfil].id_usuario_modifico as id_usuario_modifico,
	[doc_estadoTipoDocumento_perfil].id_usuario_creo as id_usuario_creo,
	[doc_estadoTipoDocumento_perfil].fechaModificacion as fechaModificacion,
	[doc_estadoTipoDocumento_perfil].fechaCreacion as fechaCreacion,
	[doc_estadoTipoDocumento_perfil].active as active,
	[doc_estadoTipoDocumento_perfil].[estadoTipoDocumento_perfil] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_estadoTipoDocumento_perfil]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_estadoTipoDocumento_perfil].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_estadoTipoDocumento_perfil].[id_usuario_creo]
	where ' + @p_filtro)
END
