[doc_estadoTipoDocumento_destino].[estadoTipoDocumento] as [doc_estadoTipoDocumento_destino_estadoTipoDocumento],
[doc_estadoTipoDocumento_destino].[estadoTipoDocumento_codigo] as [doc_estadoTipoDocumento_destino_estadoTipoDocumento_codigo],
[doc_estadoTipoDocumento_destino].[afectaIndicador] as [doc_estadoTipoDocumento_destino_afectaIndicador],
[doc_estadoTipoDocumento_destino].[editaDocumento] as [doc_estadoTipoDocumento_destino_editaDocumento],
[doc_estadoTipoDocumento_destino].[orden] as [doc_estadoTipoDocumento_destino_orden],
[doc_estadoTipoDocumento_destino].[puedeRegresar] as [doc_estadoTipoDocumento_destino_puedeRegresar],
[doc_estadoTipoDocumento_destino].[color] as [doc_estadoTipoDocumento_destino_color],
[doc_estadoTipoDocumento_destino].[afectaInventario] as [doc_estadoTipoDocumento_destino_afectaInventario],
[doc_estadoTipoDocumento_destino].[id_tipoDocumento] as [doc_estadoTipoDocumento_destino_id_tipoDocumento],
[doc_estadoTipoDocumento_destino].[descripcion] as [doc_estadoTipoDocumento_destino_descripcion],
[doc_estadoTipoDocumento_destino].[observacionesObligatorio] as [doc_estadoTipoDocumento_destino_observacionesObligatorio],
[doc_estadoTipoDocumento_destino].[motivoObligatorio] as [doc_estadoTipoDocumento_destino_motivoObligatorio],
[doc_estadoTipoDocumento_destino].[cmm] as [doc_estadoTipoDocumento_destino_cmm],
		[doc_estadoTipoDocumento_subtipoDocumento].[sp_ejecucionfinal] AS [sp_ejecucionfinal],
		[doc_estadoTipoDocumento_subtipoDocumento].[tiempoDeEjecucion] AS [tiempoDeEjecucion],
		[doc_estadoTipoDocumento_subtipoDocumento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_estadoTipoDocumento_subtipoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_estadoTipoDocumento_subtipoDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_estadoTipoDocumento_subtipoDocumento].[id_usuario_creo]
	INNER JOIN [doc_estadoTipoDocumento] ON [doc_estadoTipoDocumento].id=[doc_estadoTipoDocumento_subtipoDocumento].[id_estadoTipoDocumento]
	INNER JOIN [doc_subtipoDocumento] ON [doc_subtipoDocumento].id=[doc_estadoTipoDocumento_subtipoDocumento].[id_subtipoDocumento]
	INNER JOIN [doc_estadoTipoDocumento] AS [doc_estadoTipoDocumento_destino] ON [doc_estadoTipoDocumento_destino].id=[doc_estadoTipoDocumento_subtipoDocumento].[id_estadoTipoDocumento_destino]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_estadoTipoDocumento_subtipoDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
