CREATE PROCEDURE [upd_doc_estadoTipoDocumento_subtipoDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_estadoTipoDocumento_subtipoDocumento varchar(300) = null,
		@p_id_estadoTipoDocumento int = null,
		@p_id_subtipoDocumento int = null,
		@p_id_estadoTipoDocumento_destino int = null,
		@p_sp_ejecucionfinal varchar(300) = null,
		@p_tiempoDeEjecucion float = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_estadoTipoDocumento_subtipoDocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[estadoTipoDocumento_subtipoDocumento] = isnull(@p_estadoTipoDocumento_subtipoDocumento,[estadoTipoDocumento_subtipoDocumento]),
			[id_estadoTipoDocumento] = isnull(@p_id_estadoTipoDocumento,[id_estadoTipoDocumento]),
			[id_subtipoDocumento] = isnull(@p_id_subtipoDocumento,[id_subtipoDocumento]),
			[id_estadoTipoDocumento_destino] = isnull(@p_id_estadoTipoDocumento_destino,[id_estadoTipoDocumento_destino]),
			[sp_ejecucionfinal] = isnull(@p_sp_ejecucionfinal,[sp_ejecucionfinal]),
			[tiempoDeEjecucion] = isnull(@p_tiempoDeEjecucion,[tiempoDeEjecucion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
