GO
CREATE PROCEDURE [ins_doc_estadoTipoDocumento_subtipoDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_estadoTipoDocumento_subtipoDocumento varchar(300),
		@p_id_estadoTipoDocumento int,
		@p_id_subtipoDocumento int,
		@p_id_estadoTipoDocumento_destino int,
		@p_sp_ejecucionfinal varchar(300),
		@p_tiempoDeEjecucion float,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_estadoTipoDocumento_subtipoDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[estadoTipoDocumento_subtipoDocumento],
			[id_estadoTipoDocumento],
			[id_subtipoDocumento],
			[id_estadoTipoDocumento_destino],
			[sp_ejecucionfinal],
			[tiempoDeEjecucion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_estadoTipoDocumento_subtipoDocumento,
			@p_id_estadoTipoDocumento,
			@p_id_subtipoDocumento,
			@p_id_estadoTipoDocumento_destino,
			@p_sp_ejecucionfinal,
			@p_tiempoDeEjecucion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_estadoTipoDocumento_subtipoDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
