CREATE PROCEDURE [aud_doc_estadoTipoDocumento_subtipoDocumento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_estadoTipoDocumento_subtipoDocumento].id as id_tabla,
	[doc_estadoTipoDocumento_subtipoDocumento].id_usuario_modifico as id_usuario_modifico,
	[doc_estadoTipoDocumento_subtipoDocumento].id_usuario_creo as id_usuario_creo,
