CREATE  VIEW [view_doc_estrategiaPrioridad] AS
SELECT 	[doc_estrategiaPrioridad].[id] AS [id],
		[doc_estrategiaPrioridad].[uid] AS [uid],
		[doc_estrategiaPrioridad].[eid] AS [eid],
		[doc_estrategiaPrioridad].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_estrategiaPrioridad].[id_usuario_creo] AS [id_usuario_creo],
		[doc_estrategiaPrioridad].[fechaModificacion] AS [fechaModificacion],
		[doc_estrategiaPrioridad].[fechaCreacion] AS [fechaCreacion],
		[doc_estrategiaPrioridad].[active] AS [active],
		[doc_estrategiaPrioridad].[estrategiaPrioridad] AS [estrategiaPrioridad],
		[doc_estrategiaPrioridad].[estrategiaPrioridad_codigo] AS [estrategiaPrioridad_codigo],
		[doc_estrategiaPrioridad].[lunesIni_hh] AS [lunesIni_hh],
		[doc_estrategiaPrioridad].[lunesFin_hh] AS [lunesFin_hh],
		[doc_estrategiaPrioridad].[martesIni_hh] AS [martesIni_hh],
		[doc_estrategiaPrioridad].[martesFin_hh] AS [martesFin_hh],
		[doc_estrategiaPrioridad].[miercolesIni_hh] AS [miercolesIni_hh],
		[doc_estrategiaPrioridad].[miercolesFin_hh] AS [miercolesFin_hh],
		[doc_estrategiaPrioridad].[juevesIni_hh] AS [juevesIni_hh],
		[doc_estrategiaPrioridad].[juevesFin_hh] AS [juevesFin_hh],
		[doc_estrategiaPrioridad].[viernesIni_hh] AS [viernesIni_hh],
		[doc_estrategiaPrioridad].[viernesFin_hh] AS [viernesFin_hh],
		[doc_estrategiaPrioridad].[sabadoIni_hh] AS [sabadoIni_hh],
		[doc_estrategiaPrioridad].[sabadoFin_hh] AS [sabadoFin_hh],
		[doc_estrategiaPrioridad].[domingoIni_hh] AS [domingoIni_hh],
		[doc_estrategiaPrioridad].[domingoFin_hh] AS [domingoFin_hh],
		[doc_estrategiaPrioridad].[festivoIni_hh] AS [festivoIni_hh],
		[doc_estrategiaPrioridad].[festivoFin_hh] AS [festivoFin_hh],
		[doc_estrategiaPrioridad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_estrategiaPrioridad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_estrategiaPrioridad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_estrategiaPrioridad].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_estrategiaPrioridad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_estrategiaPrioridad].active=1
