CREATE PROCEDURE [upd_doc_estrategiaPrioridad]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_estrategiaPrioridad varchar(300) = null,
		@p_estrategiaPrioridad_codigo varchar(100) = null,
		@p_lunesIni_hh smalldatetime = null,
		@p_lunesFin_hh smalldatetime = null,
		@p_martesIni_hh smalldatetime = null,
		@p_martesFin_hh smalldatetime = null,
		@p_miercolesIni_hh smalldatetime = null,
		@p_miercolesFin_hh smalldatetime = null,
		@p_juevesIni_hh smalldatetime = null,
		@p_juevesFin_hh smalldatetime = null,
		@p_viernesIni_hh smalldatetime = null,
		@p_viernesFin_hh smalldatetime = null,
		@p_sabadoIni_hh smalldatetime = null,
		@p_sabadoFin_hh smalldatetime = null,
		@p_domingoIni_hh smalldatetime = null,
		@p_domingoFin_hh smalldatetime = null,
		@p_festivoIni_hh smalldatetime = null,
		@p_festivoFin_hh smalldatetime = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_estrategiaPrioridad]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[estrategiaPrioridad] = isnull(@p_estrategiaPrioridad,[estrategiaPrioridad]),
			[estrategiaPrioridad_codigo] = isnull(@p_estrategiaPrioridad_codigo,[estrategiaPrioridad_codigo]),
			[lunesIni_hh] = isnull(@p_lunesIni_hh,[lunesIni_hh]),
			[lunesFin_hh] = isnull(@p_lunesFin_hh,[lunesFin_hh]),
			[martesIni_hh] = isnull(@p_martesIni_hh,[martesIni_hh]),
			[martesFin_hh] = isnull(@p_martesFin_hh,[martesFin_hh]),
			[miercolesIni_hh] = isnull(@p_miercolesIni_hh,[miercolesIni_hh]),
			[miercolesFin_hh] = isnull(@p_miercolesFin_hh,[miercolesFin_hh]),
			[juevesIni_hh] = isnull(@p_juevesIni_hh,[juevesIni_hh]),
			[juevesFin_hh] = isnull(@p_juevesFin_hh,[juevesFin_hh]),
			[viernesIni_hh] = isnull(@p_viernesIni_hh,[viernesIni_hh]),
			[viernesFin_hh] = isnull(@p_viernesFin_hh,[viernesFin_hh]),
			[sabadoIni_hh] = isnull(@p_sabadoIni_hh,[sabadoIni_hh]),
			[sabadoFin_hh] = isnull(@p_sabadoFin_hh,[sabadoFin_hh]),
			[domingoIni_hh] = isnull(@p_domingoIni_hh,[domingoIni_hh]),
			[domingoFin_hh] = isnull(@p_domingoFin_hh,[domingoFin_hh]),
			[festivoIni_hh] = isnull(@p_festivoIni_hh,[festivoIni_hh]),
			[festivoFin_hh] = isnull(@p_festivoFin_hh,[festivoFin_hh]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
