CREATE PROCEDURE [ins_doc_estrategiaPrioridad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_estrategiaPrioridad varchar(300),
		@p_estrategiaPrioridad_codigo varchar(100),
		@p_lunesIni_hh smalldatetime,
		@p_lunesFin_hh smalldatetime,
		@p_martesIni_hh smalldatetime,
		@p_martesFin_hh smalldatetime,
		@p_miercolesIni_hh smalldatetime,
		@p_miercolesFin_hh smalldatetime,
		@p_juevesIni_hh smalldatetime,
		@p_juevesFin_hh smalldatetime,
		@p_viernesIni_hh smalldatetime,
		@p_viernesFin_hh smalldatetime,
		@p_sabadoIni_hh smalldatetime,
		@p_sabadoFin_hh smalldatetime,
		@p_domingoIni_hh smalldatetime,
		@p_domingoFin_hh smalldatetime,
		@p_festivoIni_hh smalldatetime,
		@p_festivoFin_hh smalldatetime,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_estrategiaPrioridad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[estrategiaPrioridad],
			[estrategiaPrioridad_codigo],
			[lunesIni_hh],
			[lunesFin_hh],
			[martesIni_hh],
			[martesFin_hh],
			[miercolesIni_hh],
			[miercolesFin_hh],
			[juevesIni_hh],
			[juevesFin_hh],
			[viernesIni_hh],
			[viernesFin_hh],
			[sabadoIni_hh],
			[sabadoFin_hh],
			[domingoIni_hh],
			[domingoFin_hh],
			[festivoIni_hh],
			[festivoFin_hh],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_estrategiaPrioridad,
			@p_estrategiaPrioridad_codigo,
			@p_lunesIni_hh,
			@p_lunesFin_hh,
			@p_martesIni_hh,
			@p_martesFin_hh,
			@p_miercolesIni_hh,
			@p_miercolesFin_hh,
			@p_juevesIni_hh,
			@p_juevesFin_hh,
			@p_viernesIni_hh,
			@p_viernesFin_hh,
			@p_sabadoIni_hh,
			@p_sabadoFin_hh,
			@p_domingoIni_hh,
			@p_domingoFin_hh,
			@p_festivoIni_hh,
			@p_festivoFin_hh,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_estrategiaPrioridad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
