IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_evaluacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_evaluacion]
GO
CREATE PROCEDURE [ins_doc_evaluacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_evaluacion varchar(300),
		@p_evaluacion_codigo varchar(100),
		@p_activa bit,
		@p_id_subtipoDocumento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_evaluacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[evaluacion],
			[evaluacion_codigo],
			[activa],
			[id_subtipoDocumento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_evaluacion,
			@p_evaluacion_codigo,
			@p_activa,
			@p_id_subtipoDocumento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_evaluacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
