CREATE PROCEDURE [ins_doc_documento_evaluacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_evaluacion varchar(300),
		@p_personaEncuestada varchar(100),
		@p_fechaEncuesta_ff smalldatetime,
		@p_id_documento int,
		@p_id_evaluacion int,
		@p_observaciones varchar(1000),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento_evaluacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento_evaluacion],
			[personaEncuestada],
			[fechaEncuesta_ff],
			[id_documento],
			[id_evaluacion],
			[observaciones],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_evaluacion,
			@p_personaEncuestada,
			@p_fechaEncuesta_ff,
			@p_id_documento,
			@p_id_evaluacion,
			@p_observaciones,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento_evaluacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
