GO
CREATE PROCEDURE [upd_doc_documento_evaluacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_documento_evaluacion varchar(300) = null,
		@p_personaEncuestada varchar(100) = null,
		@p_fechaEncuesta_ff smalldatetime = null,
		@p_id_documento int = null,
		@p_id_evaluacion int = null,
		@p_observaciones varchar(1000) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_documento_evaluacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[documento_evaluacion] = isnull(@p_documento_evaluacion,[documento_evaluacion]),
			[personaEncuestada] = isnull(@p_personaEncuestada,[personaEncuestada]),
			[fechaEncuesta_ff] = isnull(@p_fechaEncuesta_ff,[fechaEncuesta_ff]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[id_evaluacion] = isnull(@p_id_evaluacion,[id_evaluacion]),
			[observaciones] = isnull(@p_observaciones,[observaciones]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
