CREATE PROCEDURE [upd_doc_flujoDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_flujoDocumento varchar(300) = null,
		@p_flujoDocumento_codigo varchar(100) = null,
		@p_restrictivo bit = null,
		@p_id_subtipoDocumento_origen int = null,
		@p_id_subtipoDocumento_destino int = null,
		@p_id_estadoTipoDocumento_origen int = null,
		@p_id_estadoTipoDocumento_resultado int = null,
		@p_replicarItems int = null,
		@p_replicarAtributos bit = null,
		@p_replicarItemsActividades int = null,
		@p_replicarComentario int = null,
		@p_cmm varchar(300) = null,
		@p_id_flujoFormulario int = null
AS
BEGIN
		UPDATE [doc_flujoDocumento]
