GO
CREATE PROCEDURE [ins_doc_flujoDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_flujoDocumento varchar(300),
		@p_flujoDocumento_codigo varchar(100),
		@p_restrictivo bit,
		@p_id_subtipoDocumento_origen int,
		@p_id_subtipoDocumento_destino int,
		@p_id_estadoTipoDocumento_origen int,
		@p_id_estadoTipoDocumento_resultado int,
		@p_replicarItems int,
		@p_replicarAtributos bit,
		@p_replicarItemsActividades int,
		@p_replicarComentario int,
		@p_cmm varchar(300),
		@p_id_flujoFormulario int
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_flujoDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[flujoDocumento],
			[flujoDocumento_codigo],
			[restrictivo],
			[id_subtipoDocumento_origen],
			[id_subtipoDocumento_destino],
			[id_estadoTipoDocumento_origen],
			[id_estadoTipoDocumento_resultado],
			[replicarItems],
			[replicarAtributos],
			[replicarItemsActividades],
			[replicarComentario],
			[cmm],
			[id_flujoFormulario])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_flujoDocumento,
			@p_flujoDocumento_codigo,
			@p_restrictivo,
			@p_id_subtipoDocumento_origen,
			@p_id_subtipoDocumento_destino,
			@p_id_estadoTipoDocumento_origen,
			@p_id_estadoTipoDocumento_resultado,
			@p_replicarItems,
			@p_replicarAtributos,
			@p_replicarItemsActividades,
			@p_replicarComentario,
			@p_cmm,
			@p_id_flujoFormulario)
		SET @v_id = scope_identity()
UPDATE [doc_flujoDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
