	[doc_flujoDocumento].id_usuario_modifico as id_usuario_modifico,
	[doc_flujoDocumento].id_usuario_creo as id_usuario_creo,
	[doc_flujoDocumento].fechaModificacion as fechaModificacion,
	[doc_flujoDocumento].fechaCreacion as fechaCreacion,
	[doc_flujoDocumento].active as active,
	[doc_flujoDocumento].[flujoDocumento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_flujoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_flujoDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_flujoDocumento].[id_usuario_creo]
	where ' + @p_filtro)
END
