IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_formaPago]')) DROP VIEW [dbo].[view_doc_formaPago]
GO
CREATE  VIEW [view_doc_formaPago] AS
SELECT 	[doc_formaPago].[id] AS [id],
		[doc_formaPago].[uid] AS [uid],
		[doc_formaPago].[eid] AS [eid],
		[doc_formaPago].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_formaPago].[id_usuario_creo] AS [id_usuario_creo],
		[doc_formaPago].[fechaModificacion] AS [fechaModificacion],
		[doc_formaPago].[fechaCreacion] AS [fechaCreacion],
		[doc_formaPago].[active] AS [active],
		[doc_formaPago].[formaPago] AS [formaPago],
		[doc_formaPago].[formaPago_codigo] AS [formaPago_codigo],
		[doc_formaPago].[diasPago] AS [diasPago],
		[doc_formaPago].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_formaPago]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_formaPago].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_formaPago].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_formaPago].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_formaPago].active=1
GO
