IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_formaPago]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_formaPago]
GO
CREATE PROCEDURE [ins_doc_formaPago]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_formaPago varchar(300),
		@p_formaPago_codigo varchar(100),
		@p_diasPago int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_formaPago]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[formaPago],
			[formaPago_codigo],
			[diasPago],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_formaPago,
			@p_formaPago_codigo,
			@p_diasPago,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_formaPago] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
