CREATE PROCEDURE [aud_doc_formaPago]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_formaPago].id as id_tabla,
	[doc_formaPago].id_usuario_modifico as id_usuario_modifico,
	[doc_formaPago].id_usuario_creo as id_usuario_creo,
	[doc_formaPago].fechaModificacion as fechaModificacion,
	[doc_formaPago].fechaCreacion as fechaCreacion,
	[doc_formaPago].active as active,
	[doc_formaPago].[formaPago] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_formaPago]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_formaPago].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_formaPago].[id_usuario_creo]
	where ' + @p_filtro)
END
