IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_incoterm]')) DROP VIEW [dbo].[view_doc_incoterm]
GO
CREATE  VIEW [view_doc_incoterm] AS
SELECT 	[doc_incoterm].[id] AS [id],
		[doc_incoterm].[uid] AS [uid],
		[doc_incoterm].[eid] AS [eid],
		[doc_incoterm].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_incoterm].[id_usuario_creo] AS [id_usuario_creo],
		[doc_incoterm].[fechaModificacion] AS [fechaModificacion],
		[doc_incoterm].[fechaCreacion] AS [fechaCreacion],
		[doc_incoterm].[active] AS [active],
		[doc_incoterm].[incoterm] AS [incoterm],
		[doc_incoterm].[incoterm_codigo] AS [incoterm_codigo],
		[doc_incoterm].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_incoterm]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_incoterm].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_incoterm].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_incoterm].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_incoterm].active=1
GO
