	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_itemDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_itemDocumento].[id_usuario_creo]
	INNER JOIN [doc_documento] ON [doc_documento].id=[doc_itemDocumento].[id_documento]
	INNER JOIN [doc_itemDocumento] AS [doc_itemDocumento_padre] ON [doc_itemDocumento_padre].id=[doc_itemDocumento].[id_itemDocumento]
	INNER JOIN [doc_centroCosto] ON [doc_centroCosto].id=[doc_itemDocumento].[id_centroCosto]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[doc_itemDocumento].[id_catalogo]
	INNER JOIN [gen_bodega] ON [gen_bodega].id=[doc_itemDocumento].[id_bodega]
	INNER JOIN [doc_incoterm] ON [doc_incoterm].id=[doc_itemDocumento].[id_incoterm]
	INNER JOIN [doc_itemDocumento] AS [doc_itemDocumento_superior] ON [doc_itemDocumento_superior].id=[doc_itemDocumento].[id_itemDocumento_superior]
	INNER JOIN [cat_listaPrecio] ON [cat_listaPrecio].id=[doc_itemDocumento].[id_listaprecio]
	INNER JOIN [ort_reporteTecnico] ON [ort_reporteTecnico].id=[doc_itemDocumento].[id_reporteTecnico]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_itemDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_itemDocumento].active=1
GO
