CREATE PROCEDURE [upd_doc_itemDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_itemDocumento varchar(300) = null,
		@p_itemDocumento_codigo varchar(100) = null,
		@p_detalle varchar(300) = null,
		@p_horasOrdinales float = null,
		@p_horasFestivas float = null,
		@p_horasNocturnas float = null,
		@p_cantidadPlaneado float = null,
		@p_cantidadEjecutado float = null,
		@p_valorUnitarioPlaneado money = null,
		@p_valorUnitarioEjecutado money = null,
		@p_subtotalPlaneado money = null,
		@p_subtotalEjecutado money = null,
		@p_totalPlaneado money = null,
		@p_totalEjecutado money = null,
		@p_porciva float = null,
		@p_ivaPlaneado money = null,
		@p_ivaEjecutado money = null,
		@p_porcdto float = null,
		@p_dtoPlaneado money = null,
		@p_dtoEjecutado money = null,
		@p_costear bit = null,
		@p_esUrgente bit = null,
		@p_vencimientoGarantia_ff smalldatetime = null,
		@p_horasGarantia float = null,
		@p_porcentajeCliente float = null,
		@p_porcentajeDistribuidor float = null,
		@p_porcentajeFabricante float = null,
		@p_afectoInventario bit = null,
		@p_id_documento int = null,
		@p_id_itemDocumento int = null,
		@p_id_centroCosto int = null,
		@p_id_catalogo int = null,
		@p_id_bodega int = null,
		@p_id_incoterm int = null,
		@p_id_itemDocumento_superior int = null,
		@p_costoPlaneado float = null,
		@p_costoEjecutado float = null,
		@p_id_listaprecio int = null,
		@p_vrbase float = null,
		@p_vrenlista float = null,
		@p_porcdescuento float = null,
		@p_cantAuxiliar float = null,
		@p_porcentajeMargen float = null,
		@p_margenPlaneado float = null,
		@p_cmm varchar(300) = null,
		@p_id_reporteTecnico int = null
AS
BEGIN
		UPDATE [doc_itemDocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[itemDocumento] = isnull(@p_itemDocumento,[itemDocumento]),
			[itemDocumento_codigo] = isnull(@p_itemDocumento_codigo,[itemDocumento_codigo]),
			[detalle] = isnull(@p_detalle,[detalle]),
			[horasOrdinales] = isnull(@p_horasOrdinales,[horasOrdinales]),
			[horasFestivas] = isnull(@p_horasFestivas,[horasFestivas]),
			[horasNocturnas] = isnull(@p_horasNocturnas,[horasNocturnas]),
			[cantidadPlaneado] = isnull(@p_cantidadPlaneado,[cantidadPlaneado]),
			[cantidadEjecutado] = isnull(@p_cantidadEjecutado,[cantidadEjecutado]),
			[valorUnitarioPlaneado] = isnull(@p_valorUnitarioPlaneado,[valorUnitarioPlaneado]),
			[valorUnitarioEjecutado] = isnull(@p_valorUnitarioEjecutado,[valorUnitarioEjecutado]),
			[subtotalPlaneado] = isnull(@p_subtotalPlaneado,[subtotalPlaneado]),
			[subtotalEjecutado] = isnull(@p_subtotalEjecutado,[subtotalEjecutado]),
			[totalPlaneado] = isnull(@p_totalPlaneado,[totalPlaneado]),
			[totalEjecutado] = isnull(@p_totalEjecutado,[totalEjecutado]),
			[porciva] = isnull(@p_porciva,[porciva]),
			[ivaPlaneado] = isnull(@p_ivaPlaneado,[ivaPlaneado]),
			[ivaEjecutado] = isnull(@p_ivaEjecutado,[ivaEjecutado]),
			[porcdto] = isnull(@p_porcdto,[porcdto]),
			[dtoPlaneado] = isnull(@p_dtoPlaneado,[dtoPlaneado]),
			[dtoEjecutado] = isnull(@p_dtoEjecutado,[dtoEjecutado]),
			[costear] = isnull(@p_costear,[costear]),
			[esUrgente] = isnull(@p_esUrgente,[esUrgente]),
			[vencimientoGarantia_ff] = isnull(@p_vencimientoGarantia_ff,[vencimientoGarantia_ff]),
			[horasGarantia] = isnull(@p_horasGarantia,[horasGarantia]),
			[porcentajeCliente] = isnull(@p_porcentajeCliente,[porcentajeCliente]),
			[porcentajeDistribuidor] = isnull(@p_porcentajeDistribuidor,[porcentajeDistribuidor]),
			[porcentajeFabricante] = isnull(@p_porcentajeFabricante,[porcentajeFabricante]),
			[afectoInventario] = isnull(@p_afectoInventario,[afectoInventario]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[id_itemDocumento] = isnull(@p_id_itemDocumento,[id_itemDocumento]),
			[id_centroCosto] = isnull(@p_id_centroCosto,[id_centroCosto]),
			[id_catalogo] = isnull(@p_id_catalogo,[id_catalogo]),
			[id_bodega] = isnull(@p_id_bodega,[id_bodega]),
			[id_incoterm] = isnull(@p_id_incoterm,[id_incoterm]),
			[id_itemDocumento_superior] = isnull(@p_id_itemDocumento_superior,[id_itemDocumento_superior]),
			[costoPlaneado] = isnull(@p_costoPlaneado,[costoPlaneado]),
			[costoEjecutado] = isnull(@p_costoEjecutado,[costoEjecutado]),
			[id_listaprecio] = isnull(@p_id_listaprecio,[id_listaprecio]),
			[vrbase] = isnull(@p_vrbase,[vrbase]),
			[vrenlista] = isnull(@p_vrenlista,[vrenlista]),
			[porcdescuento] = isnull(@p_porcdescuento,[porcdescuento]),
			[cantAuxiliar] = isnull(@p_cantAuxiliar,[cantAuxiliar]),
			[porcentajeMargen] = isnull(@p_porcentajeMargen,[porcentajeMargen]),
			[margenPlaneado] = isnull(@p_margenPlaneado,[margenPlaneado]),
			[cmm] = isnull(@p_cmm,[cmm]),
			[id_reporteTecnico] = isnull(@p_id_reporteTecnico,[id_reporteTecnico])
		WHERE (id = @p_id)
END
