IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_itemDocumento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_itemDocumento]
GO
CREATE PROCEDURE [ins_doc_itemDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_itemDocumento varchar(300),
		@p_itemDocumento_codigo varchar(100),
		@p_detalle varchar(300),
		@p_horasOrdinales float,
		@p_horasFestivas float,
		@p_horasNocturnas float,
		@p_cantidadPlaneado float,
		@p_cantidadEjecutado float,
		@p_valorUnitarioPlaneado money,
		@p_valorUnitarioEjecutado money,
		@p_subtotalPlaneado money,
		@p_subtotalEjecutado money,
		@p_totalPlaneado money,
		@p_totalEjecutado money,
		@p_porciva float,
		@p_ivaPlaneado money,
		@p_ivaEjecutado money,
		@p_porcdto float,
		@p_dtoPlaneado money,
		@p_dtoEjecutado money,
		@p_costear bit,
		@p_esUrgente bit,
		@p_vencimientoGarantia_ff smalldatetime,
		@p_horasGarantia float,
		@p_porcentajeCliente float,
		@p_porcentajeDistribuidor float,
		@p_porcentajeFabricante float,
		@p_afectoInventario bit,
		@p_id_documento int,
		@p_id_itemDocumento int,
		@p_id_centroCosto int,
		@p_id_catalogo int,
		@p_id_bodega int,
		@p_id_incoterm int,
		@p_id_itemDocumento_superior int,
		@p_costoPlaneado float,
		@p_costoEjecutado float,
		@p_id_listaprecio int,
		@p_vrbase float,
		@p_vrenlista float,
		@p_porcdescuento float,
		@p_cantAuxiliar float,
		@p_porcentajeMargen float,
		@p_margenPlaneado float,
		@p_cmm varchar(300),
		@p_id_reporteTecnico int
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_itemDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[itemDocumento],
			[itemDocumento_codigo],
			[detalle],
			[horasOrdinales],
			[horasFestivas],
			[horasNocturnas],
			[cantidadPlaneado],
			[cantidadEjecutado],
			[valorUnitarioPlaneado],
			[valorUnitarioEjecutado],
			[subtotalPlaneado],
			[subtotalEjecutado],
			[totalPlaneado],
			[totalEjecutado],
			[porciva],
			[ivaPlaneado],
			[ivaEjecutado],
			[porcdto],
			[dtoPlaneado],
			[dtoEjecutado],
			[costear],
			[esUrgente],
			[vencimientoGarantia_ff],
			[horasGarantia],
			[porcentajeCliente],
			[porcentajeDistribuidor],
			[porcentajeFabricante],
			[afectoInventario],
			[id_documento],
			[id_itemDocumento],
			[id_centroCosto],
			[id_catalogo],
			[id_bodega],
			[id_incoterm],
			[id_itemDocumento_superior],
			[costoPlaneado],
			[costoEjecutado],
			[id_listaprecio],
			[vrbase],
			[vrenlista],
			[porcdescuento],
			[cantAuxiliar],
			[porcentajeMargen],
			[margenPlaneado],
			[cmm],
			[id_reporteTecnico])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_itemDocumento,
			@p_itemDocumento_codigo,
			@p_detalle,
			@p_horasOrdinales,
			@p_horasFestivas,
			@p_horasNocturnas,
			@p_cantidadPlaneado,
			@p_cantidadEjecutado,
			@p_valorUnitarioPlaneado,
			@p_valorUnitarioEjecutado,
			@p_subtotalPlaneado,
			@p_subtotalEjecutado,
			@p_totalPlaneado,
			@p_totalEjecutado,
			@p_porciva,
			@p_ivaPlaneado,
			@p_ivaEjecutado,
			@p_porcdto,
			@p_dtoPlaneado,
			@p_dtoEjecutado,
			@p_costear,
			@p_esUrgente,
			@p_vencimientoGarantia_ff,
			@p_horasGarantia,
			@p_porcentajeCliente,
			@p_porcentajeDistribuidor,
			@p_porcentajeFabricante,
			@p_afectoInventario,
			@p_id_documento,
			@p_id_itemDocumento,
			@p_id_centroCosto,
			@p_id_catalogo,
			@p_id_bodega,
			@p_id_incoterm,
			@p_id_itemDocumento_superior,
			@p_costoPlaneado,
			@p_costoEjecutado,
			@p_id_listaprecio,
			@p_vrbase,
			@p_vrenlista,
			@p_porcdescuento,
			@p_cantAuxiliar,
			@p_porcentajeMargen,
			@p_margenPlaneado,
			@p_cmm,
			@p_id_reporteTecnico)
		SET @v_id = scope_identity()
UPDATE [doc_itemDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
