CREATE PROCEDURE [aud_doc_itemDocumento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_itemDocumento].id as id_tabla,
	[doc_itemDocumento].id_usuario_modifico as id_usuario_modifico,
	[doc_itemDocumento].id_usuario_creo as id_usuario_creo,
	[doc_itemDocumento].fechaModificacion as fechaModificacion,
	[doc_itemDocumento].fechaCreacion as fechaCreacion,
	[doc_itemDocumento].active as active,
	[doc_itemDocumento].[itemDocumento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_itemDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_itemDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_itemDocumento].[id_usuario_creo]
	where ' + @p_filtro)
END
