IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_medioSolicitud]')) DROP VIEW [dbo].[view_doc_medioSolicitud]
GO
CREATE  VIEW [view_doc_medioSolicitud] AS
SELECT 	[doc_medioSolicitud].[id] AS [id],
		[doc_medioSolicitud].[uid] AS [uid],
		[doc_medioSolicitud].[eid] AS [eid],
		[doc_medioSolicitud].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_medioSolicitud].[id_usuario_creo] AS [id_usuario_creo],
		[doc_medioSolicitud].[fechaModificacion] AS [fechaModificacion],
		[doc_medioSolicitud].[fechaCreacion] AS [fechaCreacion],
		[doc_medioSolicitud].[active] AS [active],
		[doc_medioSolicitud].[medioSolicitud] AS [medioSolicitud],
		[doc_medioSolicitud].[medioSolicitud_codigo] AS [medioSolicitud_codigo],
		[doc_medioSolicitud].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_medioSolicitud]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_medioSolicitud].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_medioSolicitud].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_medioSolicitud].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_medioSolicitud].active=1
