IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_motivoestado]')) DROP VIEW [dbo].[view_doc_motivoestado]
GO
CREATE  VIEW [view_doc_motivoestado] AS
SELECT 	[doc_motivoestado].[id] AS [id],
		[doc_motivoestado].[uid] AS [uid],
		[doc_motivoestado].[eid] AS [eid],
		[doc_motivoestado].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_motivoestado].[id_usuario_creo] AS [id_usuario_creo],
		[doc_motivoestado].[fechaModificacion] AS [fechaModificacion],
		[doc_motivoestado].[fechaCreacion] AS [fechaCreacion],
		[doc_motivoestado].[active] AS [active],
		[doc_motivoestado].[motivoestado] AS [motivoestado],
		[doc_motivoestado].[motivoestado_codigo] AS [motivoestado_codigo],
		[doc_motivoestado].[id_estadoTipoDocumento] AS [id_estadoTipoDocumento],
[doc_estadoTipoDocumento].[estadoTipoDocumento] as [doc_estadoTipoDocumento_estadoTipoDocumento],
[doc_estadoTipoDocumento].[estadoTipoDocumento_codigo] as [doc_estadoTipoDocumento_estadoTipoDocumento_codigo],
[doc_estadoTipoDocumento].[afectaIndicador] as [doc_estadoTipoDocumento_afectaIndicador],
[doc_estadoTipoDocumento].[editaDocumento] as [doc_estadoTipoDocumento_editaDocumento],
[doc_estadoTipoDocumento].[orden] as [doc_estadoTipoDocumento_orden],
[doc_estadoTipoDocumento].[puedeRegresar] as [doc_estadoTipoDocumento_puedeRegresar],
[doc_estadoTipoDocumento].[color] as [doc_estadoTipoDocumento_color],
[doc_estadoTipoDocumento].[afectaInventario] as [doc_estadoTipoDocumento_afectaInventario],
[doc_estadoTipoDocumento].[id_tipoDocumento] as [doc_estadoTipoDocumento_id_tipoDocumento],
[doc_estadoTipoDocumento].[descripcion] as [doc_estadoTipoDocumento_descripcion],
[doc_estadoTipoDocumento].[observacionesObligatorio] as [doc_estadoTipoDocumento_observacionesObligatorio],
[doc_estadoTipoDocumento].[motivoObligatorio] as [doc_estadoTipoDocumento_motivoObligatorio],
[doc_estadoTipoDocumento].[cmm] as [doc_estadoTipoDocumento_cmm],
		[doc_motivoestado].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_motivoestado]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_motivoestado].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_motivoestado].[id_usuario_creo]
	INNER JOIN [doc_estadoTipoDocumento] ON [doc_estadoTipoDocumento].id=[doc_motivoestado].[id_estadoTipoDocumento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_motivoestado].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_motivoestado].active=1
GO
