IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_motivoestado]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_motivoestado]
GO
CREATE PROCEDURE [ins_doc_motivoestado]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_motivoestado varchar(300),
		@p_motivoestado_codigo varchar(100),
		@p_id_estadoTipoDocumento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_motivoestado]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[motivoestado],
			[motivoestado_codigo],
			[id_estadoTipoDocumento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_motivoestado,
			@p_motivoestado_codigo,
			@p_id_estadoTipoDocumento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_motivoestado] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
