GO
CREATE PROCEDURE [upd_doc_opcionCondicion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_opcionCondicion varchar(300) = null,
		@p_opcionCondicion_codigo varchar(100) = null,
		@p_id_condicion int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_opcionCondicion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[opcionCondicion] = isnull(@p_opcionCondicion,[opcionCondicion]),
			[opcionCondicion_codigo] = isnull(@p_opcionCondicion_codigo,[opcionCondicion_codigo]),
			[id_condicion] = isnull(@p_id_condicion,[id_condicion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
