IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_opcionCondicion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_opcionCondicion]
GO
CREATE PROCEDURE [ins_doc_opcionCondicion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_opcionCondicion varchar(300),
		@p_opcionCondicion_codigo varchar(100),
		@p_id_condicion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_opcionCondicion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[opcionCondicion],
			[opcionCondicion_codigo],
			[id_condicion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_opcionCondicion,
			@p_opcionCondicion_codigo,
			@p_id_condicion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_opcionCondicion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
