CREATE PROCEDURE [ins_doc_opcionRespuesta]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_opcionRespuesta varchar(300),
