CREATE PROCEDURE [aud_doc_opcionRespuesta]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_opcionRespuesta].id as id_tabla,
	[doc_opcionRespuesta].id_usuario_modifico as id_usuario_modifico,
	[doc_opcionRespuesta].id_usuario_creo as id_usuario_creo,
	[doc_opcionRespuesta].fechaModificacion as fechaModificacion,
	[doc_opcionRespuesta].fechaCreacion as fechaCreacion,
	[doc_opcionRespuesta].active as active,
	[doc_opcionRespuesta].[opcionRespuesta] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_opcionRespuesta]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_opcionRespuesta].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_opcionRespuesta].[id_usuario_creo]
	where ' + @p_filtro)
END
