IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_pendienteDocumento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_pendienteDocumento]
GO
CREATE PROCEDURE [ins_doc_pendienteDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_pendienteDocumento varchar(300),
		@p_pendienteDocumento_codigo varchar(100),
		@p_cantidad float,
		@p_id_documento int,
		@p_id_catalogo int,
		@p_olvidar bit,
		@p_id_reporteTecnico int,
		@p_id_tipoPendiente int,
		@p_cmm varchar(300),
		@p_id_subtipoDocumento int
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_pendienteDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[pendienteDocumento],
			[pendienteDocumento_codigo],
			[cantidad],
			[id_documento],
			[id_catalogo],
			[olvidar],
			[id_reporteTecnico],
			[id_tipoPendiente],
			[cmm],
			[id_subtipoDocumento])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_pendienteDocumento,
			@p_pendienteDocumento_codigo,
			@p_cantidad,
			@p_id_documento,
			@p_id_catalogo,
			@p_olvidar,
			@p_id_reporteTecnico,
			@p_id_tipoPendiente,
			@p_cmm,
			@p_id_subtipoDocumento)
		SET @v_id = scope_identity()
UPDATE [doc_pendienteDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
