CREATE PROCEDURE [reg_doc_pendienteDocumento_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[pendienteDocumento] AS [pendienteDocumento],
		[pendienteDocumento_codigo] AS [pendienteDocumento_codigo],
		[cantidad] AS [cantidad],
		[id_documento] AS [id_documento],
		[id_catalogo] AS [id_catalogo],
		[olvidar] AS [olvidar],
		[id_reporteTecnico] AS [id_reporteTecnico],
		[id_tipoPendiente] AS [id_tipoPendiente],
		[cmm] AS [cmm],
		[id_subtipoDocumento] AS [id_subtipoDocumento]
	FROM [doc_pendienteDocumento]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
