GO
CREATE PROCEDURE [ins_doc_pendienteDocumento_doc_itemDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_pendienteDocumento_doc_itemDocumento varchar(300),
		@p_id_pendienteDocumento int,
		@p_id_itemDocumento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_pendienteDocumento_doc_itemDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[pendienteDocumento_doc_itemDocumento],
			[id_pendienteDocumento],
			[id_itemDocumento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_pendienteDocumento_doc_itemDocumento,
			@p_id_pendienteDocumento,
			@p_id_itemDocumento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_pendienteDocumento_doc_itemDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
