	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_pendienteDocumento_doc_itemDocumento].id as id_tabla,
	[doc_pendienteDocumento_doc_itemDocumento].id_usuario_modifico as id_usuario_modifico,
	[doc_pendienteDocumento_doc_itemDocumento].id_usuario_creo as id_usuario_creo,
	[doc_pendienteDocumento_doc_itemDocumento].fechaModificacion as fechaModificacion,
	[doc_pendienteDocumento_doc_itemDocumento].fechaCreacion as fechaCreacion,
	[doc_pendienteDocumento_doc_itemDocumento].active as active,
	[doc_pendienteDocumento_doc_itemDocumento].[pendienteDocumento_doc_itemDocumento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_pendienteDocumento_doc_itemDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_pendienteDocumento_doc_itemDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_pendienteDocumento_doc_itemDocumento].[id_usuario_creo]
	where ' + @p_filtro)
END
