IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_pregunta]')) DROP VIEW [dbo].[view_doc_pregunta]
GO
CREATE  VIEW [view_doc_pregunta] AS
SELECT 	[doc_pregunta].[id] AS [id],
		[doc_pregunta].[uid] AS [uid],
		[doc_pregunta].[eid] AS [eid],
		[doc_pregunta].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_pregunta].[id_usuario_creo] AS [id_usuario_creo],
		[doc_pregunta].[fechaModificacion] AS [fechaModificacion],
		[doc_pregunta].[fechaCreacion] AS [fechaCreacion],
		[doc_pregunta].[active] AS [active],
		[doc_pregunta].[pregunta] AS [pregunta],
		[doc_pregunta].[pregunta_codigo] AS [pregunta_codigo],
		[doc_pregunta].[orden] AS [orden],
		[doc_pregunta].[activa] AS [activa],
		[doc_pregunta].[valor] AS [valor],
		[doc_pregunta].[id_evaluacion] AS [id_evaluacion],
[doc_evaluacion].[evaluacion] as [doc_evaluacion_evaluacion],
[doc_evaluacion].[evaluacion_codigo] as [doc_evaluacion_evaluacion_codigo],
[doc_evaluacion].[activa] as [doc_evaluacion_activa],
[doc_evaluacion].[id_subtipoDocumento] as [doc_evaluacion_id_subtipoDocumento],
[doc_evaluacion].[cmm] as [doc_evaluacion_cmm],
		[doc_pregunta].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_pregunta]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_pregunta].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_pregunta].[id_usuario_creo]
	INNER JOIN [doc_evaluacion] ON [doc_evaluacion].id=[doc_pregunta].[id_evaluacion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_pregunta].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_pregunta].active=1
GO
