IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_pregunta]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_pregunta]
GO
CREATE PROCEDURE [ins_doc_pregunta]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_pregunta varchar(300),
		@p_pregunta_codigo varchar(100),
		@p_orden int,
		@p_activa bit,
		@p_valor int,
		@p_id_evaluacion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_pregunta]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[pregunta],
			[pregunta_codigo],
			[orden],
			[activa],
			[valor],
			[id_evaluacion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_pregunta,
			@p_pregunta_codigo,
			@p_orden,
			@p_activa,
			@p_valor,
			@p_id_evaluacion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_pregunta] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
