GO
CREATE  VIEW [view_doc_prioridadDocumento] AS
SELECT 	[doc_prioridadDocumento].[id] AS [id],
		[doc_prioridadDocumento].[uid] AS [uid],
		[doc_prioridadDocumento].[eid] AS [eid],
		[doc_prioridadDocumento].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_prioridadDocumento].[id_usuario_creo] AS [id_usuario_creo],
		[doc_prioridadDocumento].[fechaModificacion] AS [fechaModificacion],
		[doc_prioridadDocumento].[fechaCreacion] AS [fechaCreacion],
		[doc_prioridadDocumento].[active] AS [active],
		[doc_prioridadDocumento].[prioridadDocumento] AS [prioridadDocumento],
		[doc_prioridadDocumento].[prioridadDocumento_codigo] AS [prioridadDocumento_codigo],
		[doc_prioridadDocumento].[tiempoRespuesta] AS [tiempoRespuesta],
		[doc_prioridadDocumento].[id_tipoDocumento] AS [id_tipoDocumento],
[doc_tipoDocumento].[tipoDocumento] as [doc_tipoDocumento_tipoDocumento],
[doc_tipoDocumento].[tipoDocumento_codigo] as [doc_tipoDocumento_tipoDocumento_codigo],
[doc_tipoDocumento].[esSalida] as [doc_tipoDocumento_esSalida],
[doc_tipoDocumento].[mostrarBodega] as [doc_tipoDocumento_mostrarBodega],
[doc_tipoDocumento].[mostrarCentroCosto] as [doc_tipoDocumento_mostrarCentroCosto],
[doc_tipoDocumento].[mostrarIncoterm] as [doc_tipoDocumento_mostrarIncoterm],
[doc_tipoDocumento].[puedeSerMayor] as [doc_tipoDocumento_puedeSerMayor],
[doc_tipoDocumento].[puedeSerMenor] as [doc_tipoDocumento_puedeSerMenor],
[doc_tipoDocumento].[esUrgente] as [doc_tipoDocumento_esUrgente],
[doc_tipoDocumento].[cmm] as [doc_tipoDocumento_cmm],
		[doc_prioridadDocumento].[id_estrategiaPrioridad] AS [id_estrategiaPrioridad],
[doc_estrategiaPrioridad].[estrategiaPrioridad] as [doc_estrategiaPrioridad_estrategiaPrioridad],
[doc_estrategiaPrioridad].[estrategiaPrioridad_codigo] as [doc_estrategiaPrioridad_estrategiaPrioridad_codigo],
[doc_estrategiaPrioridad].[lunesIni_hh] as [doc_estrategiaPrioridad_lunesIni_hh],
[doc_estrategiaPrioridad].[lunesFin_hh] as [doc_estrategiaPrioridad_lunesFin_hh],
[doc_estrategiaPrioridad].[martesIni_hh] as [doc_estrategiaPrioridad_martesIni_hh],
[doc_estrategiaPrioridad].[martesFin_hh] as [doc_estrategiaPrioridad_martesFin_hh],
[doc_estrategiaPrioridad].[miercolesIni_hh] as [doc_estrategiaPrioridad_miercolesIni_hh],
[doc_estrategiaPrioridad].[miercolesFin_hh] as [doc_estrategiaPrioridad_miercolesFin_hh],
[doc_estrategiaPrioridad].[juevesIni_hh] as [doc_estrategiaPrioridad_juevesIni_hh],
[doc_estrategiaPrioridad].[juevesFin_hh] as [doc_estrategiaPrioridad_juevesFin_hh],
[doc_estrategiaPrioridad].[viernesIni_hh] as [doc_estrategiaPrioridad_viernesIni_hh],
[doc_estrategiaPrioridad].[viernesFin_hh] as [doc_estrategiaPrioridad_viernesFin_hh],
[doc_estrategiaPrioridad].[sabadoIni_hh] as [doc_estrategiaPrioridad_sabadoIni_hh],
[doc_estrategiaPrioridad].[sabadoFin_hh] as [doc_estrategiaPrioridad_sabadoFin_hh],
[doc_estrategiaPrioridad].[domingoIni_hh] as [doc_estrategiaPrioridad_domingoIni_hh],
[doc_estrategiaPrioridad].[domingoFin_hh] as [doc_estrategiaPrioridad_domingoFin_hh],
[doc_estrategiaPrioridad].[festivoIni_hh] as [doc_estrategiaPrioridad_festivoIni_hh],
[doc_estrategiaPrioridad].[festivoFin_hh] as [doc_estrategiaPrioridad_festivoFin_hh],
[doc_estrategiaPrioridad].[cmm] as [doc_estrategiaPrioridad_cmm],
		[doc_prioridadDocumento].[orden] AS [orden],
		[doc_prioridadDocumento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_prioridadDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_prioridadDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_prioridadDocumento].[id_usuario_creo]
	INNER JOIN [doc_tipoDocumento] ON [doc_tipoDocumento].id=[doc_prioridadDocumento].[id_tipoDocumento]
	INNER JOIN [doc_estrategiaPrioridad] ON [doc_estrategiaPrioridad].id=[doc_prioridadDocumento].[id_estrategiaPrioridad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_prioridadDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_prioridadDocumento].active=1
