		[doc_prioridadSubtipoDocumento].[prioridadSubtipoDocumento] AS [prioridadSubtipoDocumento],
		[doc_prioridadSubtipoDocumento].[prioridadSubtipoDocumento_codigo] AS [prioridadSubtipoDocumento_codigo],
		[doc_prioridadSubtipoDocumento].[id_subtipoDocumento] AS [id_subtipoDocumento],
[doc_subtipoDocumento].[subtipoDocumento] as [doc_subtipoDocumento_subtipoDocumento],
[doc_subtipoDocumento].[subtipoDocumento_codigo] as [doc_subtipoDocumento_subtipoDocumento_codigo],
[doc_subtipoDocumento].[prefijo] as [doc_subtipoDocumento_prefijo],
[doc_subtipoDocumento].[consecutivo] as [doc_subtipoDocumento_consecutivo],
[doc_subtipoDocumento].[id_tipoDocumento] as [doc_subtipoDocumento_id_tipoDocumento],
[doc_subtipoDocumento].[programarPlaneadas] as [doc_subtipoDocumento_programarPlaneadas],
[doc_subtipoDocumento].[cargarSolicitante] as [doc_subtipoDocumento_cargarSolicitante],
[doc_subtipoDocumento].[verCentroCosto] as [doc_subtipoDocumento_verCentroCosto],
[doc_subtipoDocumento].[verIncoterm] as [doc_subtipoDocumento_verIncoterm],
[doc_subtipoDocumento].[valUrgente] as [doc_subtipoDocumento_valUrgente],
[doc_subtipoDocumento].[bloquearDespacho] as [doc_subtipoDocumento_bloquearDespacho],
[doc_subtipoDocumento].[cerrarSol] as [doc_subtipoDocumento_cerrarSol],
[doc_subtipoDocumento].[ejecutaDevolucion] as [doc_subtipoDocumento_ejecutaDevolucion],
[doc_subtipoDocumento].[tipoCobro] as [doc_subtipoDocumento_tipoCobro],
[doc_subtipoDocumento].[mostrarPendienteDocumento] as [doc_subtipoDocumento_mostrarPendienteDocumento],
[doc_subtipoDocumento].[cantidadAuxiliar] as [doc_subtipoDocumento_cantidadAuxiliar],
[doc_subtipoDocumento].[mostrarValoresEjecutados] as [doc_subtipoDocumento_mostrarValoresEjecutados],
[doc_subtipoDocumento].[archivosAdjuntosApp] as [doc_subtipoDocumento_archivosAdjuntosApp],
[doc_subtipoDocumento].[cmm] as [doc_subtipoDocumento_cmm],
		[doc_prioridadSubtipoDocumento].[id_prioridadDocumento] AS [id_prioridadDocumento],
[doc_prioridadDocumento].[prioridadDocumento] as [doc_prioridadDocumento_prioridadDocumento],
[doc_prioridadDocumento].[prioridadDocumento_codigo] as [doc_prioridadDocumento_prioridadDocumento_codigo],
[doc_prioridadDocumento].[tiempoRespuesta] as [doc_prioridadDocumento_tiempoRespuesta],
[doc_prioridadDocumento].[id_tipoDocumento] as [doc_prioridadDocumento_id_tipoDocumento],
[doc_prioridadDocumento].[id_estrategiaPrioridad] as [doc_prioridadDocumento_id_estrategiaPrioridad],
[doc_prioridadDocumento].[orden] as [doc_prioridadDocumento_orden],
[doc_prioridadDocumento].[cmm] as [doc_prioridadDocumento_cmm],
		[doc_prioridadSubtipoDocumento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_prioridadSubtipoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_prioridadSubtipoDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_prioridadSubtipoDocumento].[id_usuario_creo]
	INNER JOIN [doc_subtipoDocumento] ON [doc_subtipoDocumento].id=[doc_prioridadSubtipoDocumento].[id_subtipoDocumento]
	INNER JOIN [doc_prioridadDocumento] ON [doc_prioridadDocumento].id=[doc_prioridadSubtipoDocumento].[id_prioridadDocumento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_prioridadSubtipoDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_prioridadSubtipoDocumento].active=1
