CREATE PROCEDURE [upd_doc_prioridadSubtipoDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_prioridadSubtipoDocumento varchar(300) = null,
		@p_prioridadSubtipoDocumento_codigo varchar(100) = null,
		@p_id_subtipoDocumento int = null,
		@p_id_prioridadDocumento int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_prioridadSubtipoDocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[prioridadSubtipoDocumento] = isnull(@p_prioridadSubtipoDocumento,[prioridadSubtipoDocumento]),
			[prioridadSubtipoDocumento_codigo] = isnull(@p_prioridadSubtipoDocumento_codigo,[prioridadSubtipoDocumento_codigo]),
			[id_subtipoDocumento] = isnull(@p_id_subtipoDocumento,[id_subtipoDocumento]),
			[id_prioridadDocumento] = isnull(@p_id_prioridadDocumento,[id_prioridadDocumento]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
