GO
CREATE PROCEDURE [ins_doc_prioridadSubtipoDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_prioridadSubtipoDocumento varchar(300),
		@p_prioridadSubtipoDocumento_codigo varchar(100),
		@p_id_subtipoDocumento int,
		@p_id_prioridadDocumento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_prioridadSubtipoDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[prioridadSubtipoDocumento],
			[prioridadSubtipoDocumento_codigo],
			[id_subtipoDocumento],
			[id_prioridadDocumento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_prioridadSubtipoDocumento,
			@p_prioridadSubtipoDocumento_codigo,
			@p_id_subtipoDocumento,
			@p_id_prioridadDocumento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_prioridadSubtipoDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
