CREATE PROCEDURE [upd_doc_soporteItemDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_soporteItemDocumento varchar(300) = null,
		@p_soporteItemDocumento_codigo varchar(100) = null,
		@p_duracionPlaneada float = null,
		@p_Valor money = null,
		@p_Costo money = null,
		@p_id_itemDocumento int = null,
		@p_id_usuario int = null,
		@p_duracionEjecutada float = null,
		@p_horasOrdinales float = null,
		@p_horasFestivas float = null,
		@p_horasNocturnas float = null,
		@p_periodo varchar(50) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_soporteItemDocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[soporteItemDocumento] = isnull(@p_soporteItemDocumento,[soporteItemDocumento]),
			[soporteItemDocumento_codigo] = isnull(@p_soporteItemDocumento_codigo,[soporteItemDocumento_codigo]),
			[duracionPlaneada] = isnull(@p_duracionPlaneada,[duracionPlaneada]),
			[Valor] = isnull(@p_Valor,[Valor]),
			[Costo] = isnull(@p_Costo,[Costo]),
			[id_itemDocumento] = isnull(@p_id_itemDocumento,[id_itemDocumento]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[duracionEjecutada] = isnull(@p_duracionEjecutada,[duracionEjecutada]),
			[horasOrdinales] = isnull(@p_horasOrdinales,[horasOrdinales]),
			[horasFestivas] = isnull(@p_horasFestivas,[horasFestivas]),
			[horasNocturnas] = isnull(@p_horasNocturnas,[horasNocturnas]),
			[periodo] = isnull(@p_periodo,[periodo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
