GO
CREATE PROCEDURE [ins_doc_soporteItemDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_soporteItemDocumento varchar(300),
		@p_soporteItemDocumento_codigo varchar(100),
		@p_duracionPlaneada float,
		@p_Valor money,
		@p_Costo money,
		@p_id_itemDocumento int,
		@p_id_usuario int,
		@p_duracionEjecutada float,
		@p_horasOrdinales float,
		@p_horasFestivas float,
		@p_horasNocturnas float,
		@p_periodo varchar(50),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_soporteItemDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[soporteItemDocumento],
			[soporteItemDocumento_codigo],
			[duracionPlaneada],
			[Valor],
			[Costo],
			[id_itemDocumento],
			[id_usuario],
			[duracionEjecutada],
			[horasOrdinales],
			[horasFestivas],
			[horasNocturnas],
			[periodo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_soporteItemDocumento,
			@p_soporteItemDocumento_codigo,
			@p_duracionPlaneada,
			@p_Valor,
			@p_Costo,
			@p_id_itemDocumento,
			@p_id_usuario,
			@p_duracionEjecutada,
			@p_horasOrdinales,
			@p_horasFestivas,
			@p_horasNocturnas,
			@p_periodo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_soporteItemDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
