		[doc_subtipoDocumento].[eid] AS [eid],
		[doc_subtipoDocumento].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_subtipoDocumento].[id_usuario_creo] AS [id_usuario_creo],
		[doc_subtipoDocumento].[fechaModificacion] AS [fechaModificacion],
		[doc_subtipoDocumento].[fechaCreacion] AS [fechaCreacion],
		[doc_subtipoDocumento].[active] AS [active],
		[doc_subtipoDocumento].[subtipoDocumento] AS [subtipoDocumento],
		[doc_subtipoDocumento].[subtipoDocumento_codigo] AS [subtipoDocumento_codigo],
		[doc_subtipoDocumento].[prefijo] AS [prefijo],
		[doc_subtipoDocumento].[consecutivo] AS [consecutivo],
		[doc_subtipoDocumento].[id_tipoDocumento] AS [id_tipoDocumento],
[doc_tipoDocumento].[tipoDocumento] as [doc_tipoDocumento_tipoDocumento],
[doc_tipoDocumento].[tipoDocumento_codigo] as [doc_tipoDocumento_tipoDocumento_codigo],
[doc_tipoDocumento].[esSalida] as [doc_tipoDocumento_esSalida],
[doc_tipoDocumento].[mostrarBodega] as [doc_tipoDocumento_mostrarBodega],
[doc_tipoDocumento].[mostrarCentroCosto] as [doc_tipoDocumento_mostrarCentroCosto],
[doc_tipoDocumento].[mostrarIncoterm] as [doc_tipoDocumento_mostrarIncoterm],
[doc_tipoDocumento].[puedeSerMayor] as [doc_tipoDocumento_puedeSerMayor],
[doc_tipoDocumento].[puedeSerMenor] as [doc_tipoDocumento_puedeSerMenor],
[doc_tipoDocumento].[esUrgente] as [doc_tipoDocumento_esUrgente],
[doc_tipoDocumento].[cmm] as [doc_tipoDocumento_cmm],
		[doc_subtipoDocumento].[programarPlaneadas] AS [programarPlaneadas],
		[doc_subtipoDocumento].[cargarSolicitante] AS [cargarSolicitante],
		[doc_subtipoDocumento].[verCentroCosto] AS [verCentroCosto],
		[doc_subtipoDocumento].[verIncoterm] AS [verIncoterm],
		[doc_subtipoDocumento].[valUrgente] AS [valUrgente],
		[doc_subtipoDocumento].[bloquearDespacho] AS [bloquearDespacho],
		[doc_subtipoDocumento].[cerrarSol] AS [cerrarSol],
		[doc_subtipoDocumento].[ejecutaDevolucion] AS [ejecutaDevolucion],
		[doc_subtipoDocumento].[tipoCobro] AS [tipoCobro],
		[doc_subtipoDocumento].[mostrarPendienteDocumento] AS [mostrarPendienteDocumento],
		[doc_subtipoDocumento].[cantidadAuxiliar] AS [cantidadAuxiliar],
		[doc_subtipoDocumento].[mostrarValoresEjecutados] AS [mostrarValoresEjecutados],
		[doc_subtipoDocumento].[archivosAdjuntosApp] AS [archivosAdjuntosApp],
		[doc_subtipoDocumento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_subtipoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_subtipoDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_subtipoDocumento].[id_usuario_creo]
	INNER JOIN [doc_tipoDocumento] ON [doc_tipoDocumento].id=[doc_subtipoDocumento].[id_tipoDocumento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_subtipoDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_subtipoDocumento].active=1
