IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_tarea]')) DROP VIEW [dbo].[view_doc_tarea]
GO
CREATE  VIEW [view_doc_tarea] AS
SELECT 	[doc_tarea].[id] AS [id],
		[doc_tarea].[uid] AS [uid],
		[doc_tarea].[eid] AS [eid],
		[doc_tarea].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_tarea].[id_usuario_creo] AS [id_usuario_creo],
		[doc_tarea].[fechaModificacion] AS [fechaModificacion],
		[doc_tarea].[fechaCreacion] AS [fechaCreacion],
		[doc_tarea].[active] AS [active],
		[doc_tarea].[tarea] AS [tarea],
		[doc_tarea].[tarea_codigo] AS [tarea_codigo],
		[doc_tarea].[id_catalogo] AS [id_catalogo],
[cat_catalogo].[catalogo] as [cat_catalogo_catalogo],
[cat_catalogo].[catalogo_codigo] as [cat_catalogo_catalogo_codigo],
[cat_catalogo].[codigoInventario] as [cat_catalogo_codigoInventario],
[cat_catalogo].[precioVenta] as [cat_catalogo_precioVenta],
[cat_catalogo].[tiempoConsecucion] as [cat_catalogo_tiempoConsecucion],
[cat_catalogo].[esNacional] as [cat_catalogo_esNacional],
[cat_catalogo].[id_familia] as [cat_catalogo_id_familia],
[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[doc_tarea].[id_cargo] AS [id_cargo],
[seg_cargo].[cargo] as [seg_cargo_cargo],
[seg_cargo].[cargo_codigo] as [seg_cargo_cargo_codigo],
[seg_cargo].[esTecnico] as [seg_cargo_esTecnico],
[seg_cargo].[esComercial] as [seg_cargo_esComercial],
[seg_cargo].[esCoordinador] as [seg_cargo_esCoordinador],
[seg_cargo].[valorHora] as [seg_cargo_valorHora],
[seg_cargo].[esAdministrativo] as [seg_cargo_esAdministrativo],
[seg_cargo].[cmm] as [seg_cargo_cmm],
		[doc_tarea].[fechaPlaneada_fh] AS [fechaPlaneada_fh],
		[doc_tarea].[porcentajeAvance] AS [porcentajeAvance],
		[doc_tarea].[id_documento] AS [id_documento],
[doc_documento].[documento] as [doc_documento_documento],
[doc_documento].[documento_codigo] as [doc_documento_documento_codigo],
[doc_documento].[documento_numero] as [doc_documento_documento_numero],
[doc_documento].[prefijo] as [doc_documento_prefijo],
[doc_documento].[subtotal] as [doc_documento_subtotal],
[doc_documento].[descuento] as [doc_documento_descuento],
[doc_documento].[iva] as [doc_documento_iva],
[doc_documento].[total] as [doc_documento_total],
[doc_documento].[costo] as [doc_documento_costo],
[doc_documento].[rentabilidad] as [doc_documento_rentabilidad],
[doc_documento].[trm] as [doc_documento_trm],
[doc_documento].[fecha_fh] as [doc_documento_fecha_fh],
[doc_documento].[fechaSugerida_fh] as [doc_documento_fechaSugerida_fh],
[doc_documento].[fechaCierre_ff] as [doc_documento_fechaCierre_ff],
[doc_documento].[fechaLimite_fh] as [doc_documento_fechaLimite_fh],
[doc_documento].[id_subtipoDocumento] as [doc_documento_id_subtipoDocumento],
[doc_documento].[id_tercero_cliente] as [doc_documento_id_tercero_cliente],
[doc_documento].[id_documento] as [doc_documento_id_documento],
[doc_documento].[id_tercero_proveedor] as [doc_documento_id_tercero_proveedor],
[doc_documento].[id_prioridadDocumento] as [doc_documento_id_prioridadDocumento],
[doc_documento].[id_moneda] as [doc_documento_id_moneda],
[doc_documento].[id_estadoTipoDocumento] as [doc_documento_id_estadoTipoDocumento],
[doc_documento].[id_motivoestado] as [doc_documento_id_motivoestado],
[doc_documento].[subtotalPlaneado] as [doc_documento_subtotalPlaneado],
[doc_documento].[descuentoPlaneado] as [doc_documento_descuentoPlaneado],
[doc_documento].[ivaPlaneado] as [doc_documento_ivaPlaneado],
[doc_documento].[totalPlaneado] as [doc_documento_totalPlaneado],
[doc_documento].[costoPlaneado] as [doc_documento_costoPlaneado],
[doc_documento].[id_usuario_asignado] as [doc_documento_id_usuario_asignado],
[doc_documento].[id_usuario_enUso] as [doc_documento_id_usuario_enUso],
[doc_documento].[identificador] as [doc_documento_identificador],
[doc_documento].[cmm] as [doc_documento_cmm],
		[doc_tarea].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_tarea]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_tarea].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_tarea].[id_usuario_creo]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[doc_tarea].[id_catalogo]
	INNER JOIN [seg_cargo] ON [seg_cargo].id=[doc_tarea].[id_cargo]
	INNER JOIN [doc_documento] ON [doc_documento].id=[doc_tarea].[id_documento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_tarea].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_tarea].active=1
GO
