IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_doc_tarea]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_doc_tarea]
GO
CREATE PROCEDURE [upd_doc_tarea]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_tarea varchar(300) = null,
		@p_tarea_codigo varchar(100) = null,
		@p_id_catalogo int = null,
		@p_id_cargo int = null,
		@p_fechaPlaneada_fh smalldatetime = null,
		@p_porcentajeAvance int = null,
		@p_id_documento int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_tarea]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tarea] = isnull(@p_tarea,[tarea]),
			[tarea_codigo] = isnull(@p_tarea_codigo,[tarea_codigo]),
			[id_catalogo] = isnull(@p_id_catalogo,[id_catalogo]),
			[id_cargo] = isnull(@p_id_cargo,[id_cargo]),
			[fechaPlaneada_fh] = isnull(@p_fechaPlaneada_fh,[fechaPlaneada_fh]),
			[porcentajeAvance] = isnull(@p_porcentajeAvance,[porcentajeAvance]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
