IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_tarea]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_tarea]
GO
CREATE PROCEDURE [ins_doc_tarea]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tarea varchar(300),
		@p_tarea_codigo varchar(100),
		@p_id_catalogo int,
		@p_id_cargo int,
		@p_fechaPlaneada_fh smalldatetime,
		@p_porcentajeAvance int,
		@p_id_documento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_tarea]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tarea],
			[tarea_codigo],
			[id_catalogo],
			[id_cargo],
			[fechaPlaneada_fh],
			[porcentajeAvance],
			[id_documento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tarea,
			@p_tarea_codigo,
			@p_id_catalogo,
			@p_id_cargo,
			@p_fechaPlaneada_fh,
			@p_porcentajeAvance,
			@p_id_documento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_tarea] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
