IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[aud_doc_tarea]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[aud_doc_tarea]
GO
CREATE PROCEDURE [aud_doc_tarea]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_tarea].id as id_tabla,
	[doc_tarea].id_usuario_modifico as id_usuario_modifico,
	[doc_tarea].id_usuario_creo as id_usuario_creo,
	[doc_tarea].fechaModificacion as fechaModificacion,
	[doc_tarea].fechaCreacion as fechaCreacion,
	[doc_tarea].active as active,
	[doc_tarea].[tarea] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_tarea]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_tarea].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_tarea].[id_usuario_creo]
	where ' + @p_filtro)
END
