IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_doc_tipoDocumento]')) DROP VIEW [dbo].[view_doc_tipoDocumento]
GO
CREATE  VIEW [view_doc_tipoDocumento] AS
SELECT 	[doc_tipoDocumento].[id] AS [id],
		[doc_tipoDocumento].[uid] AS [uid],
		[doc_tipoDocumento].[eid] AS [eid],
		[doc_tipoDocumento].[id_usuario_modifico] AS [id_usuario_modifico],
		[doc_tipoDocumento].[id_usuario_creo] AS [id_usuario_creo],
		[doc_tipoDocumento].[fechaModificacion] AS [fechaModificacion],
		[doc_tipoDocumento].[fechaCreacion] AS [fechaCreacion],
		[doc_tipoDocumento].[active] AS [active],
		[doc_tipoDocumento].[tipoDocumento] AS [tipoDocumento],
		[doc_tipoDocumento].[tipoDocumento_codigo] AS [tipoDocumento_codigo],
		[doc_tipoDocumento].[esSalida] AS [esSalida],
		[doc_tipoDocumento].[mostrarBodega] AS [mostrarBodega],
		[doc_tipoDocumento].[mostrarCentroCosto] AS [mostrarCentroCosto],
		[doc_tipoDocumento].[mostrarIncoterm] AS [mostrarIncoterm],
		[doc_tipoDocumento].[puedeSerMayor] AS [puedeSerMayor],
		[doc_tipoDocumento].[puedeSerMenor] AS [puedeSerMenor],
		[doc_tipoDocumento].[esUrgente] AS [esUrgente],
		[doc_tipoDocumento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [doc_tipoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_tipoDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_tipoDocumento].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [doc_tipoDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [doc_tipoDocumento].active=1
