GO
CREATE PROCEDURE [upd_doc_tipoDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_tipoDocumento varchar(300) = null,
		@p_tipoDocumento_codigo varchar(100) = null,
		@p_esSalida bit = null,
		@p_mostrarBodega bit = null,
		@p_mostrarCentroCosto bit = null,
		@p_mostrarIncoterm bit = null,
		@p_puedeSerMayor bit = null,
		@p_puedeSerMenor bit = null,
		@p_esUrgente bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_tipoDocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tipoDocumento] = isnull(@p_tipoDocumento,[tipoDocumento]),
			[tipoDocumento_codigo] = isnull(@p_tipoDocumento_codigo,[tipoDocumento_codigo]),
			[esSalida] = isnull(@p_esSalida,[esSalida]),
			[mostrarBodega] = isnull(@p_mostrarBodega,[mostrarBodega]),
			[mostrarCentroCosto] = isnull(@p_mostrarCentroCosto,[mostrarCentroCosto]),
			[mostrarIncoterm] = isnull(@p_mostrarIncoterm,[mostrarIncoterm]),
			[puedeSerMayor] = isnull(@p_puedeSerMayor,[puedeSerMayor]),
			[puedeSerMenor] = isnull(@p_puedeSerMenor,[puedeSerMenor]),
			[esUrgente] = isnull(@p_esUrgente,[esUrgente]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
