IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_tipoDocumento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_tipoDocumento]
GO
CREATE PROCEDURE [ins_doc_tipoDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoDocumento varchar(300),
		@p_tipoDocumento_codigo varchar(100),
		@p_esSalida bit,
		@p_mostrarBodega bit,
		@p_mostrarCentroCosto bit,
		@p_mostrarIncoterm bit,
		@p_puedeSerMayor bit,
		@p_puedeSerMenor bit,
		@p_esUrgente bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_tipoDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoDocumento],
			[tipoDocumento_codigo],
			[esSalida],
			[mostrarBodega],
			[mostrarCentroCosto],
			[mostrarIncoterm],
			[puedeSerMayor],
			[puedeSerMenor],
			[esUrgente],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoDocumento,
			@p_tipoDocumento_codigo,
			@p_esSalida,
			@p_mostrarBodega,
			@p_mostrarCentroCosto,
			@p_mostrarIncoterm,
			@p_puedeSerMayor,
			@p_puedeSerMenor,
			@p_esUrgente,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_tipoDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
