CREATE PROCEDURE [aud_doc_tipoDocumento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_tipoDocumento].id as id_tabla,
	[doc_tipoDocumento].id_usuario_modifico as id_usuario_modifico,
	[doc_tipoDocumento].id_usuario_creo as id_usuario_creo,
	[doc_tipoDocumento].fechaModificacion as fechaModificacion,
	[doc_tipoDocumento].fechaCreacion as fechaCreacion,
	[doc_tipoDocumento].active as active,
	[doc_tipoDocumento].[tipoDocumento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_tipoDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_tipoDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_tipoDocumento].[id_usuario_creo]
	where ' + @p_filtro)
END
