IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_doc_tipoPendiente]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_doc_tipoPendiente]
GO
CREATE PROCEDURE [upd_doc_tipoPendiente]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_tipoPendiente varchar(300) = null,
		@p_tipoPendiente_codigo varchar(100) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [doc_tipoPendiente]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tipoPendiente] = isnull(@p_tipoPendiente,[tipoPendiente]),
			[tipoPendiente_codigo] = isnull(@p_tipoPendiente_codigo,[tipoPendiente_codigo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
