IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_doc_tipoPendiente]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_doc_tipoPendiente]
GO
CREATE PROCEDURE [ins_doc_tipoPendiente]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoPendiente varchar(300),
		@p_tipoPendiente_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_tipoPendiente]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoPendiente],
			[tipoPendiente_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoPendiente,
			@p_tipoPendiente_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_tipoPendiente] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
