IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[aud_doc_tipoPendiente]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[aud_doc_tipoPendiente]
GO
CREATE PROCEDURE [aud_doc_tipoPendiente]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [doc_tipoPendiente].id as id_tabla,
	[doc_tipoPendiente].id_usuario_modifico as id_usuario_modifico,
	[doc_tipoPendiente].id_usuario_creo as id_usuario_creo,
	[doc_tipoPendiente].fechaModificacion as fechaModificacion,
	[doc_tipoPendiente].fechaCreacion as fechaCreacion,
	[doc_tipoPendiente].active as active,
	[doc_tipoPendiente].[tipoPendiente] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [doc_tipoPendiente]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[doc_tipoPendiente].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[doc_tipoPendiente].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
