	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_alquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_alquiler].[id_usuario_creo]
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[equ_alquiler].[id_sucursal]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[equ_alquiler].[id_tercero]
	INNER JOIN [doc_subtipoDocumento] ON [doc_subtipoDocumento].id=[equ_alquiler].[id_subtipoDocumento]
	INNER JOIN [doc_documento] ON [doc_documento].id=[equ_alquiler].[id_documento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_alquiler].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_alquiler].active=1
