GO
CREATE PROCEDURE [upd_equ_alquiler]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_alquiler varchar(300) = null,
		@p_alquiler_codigo varchar(100) = null,
		@p_fechaCompromiso_ff smalldatetime = null,
		@p_id_sucursal int = null,
		@p_id_tercero int = null,
		@p_id_subtipoDocumento int = null,
		@p_fechaFin_ff smalldatetime = null,
		@p_mesVencido bit = null,
		@p_alquiler_numero int = null,
		@p_observaciones varchar(500) = null,
		@p_id_documento int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_alquiler]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[alquiler] = isnull(@p_alquiler,[alquiler]),
			[alquiler_codigo] = isnull(@p_alquiler_codigo,[alquiler_codigo]),
			[fechaCompromiso_ff] = isnull(@p_fechaCompromiso_ff,[fechaCompromiso_ff]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[id_tercero] = isnull(@p_id_tercero,[id_tercero]),
			[id_subtipoDocumento] = isnull(@p_id_subtipoDocumento,[id_subtipoDocumento]),
			[fechaFin_ff] = isnull(@p_fechaFin_ff,[fechaFin_ff]),
			[mesVencido] = isnull(@p_mesVencido,[mesVencido]),
			[alquiler_numero] = isnull(@p_alquiler_numero,[alquiler_numero]),
			[observaciones] = isnull(@p_observaciones,[observaciones]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
