IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_alquiler]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_alquiler]
GO
CREATE PROCEDURE [ins_equ_alquiler]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_alquiler varchar(300),
		@p_alquiler_codigo varchar(100),
		@p_fechaCompromiso_ff smalldatetime,
		@p_id_sucursal int,
		@p_id_tercero int,
		@p_id_subtipoDocumento int,
		@p_fechaFin_ff smalldatetime,
		@p_mesVencido bit,
		@p_alquiler_numero int,
		@p_observaciones varchar(500),
		@p_id_documento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_alquiler]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[alquiler],
			[alquiler_codigo],
			[fechaCompromiso_ff],
			[id_sucursal],
			[id_tercero],
			[id_subtipoDocumento],
			[fechaFin_ff],
			[mesVencido],
			[alquiler_numero],
			[observaciones],
			[id_documento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_alquiler,
			@p_alquiler_codigo,
			@p_fechaCompromiso_ff,
			@p_id_sucursal,
			@p_id_tercero,
			@p_id_subtipoDocumento,
			@p_fechaFin_ff,
			@p_mesVencido,
			@p_alquiler_numero,
			@p_observaciones,
			@p_id_documento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_alquiler] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
