GO
CREATE PROCEDURE [aud_equ_alquiler]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_alquiler].id as id_tabla,
	[equ_alquiler].id_usuario_modifico as id_usuario_modifico,
	[equ_alquiler].id_usuario_creo as id_usuario_creo,
	[equ_alquiler].fechaModificacion as fechaModificacion,
	[equ_alquiler].fechaCreacion as fechaCreacion,
	[equ_alquiler].active as active,
	[equ_alquiler].[alquiler] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_alquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_alquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_alquiler].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
