		[cat_catalogo_equipo].[tiempoConsecucion] AS [cat_catalogo_equipo_tiempoConsecucion],
		[cat_catalogo_equipo].[esNacional] AS [cat_catalogo_equipo_esNacional],
		[cat_catalogo_equipo].[id_familia] AS [cat_catalogo_equipo_id_familia],
		[cat_catalogo_equipo].[id_subtipoCatalogo] AS [cat_catalogo_equipo_id_subtipoCatalogo],
		[cat_catalogo_equipo].[id_unidad] AS [cat_catalogo_equipo_id_unidad],
		[cat_catalogo_equipo].[id_impuesto] AS [cat_catalogo_equipo_id_impuesto],
		[cat_catalogo_equipo].[descripcion] AS [cat_catalogo_equipo_descripcion],
		[cat_catalogo_equipo].[bloquearCostear] AS [cat_catalogo_equipo_bloquearCostear],
		[cat_catalogo_equipo].[cmm] AS [cat_catalogo_equipo_cmm],
		[equ_analisisFalla].[id_falla] AS [id_falla],
[equ_falla].[falla] as [equ_falla_falla],
[equ_falla].[falla_codigo] as [equ_falla_falla_codigo],
[equ_falla].[procedimiento] as [equ_falla_procedimiento],
[equ_falla].[id_tipoFalla] as [equ_falla_id_tipoFalla],
[equ_falla].[id_falla] as [equ_falla_id_falla],
[equ_falla].[cmm] as [equ_falla_cmm],
		[equ_analisisFalla].[id_falla_causa] AS [id_falla_causa],
[equ_falla_causa].[falla] as [equ_falla_causa_falla],
[equ_falla_causa].[falla_codigo] as [equ_falla_causa_falla_codigo],
[equ_falla_causa].[procedimiento] as [equ_falla_causa_procedimiento],
[equ_falla_causa].[id_tipoFalla] as [equ_falla_causa_id_tipoFalla],
[equ_falla_causa].[id_falla] as [equ_falla_causa_id_falla],
[equ_falla_causa].[cmm] as [equ_falla_causa_cmm],
		[equ_analisisFalla].[id_falla_efecto] AS [id_falla_efecto],
[equ_falla_efecto].[falla] as [equ_falla_efecto_falla],
[equ_falla_efecto].[falla_codigo] as [equ_falla_efecto_falla_codigo],
[equ_falla_efecto].[procedimiento] as [equ_falla_efecto_procedimiento],
[equ_falla_efecto].[id_tipoFalla] as [equ_falla_efecto_id_tipoFalla],
[equ_falla_efecto].[id_falla] as [equ_falla_efecto_id_falla],
[equ_falla_efecto].[cmm] as [equ_falla_efecto_cmm],
		[equ_analisisFalla].[id_falla_solucion] AS [id_falla_solucion],
[equ_falla_solucion].[falla] as [equ_falla_solucion_falla],
[equ_falla_solucion].[falla_codigo] as [equ_falla_solucion_falla_codigo],
[equ_falla_solucion].[procedimiento] as [equ_falla_solucion_procedimiento],
[equ_falla_solucion].[id_tipoFalla] as [equ_falla_solucion_id_tipoFalla],
[equ_falla_solucion].[id_falla] as [equ_falla_solucion_id_falla],
[equ_falla_solucion].[cmm] as [equ_falla_solucion_cmm],
		[equ_analisisFalla].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_analisisFalla]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_analisisFalla].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_analisisFalla].[id_usuario_creo]
	INNER JOIN [cat_catalogo.equipo] ON [cat_catalogo.equipo].id=[equ_analisisFalla].[id_catalogo.equipo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_equipo] ON [cat_catalogo.equipo].id = [cat_catalogo_equipo].id
	INNER JOIN [equ_falla] ON [equ_falla].id=[equ_analisisFalla].[id_falla]
	INNER JOIN [equ_falla] AS [equ_falla_causa] ON [equ_falla_causa].id=[equ_analisisFalla].[id_falla_causa]
	INNER JOIN [equ_falla] AS [equ_falla_efecto] ON [equ_falla_efecto].id=[equ_analisisFalla].[id_falla_efecto]
	INNER JOIN [equ_falla] AS [equ_falla_solucion] ON [equ_falla_solucion].id=[equ_analisisFalla].[id_falla_solucion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_analisisFalla].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_analisisFalla].active=1
