GO
CREATE PROCEDURE [upd_equ_analisisFalla]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_analisisFalla varchar(300) = null,
		@p_analisisFalla_codigo varchar(100) = null,
		@p_id_catalogo_equipo int = null,
		@p_id_falla int = null,
		@p_id_falla_causa int = null,
		@p_id_falla_efecto int = null,
		@p_id_falla_solucion int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_analisisFalla]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[analisisFalla] = isnull(@p_analisisFalla,[analisisFalla]),
			[analisisFalla_codigo] = isnull(@p_analisisFalla_codigo,[analisisFalla_codigo]),
			[id_catalogo.equipo] = isnull(@p_id_catalogo_equipo,[id_catalogo.equipo]),
			[id_falla] = isnull(@p_id_falla,[id_falla]),
			[id_falla_causa] = isnull(@p_id_falla_causa,[id_falla_causa]),
			[id_falla_efecto] = isnull(@p_id_falla_efecto,[id_falla_efecto]),
			[id_falla_solucion] = isnull(@p_id_falla_solucion,[id_falla_solucion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
