IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_analisisFalla]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_analisisFalla]
GO
CREATE PROCEDURE [ins_equ_analisisFalla]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_analisisFalla varchar(300),
		@p_analisisFalla_codigo varchar(100),
		@p_id_catalogo_equipo int,
		@p_id_falla int,
		@p_id_falla_causa int,
		@p_id_falla_efecto int,
		@p_id_falla_solucion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_analisisFalla]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[analisisFalla],
			[analisisFalla_codigo],
			[id_catalogo.equipo],
			[id_falla],
			[id_falla_causa],
			[id_falla_efecto],
			[id_falla_solucion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_analisisFalla,
			@p_analisisFalla_codigo,
			@p_id_catalogo_equipo,
			@p_id_falla,
			@p_id_falla_causa,
			@p_id_falla_efecto,
			@p_id_falla_solucion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_analisisFalla] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
