		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[analisisFalla] AS [analisisFalla],
		[analisisFalla_codigo] AS [analisisFalla_codigo],
		[id_catalogo.equipo] AS [id_catalogo.equipo],
		[id_falla] AS [id_falla],
		[id_falla_causa] AS [id_falla_causa],
		[id_falla_efecto] AS [id_falla_efecto],
		[id_falla_solucion] AS [id_falla_solucion],
		[cmm] AS [cmm]
	FROM [equ_analisisFalla]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
