IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_campana]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_campana]
GO
CREATE PROCEDURE [ins_equ_campana]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_campana varchar(300),
		@p_campana_codigo varchar(100),
		@p_detalleCampana varchar(8000),
		@p_fechaInicio_ff smalldatetime,
		@p_fechafin_ff smalldatetime,
		@p_activo bit,
		@p_id_tercero int,
		@p_id_catalogo_tempario int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_campana]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[campana],
			[campana_codigo],
			[detalleCampana],
			[fechaInicio_ff],
			[fechafin_ff],
			[activo],
			[id_tercero],
			[id_catalogo.tempario],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_campana,
			@p_campana_codigo,
			@p_detalleCampana,
			@p_fechaInicio_ff,
			@p_fechafin_ff,
			@p_activo,
			@p_id_tercero,
			@p_id_catalogo_tempario,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_campana] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
