CREATE PROCEDURE [aud_equ_campana]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_campana].id as id_tabla,
	[equ_campana].id_usuario_modifico as id_usuario_modifico,
	[equ_campana].id_usuario_creo as id_usuario_creo,
	[equ_campana].fechaModificacion as fechaModificacion,
	[equ_campana].fechaCreacion as fechaCreacion,
	[equ_campana].active as active,
	[equ_campana].[campana] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_campana]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_campana].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_campana].[id_usuario_creo]
	where ' + @p_filtro)
END
