		[doc_documento_ot].[id_usuario_enUso] AS [doc_documento_ot_id_usuario_enUso],
		[doc_documento_ot].[identificador] AS [doc_documento_ot_identificador],
		[doc_documento_ot].[cmm] AS [doc_documento_ot_cmm],
		[equ_campana_documento.OT].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_campana_documento.OT]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_campana_documento.OT].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_campana_documento.OT].[id_usuario_creo]
	INNER JOIN [equ_campana] ON [equ_campana].id=[equ_campana_documento.OT].[id_campana]
	INNER JOIN [doc_documento.ot] ON [doc_documento.ot].id=[equ_campana_documento.OT].[id_documento.ot]
	INNER JOIN [doc_documento] aS [doc_documento_ot] ON [doc_documento.ot].id = [doc_documento_ot].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_campana_documento.OT].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
