IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_campana_documento_OT]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_campana_documento_OT]
GO
CREATE PROCEDURE [ins_equ_campana_documento_OT]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_campana_documento_OT varchar(300),
		@p_id_campana int,
		@p_id_documento_ot int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_campana_documento.OT]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[campana_documento.OT],
			[id_campana],
			[id_documento.ot],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_campana_documento_OT,
			@p_id_campana,
			@p_id_documento_ot,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_campana_documento.OT] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
