CREATE PROCEDURE [aud_equ_campana_documento_OT]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_campana_documento.OT].id as id_tabla,
	[equ_campana_documento.OT].id_usuario_modifico as id_usuario_modifico,
	[equ_campana_documento.OT].id_usuario_creo as id_usuario_creo,
	[equ_campana_documento.OT].fechaModificacion as fechaModificacion,
	[equ_campana_documento.OT].fechaCreacion as fechaCreacion,
	[equ_campana_documento.OT].active as active,
	[equ_campana_documento.OT].[campana_documento.OT] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_campana_documento.OT]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_campana_documento.OT].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_campana_documento.OT].[id_usuario_creo]
	where ' + @p_filtro)
END
