GO
CREATE PROCEDURE [upd_equ_cicloHorometro]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_cicloHorometro varchar(300) = null,
		@p_cicloHorometro_codigo varchar(100) = null,
		@p_id_equipo int = null,
		@p_horometroInicial float = null,
		@p_horometroFinal float = null,
		@p_afectarProyeccion bit = null,
		@p_reparacionMayor bit = null,
		@p_reiniciarHorometro bit = null,
		@p_Nciclo int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_cicloHorometro]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[cicloHorometro] = isnull(@p_cicloHorometro,[cicloHorometro]),
			[cicloHorometro_codigo] = isnull(@p_cicloHorometro_codigo,[cicloHorometro_codigo]),
			[id_equipo] = isnull(@p_id_equipo,[id_equipo]),
			[horometroInicial] = isnull(@p_horometroInicial,[horometroInicial]),
			[horometroFinal] = isnull(@p_horometroFinal,[horometroFinal]),
			[afectarProyeccion] = isnull(@p_afectarProyeccion,[afectarProyeccion]),
			[reparacionMayor] = isnull(@p_reparacionMayor,[reparacionMayor]),
			[reiniciarHorometro] = isnull(@p_reiniciarHorometro,[reiniciarHorometro]),
			[Nciclo] = isnull(@p_Nciclo,[Nciclo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
