IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_cicloHorometro]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_cicloHorometro]
GO
CREATE PROCEDURE [ins_equ_cicloHorometro]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_cicloHorometro varchar(300),
		@p_cicloHorometro_codigo varchar(100),
		@p_id_equipo int,
		@p_horometroInicial float,
		@p_horometroFinal float,
		@p_afectarProyeccion bit,
		@p_reparacionMayor bit,
		@p_reiniciarHorometro bit,
		@p_Nciclo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_cicloHorometro]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[cicloHorometro],
			[cicloHorometro_codigo],
			[id_equipo],
			[horometroInicial],
			[horometroFinal],
			[afectarProyeccion],
			[reparacionMayor],
			[reiniciarHorometro],
			[Nciclo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_cicloHorometro,
			@p_cicloHorometro_codigo,
			@p_id_equipo,
			@p_horometroInicial,
			@p_horometroFinal,
			@p_afectarProyeccion,
			@p_reparacionMayor,
			@p_reiniciarHorometro,
			@p_Nciclo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_cicloHorometro] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
