CREATE PROCEDURE [aud_equ_cicloHorometro]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_cicloHorometro].id as id_tabla,
	[equ_cicloHorometro].id_usuario_modifico as id_usuario_modifico,
	[equ_cicloHorometro].id_usuario_creo as id_usuario_creo,
	[equ_cicloHorometro].fechaModificacion as fechaModificacion,
	[equ_cicloHorometro].fechaCreacion as fechaCreacion,
	[equ_cicloHorometro].active as active,
	[equ_cicloHorometro].[cicloHorometro] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_cicloHorometro]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_cicloHorometro].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_cicloHorometro].[id_usuario_creo]
	where ' + @p_filtro)
END
