	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_detalleAlquiler].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[equ_detalleAlquiler].[id_equipo]
	INNER JOIN [doc_documento.alquiler] ON [doc_documento.alquiler].id=[equ_detalleAlquiler].[id_documento.alquiler]
	INNER JOIN [doc_documento] aS [doc_documento_alquiler] ON [doc_documento.alquiler].id = [doc_documento_alquiler].id
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[equ_detalleAlquiler].[id_sucursal]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[equ_detalleAlquiler].[id_tercero]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[equ_detalleAlquiler].[id_catalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_detalleAlquiler].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_detalleAlquiler].active=1
GO
