GO
CREATE PROCEDURE [upd_equ_detalleAlquiler]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detalleAlquiler varchar(300) = null,
		@p_detalleAlquiler_codigo varchar(100) = null,
		@p_fechaDevolucion_ff smalldatetime = null,
		@p_valorHora money = null,
		@p_ValorHoraStandBy money = null,
		@p_valorPeriodo money = null,
		@p_valorMulta money = null,
		@p_fechaDespacho_ff smalldatetime = null,
		@p_id_equipo int = null,
		@p_id_documento_alquiler int = null,
		@p_id_sucursal int = null,
		@p_id_tercero int = null,
		@p_fechaUltimaFactura_fh smalldatetime = null,
		@p_valorMes float = null,
		@p_fechaInicioFactura_fh smalldatetime = null,
		@p_cantidadSolicitada int = null,
		@p_cantidadAlquilada int = null,
		@p_id_catalogo int = null,
		@p_estadoalquiler int = null,
		@p_esSerializado bit = null,
		@p_bloquearDespacho bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_detalleAlquiler]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detalleAlquiler] = isnull(@p_detalleAlquiler,[detalleAlquiler]),
			[detalleAlquiler_codigo] = isnull(@p_detalleAlquiler_codigo,[detalleAlquiler_codigo]),
			[fechaDevolucion_ff] = isnull(@p_fechaDevolucion_ff,[fechaDevolucion_ff]),
			[valorHora] = isnull(@p_valorHora,[valorHora]),
			[ValorHoraStandBy] = isnull(@p_ValorHoraStandBy,[ValorHoraStandBy]),
			[valorPeriodo] = isnull(@p_valorPeriodo,[valorPeriodo]),
			[valorMulta] = isnull(@p_valorMulta,[valorMulta]),
			[fechaDespacho_ff] = isnull(@p_fechaDespacho_ff,[fechaDespacho_ff]),
			[id_equipo] = isnull(@p_id_equipo,[id_equipo]),
			[id_documento.alquiler] = isnull(@p_id_documento_alquiler,[id_documento.alquiler]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[id_tercero] = isnull(@p_id_tercero,[id_tercero]),
			[fechaUltimaFactura_fh] = isnull(@p_fechaUltimaFactura_fh,[fechaUltimaFactura_fh]),
			[valorMes] = isnull(@p_valorMes,[valorMes]),
			[fechaInicioFactura_fh] = isnull(@p_fechaInicioFactura_fh,[fechaInicioFactura_fh]),
			[cantidadSolicitada] = isnull(@p_cantidadSolicitada,[cantidadSolicitada]),
			[cantidadAlquilada] = isnull(@p_cantidadAlquilada,[cantidadAlquilada]),
			[id_catalogo] = isnull(@p_id_catalogo,[id_catalogo]),
			[estadoalquiler] = isnull(@p_estadoalquiler,[estadoalquiler]),
			[esSerializado] = isnull(@p_esSerializado,[esSerializado]),
			[bloquearDespacho] = isnull(@p_bloquearDespacho,[bloquearDespacho]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
