GO
CREATE PROCEDURE [ins_equ_detalleAlquiler]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detalleAlquiler varchar(300),
		@p_detalleAlquiler_codigo varchar(100),
		@p_fechaDevolucion_ff smalldatetime,
		@p_valorHora money,
		@p_ValorHoraStandBy money,
		@p_valorPeriodo money,
		@p_valorMulta money,
		@p_fechaDespacho_ff smalldatetime,
		@p_id_equipo int,
		@p_id_documento_alquiler int,
		@p_id_sucursal int,
		@p_id_tercero int,
		@p_fechaUltimaFactura_fh smalldatetime,
		@p_valorMes float,
		@p_fechaInicioFactura_fh smalldatetime,
		@p_cantidadSolicitada int,
		@p_cantidadAlquilada int,
		@p_id_catalogo int,
		@p_estadoalquiler int,
		@p_esSerializado bit,
		@p_bloquearDespacho bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_detalleAlquiler]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detalleAlquiler],
			[detalleAlquiler_codigo],
			[fechaDevolucion_ff],
			[valorHora],
			[ValorHoraStandBy],
			[valorPeriodo],
			[valorMulta],
			[fechaDespacho_ff],
			[id_equipo],
			[id_documento.alquiler],
			[id_sucursal],
			[id_tercero],
			[fechaUltimaFactura_fh],
			[valorMes],
			[fechaInicioFactura_fh],
			[cantidadSolicitada],
			[cantidadAlquilada],
			[id_catalogo],
			[estadoalquiler],
			[esSerializado],
			[bloquearDespacho],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detalleAlquiler,
			@p_detalleAlquiler_codigo,
			@p_fechaDevolucion_ff,
			@p_valorHora,
			@p_ValorHoraStandBy,
			@p_valorPeriodo,
			@p_valorMulta,
			@p_fechaDespacho_ff,
			@p_id_equipo,
			@p_id_documento_alquiler,
			@p_id_sucursal,
			@p_id_tercero,
			@p_fechaUltimaFactura_fh,
			@p_valorMes,
			@p_fechaInicioFactura_fh,
			@p_cantidadSolicitada,
			@p_cantidadAlquilada,
			@p_id_catalogo,
			@p_estadoalquiler,
			@p_esSerializado,
			@p_bloquearDespacho,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_detalleAlquiler] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
