		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[detalleAlquiler] AS [detalleAlquiler],
		[detalleAlquiler_codigo] AS [detalleAlquiler_codigo],
		[fechaDevolucion_ff] AS [fechaDevolucion_ff],
		[valorHora] AS [valorHora],
		[ValorHoraStandBy] AS [ValorHoraStandBy],
		[valorPeriodo] AS [valorPeriodo],
		[valorMulta] AS [valorMulta],
		[fechaDespacho_ff] AS [fechaDespacho_ff],
		[id_equipo] AS [id_equipo],
		[id_documento.alquiler] AS [id_documento.alquiler],
		[id_sucursal] AS [id_sucursal],
		[id_tercero] AS [id_tercero],
		[fechaUltimaFactura_fh] AS [fechaUltimaFactura_fh],
		[valorMes] AS [valorMes],
		[fechaInicioFactura_fh] AS [fechaInicioFactura_fh],
		[cantidadSolicitada] AS [cantidadSolicitada],
		[cantidadAlquilada] AS [cantidadAlquilada],
		[id_catalogo] AS [id_catalogo],
		[estadoalquiler] AS [estadoalquiler],
		[esSerializado] AS [esSerializado],
		[bloquearDespacho] AS [bloquearDespacho],
		[cmm] AS [cmm]
	FROM [equ_detalleAlquiler]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

