GO
CREATE PROCEDURE [aud_equ_detalleAlquiler]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_detalleAlquiler].id as id_tabla,
	[equ_detalleAlquiler].id_usuario_modifico as id_usuario_modifico,
	[equ_detalleAlquiler].id_usuario_creo as id_usuario_creo,
	[equ_detalleAlquiler].fechaModificacion as fechaModificacion,
	[equ_detalleAlquiler].fechaCreacion as fechaCreacion,
	[equ_detalleAlquiler].active as active,
	[equ_detalleAlquiler].[detalleAlquiler] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_detalleAlquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_detalleAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_detalleAlquiler].[id_usuario_creo]
	where ' + @p_filtro)
END
