	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_detallePagoAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_detallePagoAlquiler].[id_usuario_creo]
	INNER JOIN [equ_pagoAlquiler] ON [equ_pagoAlquiler].id=[equ_detallePagoAlquiler].[id_pagoAlquiler]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[equ_detallePagoAlquiler].[id_equipo]
	INNER JOIN [doc_documento] ON [doc_documento].id=[equ_detallePagoAlquiler].[id_documento]
	INNER JOIN [doc_itemDocumento] ON [doc_itemDocumento].id=[equ_detallePagoAlquiler].[id_itemDocumento]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_detallePagoAlquiler].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_detallePagoAlquiler].active=1
