CREATE PROCEDURE [upd_equ_detallePagoAlquiler]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detallePagoAlquiler varchar(300) = null,
		@p_detallePagoAlquiler_codigo varchar(100) = null,
		@p_valor money = null,
		@p_horometro float = null,
		@p_id_pagoAlquiler int = null,
		@p_id_equipo int = null,
		@p_valorMulta float = null,
		@p_facturado bit = null,
		@p_fechaInicial_ff smalldatetime = null,
		@p_fechaFin_ff smalldatetime = null,
		@p_id_documento int = null,
		@p_id_itemDocumento int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_detallePagoAlquiler]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detallePagoAlquiler] = isnull(@p_detallePagoAlquiler,[detallePagoAlquiler]),
			[detallePagoAlquiler_codigo] = isnull(@p_detallePagoAlquiler_codigo,[detallePagoAlquiler_codigo]),
			[valor] = isnull(@p_valor,[valor]),
			[horometro] = isnull(@p_horometro,[horometro]),
			[id_pagoAlquiler] = isnull(@p_id_pagoAlquiler,[id_pagoAlquiler]),
			[id_equipo] = isnull(@p_id_equipo,[id_equipo]),
			[valorMulta] = isnull(@p_valorMulta,[valorMulta]),
			[facturado] = isnull(@p_facturado,[facturado]),
			[fechaInicial_ff] = isnull(@p_fechaInicial_ff,[fechaInicial_ff]),
			[fechaFin_ff] = isnull(@p_fechaFin_ff,[fechaFin_ff]),
			[id_documento] = isnull(@p_id_documento,[id_documento]),
			[id_itemDocumento] = isnull(@p_id_itemDocumento,[id_itemDocumento]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
