GO
CREATE PROCEDURE [ins_equ_detallePagoAlquiler]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detallePagoAlquiler varchar(300),
		@p_detallePagoAlquiler_codigo varchar(100),
		@p_valor money,
		@p_horometro float,
		@p_id_pagoAlquiler int,
		@p_id_equipo int,
		@p_valorMulta float,
		@p_facturado bit,
		@p_fechaInicial_ff smalldatetime,
		@p_fechaFin_ff smalldatetime,
		@p_id_documento int,
		@p_id_itemDocumento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_detallePagoAlquiler]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detallePagoAlquiler],
			[detallePagoAlquiler_codigo],
			[valor],
			[horometro],
			[id_pagoAlquiler],
			[id_equipo],
			[valorMulta],
			[facturado],
			[fechaInicial_ff],
			[fechaFin_ff],
			[id_documento],
			[id_itemDocumento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detallePagoAlquiler,
			@p_detallePagoAlquiler_codigo,
			@p_valor,
			@p_horometro,
			@p_id_pagoAlquiler,
			@p_id_equipo,
			@p_valorMulta,
			@p_facturado,
			@p_fechaInicial_ff,
			@p_fechaFin_ff,
			@p_id_documento,
			@p_id_itemDocumento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_detallePagoAlquiler] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
