CREATE PROCEDURE [aud_equ_detallePagoAlquiler]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_detallePagoAlquiler].id as id_tabla,
	[equ_detallePagoAlquiler].id_usuario_modifico as id_usuario_modifico,
	[equ_detallePagoAlquiler].id_usuario_creo as id_usuario_creo,
	[equ_detallePagoAlquiler].fechaModificacion as fechaModificacion,
	[equ_detallePagoAlquiler].fechaCreacion as fechaCreacion,
	[equ_detallePagoAlquiler].active as active,
	[equ_detallePagoAlquiler].[detallePagoAlquiler] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_detallePagoAlquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_detallePagoAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_detallePagoAlquiler].[id_usuario_creo]
	where ' + @p_filtro)
END
