	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_equipo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_equipo].[id_usuario_creo]
	INNER JOIN [cat_catalogo.equipo] ON [cat_catalogo.equipo].id=[equ_equipo].[id_catalogo.equipo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_equipo] ON [cat_catalogo.equipo].id = [cat_catalogo_equipo].id
	INNER JOIN [cat_sistema] ON [cat_sistema].id=[equ_equipo].[id_sistema]
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[equ_equipo].[id_sucursal]
	INNER JOIN [gen_zona] ON [gen_zona].id=[equ_equipo].[id_zona]
	INNER JOIN [cat_versionEquipo] ON [cat_versionEquipo].id=[equ_equipo].[id_versionEquipo]
	INNER JOIN [ter_tercero] AS [ter_tercero_comprador] ON [ter_tercero_comprador].id=[equ_equipo].[id_tercero_comprador]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[equ_equipo].[id_tercero]
	INNER JOIN [ter_tercero] AS [ter_tercero_servicio] ON [ter_tercero_servicio].id=[equ_equipo].[id_tercero_servicio]
	INNER JOIN [equ_equipo] AS [equ_equipo_padre] ON [equ_equipo_padre].id=[equ_equipo].[id_equipo]
	INNER JOIN [equ_estadoEquipo] ON [equ_estadoEquipo].id=[equ_equipo].[id_estadoEquipo]
	INNER JOIN [doc_centroCosto] ON [doc_centroCosto].id=[equ_equipo].[id_centroCosto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_equipo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_equipo].active=1
