GO
CREATE PROCEDURE [upd_equ_equipo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_equipo varchar(300) = null,
		@p_equipo_codigo varchar(100) = null,
		@p_equipo_serial varchar(100) = null,
		@p_nombreContacto varchar(100) = null,
		@p_telefonoContacto varchar(100) = null,
		@p_ubicacion varchar(300) = null,
		@p_observaciones varchar(300) = null,
		@p_fechaPuestaMarcha_fh smalldatetime = null,
		@p_vencimientoGarantiaFabrica_ff smalldatetime = null,
		@p_vencimientoGarantiaDistribuidor_ff smalldatetime = null,
		@p_horasGarantia float = null,
		@p_ultimaLectura_fh smalldatetime = null,
		@p_horometroActual float = null,
		@p_promedioHoras float = null,
		@p_costo money = null,
		@p_fechaImportacion_ff smalldatetime = null,
		@p_garantiaCancelada varchar(100) = null,
		@p_id_catalogo_equipo int = null,
		@p_id_sistema int = null,
		@p_id_sucursal int = null,
		@p_id_zona int = null,
		@p_id_versionEquipo int = null,
		@p_id_tercero_comprador int = null,
		@p_id_tercero int = null,
		@p_id_tercero_servicio int = null,
		@p_id_equipo int = null,
		@p_id_estadoEquipo int = null,
		@p_id_centroCosto int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_equipo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[equipo] = isnull(@p_equipo,[equipo]),
			[equipo_codigo] = isnull(@p_equipo_codigo,[equipo_codigo]),
			[equipo_serial] = isnull(@p_equipo_serial,[equipo_serial]),
			[nombreContacto] = isnull(@p_nombreContacto,[nombreContacto]),
			[telefonoContacto] = isnull(@p_telefonoContacto,[telefonoContacto]),
			[ubicacion] = isnull(@p_ubicacion,[ubicacion]),
			[observaciones] = isnull(@p_observaciones,[observaciones]),
			[fechaPuestaMarcha_fh] = isnull(@p_fechaPuestaMarcha_fh,[fechaPuestaMarcha_fh]),
			[vencimientoGarantiaFabrica_ff] = isnull(@p_vencimientoGarantiaFabrica_ff,[vencimientoGarantiaFabrica_ff]),
			[vencimientoGarantiaDistribuidor_ff] = isnull(@p_vencimientoGarantiaDistribuidor_ff,[vencimientoGarantiaDistribuidor_ff]),
			[horasGarantia] = isnull(@p_horasGarantia,[horasGarantia]),
			[ultimaLectura_fh] = isnull(@p_ultimaLectura_fh,[ultimaLectura_fh]),
			[horometroActual] = isnull(@p_horometroActual,[horometroActual]),
			[promedioHoras] = isnull(@p_promedioHoras,[promedioHoras]),
			[costo] = isnull(@p_costo,[costo]),
			[fechaImportacion_ff] = isnull(@p_fechaImportacion_ff,[fechaImportacion_ff]),
			[garantiaCancelada] = isnull(@p_garantiaCancelada,[garantiaCancelada]),
			[id_catalogo.equipo] = isnull(@p_id_catalogo_equipo,[id_catalogo.equipo]),
			[id_sistema] = isnull(@p_id_sistema,[id_sistema]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[id_zona] = isnull(@p_id_zona,[id_zona]),
			[id_versionEquipo] = isnull(@p_id_versionEquipo,[id_versionEquipo]),
			[id_tercero_comprador] = isnull(@p_id_tercero_comprador,[id_tercero_comprador]),
			[id_tercero] = isnull(@p_id_tercero,[id_tercero]),
			[id_tercero_servicio] = isnull(@p_id_tercero_servicio,[id_tercero_servicio]),
			[id_equipo] = isnull(@p_id_equipo,[id_equipo]),
			[id_estadoEquipo] = isnull(@p_id_estadoEquipo,[id_estadoEquipo]),
			[id_centroCosto] = isnull(@p_id_centroCosto,[id_centroCosto]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
