IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_equipo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_equipo]
GO
CREATE PROCEDURE [ins_equ_equipo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_equipo varchar(300),
		@p_equipo_codigo varchar(100),
		@p_equipo_serial varchar(100),
		@p_nombreContacto varchar(100),
		@p_telefonoContacto varchar(100),
		@p_ubicacion varchar(300),
		@p_observaciones varchar(300),
		@p_fechaPuestaMarcha_fh smalldatetime,
		@p_vencimientoGarantiaFabrica_ff smalldatetime,
		@p_vencimientoGarantiaDistribuidor_ff smalldatetime,
		@p_horasGarantia float,
		@p_ultimaLectura_fh smalldatetime,
		@p_horometroActual float,
		@p_promedioHoras float,
		@p_costo money,
		@p_fechaImportacion_ff smalldatetime,
		@p_garantiaCancelada varchar(100),
		@p_id_catalogo_equipo int,
		@p_id_sistema int,
		@p_id_sucursal int,
		@p_id_zona int,
		@p_id_versionEquipo int,
		@p_id_tercero_comprador int,
		@p_id_tercero int,
		@p_id_tercero_servicio int,
		@p_id_equipo int,
		@p_id_estadoEquipo int,
		@p_id_centroCosto int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_equipo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[equipo],
			[equipo_codigo],
			[equipo_serial],
			[nombreContacto],
			[telefonoContacto],
			[ubicacion],
			[observaciones],
			[fechaPuestaMarcha_fh],
			[vencimientoGarantiaFabrica_ff],
			[vencimientoGarantiaDistribuidor_ff],
			[horasGarantia],
			[ultimaLectura_fh],
			[horometroActual],
			[promedioHoras],
			[costo],
			[fechaImportacion_ff],
			[garantiaCancelada],
			[id_catalogo.equipo],
			[id_sistema],
			[id_sucursal],
			[id_zona],
			[id_versionEquipo],
			[id_tercero_comprador],
			[id_tercero],
			[id_tercero_servicio],
			[id_equipo],
			[id_estadoEquipo],
			[id_centroCosto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_equipo,
			@p_equipo_codigo,
			@p_equipo_serial,
			@p_nombreContacto,
			@p_telefonoContacto,
			@p_ubicacion,
			@p_observaciones,
			@p_fechaPuestaMarcha_fh,
			@p_vencimientoGarantiaFabrica_ff,
			@p_vencimientoGarantiaDistribuidor_ff,
			@p_horasGarantia,
			@p_ultimaLectura_fh,
			@p_horometroActual,
			@p_promedioHoras,
			@p_costo,
			@p_fechaImportacion_ff,
			@p_garantiaCancelada,
			@p_id_catalogo_equipo,
			@p_id_sistema,
			@p_id_sucursal,
			@p_id_zona,
			@p_id_versionEquipo,
			@p_id_tercero_comprador,
			@p_id_tercero,
			@p_id_tercero_servicio,
			@p_id_equipo,
			@p_id_estadoEquipo,
			@p_id_centroCosto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_equipo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
