		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[equipo] AS [equipo],
		[equipo_codigo] AS [equipo_codigo],
		[equipo_serial] AS [equipo_serial],
		[nombreContacto] AS [nombreContacto],
		[telefonoContacto] AS [telefonoContacto],
		[ubicacion] AS [ubicacion],
		[observaciones] AS [observaciones],
		[fechaPuestaMarcha_fh] AS [fechaPuestaMarcha_fh],
		[vencimientoGarantiaFabrica_ff] AS [vencimientoGarantiaFabrica_ff],
		[vencimientoGarantiaDistribuidor_ff] AS [vencimientoGarantiaDistribuidor_ff],
		[horasGarantia] AS [horasGarantia],
		[ultimaLectura_fh] AS [ultimaLectura_fh],
		[horometroActual] AS [horometroActual],
		[promedioHoras] AS [promedioHoras],
		[costo] AS [costo],
		[fechaImportacion_ff] AS [fechaImportacion_ff],
		[garantiaCancelada] AS [garantiaCancelada],
		[id_catalogo.equipo] AS [id_catalogo.equipo],
		[id_sistema] AS [id_sistema],
		[id_sucursal] AS [id_sucursal],
		[id_zona] AS [id_zona],
		[id_versionEquipo] AS [id_versionEquipo],
		[id_tercero_comprador] AS [id_tercero_comprador],
		[id_tercero] AS [id_tercero],
		[id_tercero_servicio] AS [id_tercero_servicio],
		[id_equipo] AS [id_equipo],
		[id_estadoEquipo] AS [id_estadoEquipo],
		[id_centroCosto] AS [id_centroCosto],
		[cmm] AS [cmm]
	FROM [equ_equipo]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
