IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[aud_equ_equipo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[aud_equ_equipo]
GO
CREATE PROCEDURE [aud_equ_equipo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_equipo].id as id_tabla,
	[equ_equipo].id_usuario_modifico as id_usuario_modifico,
	[equ_equipo].id_usuario_creo as id_usuario_creo,
	[equ_equipo].fechaModificacion as fechaModificacion,
	[equ_equipo].fechaCreacion as fechaCreacion,
	[equ_equipo].active as active,
	[equ_equipo].[equipo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_equipo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_equipo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_equipo].[id_usuario_creo]
	where ' + @p_filtro)
END
