IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_dis_obra_equipo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_dis_obra_equipo]
GO
CREATE PROCEDURE [ins_dis_obra_equipo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_obra_equipo varchar(300),
		@p_id_obra int,
		@p_id_equipo int,
		@p_promedioEsperado float,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [dis_obra_equipo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[obra_equipo],
			[id_obra],
			[id_equipo],
			[promedioEsperado],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_obra_equipo,
			@p_id_obra,
			@p_id_equipo,
			@p_promedioEsperado,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [dis_obra_equipo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
