[cat_catalogo].[tiempoConsecucion] as [cat_catalogo_tiempoConsecucion],
[cat_catalogo].[esNacional] as [cat_catalogo_esNacional],
[cat_catalogo].[id_familia] as [cat_catalogo_id_familia],
[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[equ_equipo_itemDocumento].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_equipo_itemDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_equipo_itemDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_equipo_itemDocumento].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[equ_equipo_itemDocumento].[id_equipo]
	INNER JOIN [doc_itemDocumento] ON [doc_itemDocumento].id=[equ_equipo_itemDocumento].[id_itemDocumento]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[equ_equipo_itemDocumento].[id_catalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_equipo_itemDocumento].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
