IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_equipo_itemDocumento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_equipo_itemDocumento]
GO
CREATE PROCEDURE [ins_equ_equipo_itemDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_equipo_itemDocumento varchar(300),
		@p_id_equipo int,
		@p_id_itemDocumento int,
		@p_id_catalogo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_equipo_itemDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[equipo_itemDocumento],
			[id_equipo],
			[id_itemDocumento],
			[id_catalogo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_equipo_itemDocumento,
			@p_id_equipo,
			@p_id_itemDocumento,
			@p_id_catalogo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_equipo_itemDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
