CREATE PROCEDURE [aud_equ_equipo_itemDocumento]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_equipo_itemDocumento].id as id_tabla,
	[equ_equipo_itemDocumento].id_usuario_modifico as id_usuario_modifico,
	[equ_equipo_itemDocumento].id_usuario_creo as id_usuario_creo,
	[equ_equipo_itemDocumento].fechaModificacion as fechaModificacion,
	[equ_equipo_itemDocumento].fechaCreacion as fechaCreacion,
	[equ_equipo_itemDocumento].active as active,
	[equ_equipo_itemDocumento].[equipo_itemDocumento] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_equipo_itemDocumento]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_equipo_itemDocumento].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_equipo_itemDocumento].[id_usuario_creo]
	where ' + @p_filtro)
END
