[equ_equipo].[costo] as [equ_equipo_costo],
[equ_equipo].[fechaImportacion_ff] as [equ_equipo_fechaImportacion_ff],
[equ_equipo].[garantiaCancelada] as [equ_equipo_garantiaCancelada],
[equ_equipo].[id_catalogo.equipo] as [equ_equipo_id_catalogo.equipo],
[equ_equipo].[id_sistema] as [equ_equipo_id_sistema],
[equ_equipo].[id_sucursal] as [equ_equipo_id_sucursal],
[equ_equipo].[id_zona] as [equ_equipo_id_zona],
[equ_equipo].[id_versionEquipo] as [equ_equipo_id_versionEquipo],
[equ_equipo].[id_tercero_comprador] as [equ_equipo_id_tercero_comprador],
[equ_equipo].[id_tercero] as [equ_equipo_id_tercero],
[equ_equipo].[id_tercero_servicio] as [equ_equipo_id_tercero_servicio],
[equ_equipo].[id_equipo] as [equ_equipo_id_equipo],
[equ_equipo].[id_estadoEquipo] as [equ_equipo_id_estadoEquipo],
[equ_equipo].[id_centroCosto] as [equ_equipo_id_centroCosto],
[equ_equipo].[cmm] as [equ_equipo_cmm],
		[equ_equipoAtributo].[id_atributo] AS [id_atributo],
[cat_atributo].[atributo] as [cat_atributo_atributo],
[cat_atributo].[atributo_codigo] as [cat_atributo_atributo_codigo],
[cat_atributo].[id_unidad] as [cat_atributo_id_unidad],
[cat_atributo].[cmm] as [cat_atributo_cmm],
		[equ_equipoAtributo].[id_opcionAtributo] AS [id_opcionAtributo],
[equ_opcionAtributo].[opcionAtributo] as [equ_opcionAtributo_opcionAtributo],
[equ_opcionAtributo].[opcionAtributo_codigo] as [equ_opcionAtributo_opcionAtributo_codigo],
[equ_opcionAtributo].[orden] as [equ_opcionAtributo_orden],
[equ_opcionAtributo].[id_atributo] as [equ_opcionAtributo_id_atributo],
[equ_opcionAtributo].[cmm] as [equ_opcionAtributo_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_equipoAtributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_equipoAtributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_equipoAtributo].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[equ_equipoAtributo].[id_equipo]
	INNER JOIN [cat_atributo] ON [cat_atributo].id=[equ_equipoAtributo].[id_atributo]
	INNER JOIN [equ_opcionAtributo] ON [equ_opcionAtributo].id=[equ_equipoAtributo].[id_opcionAtributo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_equipoAtributo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_equipoAtributo].active=1
