IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_equipoAtributo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_equipoAtributo]
GO
CREATE PROCEDURE [ins_equ_equipoAtributo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_equipoAtributo nvarchar(-1),
		@p_equipoAtributo_codigo varchar(500),
		@p_id_equipo int,
		@p_id_atributo int,
		@p_id_opcionAtributo int
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_equipoAtributo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[equipoAtributo],
			[equipoAtributo_codigo],
			[id_equipo],
			[id_atributo],
			[id_opcionAtributo])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_equipoAtributo,
			@p_equipoAtributo_codigo,
			@p_id_equipo,
			@p_id_atributo,
			@p_id_opcionAtributo)
		SET @v_id = scope_identity()
UPDATE [equ_equipoAtributo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
