CREATE PROCEDURE [aud_equ_equipoAtributo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_equipoAtributo].id as id_tabla,
	[equ_equipoAtributo].id_usuario_modifico as id_usuario_modifico,
	[equ_equipoAtributo].id_usuario_creo as id_usuario_creo,
	[equ_equipoAtributo].fechaModificacion as fechaModificacion,
	[equ_equipoAtributo].fechaCreacion as fechaCreacion,
	[equ_equipoAtributo].active as active,
	[equ_equipoAtributo].[equipoAtributo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_equipoAtributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_equipoAtributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_equipoAtributo].[id_usuario_creo]
	where ' + @p_filtro)
END
