IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_equ_falla]')) DROP VIEW [dbo].[view_equ_falla]
GO
CREATE  VIEW [view_equ_falla] AS
SELECT 	[equ_falla].[id] AS [id],
		[equ_falla].[uid] AS [uid],
		[equ_falla].[eid] AS [eid],
		[equ_falla].[id_usuario_modifico] AS [id_usuario_modifico],
		[equ_falla].[id_usuario_creo] AS [id_usuario_creo],
		[equ_falla].[fechaModificacion] AS [fechaModificacion],
		[equ_falla].[fechaCreacion] AS [fechaCreacion],
		[equ_falla].[active] AS [active],
		[equ_falla].[falla] AS [falla],
		[equ_falla].[falla_codigo] AS [falla_codigo],
		[equ_falla].[procedimiento] AS [procedimiento],
		[equ_falla].[id_tipoFalla] AS [id_tipoFalla],
[equ_tipoFalla].[tipoFalla] as [equ_tipoFalla_tipoFalla],
[equ_tipoFalla].[tipoFalla_codigo] as [equ_tipoFalla_tipoFalla_codigo],
[equ_tipoFalla].[cmm] as [equ_tipoFalla_cmm],
		[equ_falla].[id_falla] AS [id_falla],
[equ_falla_padre].[falla] as [equ_falla_padre_falla],
[equ_falla_padre].[falla_codigo] as [equ_falla_padre_falla_codigo],
[equ_falla_padre].[procedimiento] as [equ_falla_padre_procedimiento],
[equ_falla_padre].[id_tipoFalla] as [equ_falla_padre_id_tipoFalla],
[equ_falla_padre].[id_falla] as [equ_falla_padre_id_falla],
[equ_falla_padre].[cmm] as [equ_falla_padre_cmm],
		[equ_falla].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_falla]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_falla].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_falla].[id_usuario_creo]
	INNER JOIN [equ_tipoFalla] ON [equ_tipoFalla].id=[equ_falla].[id_tipoFalla]
	INNER JOIN [equ_falla] AS [equ_falla_padre] ON [equ_falla_padre].id=[equ_falla].[id_falla]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_falla].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_falla].active=1
GO
