CREATE PROCEDURE [aud_equ_falla]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_falla].id as id_tabla,
	[equ_falla].id_usuario_modifico as id_usuario_modifico,
	[equ_falla].id_usuario_creo as id_usuario_creo,
	[equ_falla].fechaModificacion as fechaModificacion,
	[equ_falla].fechaCreacion as fechaCreacion,
	[equ_falla].active as active,
	[equ_falla].[falla] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_falla]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_falla].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_falla].[id_usuario_creo]
	where ' + @p_filtro)
END
