[equ_falla].[falla_codigo] as [equ_falla_falla_codigo],
[equ_falla].[procedimiento] as [equ_falla_procedimiento],
[equ_falla].[id_tipoFalla] as [equ_falla_id_tipoFalla],
[equ_falla].[id_falla] as [equ_falla_id_falla],
[equ_falla].[cmm] as [equ_falla_cmm],
		[equ_familia_falla].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_familia_falla]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_familia_falla].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_familia_falla].[id_usuario_creo]
	INNER JOIN [gen_familia] ON [gen_familia].id=[equ_familia_falla].[id_familia]
	INNER JOIN [equ_falla] ON [equ_falla].id=[equ_familia_falla].[id_falla]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_familia_falla].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
