IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_familia_falla]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_familia_falla]
GO
CREATE PROCEDURE [ins_equ_familia_falla]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_familia_falla varchar(300),
		@p_id_familia int,
		@p_id_falla int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_familia_falla]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[familia_falla],
			[id_familia],
			[id_falla],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_familia_falla,
			@p_id_familia,
			@p_id_falla,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_familia_falla] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
