CREATE  VIEW [view_equ_opcionAtributo] AS
SELECT 	[equ_opcionAtributo].[id] AS [id],
		[equ_opcionAtributo].[uid] AS [uid],
		[equ_opcionAtributo].[eid] AS [eid],
		[equ_opcionAtributo].[id_usuario_modifico] AS [id_usuario_modifico],
		[equ_opcionAtributo].[id_usuario_creo] AS [id_usuario_creo],
		[equ_opcionAtributo].[fechaModificacion] AS [fechaModificacion],
		[equ_opcionAtributo].[fechaCreacion] AS [fechaCreacion],
		[equ_opcionAtributo].[active] AS [active],
		[equ_opcionAtributo].[opcionAtributo] AS [opcionAtributo],
		[equ_opcionAtributo].[opcionAtributo_codigo] AS [opcionAtributo_codigo],
		[equ_opcionAtributo].[orden] AS [orden],
		[equ_opcionAtributo].[id_atributo] AS [id_atributo],
[cat_atributo].[atributo] as [cat_atributo_atributo],
[cat_atributo].[atributo_codigo] as [cat_atributo_atributo_codigo],
[cat_atributo].[id_unidad] as [cat_atributo_id_unidad],
[cat_atributo].[cmm] as [cat_atributo_cmm],
		[equ_opcionAtributo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_opcionAtributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_opcionAtributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_opcionAtributo].[id_usuario_creo]
	INNER JOIN [cat_atributo] ON [cat_atributo].id=[equ_opcionAtributo].[id_atributo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_opcionAtributo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_opcionAtributo].active=1
