	[equ_opcionAtributo].id_usuario_modifico as id_usuario_modifico,
	[equ_opcionAtributo].id_usuario_creo as id_usuario_creo,
	[equ_opcionAtributo].fechaModificacion as fechaModificacion,
	[equ_opcionAtributo].fechaCreacion as fechaCreacion,
	[equ_opcionAtributo].active as active,
	[equ_opcionAtributo].[opcionAtributo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_opcionAtributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_opcionAtributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_opcionAtributo].[id_usuario_creo]
	where ' + @p_filtro)
END
