GO
CREATE  VIEW [view_equ_opcionAtributoDependiente] AS
SELECT 	[equ_opcionAtributoDependiente].[id] AS [id],
		[equ_opcionAtributoDependiente].[uid] AS [uid],
		[equ_opcionAtributoDependiente].[eid] AS [eid],
		[equ_opcionAtributoDependiente].[id_usuario_modifico] AS [id_usuario_modifico],
		[equ_opcionAtributoDependiente].[id_usuario_creo] AS [id_usuario_creo],
		[equ_opcionAtributoDependiente].[fechaModificacion] AS [fechaModificacion],
		[equ_opcionAtributoDependiente].[fechaCreacion] AS [fechaCreacion],
		[equ_opcionAtributoDependiente].[active] AS [active],
		[equ_opcionAtributoDependiente].[opcionAtributoDependiente] AS [opcionAtributoDependiente],
		[equ_opcionAtributoDependiente].[opcionAtributoDependiente_codigo] AS [opcionAtributoDependiente_codigo],
		[equ_opcionAtributoDependiente].[id_opcionAtributo_hijo] AS [id_opcionAtributo_hijo],
[equ_opcionAtributo_hijo].[opcionAtributo] as [equ_opcionAtributo_hijo_opcionAtributo],
[equ_opcionAtributo_hijo].[opcionAtributo_codigo] as [equ_opcionAtributo_hijo_opcionAtributo_codigo],
[equ_opcionAtributo_hijo].[orden] as [equ_opcionAtributo_hijo_orden],
[equ_opcionAtributo_hijo].[id_atributo] as [equ_opcionAtributo_hijo_id_atributo],
[equ_opcionAtributo_hijo].[cmm] as [equ_opcionAtributo_hijo_cmm],
		[equ_opcionAtributoDependiente].[id_opcionAtributo_padre] AS [id_opcionAtributo_padre],
[equ_opcionAtributo_padre].[opcionAtributo] as [equ_opcionAtributo_padre_opcionAtributo],
[equ_opcionAtributo_padre].[opcionAtributo_codigo] as [equ_opcionAtributo_padre_opcionAtributo_codigo],
[equ_opcionAtributo_padre].[orden] as [equ_opcionAtributo_padre_orden],
[equ_opcionAtributo_padre].[id_atributo] as [equ_opcionAtributo_padre_id_atributo],
[equ_opcionAtributo_padre].[cmm] as [equ_opcionAtributo_padre_cmm],
		[equ_opcionAtributoDependiente].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_opcionAtributoDependiente]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_opcionAtributoDependiente].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_opcionAtributoDependiente].[id_usuario_creo]
	INNER JOIN [equ_opcionAtributo] AS [equ_opcionAtributo_hijo] ON [equ_opcionAtributo_hijo].id=[equ_opcionAtributoDependiente].[id_opcionAtributo_hijo]
	INNER JOIN [equ_opcionAtributo] AS [equ_opcionAtributo_padre] ON [equ_opcionAtributo_padre].id=[equ_opcionAtributoDependiente].[id_opcionAtributo_padre]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_opcionAtributoDependiente].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_opcionAtributoDependiente].active=1
