CREATE PROCEDURE [upd_equ_opcionAtributoDependiente]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_opcionAtributoDependiente varchar(300) = null,
		@p_opcionAtributoDependiente_codigo varchar(100) = null,
		@p_id_opcionAtributo_hijo int = null,
		@p_id_opcionAtributo_padre int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_opcionAtributoDependiente]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[opcionAtributoDependiente] = isnull(@p_opcionAtributoDependiente,[opcionAtributoDependiente]),
			[opcionAtributoDependiente_codigo] = isnull(@p_opcionAtributoDependiente_codigo,[opcionAtributoDependiente_codigo]),
			[id_opcionAtributo_hijo] = isnull(@p_id_opcionAtributo_hijo,[id_opcionAtributo_hijo]),
			[id_opcionAtributo_padre] = isnull(@p_id_opcionAtributo_padre,[id_opcionAtributo_padre]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
