IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_opcionAtributoDependiente]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_opcionAtributoDependiente]
GO
CREATE PROCEDURE [ins_equ_opcionAtributoDependiente]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_opcionAtributoDependiente varchar(300),
		@p_opcionAtributoDependiente_codigo varchar(100),
		@p_id_opcionAtributo_hijo int,
		@p_id_opcionAtributo_padre int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_opcionAtributoDependiente]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[opcionAtributoDependiente],
			[opcionAtributoDependiente_codigo],
			[id_opcionAtributo_hijo],
			[id_opcionAtributo_padre],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_opcionAtributoDependiente,
			@p_opcionAtributoDependiente_codigo,
			@p_id_opcionAtributo_hijo,
			@p_id_opcionAtributo_padre,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_opcionAtributoDependiente] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
