CREATE PROCEDURE [aud_equ_opcionAtributoDependiente]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_opcionAtributoDependiente].id as id_tabla,
	[equ_opcionAtributoDependiente].id_usuario_modifico as id_usuario_modifico,
	[equ_opcionAtributoDependiente].id_usuario_creo as id_usuario_creo,
	[equ_opcionAtributoDependiente].fechaModificacion as fechaModificacion,
	[equ_opcionAtributoDependiente].fechaCreacion as fechaCreacion,
	[equ_opcionAtributoDependiente].active as active,
	[equ_opcionAtributoDependiente].[opcionAtributoDependiente] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_opcionAtributoDependiente]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_opcionAtributoDependiente].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_opcionAtributoDependiente].[id_usuario_creo]
	where ' + @p_filtro)
END
