IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_overhall]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_overhall]
GO
CREATE PROCEDURE [ins_equ_overhall]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_overhall varchar(300),
		@p_overhall_codigo varchar(100),
		@p_horometro float,
		@p_fecha_ff smalldatetime,
		@p_id_equipo int,
		@p_id_documento_ot int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_overhall]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[overhall],
			[overhall_codigo],
			[horometro],
			[fecha_ff],
			[id_equipo],
			[id_documento.ot],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_overhall,
			@p_overhall_codigo,
			@p_horometro,
			@p_fecha_ff,
			@p_id_equipo,
			@p_id_documento_ot,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_overhall] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
