	[equ_overhall].id_usuario_modifico as id_usuario_modifico,
	[equ_overhall].id_usuario_creo as id_usuario_creo,
	[equ_overhall].fechaModificacion as fechaModificacion,
	[equ_overhall].fechaCreacion as fechaCreacion,
