[doc_documento.alquiler].[documento.alquiler] as [doc_documento.alquiler_documento.alquiler],
[doc_documento.alquiler].[fechaFin_ff] as [doc_documento.alquiler_fechaFin_ff],
[doc_documento.alquiler].[mesVencido] as [doc_documento.alquiler_mesVencido],
[doc_documento.alquiler].[observaciones] as [doc_documento.alquiler_observaciones],
[doc_documento.alquiler].[ejecutaDevolucion] as [doc_documento.alquiler_ejecutaDevolucion],
[doc_documento.alquiler].[cmm] as [doc_documento.alquiler_cmm],
		[doc_documento_alquiler].[documento_codigo] AS [doc_documento_alquiler_documento_codigo],
		[doc_documento_alquiler].[documento_numero] AS [doc_documento_alquiler_documento_numero],
		[doc_documento_alquiler].[prefijo] AS [doc_documento_alquiler_prefijo],
		[doc_documento_alquiler].[subtotal] AS [doc_documento_alquiler_subtotal],
		[doc_documento_alquiler].[descuento] AS [doc_documento_alquiler_descuento],
		[doc_documento_alquiler].[iva] AS [doc_documento_alquiler_iva],
		[doc_documento_alquiler].[total] AS [doc_documento_alquiler_total],
		[doc_documento_alquiler].[costo] AS [doc_documento_alquiler_costo],
		[doc_documento_alquiler].[rentabilidad] AS [doc_documento_alquiler_rentabilidad],
		[doc_documento_alquiler].[trm] AS [doc_documento_alquiler_trm],
		[doc_documento_alquiler].[fecha_fh] AS [doc_documento_alquiler_fecha_fh],
		[doc_documento_alquiler].[fechaSugerida_fh] AS [doc_documento_alquiler_fechaSugerida_fh],
		[doc_documento_alquiler].[fechaCierre_ff] AS [doc_documento_alquiler_fechaCierre_ff],
		[doc_documento_alquiler].[fechaLimite_fh] AS [doc_documento_alquiler_fechaLimite_fh],
		[doc_documento_alquiler].[id_subtipoDocumento] AS [doc_documento_alquiler_id_subtipoDocumento],
		[doc_documento_alquiler].[id_tercero_cliente] AS [doc_documento_alquiler_id_tercero_cliente],
		[doc_documento_alquiler].[id_documento] AS [doc_documento_alquiler_id_documento],
		[doc_documento_alquiler].[id_tercero_proveedor] AS [doc_documento_alquiler_id_tercero_proveedor],
		[doc_documento_alquiler].[id_prioridadDocumento] AS [doc_documento_alquiler_id_prioridadDocumento],
		[doc_documento_alquiler].[id_moneda] AS [doc_documento_alquiler_id_moneda],
		[doc_documento_alquiler].[id_estadoTipoDocumento] AS [doc_documento_alquiler_id_estadoTipoDocumento],
		[doc_documento_alquiler].[id_motivoestado] AS [doc_documento_alquiler_id_motivoestado],
		[doc_documento_alquiler].[subtotalPlaneado] AS [doc_documento_alquiler_subtotalPlaneado],
		[doc_documento_alquiler].[descuentoPlaneado] AS [doc_documento_alquiler_descuentoPlaneado],
		[doc_documento_alquiler].[ivaPlaneado] AS [doc_documento_alquiler_ivaPlaneado],
		[doc_documento_alquiler].[totalPlaneado] AS [doc_documento_alquiler_totalPlaneado],
		[doc_documento_alquiler].[costoPlaneado] AS [doc_documento_alquiler_costoPlaneado],
		[doc_documento_alquiler].[id_usuario_asignado] AS [doc_documento_alquiler_id_usuario_asignado],
		[doc_documento_alquiler].[id_usuario_enUso] AS [doc_documento_alquiler_id_usuario_enUso],
		[doc_documento_alquiler].[identificador] AS [doc_documento_alquiler_identificador],
		[doc_documento_alquiler].[cmm] AS [doc_documento_alquiler_cmm],
		[equ_pagoAlquiler].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_pagoAlquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_pagoAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_pagoAlquiler].[id_usuario_creo]
	INNER JOIN [doc_documento.alquiler] ON [doc_documento.alquiler].id=[equ_pagoAlquiler].[id_documento.alquiler]
	INNER JOIN [doc_documento] aS [doc_documento_alquiler] ON [doc_documento.alquiler].id = [doc_documento_alquiler].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_pagoAlquiler].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_pagoAlquiler].active=1
