GO
CREATE PROCEDURE [upd_equ_pagoAlquiler]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_pagoAlquiler varchar(300) = null,
		@p_pagoAlquiler_codigo varchar(100) = null,
		@p_valorPorCobrar money = null,
		@p_valorFacturado money = null,
		@p_numeroFactura varchar(100) = null,
		@p_fechaEsperadaPago_ff smalldatetime = null,
		@p_fecha_factura_ff smalldatetime = null,
		@p_id_documento_alquiler int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [equ_pagoAlquiler]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[pagoAlquiler] = isnull(@p_pagoAlquiler,[pagoAlquiler]),
			[pagoAlquiler_codigo] = isnull(@p_pagoAlquiler_codigo,[pagoAlquiler_codigo]),
			[valorPorCobrar] = isnull(@p_valorPorCobrar,[valorPorCobrar]),
			[valorFacturado] = isnull(@p_valorFacturado,[valorFacturado]),
			[numeroFactura] = isnull(@p_numeroFactura,[numeroFactura]),
			[fechaEsperadaPago_ff] = isnull(@p_fechaEsperadaPago_ff,[fechaEsperadaPago_ff]),
			[fecha_factura_ff] = isnull(@p_fecha_factura_ff,[fecha_factura_ff]),
			[id_documento.alquiler] = isnull(@p_id_documento_alquiler,[id_documento.alquiler]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
