IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_pagoAlquiler]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_pagoAlquiler]
GO
CREATE PROCEDURE [ins_equ_pagoAlquiler]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_pagoAlquiler varchar(300),
		@p_pagoAlquiler_codigo varchar(100),
		@p_valorPorCobrar money,
		@p_valorFacturado money,
		@p_numeroFactura varchar(100),
		@p_fechaEsperadaPago_ff smalldatetime,
		@p_fecha_factura_ff smalldatetime,
		@p_id_documento_alquiler int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_pagoAlquiler]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[pagoAlquiler],
			[pagoAlquiler_codigo],
			[valorPorCobrar],
			[valorFacturado],
			[numeroFactura],
			[fechaEsperadaPago_ff],
			[fecha_factura_ff],
			[id_documento.alquiler],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_pagoAlquiler,
			@p_pagoAlquiler_codigo,
			@p_valorPorCobrar,
			@p_valorFacturado,
			@p_numeroFactura,
			@p_fechaEsperadaPago_ff,
			@p_fecha_factura_ff,
			@p_id_documento_alquiler,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_pagoAlquiler] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
