CREATE PROCEDURE [aud_equ_pagoAlquiler]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_pagoAlquiler].id as id_tabla,
	[equ_pagoAlquiler].id_usuario_modifico as id_usuario_modifico,
	[equ_pagoAlquiler].id_usuario_creo as id_usuario_creo,
	[equ_pagoAlquiler].fechaModificacion as fechaModificacion,
	[equ_pagoAlquiler].fechaCreacion as fechaCreacion,
	[equ_pagoAlquiler].active as active,
	[equ_pagoAlquiler].[pagoAlquiler] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_pagoAlquiler]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_pagoAlquiler].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_pagoAlquiler].[id_usuario_creo]
	where ' + @p_filtro)
END
