		[doc_documento_prestamo].[cmm] AS [doc_documento_prestamo_cmm],
		[equ_prestamo_equipo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [equ_prestamo_equipo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_prestamo_equipo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_prestamo_equipo].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[equ_prestamo_equipo].[id_equipo]
	INNER JOIN [doc_documento.prestamo] ON [doc_documento.prestamo].id=[equ_prestamo_equipo].[id_documento.prestamo]
	INNER JOIN [doc_documento] aS [doc_documento_prestamo] ON [doc_documento.prestamo].id = [doc_documento_prestamo].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_prestamo_equipo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
