IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_prestamo_equipo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_prestamo_equipo]
GO
CREATE PROCEDURE [ins_equ_prestamo_equipo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_prestamo_equipo varchar(300),
		@p_fechaDevolucion_ff smalldatetime,
		@p_id_equipo int,
		@p_id_documento_prestamo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_prestamo_equipo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[prestamo_equipo],
			[fechaDevolucion_ff],
			[id_equipo],
			[id_documento.prestamo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_prestamo_equipo,
			@p_fechaDevolucion_ff,
			@p_id_equipo,
			@p_id_documento_prestamo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_prestamo_equipo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
