IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_tipoTrazabilidad]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_tipoTrazabilidad]
GO
CREATE PROCEDURE [ins_equ_tipoTrazabilidad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoTrazabilidad varchar(300),
		@p_tipoTrazabilidad_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_tipoTrazabilidad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoTrazabilidad],
			[tipoTrazabilidad_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoTrazabilidad,
			@p_tipoTrazabilidad_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_tipoTrazabilidad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
