GO
CREATE PROCEDURE [aud_equ_tipoTrazabilidad]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_tipoTrazabilidad].id as id_tabla,
	[equ_tipoTrazabilidad].id_usuario_modifico as id_usuario_modifico,
	[equ_tipoTrazabilidad].id_usuario_creo as id_usuario_creo,
	[equ_tipoTrazabilidad].fechaModificacion as fechaModificacion,
	[equ_tipoTrazabilidad].fechaCreacion as fechaCreacion,
	[equ_tipoTrazabilidad].active as active,
	[equ_tipoTrazabilidad].[tipoTrazabilidad] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_tipoTrazabilidad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_tipoTrazabilidad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_tipoTrazabilidad].[id_usuario_creo]
	where ' + @p_filtro)
END
