	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_trazabilidad].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[equ_trazabilidad].[id_equipo]
	INNER JOIN [equ_equipo] AS [equ_equipo_padre] ON [equ_equipo_padre].id=[equ_trazabilidad].[id_equipo_padre]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[equ_trazabilidad].[id_tercero]
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[equ_trazabilidad].[id_sucursal]
	INNER JOIN [doc_documento.alquiler] ON [doc_documento.alquiler].id=[equ_trazabilidad].[id_documento.alquiler]
	INNER JOIN [doc_documento] aS [doc_documento_alquiler] ON [doc_documento.alquiler].id = [doc_documento_alquiler].id
	INNER JOIN [ort_reporteTecnico] ON [ort_reporteTecnico].id=[equ_trazabilidad].[id_reporteTecnico]
	INNER JOIN [dis_evento] ON [dis_evento].id=[equ_trazabilidad].[id_evento]
	INNER JOIN [doc_documento] ON [doc_documento].id=[equ_trazabilidad].[id_documento]
	INNER JOIN [equ_tipoTrazabilidad] ON [equ_tipoTrazabilidad].id=[equ_trazabilidad].[id_tipoTrazabilidad]
	INNER JOIN [equ_cicloHorometro] ON [equ_cicloHorometro].id=[equ_trazabilidad].[id_cicloHorometro]
	INNER JOIN [cat_posicion] ON [cat_posicion].id=[equ_trazabilidad].[id_posicion]
	INNER JOIN [equ_estadoEquipo] ON [equ_estadoEquipo].id=[equ_trazabilidad].[id_estadoEquipo]
	INNER JOIN [doc_documento.prestamo] ON [doc_documento.prestamo].id=[equ_trazabilidad].[id_documento.prestamo]
	INNER JOIN [doc_documento] aS [doc_documento_prestamo] ON [doc_documento.prestamo].id = [doc_documento_prestamo].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [equ_trazabilidad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [equ_trazabilidad].active=1
