IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_equ_trazabilidad]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_equ_trazabilidad]
GO
CREATE PROCEDURE [ins_equ_trazabilidad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_trazabilidad varchar(300),
		@p_trazabilidad_codigo varchar(100),
		@p_horometro float,
		@p_fecha_ff smalldatetime,
		@p_esSoporte bit,
		@p_id_equipo int,
		@p_id_equipo_padre int,
		@p_id_tercero int,
		@p_id_sucursal int,
		@p_id_documento_alquiler int,
		@p_id_reporteTecnico int,
		@p_id_evento int,
		@p_id_documento int,
		@p_id_tipoTrazabilidad int,
		@p_id_cicloHorometro int,
		@p_id_posicion int,
		@p_id_estadoEquipo int,
		@p_id_documento_prestamo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [equ_trazabilidad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[trazabilidad],
			[trazabilidad_codigo],
			[horometro],
			[fecha_ff],
			[esSoporte],
			[id_equipo],
			[id_equipo_padre],
			[id_tercero],
			[id_sucursal],
			[id_documento.alquiler],
			[id_reporteTecnico],
			[id_evento],
			[id_documento],
			[id_tipoTrazabilidad],
			[id_cicloHorometro],
			[id_posicion],
			[id_estadoEquipo],
			[id_documento.prestamo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_trazabilidad,
			@p_trazabilidad_codigo,
			@p_horometro,
			@p_fecha_ff,
			@p_esSoporte,
			@p_id_equipo,
			@p_id_equipo_padre,
			@p_id_tercero,
			@p_id_sucursal,
			@p_id_documento_alquiler,
			@p_id_reporteTecnico,
			@p_id_evento,
			@p_id_documento,
			@p_id_tipoTrazabilidad,
			@p_id_cicloHorometro,
			@p_id_posicion,
			@p_id_estadoEquipo,
			@p_id_documento_prestamo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [equ_trazabilidad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
