GO
CREATE PROCEDURE [reg_equ_trazabilidad_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[trazabilidad] AS [trazabilidad],
		[trazabilidad_codigo] AS [trazabilidad_codigo],
		[horometro] AS [horometro],
		[fecha_ff] AS [fecha_ff],
		[esSoporte] AS [esSoporte],
		[id_equipo] AS [id_equipo],
		[id_equipo_padre] AS [id_equipo_padre],
		[id_tercero] AS [id_tercero],
		[id_sucursal] AS [id_sucursal],
		[id_documento.alquiler] AS [id_documento.alquiler],
		[id_reporteTecnico] AS [id_reporteTecnico],
		[id_evento] AS [id_evento],
		[id_documento] AS [id_documento],
		[id_tipoTrazabilidad] AS [id_tipoTrazabilidad],
		[id_cicloHorometro] AS [id_cicloHorometro],
		[id_posicion] AS [id_posicion],
		[id_estadoEquipo] AS [id_estadoEquipo],
		[id_documento.prestamo] AS [id_documento.prestamo],
		[cmm] AS [cmm]
	FROM [equ_trazabilidad]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
