CREATE PROCEDURE [aud_equ_trazabilidad]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [equ_trazabilidad].id as id_tabla,
	[equ_trazabilidad].id_usuario_modifico as id_usuario_modifico,
	[equ_trazabilidad].id_usuario_creo as id_usuario_creo,
	[equ_trazabilidad].fechaModificacion as fechaModificacion,
	[equ_trazabilidad].fechaCreacion as fechaCreacion,
	[equ_trazabilidad].active as active,
	[equ_trazabilidad].[trazabilidad] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [equ_trazabilidad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[equ_trazabilidad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[equ_trazabilidad].[id_usuario_creo]
	where ' + @p_filtro)
END
