IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_accesosSamm]')) DROP VIEW [dbo].[view_gen_accesosSamm]
GO
CREATE  VIEW [view_gen_accesosSamm] AS
SELECT 	[gen_accesosSamm].[id] AS [id],
		[gen_accesosSamm].[uid] AS [uid],
		[gen_accesosSamm].[eid] AS [eid],
		[gen_accesosSamm].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_accesosSamm].[id_usuario_creo] AS [id_usuario_creo],
		[gen_accesosSamm].[fechaModificacion] AS [fechaModificacion],
		[gen_accesosSamm].[fechaCreacion] AS [fechaCreacion],
		[gen_accesosSamm].[active] AS [active],
		[gen_accesosSamm].[accesosSamm] AS [accesosSamm],
		[gen_accesosSamm].[accesosSamm_codigo] AS [accesosSamm_codigo],
		[gen_accesosSamm].[direccionIP] AS [direccionIP],
		[gen_accesosSamm].[esHijo] AS [esHijo],
		[gen_accesosSamm].[esSalida] AS [esSalida],
		[gen_accesosSamm].[edita] AS [edita],
		[gen_accesosSamm].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_accesosSamm]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_accesosSamm].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_accesosSamm].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_accesosSamm].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_accesosSamm].active=1
GO
