GO
CREATE PROCEDURE [upd_gen_accesosSamm]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_accesosSamm varchar(300) = null,
		@p_accesosSamm_codigo varchar(100) = null,
		@p_direccionIP varchar(100) = null,
		@p_esHijo bit = null,
		@p_esSalida bit = null,
		@p_edita bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_accesosSamm]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[accesosSamm] = isnull(@p_accesosSamm,[accesosSamm]),
			[accesosSamm_codigo] = isnull(@p_accesosSamm_codigo,[accesosSamm_codigo]),
			[direccionIP] = isnull(@p_direccionIP,[direccionIP]),
			[esHijo] = isnull(@p_esHijo,[esHijo]),
			[esSalida] = isnull(@p_esSalida,[esSalida]),
			[edita] = isnull(@p_edita,[edita]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
