IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_accesosSamm]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_accesosSamm]
GO
CREATE PROCEDURE [ins_gen_accesosSamm]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_accesosSamm varchar(300),
		@p_accesosSamm_codigo varchar(100),
		@p_direccionIP varchar(100),
		@p_esHijo bit,
		@p_esSalida bit,
		@p_edita bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_accesosSamm]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[accesosSamm],
			[accesosSamm_codigo],
			[direccionIP],
			[esHijo],
			[esSalida],
			[edita],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_accesosSamm,
			@p_accesosSamm_codigo,
			@p_direccionIP,
			@p_esHijo,
			@p_esSalida,
			@p_edita,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_accesosSamm] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
