GO
CREATE  VIEW [view_gen_accionNotificacion] AS
SELECT 	[gen_accionNotificacion].[id] AS [id],
		[gen_accionNotificacion].[uid] AS [uid],
		[gen_accionNotificacion].[eid] AS [eid],
		[gen_accionNotificacion].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_accionNotificacion].[id_usuario_creo] AS [id_usuario_creo],
		[gen_accionNotificacion].[fechaModificacion] AS [fechaModificacion],
		[gen_accionNotificacion].[fechaCreacion] AS [fechaCreacion],
		[gen_accionNotificacion].[active] AS [active],
		[gen_accionNotificacion].[accionNotificacion] AS [accionNotificacion],
		[gen_accionNotificacion].[accionNotificacion_codigo] AS [accionNotificacion_codigo],
		[gen_accionNotificacion].[id_tipoNotificacion] AS [id_tipoNotificacion],
[gen_tipoNotificacion].[tipoNotificacion] as [gen_tipoNotificacion_tipoNotificacion],
[gen_tipoNotificacion].[tipoNotificacion_codigo] as [gen_tipoNotificacion_tipoNotificacion_codigo],
[gen_tipoNotificacion].[cmm] as [gen_tipoNotificacion_cmm],
		[gen_accionNotificacion].[id_puntoIntegracion] AS [id_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion] as [syn_puntoIntegracion_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion_codigo] as [syn_puntoIntegracion_puntoIntegracion_codigo],
[syn_puntoIntegracion].[tablaLocal] as [syn_puntoIntegracion_tablaLocal],
[syn_puntoIntegracion].[condicion] as [syn_puntoIntegracion_condicion],
[syn_puntoIntegracion].[urlConsumir] as [syn_puntoIntegracion_urlConsumir],
[syn_puntoIntegracion].[id_puntoIntegracion] as [syn_puntoIntegracion_id_puntoIntegracion],
[syn_puntoIntegracion].[id_sistemaIntegrar] as [syn_puntoIntegracion_id_sistemaIntegrar],
[syn_puntoIntegracion].[metodo] as [syn_puntoIntegracion_metodo],
[syn_puntoIntegracion].[cantidadReintentos] as [syn_puntoIntegracion_cantidadReintentos],
[syn_puntoIntegracion].[intervaloReintentos] as [syn_puntoIntegracion_intervaloReintentos],
[syn_puntoIntegracion].[codigosReintentos] as [syn_puntoIntegracion_codigosReintentos],
[syn_puntoIntegracion].[cmm] as [syn_puntoIntegracion_cmm],
		[gen_accionNotificacion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_accionNotificacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_accionNotificacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_accionNotificacion].[id_usuario_creo]
	INNER JOIN [gen_tipoNotificacion] ON [gen_tipoNotificacion].id=[gen_accionNotificacion].[id_tipoNotificacion]
	INNER JOIN [syn_puntoIntegracion] ON [syn_puntoIntegracion].id=[gen_accionNotificacion].[id_puntoIntegracion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_accionNotificacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_accionNotificacion].active=1
