CREATE PROCEDURE [upd_gen_accionNotificacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_accionNotificacion varchar(300) = null,
		@p_accionNotificacion_codigo varchar(100) = null,
		@p_id_tipoNotificacion int = null,
		@p_id_puntoIntegracion int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_accionNotificacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[accionNotificacion] = isnull(@p_accionNotificacion,[accionNotificacion]),
			[accionNotificacion_codigo] = isnull(@p_accionNotificacion_codigo,[accionNotificacion_codigo]),
			[id_tipoNotificacion] = isnull(@p_id_tipoNotificacion,[id_tipoNotificacion]),
			[id_puntoIntegracion] = isnull(@p_id_puntoIntegracion,[id_puntoIntegracion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
