IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_accionNotificacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_accionNotificacion]
GO
CREATE PROCEDURE [ins_gen_accionNotificacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_accionNotificacion varchar(300),
		@p_accionNotificacion_codigo varchar(100),
		@p_id_tipoNotificacion int,
		@p_id_puntoIntegracion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_accionNotificacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[accionNotificacion],
			[accionNotificacion_codigo],
			[id_tipoNotificacion],
			[id_puntoIntegracion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_accionNotificacion,
			@p_accionNotificacion_codigo,
			@p_id_tipoNotificacion,
			@p_id_puntoIntegracion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_accionNotificacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
