		[gen_archivo].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_archivo].[id_usuario_creo] AS [id_usuario_creo],
		[gen_archivo].[fechaModificacion] AS [fechaModificacion],
		[gen_archivo].[fechaCreacion] AS [fechaCreacion],
		[gen_archivo].[active] AS [active],
		[gen_archivo].[archivo] AS [archivo],
		[gen_archivo].[archivo_codigo] AS [archivo_codigo],
		[gen_archivo].[tabla] AS [tabla],
		[gen_archivo].[idObjeto] AS [idObjeto],
		[gen_archivo].[descripcion] AS [descripcion],
		[gen_archivo].[archivoBinario] AS [archivoBinario],
		[gen_archivo].[esPrincipal] AS [esPrincipal],
		[gen_archivo].[link] AS [link],
		[gen_archivo].[id_tipoArchivo] AS [id_tipoArchivo],
[gen_tipoArchivo].[tipoArchivo] as [gen_tipoArchivo_tipoArchivo],
[gen_tipoArchivo].[tipoArchivo_codigo] as [gen_tipoArchivo_tipoArchivo_codigo],
[gen_tipoArchivo].[cmm] as [gen_tipoArchivo_cmm],
		[gen_archivo].[tamano] AS [tamano],
		[gen_archivo].[cmm] AS [cmm],
		[gen_archivo].[hashArchivo] AS [hashArchivo],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_archivo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_archivo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_archivo].[id_usuario_creo]
	INNER JOIN [gen_tipoArchivo] ON [gen_tipoArchivo].id=[gen_archivo].[id_tipoArchivo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_archivo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_archivo].active=1
GO
