CREATE PROCEDURE [upd_gen_archivo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_archivo varchar(300) = null,
		@p_archivo_codigo varchar(100) = null,
		@p_tabla varchar(100) = null,
		@p_idObjeto int = null,
		@p_descripcion varchar(8000) = null,
		@p_archivoBinario varbinary = null,
		@p_esPrincipal bit = null,
		@p_link varchar(500) = null,
		@p_id_tipoArchivo int = null,
		@p_tamano float = null,
		@p_cmm varchar(300) = null,
		@p_hashArchivo varchar(100) = null
AS
BEGIN
		UPDATE [gen_archivo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[archivo] = isnull(@p_archivo,[archivo]),
			[archivo_codigo] = isnull(@p_archivo_codigo,[archivo_codigo]),
			[tabla] = isnull(@p_tabla,[tabla]),
			[idObjeto] = isnull(@p_idObjeto,[idObjeto]),
			[descripcion] = isnull(@p_descripcion,[descripcion]),
			[archivoBinario] = isnull(@p_archivoBinario,[archivoBinario]),
			[esPrincipal] = isnull(@p_esPrincipal,[esPrincipal]),
			[link] = isnull(@p_link,[link]),
			[id_tipoArchivo] = isnull(@p_id_tipoArchivo,[id_tipoArchivo]),
			[tamano] = isnull(@p_tamano,[tamano]),
			[cmm] = isnull(@p_cmm,[cmm]),
			[hashArchivo] = isnull(@p_hashArchivo,[hashArchivo])
		WHERE (id = @p_id)
END
