CREATE PROCEDURE [ins_gen_archivo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_archivo varchar(300),
		@p_archivo_codigo varchar(100),
		@p_tabla varchar(100),
		@p_idObjeto int,
		@p_descripcion varchar(8000),
		@p_archivoBinario varbinary,
		@p_esPrincipal bit,
		@p_link varchar(500),
		@p_id_tipoArchivo int,
		@p_tamano float,
		@p_cmm varchar(300),
		@p_hashArchivo varchar(100)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_archivo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[archivo],
			[archivo_codigo],
			[tabla],
			[idObjeto],
			[descripcion],
			[archivoBinario],
			[esPrincipal],
			[link],
			[id_tipoArchivo],
			[tamano],
			[cmm],
			[hashArchivo])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_archivo,
			@p_archivo_codigo,
			@p_tabla,
			@p_idObjeto,
			@p_descripcion,
			@p_archivoBinario,
			@p_esPrincipal,
			@p_link,
			@p_id_tipoArchivo,
			@p_tamano,
			@p_cmm,
			@p_hashArchivo)
		SET @v_id = scope_identity()
UPDATE [gen_archivo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
