			[fechaModificacion] = GETDATE(),
			[bodega] = isnull(@p_bodega,[bodega]),
			[bodega_codigo] = isnull(@p_bodega_codigo,[bodega_codigo]),
			[salidasEnRojo] = isnull(@p_salidasEnRojo,[salidasEnRojo]),
			[usaLocalizacion] = isnull(@p_usaLocalizacion,[usaLocalizacion]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
