IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_bodega]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_bodega]
GO
CREATE PROCEDURE [ins_gen_bodega]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_bodega varchar(300),
		@p_bodega_codigo varchar(100),
		@p_salidasEnRojo bit,
		@p_usaLocalizacion bit,
		@p_id_sucursal int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_bodega]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[bodega],
			[bodega_codigo],
			[salidasEnRojo],
			[usaLocalizacion],
			[id_sucursal],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_bodega,
			@p_bodega_codigo,
			@p_salidasEnRojo,
			@p_usaLocalizacion,
			@p_id_sucursal,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_bodega] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
