CREATE PROCEDURE [ins_cat_catalogo_bodega]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_catalogo_bodega varchar(300),
		@p_disponible float,
		@p_existencia float,
		@p_reservado float,
		@p_existenciaMinima float,
		@p_enOrdenes float,
		@p_localizacion varchar(50),
		@p_costo money,
		@p_existenciaMaxima float,
		@p_id_catalogo int,
		@p_id_bodega int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [cat_catalogo_bodega]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo_bodega],
			[disponible],
			[existencia],
			[reservado],
			[existenciaMinima],
			[enOrdenes],
			[localizacion],
			[costo],
			[existenciaMaxima],
			[id_catalogo],
			[id_bodega],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
