CREATE PROCEDURE [ins_gen_bodega_usuario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_bodega_usuario varchar(300),
		@p_id_usuario int,
		@p_id_bodega int,
		@p_sugerir bit,
		@p_ocultar bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_bodega_usuario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
