CREATE  VIEW [view_gen_config] AS
SELECT 	[gen_config].[id] AS [id],
		[gen_config].[uid] AS [uid],
		[gen_config].[eid] AS [eid],
		[gen_config].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_config].[id_usuario_creo] AS [id_usuario_creo],
		[gen_config].[fechaModificacion] AS [fechaModificacion],
		[gen_config].[fechaCreacion] AS [fechaCreacion],
		[gen_config].[active] AS [active],
		[gen_config].[config] AS [config],
		[gen_config].[config_codigo] AS [config_codigo],
		[gen_config].[modulo] AS [modulo],
		[gen_config].[valor] AS [valor],
		[gen_config].[descripcion] AS [descripcion],
		[gen_config].[idObjeto] AS [idObjeto],
		[gen_config].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_config]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_config].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_config].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_config].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_config].active=1
