IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_config]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_config]
GO
CREATE PROCEDURE [ins_gen_config]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_config varchar(300),
		@p_config_codigo varchar(100),
		@p_modulo varchar(100),
		@p_valor varchar(5000),
		@p_descripcion varchar(300),
		@p_idObjeto int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_config]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[config],
			[config_codigo],
			[modulo],
			[valor],
			[descripcion],
			[idObjeto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_config,
			@p_config_codigo,
			@p_modulo,
			@p_valor,
			@p_descripcion,
			@p_idObjeto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_config] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
