CREATE  VIEW [view_gen_configuracionAtributos] AS
SELECT 	[gen_configuracionAtributos].[id] AS [id],
		[gen_configuracionAtributos].[uid] AS [uid],
		[gen_configuracionAtributos].[eid] AS [eid],
		[gen_configuracionAtributos].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_configuracionAtributos].[id_usuario_creo] AS [id_usuario_creo],
		[gen_configuracionAtributos].[fechaModificacion] AS [fechaModificacion],
		[gen_configuracionAtributos].[fechaCreacion] AS [fechaCreacion],
		[gen_configuracionAtributos].[active] AS [active],
		[gen_configuracionAtributos].[configuracionAtributos] AS [configuracionAtributos],
		[gen_configuracionAtributos].[configuracionAtributos_codigo] AS [configuracionAtributos_codigo],
		[gen_configuracionAtributos].[id_tabla_resultado] AS [id_tabla_resultado],
		[_tablas_resultado].[tabla] AS [_tablas_resultado_tabla],
		[_tablas_resultado].[id_tabla_padre] AS [_tablas_resultado_id_tabla_padre],
		[gen_configuracionAtributos].[id_tabla_relacion] AS [id_tabla_relacion],
		[_tablas_relacion].[tabla] AS [_tablas_relacion_tabla],
		[_tablas_relacion].[id_tabla_padre] AS [_tablas_relacion_id_tabla_padre],
		[gen_configuracionAtributos].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_configuracionAtributos]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_configuracionAtributos].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_configuracionAtributos].[id_usuario_creo]
	INNER JOIN [_tablas] AS [_tablas_resultado] ON [_tablas_resultado].id=[gen_configuracionAtributos].[id_tabla_resultado]
	INNER JOIN [_tablas] AS [_tablas_relacion] ON [_tablas_relacion].id=[gen_configuracionAtributos].[id_tabla_relacion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_configuracionAtributos].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_configuracionAtributos].active=1
