GO
CREATE PROCEDURE [upd_gen_configuracionAtributos]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_configuracionAtributos varchar(300) = null,
		@p_configuracionAtributos_codigo varchar(100) = null,
		@p_id_tabla_resultado int = null,
		@p_id_tabla_relacion int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_configuracionAtributos]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[configuracionAtributos] = isnull(@p_configuracionAtributos,[configuracionAtributos]),
			[configuracionAtributos_codigo] = isnull(@p_configuracionAtributos_codigo,[configuracionAtributos_codigo]),
			[id_tabla_resultado] = isnull(@p_id_tabla_resultado,[id_tabla_resultado]),
			[id_tabla_relacion] = isnull(@p_id_tabla_relacion,[id_tabla_relacion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
