IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_configuracionAtributos]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_configuracionAtributos]
GO
CREATE PROCEDURE [ins_gen_configuracionAtributos]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_configuracionAtributos varchar(300),
		@p_configuracionAtributos_codigo varchar(100),
		@p_id_tabla_resultado int,
		@p_id_tabla_relacion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_configuracionAtributos]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[configuracionAtributos],
			[configuracionAtributos_codigo],
			[id_tabla_resultado],
			[id_tabla_relacion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_configuracionAtributos,
			@p_configuracionAtributos_codigo,
			@p_id_tabla_resultado,
			@p_id_tabla_relacion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_configuracionAtributos] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
