	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gen_configuracionAtributos].id as id_tabla,
	[gen_configuracionAtributos].id_usuario_modifico as id_usuario_modifico,
	[gen_configuracionAtributos].id_usuario_creo as id_usuario_creo,
	[gen_configuracionAtributos].fechaModificacion as fechaModificacion,
	[gen_configuracionAtributos].fechaCreacion as fechaCreacion,
	[gen_configuracionAtributos].active as active,
	[gen_configuracionAtributos].[configuracionAtributos] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gen_configuracionAtributos]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_configuracionAtributos].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_configuracionAtributos].[id_usuario_creo]
	where ' + @p_filtro)
END
