CREATE  VIEW [view_gen_configuracionServicio] AS
SELECT 	[gen_configuracionServicio].[id] AS [id],
		[gen_configuracionServicio].[uid] AS [uid],
		[gen_configuracionServicio].[eid] AS [eid],
		[gen_configuracionServicio].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_configuracionServicio].[id_usuario_creo] AS [id_usuario_creo],
		[gen_configuracionServicio].[fechaModificacion] AS [fechaModificacion],
		[gen_configuracionServicio].[fechaCreacion] AS [fechaCreacion],
		[gen_configuracionServicio].[active] AS [active],
		[gen_configuracionServicio].[configuracionServicio] AS [configuracionServicio],
		[gen_configuracionServicio].[configuracionServicio_codigo] AS [configuracionServicio_codigo],
		[gen_configuracionServicio].[id_tercero] AS [id_tercero],
[ter_tercero].[tercero] as [ter_tercero_tercero],
[ter_tercero].[tercero_codigo] as [ter_tercero_tercero_codigo],
[ter_tercero].[tercero_nit] as [ter_tercero_tercero_nit],
[ter_tercero].[direccion] as [ter_tercero_direccion],
[ter_tercero].[contacto] as [ter_tercero_contacto],
[ter_tercero].[telefono] as [ter_tercero_telefono],
[ter_tercero].[fax] as [ter_tercero_fax],
[ter_tercero].[email] as [ter_tercero_email],
[ter_tercero].[website] as [ter_tercero_website],
[ter_tercero].[representante] as [ter_tercero_representante],
[ter_tercero].[notas] as [ter_tercero_notas],
[ter_tercero].[tercero_nombreCorto] as [ter_tercero_tercero_nombreCorto],
[ter_tercero].[esCliente] as [ter_tercero_esCliente],
[ter_tercero].[esProveedor] as [ter_tercero_esProveedor],
[ter_tercero].[esTransportador] as [ter_tercero_esTransportador],
[ter_tercero].[esFabricante] as [ter_tercero_esFabricante],
[ter_tercero].[esEmpresaPropia] as [ter_tercero_esEmpresaPropia],
[ter_tercero].[clasificacion] as [ter_tercero_clasificacion],
[ter_tercero].[id_zona] as [ter_tercero_id_zona],
[ter_tercero].[id_estadoTercero] as [ter_tercero_id_estadoTercero],
[ter_tercero].[id_naturalezaTercero] as [ter_tercero_id_naturalezaTercero],
[ter_tercero].[esProspecto] as [ter_tercero_esProspecto],
[ter_tercero].[id_formaPago] as [ter_tercero_id_formaPago],
[ter_tercero].[tiempoEntrega] as [ter_tercero_tiempoEntrega],
[ter_tercero].[cmm] as [ter_tercero_cmm],
		[gen_configuracionServicio].[id_tipoServicio] AS [id_tipoServicio],
[gen_tipoServicio].[tipoServicio] as [gen_tipoServicio_tipoServicio],
[gen_tipoServicio].[tipoServicio_codigo] as [gen_tipoServicio_tipoServicio_codigo],
[gen_tipoServicio].[tieneGarantia] as [gen_tipoServicio_tieneGarantia],
[gen_tipoServicio].[diasGarantia] as [gen_tipoServicio_diasGarantia],
[gen_tipoServicio].[cmm] as [gen_tipoServicio_cmm],
		[gen_configuracionServicio].[id_catalogo] AS [id_catalogo],
[cat_catalogo].[catalogo] as [cat_catalogo_catalogo],
[cat_catalogo].[catalogo_codigo] as [cat_catalogo_catalogo_codigo],
[cat_catalogo].[codigoInventario] as [cat_catalogo_codigoInventario],
[cat_catalogo].[precioVenta] as [cat_catalogo_precioVenta],
[cat_catalogo].[tiempoConsecucion] as [cat_catalogo_tiempoConsecucion],
[cat_catalogo].[esNacional] as [cat_catalogo_esNacional],
[cat_catalogo].[id_familia] as [cat_catalogo_id_familia],
[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[gen_configuracionServicio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_configuracionServicio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_configuracionServicio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_configuracionServicio].[id_usuario_creo]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[gen_configuracionServicio].[id_tercero]
	INNER JOIN [gen_tipoServicio] ON [gen_tipoServicio].id=[gen_configuracionServicio].[id_tipoServicio]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[gen_configuracionServicio].[id_catalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_configuracionServicio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_configuracionServicio].active=1
