GO
CREATE PROCEDURE [upd_gen_configuracionServicio]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_configuracionServicio varchar(300) = null,
		@p_configuracionServicio_codigo varchar(100) = null,
		@p_id_tercero int = null,
		@p_id_tipoServicio int = null,
		@p_id_catalogo int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_configuracionServicio]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[configuracionServicio] = isnull(@p_configuracionServicio,[configuracionServicio]),
			[configuracionServicio_codigo] = isnull(@p_configuracionServicio_codigo,[configuracionServicio_codigo]),
			[id_tercero] = isnull(@p_id_tercero,[id_tercero]),
			[id_tipoServicio] = isnull(@p_id_tipoServicio,[id_tipoServicio]),
			[id_catalogo] = isnull(@p_id_catalogo,[id_catalogo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
