IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_configuracionServicio]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_configuracionServicio]
GO
CREATE PROCEDURE [ins_gen_configuracionServicio]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_configuracionServicio varchar(300),
		@p_configuracionServicio_codigo varchar(100),
		@p_id_tercero int,
		@p_id_tipoServicio int,
		@p_id_catalogo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_configuracionServicio]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[configuracionServicio],
			[configuracionServicio_codigo],
			[id_tercero],
			[id_tipoServicio],
			[id_catalogo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_configuracionServicio,
			@p_configuracionServicio_codigo,
			@p_id_tercero,
			@p_id_tipoServicio,
			@p_id_catalogo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_configuracionServicio] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
