		[gen_detalleFormulario].[soloLectura] AS [soloLectura],
		[gen_detalleFormulario].[ocultar] AS [ocultar],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_detalleFormulario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_detalleFormulario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_detalleFormulario].[id_usuario_creo]
	INNER JOIN [_tipoDato] ON [_tipoDato].id=[gen_detalleFormulario].[id_tipoDato]
	INNER JOIN [_columnas] AS [_columnas] ON [_columnas].id=[gen_detalleFormulario].[id_columna]
	INNER JOIN [cat_atributo] ON [cat_atributo].id=[gen_detalleFormulario].[id_atributo]
	INNER JOIN [gen_formulario] ON [gen_formulario].id=[gen_detalleFormulario].[id_formulario]
	INNER JOIN [gen_seccionFormulario] ON [gen_seccionFormulario].id=[gen_detalleFormulario].[id_seccionFormulario]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_detalleFormulario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_detalleFormulario].active=1
GO
