GO
CREATE PROCEDURE [upd_gen_detalleFormulario]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detalleFormulario varchar(300) = null,
		@p_detalleFormulario_codigo varchar(100) = null,
		@p_defecto nvarchar(200) = null,
		@p_esObligatorio bit = null,
		@p_orden int = null,
		@p_id_tipoDato int = null,
		@p_expresionRegular nvarchar(-1) = null,
		@p_id_columna int = null,
		@p_id_atributo int = null,
		@p_id_formulario int = null,
		@p_id_seccionFormulario int = null,
		@p_cmm varchar(300) = null,
		@p_mostrarEnGrilla bit = null,
		@p_condicion varchar(300) = null,
		@p_valorDefecto varchar(300) = null,
		@p_soloLectura bit = null,
		@p_ocultar bit = null
AS
BEGIN
		UPDATE [gen_detalleFormulario]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detalleFormulario] = isnull(@p_detalleFormulario,[detalleFormulario]),
			[detalleFormulario_codigo] = isnull(@p_detalleFormulario_codigo,[detalleFormulario_codigo]),
			[defecto] = isnull(@p_defecto,[defecto]),
			[esObligatorio] = isnull(@p_esObligatorio,[esObligatorio]),
			[orden] = isnull(@p_orden,[orden]),
			[id_tipoDato] = isnull(@p_id_tipoDato,[id_tipoDato]),
			[expresionRegular] = isnull(@p_expresionRegular,[expresionRegular]),
			[id_columna] = isnull(@p_id_columna,[id_columna]),
			[id_atributo] = isnull(@p_id_atributo,[id_atributo]),
			[id_formulario] = isnull(@p_id_formulario,[id_formulario]),
			[id_seccionFormulario] = isnull(@p_id_seccionFormulario,[id_seccionFormulario]),
			[cmm] = isnull(@p_cmm,[cmm]),
			[mostrarEnGrilla] = isnull(@p_mostrarEnGrilla,[mostrarEnGrilla]),
			[condicion] = isnull(@p_condicion,[condicion]),
			[valorDefecto] = isnull(@p_valorDefecto,[valorDefecto]),
			[soloLectura] = isnull(@p_soloLectura,[soloLectura]),
			[ocultar] = isnull(@p_ocultar,[ocultar])
		WHERE (id = @p_id)
END
GO
