IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_detalleFormulario]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_detalleFormulario]
GO
CREATE PROCEDURE [ins_gen_detalleFormulario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detalleFormulario varchar(300),
		@p_detalleFormulario_codigo varchar(100),
		@p_defecto nvarchar(200),
		@p_esObligatorio bit,
		@p_orden int,
		@p_id_tipoDato int,
		@p_expresionRegular nvarchar(-1),
		@p_id_columna int,
		@p_id_atributo int,
		@p_id_formulario int,
		@p_id_seccionFormulario int,
		@p_cmm varchar(300),
		@p_mostrarEnGrilla bit,
		@p_condicion varchar(300),
		@p_valorDefecto varchar(300),
		@p_soloLectura bit,
		@p_ocultar bit
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_detalleFormulario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detalleFormulario],
			[detalleFormulario_codigo],
			[defecto],
			[esObligatorio],
			[orden],
			[id_tipoDato],
			[expresionRegular],
			[id_columna],
			[id_atributo],
			[id_formulario],
			[id_seccionFormulario],
			[cmm],
			[mostrarEnGrilla],
			[condicion],
			[valorDefecto],
			[soloLectura],
			[ocultar])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detalleFormulario,
			@p_detalleFormulario_codigo,
			@p_defecto,
			@p_esObligatorio,
			@p_orden,
			@p_id_tipoDato,
			@p_expresionRegular,
			@p_id_columna,
			@p_id_atributo,
			@p_id_formulario,
			@p_id_seccionFormulario,
			@p_cmm,
			@p_mostrarEnGrilla,
			@p_condicion,
			@p_valorDefecto,
			@p_soloLectura,
			@p_ocultar)
		SET @v_id = scope_identity()
UPDATE [gen_detalleFormulario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
