GO
CREATE  VIEW [view_gen_detalleRegistroEnvio] AS
SELECT 	[gen_detalleRegistroEnvio].[id] AS [id],
		[gen_detalleRegistroEnvio].[uid] AS [uid],
		[gen_detalleRegistroEnvio].[eid] AS [eid],
		[gen_detalleRegistroEnvio].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_detalleRegistroEnvio].[id_usuario_creo] AS [id_usuario_creo],
		[gen_detalleRegistroEnvio].[fechaModificacion] AS [fechaModificacion],
		[gen_detalleRegistroEnvio].[fechaCreacion] AS [fechaCreacion],
		[gen_detalleRegistroEnvio].[active] AS [active],
		[gen_detalleRegistroEnvio].[detalleRegistroEnvio] AS [detalleRegistroEnvio],
		[gen_detalleRegistroEnvio].[detalleRegistroEnvio_codigo] AS [detalleRegistroEnvio_codigo],
		[gen_detalleRegistroEnvio].[email] AS [email],
		[gen_detalleRegistroEnvio].[enviado] AS [enviado],
		[gen_detalleRegistroEnvio].[enviar] AS [enviar],
		[gen_detalleRegistroEnvio].[idObjeto] AS [idObjeto],
		[gen_detalleRegistroEnvio].[id_registroEnvio] AS [id_registroEnvio],
[gen_registroEnvio].[registroEnvio] as [gen_registroEnvio_registroEnvio],
[gen_registroEnvio].[registroEnvio_codigo] as [gen_registroEnvio_registroEnvio_codigo],
[gen_registroEnvio].[tabla] as [gen_registroEnvio_tabla],
[gen_registroEnvio].[reintentar] as [gen_registroEnvio_reintentar],
[gen_registroEnvio].[id_envioCorreo] as [gen_registroEnvio_id_envioCorreo],
[gen_registroEnvio].[id_registroEnvio] as [gen_registroEnvio_id_registroEnvio],
[gen_registroEnvio].[cmm] as [gen_registroEnvio_cmm],
		[gen_detalleRegistroEnvio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_detalleRegistroEnvio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_detalleRegistroEnvio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_detalleRegistroEnvio].[id_usuario_creo]
	INNER JOIN [gen_registroEnvio] ON [gen_registroEnvio].id=[gen_detalleRegistroEnvio].[id_registroEnvio]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_detalleRegistroEnvio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_detalleRegistroEnvio].active=1
