CREATE PROCEDURE [upd_gen_detalleRegistroEnvio]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detalleRegistroEnvio varchar(300) = null,
		@p_detalleRegistroEnvio_codigo varchar(100) = null,
		@p_email varchar(200) = null,
		@p_enviado bit = null,
		@p_enviar bit = null,
		@p_idObjeto int = null,
		@p_id_registroEnvio int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_detalleRegistroEnvio]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detalleRegistroEnvio] = isnull(@p_detalleRegistroEnvio,[detalleRegistroEnvio]),
			[detalleRegistroEnvio_codigo] = isnull(@p_detalleRegistroEnvio_codigo,[detalleRegistroEnvio_codigo]),
			[email] = isnull(@p_email,[email]),
			[enviado] = isnull(@p_enviado,[enviado]),
			[enviar] = isnull(@p_enviar,[enviar]),
			[idObjeto] = isnull(@p_idObjeto,[idObjeto]),
			[id_registroEnvio] = isnull(@p_id_registroEnvio,[id_registroEnvio]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
