IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_detalleRegistroEnvio]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_detalleRegistroEnvio]
GO
CREATE PROCEDURE [ins_gen_detalleRegistroEnvio]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detalleRegistroEnvio varchar(300),
		@p_detalleRegistroEnvio_codigo varchar(100),
		@p_email varchar(200),
		@p_enviado bit,
		@p_enviar bit,
		@p_idObjeto int,
		@p_id_registroEnvio int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_detalleRegistroEnvio]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detalleRegistroEnvio],
			[detalleRegistroEnvio_codigo],
			[email],
			[enviado],
			[enviar],
			[idObjeto],
			[id_registroEnvio],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detalleRegistroEnvio,
			@p_detalleRegistroEnvio_codigo,
			@p_email,
			@p_enviado,
			@p_enviar,
			@p_idObjeto,
			@p_id_registroEnvio,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_detalleRegistroEnvio] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
