CREATE  VIEW [view_gen_diaFestivo] AS
SELECT 	[gen_diaFestivo].[id] AS [id],
		[gen_diaFestivo].[uid] AS [uid],
		[gen_diaFestivo].[eid] AS [eid],
		[gen_diaFestivo].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_diaFestivo].[id_usuario_creo] AS [id_usuario_creo],
		[gen_diaFestivo].[fechaModificacion] AS [fechaModificacion],
		[gen_diaFestivo].[fechaCreacion] AS [fechaCreacion],
		[gen_diaFestivo].[active] AS [active],
		[gen_diaFestivo].[diaFestivo] AS [diaFestivo],
		[gen_diaFestivo].[diaFestivo_codigo] AS [diaFestivo_codigo],
		[gen_diaFestivo].[fecha_ff] AS [fecha_ff],
		[gen_diaFestivo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_diaFestivo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_diaFestivo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_diaFestivo].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_diaFestivo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_diaFestivo].active=1
