IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_diaFestivo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_diaFestivo]
GO
CREATE PROCEDURE [ins_gen_diaFestivo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_diaFestivo varchar(300),
		@p_diaFestivo_codigo varchar(100),
		@p_fecha_ff smalldatetime,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_diaFestivo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[diaFestivo],
			[diaFestivo_codigo],
			[fecha_ff],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_diaFestivo,
			@p_diaFestivo_codigo,
			@p_fecha_ff,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_diaFestivo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
