CREATE  VIEW [view_gen_empresa] AS
SELECT 	[gen_empresa].[id] AS [id],
		[gen_empresa].[uid] AS [uid],
		[gen_empresa].[eid] AS [eid],
		[gen_empresa].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_empresa].[id_usuario_creo] AS [id_usuario_creo],
		[gen_empresa].[fechaModificacion] AS [fechaModificacion],
		[gen_empresa].[fechaCreacion] AS [fechaCreacion],
		[gen_empresa].[active] AS [active],
		[gen_empresa].[empresa] AS [empresa],
		[gen_empresa].[empresa_codigo] AS [empresa_codigo],
		[gen_empresa].[codigo] AS [codigo],
		[gen_empresa].[costoAdministrativoMes] AS [costoAdministrativoMes],
		[gen_empresa].[id_empresa] AS [id_empresa],
[gen_empresa_padre].[empresa] as [gen_empresa_padre_empresa],
[gen_empresa_padre].[empresa_codigo] as [gen_empresa_padre_empresa_codigo],
[gen_empresa_padre].[codigo] as [gen_empresa_padre_codigo],
[gen_empresa_padre].[costoAdministrativoMes] as [gen_empresa_padre_costoAdministrativoMes],
[gen_empresa_padre].[id_empresa] as [gen_empresa_padre_id_empresa],
[gen_empresa_padre].[cmm] as [gen_empresa_padre_cmm],
		[gen_empresa].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_empresa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_empresa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_empresa].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS [gen_empresa_padre] ON [gen_empresa_padre].id=[gen_empresa].[id_empresa]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_empresa].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_empresa].active=1
GO
