IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_empresa]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_empresa]
GO
CREATE PROCEDURE [ins_gen_empresa]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_empresa varchar(300),
		@p_empresa_codigo varchar(100),
		@p_codigo varchar(100),
		@p_costoAdministrativoMes money,
		@p_id_empresa int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_empresa]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[empresa],
			[empresa_codigo],
			[codigo],
			[costoAdministrativoMes],
			[id_empresa],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_empresa,
			@p_empresa_codigo,
			@p_codigo,
			@p_costoAdministrativoMes,
			@p_id_empresa,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_empresa] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
