[doc_subtipoDocumento].[mostrarValoresEjecutados] as [doc_subtipoDocumento_mostrarValoresEjecutados],
[doc_subtipoDocumento].[archivosAdjuntosApp] as [doc_subtipoDocumento_archivosAdjuntosApp],
[doc_subtipoDocumento].[cmm] as [doc_subtipoDocumento_cmm],
		[gen_envioCorreo].[id_estadoTipoDocumento] AS [id_estadoTipoDocumento],
[doc_estadoTipoDocumento].[estadoTipoDocumento] as [doc_estadoTipoDocumento_estadoTipoDocumento],
[doc_estadoTipoDocumento].[estadoTipoDocumento_codigo] as [doc_estadoTipoDocumento_estadoTipoDocumento_codigo],
[doc_estadoTipoDocumento].[afectaIndicador] as [doc_estadoTipoDocumento_afectaIndicador],
[doc_estadoTipoDocumento].[editaDocumento] as [doc_estadoTipoDocumento_editaDocumento],
[doc_estadoTipoDocumento].[orden] as [doc_estadoTipoDocumento_orden],
[doc_estadoTipoDocumento].[puedeRegresar] as [doc_estadoTipoDocumento_puedeRegresar],
[doc_estadoTipoDocumento].[color] as [doc_estadoTipoDocumento_color],
[doc_estadoTipoDocumento].[afectaInventario] as [doc_estadoTipoDocumento_afectaInventario],
[doc_estadoTipoDocumento].[id_tipoDocumento] as [doc_estadoTipoDocumento_id_tipoDocumento],
[doc_estadoTipoDocumento].[descripcion] as [doc_estadoTipoDocumento_descripcion],
[doc_estadoTipoDocumento].[observacionesObligatorio] as [doc_estadoTipoDocumento_observacionesObligatorio],
[doc_estadoTipoDocumento].[motivoObligatorio] as [doc_estadoTipoDocumento_motivoObligatorio],
[doc_estadoTipoDocumento].[cmm] as [doc_estadoTipoDocumento_cmm],
		[gen_envioCorreo].[cantidadMensajes] AS [cantidadMensajes],
		[gen_envioCorreo].[tiempo_por_mensajes] AS [tiempo_por_mensajes],
		[gen_envioCorreo].[cantidadReintento] AS [cantidadReintento],
		[gen_envioCorreo].[adjuntarArchivo] AS [adjuntarArchivo],
		[gen_envioCorreo].[id_remitenteCorreo] AS [id_remitenteCorreo],
[gen_remitenteCorreo].[remitenteCorreo] as [gen_remitenteCorreo_remitenteCorreo],
[gen_remitenteCorreo].[remitenteCorreo_codigo] as [gen_remitenteCorreo_remitenteCorreo_codigo],
[gen_remitenteCorreo].[servidor] as [gen_remitenteCorreo_servidor],
[gen_remitenteCorreo].[certificado] as [gen_remitenteCorreo_certificado],
[gen_remitenteCorreo].[puerto] as [gen_remitenteCorreo_puerto],
[gen_remitenteCorreo].[credenciales] as [gen_remitenteCorreo_credenciales],
[gen_remitenteCorreo].[esGSuite] as [gen_remitenteCorreo_esGSuite],
[gen_remitenteCorreo].[cuentaCertificado] as [gen_remitenteCorreo_cuentaCertificado],
[gen_remitenteCorreo].[archivoCertificado] as [gen_remitenteCorreo_archivoCertificado],
[gen_remitenteCorreo].[cmm] as [gen_remitenteCorreo_cmm],
		[gen_envioCorreo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_envioCorreo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_envioCorreo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_envioCorreo].[id_usuario_creo]
	INNER JOIN [rep_reporte] ON [rep_reporte].id=[gen_envioCorreo].[id_reporte]
	INNER JOIN [doc_subtipoDocumento] ON [doc_subtipoDocumento].id=[gen_envioCorreo].[id_subtipoDocumento]
	INNER JOIN [doc_estadoTipoDocumento] ON [doc_estadoTipoDocumento].id=[gen_envioCorreo].[id_estadoTipoDocumento]
	INNER JOIN [gen_remitenteCorreo] ON [gen_remitenteCorreo].id=[gen_envioCorreo].[id_remitenteCorreo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_envioCorreo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_envioCorreo].active=1
GO
