		INSERT INTO [gen_envioCorreo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[envioCorreo],
			[envioCorreo_codigo],
