			[cantidadMensajes],
			[tiempo_por_mensajes],
			[cantidadReintento],
			[adjuntarArchivo],
			[id_remitenteCorreo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
