CREATE PROCEDURE [aud_gen_envioCorreo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gen_envioCorreo].id as id_tabla,
	[gen_envioCorreo].id_usuario_modifico as id_usuario_modifico,
	[gen_envioCorreo].id_usuario_creo as id_usuario_creo,
	[gen_envioCorreo].fechaModificacion as fechaModificacion,
	[gen_envioCorreo].fechaCreacion as fechaCreacion,
	[gen_envioCorreo].active as active,
	[gen_envioCorreo].[envioCorreo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gen_envioCorreo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_envioCorreo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_envioCorreo].[id_usuario_creo]
	where ' + @p_filtro)
END
