GO
CREATE  VIEW [view_gen_familia] AS
SELECT 	[gen_familia].[id] AS [id],
		[gen_familia].[uid] AS [uid],
		[gen_familia].[eid] AS [eid],
		[gen_familia].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_familia].[id_usuario_creo] AS [id_usuario_creo],
		[gen_familia].[fechaModificacion] AS [fechaModificacion],
		[gen_familia].[fechaCreacion] AS [fechaCreacion],
		[gen_familia].[active] AS [active],
		[gen_familia].[familia] AS [familia],
		[gen_familia].[familia_codigo] AS [familia_codigo],
		[gen_familia].[id_familia] AS [id_familia],
[gen_familia_padre].[familia] as [gen_familia_padre_familia],
[gen_familia_padre].[familia_codigo] as [gen_familia_padre_familia_codigo],
[gen_familia_padre].[id_familia] as [gen_familia_padre_id_familia],
[gen_familia_padre].[cmm] as [gen_familia_padre_cmm],
		[gen_familia].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_familia]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_familia].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_familia].[id_usuario_creo]
	INNER JOIN [gen_familia] AS [gen_familia_padre] ON [gen_familia_padre].id=[gen_familia].[id_familia]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_familia].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_familia].active=1
GO
