IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_familia]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_familia]
GO
CREATE PROCEDURE [ins_gen_familia]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_familia varchar(300),
		@p_familia_codigo varchar(100),
		@p_id_familia int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_familia]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[familia],
			[familia_codigo],
			[id_familia],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_familia,
			@p_familia_codigo,
			@p_id_familia,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_familia] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
