GO
CREATE  VIEW [view_gen_firmaContacto] AS
SELECT 	[gen_firmaContacto].[id] AS [id],
		[gen_firmaContacto].[uid] AS [uid],
		[gen_firmaContacto].[eid] AS [eid],
		[gen_firmaContacto].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_firmaContacto].[id_usuario_creo] AS [id_usuario_creo],
		[gen_firmaContacto].[fechaModificacion] AS [fechaModificacion],
		[gen_firmaContacto].[fechaCreacion] AS [fechaCreacion],
		[gen_firmaContacto].[active] AS [active],
		[gen_firmaContacto].[firmaContacto] AS [firmaContacto],
		[gen_firmaContacto].[firmaContacto_codigo] AS [firmaContacto_codigo],
		[gen_firmaContacto].[id_contacto] AS [id_contacto],
[ter_contacto].[contacto] as [ter_contacto_contacto],
[ter_contacto].[contacto_codigo] as [ter_contacto_contacto_codigo],
[ter_contacto].[telefono] as [ter_contacto_telefono],
[ter_contacto].[Fax] as [ter_contacto_Fax],
[ter_contacto].[Email] as [ter_contacto_Email],
[ter_contacto].[Direccion] as [ter_contacto_Direccion],
[ter_contacto].[telefonoMovil] as [ter_contacto_telefonoMovil],
[ter_contacto].[id_usuario] as [ter_contacto_id_usuario],
[ter_contacto].[cargo] as [ter_contacto_cargo],
[ter_contacto].[codigoAcceso] as [ter_contacto_codigoAcceso],
[ter_contacto].[id_cargoContacto] as [ter_contacto_id_cargoContacto],
[ter_contacto].[accesoActivo] as [ter_contacto_accesoActivo],
[ter_contacto].[ter_cargoContacto_id_usuario_Modifico] as [ter_contacto_ter_cargoContacto_id_usuario_Modifico],
[ter_contacto].[ter_cargoContacto_id_usuario_Creo] as [ter_contacto_ter_cargoContacto_id_usuario_Creo],
[ter_contacto].[cmm] as [ter_contacto_cmm],
		[gen_firmaContacto].[codigoacceso] AS [codigoacceso],
		[gen_firmaContacto].[archivobinario] AS [archivobinario],
		[gen_firmaContacto].[fecha_fh] AS [fecha_fh],
		[gen_firmaContacto].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_firmaContacto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_firmaContacto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_firmaContacto].[id_usuario_creo]
	INNER JOIN [ter_contacto] ON [ter_contacto].id=[gen_firmaContacto].[id_contacto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_firmaContacto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_firmaContacto].active=1
