IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_formulario]')) DROP VIEW [dbo].[view_gen_formulario]
GO
CREATE  VIEW [view_gen_formulario] AS
SELECT 	[gen_formulario].[id] AS [id],
		[gen_formulario].[uid] AS [uid],
		[gen_formulario].[eid] AS [eid],
		[gen_formulario].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_formulario].[id_usuario_creo] AS [id_usuario_creo],
		[gen_formulario].[fechaModificacion] AS [fechaModificacion],
		[gen_formulario].[fechaCreacion] AS [fechaCreacion],
		[gen_formulario].[active] AS [active],
		[gen_formulario].[formulario] AS [formulario],
		[gen_formulario].[formulario_codigo] AS [formulario_codigo],
		[gen_formulario].[duplicar] AS [duplicar],
		[gen_formulario].[eliminarIntermedias] AS [eliminarIntermedias],
		[gen_formulario].[id_configuracionAtributos] AS [id_configuracionAtributos],
[gen_configuracionAtributos].[configuracionAtributos] as [gen_configuracionAtributos_configuracionAtributos],
[gen_configuracionAtributos].[configuracionAtributos_codigo] as [gen_configuracionAtributos_configuracionAtributos_codigo],
[gen_configuracionAtributos].[id_tabla_resultado] as [gen_configuracionAtributos_id_tabla_resultado],
[gen_configuracionAtributos].[id_tabla_relacion] as [gen_configuracionAtributos_id_tabla_relacion],
[gen_configuracionAtributos].[cmm] as [gen_configuracionAtributos_cmm],
		[gen_formulario].[id_tabla_destino] AS [id_tabla_destino],
		[_tablas_destino].[tabla] AS [_tablas_destino_tabla],
		[_tablas_destino].[id_tabla_padre] AS [_tablas_destino_id_tabla_padre],
		[gen_formulario].[cmm] AS [cmm],
		[gen_formulario].[id_formulario] AS [id_formulario],
[gen_formulario_padre].[formulario] as [gen_formulario_padre_formulario],
[gen_formulario_padre].[formulario_codigo] as [gen_formulario_padre_formulario_codigo],
[gen_formulario_padre].[duplicar] as [gen_formulario_padre_duplicar],
[gen_formulario_padre].[eliminarIntermedias] as [gen_formulario_padre_eliminarIntermedias],
[gen_formulario_padre].[id_configuracionAtributos] as [gen_formulario_padre_id_configuracionAtributos],
[gen_formulario_padre].[id_tabla_destino] as [gen_formulario_padre_id_tabla_destino],
[gen_formulario_padre].[cmm] as [gen_formulario_padre_cmm],
[gen_formulario_padre].[id_formulario] as [gen_formulario_padre_id_formulario],
[gen_formulario_padre].[condicion] as [gen_formulario_padre_condicion],
[gen_formulario_padre].[valorDefecto] as [gen_formulario_padre_valorDefecto],
		[gen_formulario].[condicion] AS [condicion],
		[gen_formulario].[valorDefecto] AS [valorDefecto],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_formulario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_formulario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_formulario].[id_usuario_creo]
	INNER JOIN [gen_configuracionAtributos] ON [gen_configuracionAtributos].id=[gen_formulario].[id_configuracionAtributos]
	INNER JOIN [_tablas] AS [_tablas_destino] ON [_tablas_destino].id=[gen_formulario].[id_tabla_destino]
	INNER JOIN [gen_formulario] AS [gen_formulario_padre] ON [gen_formulario_padre].id=[gen_formulario].[id_formulario]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_formulario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_formulario].active=1
GO
