GO
CREATE PROCEDURE [upd_gen_formulario]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_formulario varchar(300) = null,
		@p_formulario_codigo varchar(100) = null,
		@p_duplicar int = null,
		@p_eliminarIntermedias int = null,
		@p_id_configuracionAtributos int = null,
		@p_id_tabla_destino int = null,
		@p_cmm varchar(300) = null,
		@p_id_formulario int = null,
		@p_condicion varchar(300) = null,
		@p_valorDefecto varchar(300) = null
AS
BEGIN
		UPDATE [gen_formulario]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[formulario] = isnull(@p_formulario,[formulario]),
			[formulario_codigo] = isnull(@p_formulario_codigo,[formulario_codigo]),
			[duplicar] = isnull(@p_duplicar,[duplicar]),
			[eliminarIntermedias] = isnull(@p_eliminarIntermedias,[eliminarIntermedias]),
			[id_configuracionAtributos] = isnull(@p_id_configuracionAtributos,[id_configuracionAtributos]),
			[id_tabla_destino] = isnull(@p_id_tabla_destino,[id_tabla_destino]),
			[cmm] = isnull(@p_cmm,[cmm]),
			[id_formulario] = isnull(@p_id_formulario,[id_formulario]),
			[condicion] = isnull(@p_condicion,[condicion]),
			[valorDefecto] = isnull(@p_valorDefecto,[valorDefecto])
		WHERE (id = @p_id)
END
