GO
CREATE PROCEDURE [ins_gen_formulario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_formulario varchar(300),
		@p_formulario_codigo varchar(100),
		@p_duplicar int,
		@p_eliminarIntermedias int,
		@p_id_configuracionAtributos int,
		@p_id_tabla_destino int,
		@p_cmm varchar(300),
		@p_id_formulario int,
		@p_condicion varchar(300),
		@p_valorDefecto varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_formulario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[formulario],
			[formulario_codigo],
			[duplicar],
			[eliminarIntermedias],
			[id_configuracionAtributos],
			[id_tabla_destino],
			[cmm],
			[id_formulario],
			[condicion],
			[valorDefecto])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_formulario,
