			@p_id_formulario,
			@p_condicion,
			@p_valorDefecto)
		SET @v_id = scope_identity()
UPDATE [gen_formulario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
