CREATE  VIEW [view_gen_formulario_catalogo_equipo] AS
SELECT 	[gen_formulario_catalogo.equipo].[id] AS [id],
		[gen_formulario_catalogo.equipo].[uid] AS [uid],
		[gen_formulario_catalogo.equipo].[eid] AS [eid],
		[gen_formulario_catalogo.equipo].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_formulario_catalogo.equipo].[id_usuario_creo] AS [id_usuario_creo],
		[gen_formulario_catalogo.equipo].[fechaModificacion] AS [fechaModificacion],
		[gen_formulario_catalogo.equipo].[fechaCreacion] AS [fechaCreacion],
		[gen_formulario_catalogo.equipo].[active] AS [active],
		[gen_formulario_catalogo.equipo].[formulario_catalogo.equipo] AS [formulario_catalogo.equipo],
		[gen_formulario_catalogo.equipo].[id_formulario] AS [id_formulario],
[gen_formulario].[formulario] as [gen_formulario_formulario],
[gen_formulario].[formulario_codigo] as [gen_formulario_formulario_codigo],
[gen_formulario].[duplicar] as [gen_formulario_duplicar],
[gen_formulario].[eliminarIntermedias] as [gen_formulario_eliminarIntermedias],
[gen_formulario].[id_configuracionAtributos] as [gen_formulario_id_configuracionAtributos],
[gen_formulario].[id_tabla_destino] as [gen_formulario_id_tabla_destino],
[gen_formulario].[cmm] as [gen_formulario_cmm],
[gen_formulario].[id_formulario] as [gen_formulario_id_formulario],
[gen_formulario].[condicion] as [gen_formulario_condicion],
[gen_formulario].[valorDefecto] as [gen_formulario_valorDefecto],
		[gen_formulario_catalogo.equipo].[id_catalogo.equipo] AS [id_catalogo.equipo],
[cat_catalogo.equipo].[catalogo.equipo] as [cat_catalogo.equipo_catalogo.equipo],
[cat_catalogo.equipo].[garantiaMeses] as [cat_catalogo.equipo_garantiaMeses],
[cat_catalogo.equipo].[garantiaHoras] as [cat_catalogo.equipo_garantiaHoras],
[cat_catalogo.equipo].[manejaHorometro] as [cat_catalogo.equipo_manejaHorometro],
[cat_catalogo.equipo].[id_marca] as [cat_catalogo.equipo_id_marca],
[cat_catalogo.equipo].[cmm] as [cat_catalogo.equipo_cmm],
		[cat_catalogo_equipo].[catalogo_codigo] AS [cat_catalogo_equipo_catalogo_codigo],
		[cat_catalogo_equipo].[codigoInventario] AS [cat_catalogo_equipo_codigoInventario],
		[cat_catalogo_equipo].[precioVenta] AS [cat_catalogo_equipo_precioVenta],
		[cat_catalogo_equipo].[tiempoConsecucion] AS [cat_catalogo_equipo_tiempoConsecucion],
		[cat_catalogo_equipo].[esNacional] AS [cat_catalogo_equipo_esNacional],
		[cat_catalogo_equipo].[id_familia] AS [cat_catalogo_equipo_id_familia],
		[cat_catalogo_equipo].[id_subtipoCatalogo] AS [cat_catalogo_equipo_id_subtipoCatalogo],
		[cat_catalogo_equipo].[id_unidad] AS [cat_catalogo_equipo_id_unidad],
		[cat_catalogo_equipo].[id_impuesto] AS [cat_catalogo_equipo_id_impuesto],
		[cat_catalogo_equipo].[descripcion] AS [cat_catalogo_equipo_descripcion],
		[cat_catalogo_equipo].[bloquearCostear] AS [cat_catalogo_equipo_bloquearCostear],
		[cat_catalogo_equipo].[cmm] AS [cat_catalogo_equipo_cmm],
		[gen_formulario_catalogo.equipo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_formulario_catalogo.equipo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_formulario_catalogo.equipo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_formulario_catalogo.equipo].[id_usuario_creo]
	INNER JOIN [gen_formulario] ON [gen_formulario].id=[gen_formulario_catalogo.equipo].[id_formulario]
	INNER JOIN [cat_catalogo.equipo] ON [cat_catalogo.equipo].id=[gen_formulario_catalogo.equipo].[id_catalogo.equipo]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_equipo] ON [cat_catalogo.equipo].id = [cat_catalogo_equipo].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_formulario_catalogo.equipo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
