IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_impuesto]')) DROP VIEW [dbo].[view_gen_impuesto]
GO
CREATE  VIEW [view_gen_impuesto] AS
SELECT 	[gen_impuesto].[id] AS [id],
		[gen_impuesto].[uid] AS [uid],
		[gen_impuesto].[eid] AS [eid],
		[gen_impuesto].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_impuesto].[id_usuario_creo] AS [id_usuario_creo],
		[gen_impuesto].[fechaModificacion] AS [fechaModificacion],
		[gen_impuesto].[fechaCreacion] AS [fechaCreacion],
		[gen_impuesto].[active] AS [active],
		[gen_impuesto].[impuesto] AS [impuesto],
		[gen_impuesto].[impuesto_codigo] AS [impuesto_codigo],
		[gen_impuesto].[valor] AS [valor],
		[gen_impuesto].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_impuesto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_impuesto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_impuesto].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_impuesto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_impuesto].active=1
GO
