	[gen_impuesto].id_usuario_modifico as id_usuario_modifico,
	[gen_impuesto].id_usuario_creo as id_usuario_creo,
	[gen_impuesto].fechaModificacion as fechaModificacion,
	[gen_impuesto].fechaCreacion as fechaCreacion,
