IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_localizacion]')) DROP VIEW [dbo].[view_gen_localizacion]
GO
CREATE  VIEW [view_gen_localizacion] AS
SELECT 	[gen_localizacion].[id] AS [id],
		[gen_localizacion].[uid] AS [uid],
		[gen_localizacion].[eid] AS [eid],
		[gen_localizacion].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_localizacion].[id_usuario_creo] AS [id_usuario_creo],
		[gen_localizacion].[fechaModificacion] AS [fechaModificacion],
		[gen_localizacion].[fechaCreacion] AS [fechaCreacion],
		[gen_localizacion].[active] AS [active],
		[gen_localizacion].[localizacion] AS [localizacion],
		[gen_localizacion].[localizacion_codigo] AS [localizacion_codigo],
		[gen_localizacion].[id_catalogo_bodega] AS [id_catalogo_bodega],
[cat_catalogo_bodega].[catalogo] as [cat_catalogo_bodega_catalogo],
[cat_catalogo_bodega].[catalogo_codigo] as [cat_catalogo_bodega_catalogo_codigo],
[cat_catalogo_bodega].[codigoInventario] as [cat_catalogo_bodega_codigoInventario],
[cat_catalogo_bodega].[precioVenta] as [cat_catalogo_bodega_precioVenta],
[cat_catalogo_bodega].[tiempoConsecucion] as [cat_catalogo_bodega_tiempoConsecucion],
[cat_catalogo_bodega].[esNacional] as [cat_catalogo_bodega_esNacional],
[cat_catalogo_bodega].[id_familia] as [cat_catalogo_bodega_id_familia],
[cat_catalogo_bodega].[id_subtipoCatalogo] as [cat_catalogo_bodega_id_subtipoCatalogo],
[cat_catalogo_bodega].[id_unidad] as [cat_catalogo_bodega_id_unidad],
[cat_catalogo_bodega].[id_impuesto] as [cat_catalogo_bodega_id_impuesto],
[cat_catalogo_bodega].[descripcion] as [cat_catalogo_bodega_descripcion],
[cat_catalogo_bodega].[bloquearCostear] as [cat_catalogo_bodega_bloquearCostear],
[cat_catalogo_bodega].[cmm] as [cat_catalogo_bodega_cmm],
		[gen_localizacion].[existencia] AS [existencia],
		[gen_localizacion].[existenciaMaxima] AS [existenciaMaxima],
		[gen_localizacion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_localizacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_localizacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_localizacion].[id_usuario_creo]
	INNER JOIN [cat_catalogo] AS [cat_catalogo_bodega] ON [cat_catalogo_bodega].id=[gen_localizacion].[id_catalogo_bodega]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_localizacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_localizacion].active=1
GO
