CREATE PROCEDURE [upd_gen_localizacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_localizacion varchar(300) = null,
		@p_localizacion_codigo varchar(100) = null,
		@p_id_catalogo_bodega int = null,
		@p_existencia int = null,
		@p_existenciaMaxima int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_localizacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[localizacion] = isnull(@p_localizacion,[localizacion]),
			[localizacion_codigo] = isnull(@p_localizacion_codigo,[localizacion_codigo]),
			[id_catalogo_bodega] = isnull(@p_id_catalogo_bodega,[id_catalogo_bodega]),
			[existencia] = isnull(@p_existencia,[existencia]),
			[existenciaMaxima] = isnull(@p_existenciaMaxima,[existenciaMaxima]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
