CREATE PROCEDURE [ins_gen_localizacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_localizacion varchar(300),
		@p_localizacion_codigo varchar(100),
		@p_id_catalogo_bodega int,
		@p_existencia int,
		@p_existenciaMaxima int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_localizacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[localizacion],
			[localizacion_codigo],
			[id_catalogo_bodega],
			[existencia],
			[existenciaMaxima],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_localizacion,
			@p_localizacion_codigo,
			@p_id_catalogo_bodega,
			@p_existencia,
			@p_existenciaMaxima,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_localizacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
