GO
CREATE PROCEDURE [ins_gen_localizacion_itemDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_localizacion_itemDocumento varchar(300),
		@p_id_localizacion int,
		@p_id_itemDocumento int,
		@p_cantidad int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_localizacion_itemDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[localizacion_itemDocumento],
			[id_localizacion],
			[id_itemDocumento],
			[cantidad],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_localizacion_itemDocumento,
			@p_id_localizacion,
			@p_id_itemDocumento,
			@p_cantidad,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_localizacion_itemDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
