		[gen_logTrazabilidad].[uid] AS [uid],
		[gen_logTrazabilidad].[eid] AS [eid],
		[gen_logTrazabilidad].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_logTrazabilidad].[id_usuario_creo] AS [id_usuario_creo],
