IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_moneda]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_moneda]
GO
CREATE PROCEDURE [ins_gen_moneda]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_moneda varchar(300),
		@p_moneda_codigo varchar(100),
		@p_abreviatura varchar(10),
		@p_cambio float,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_moneda]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[moneda],
			[moneda_codigo],
			[abreviatura],
			[cambio],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_moneda,
			@p_moneda_codigo,
			@p_abreviatura,
			@p_cambio,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_moneda] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
