CREATE PROCEDURE [aud_gen_moneda]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gen_moneda].id as id_tabla,
	[gen_moneda].id_usuario_modifico as id_usuario_modifico,
	[gen_moneda].id_usuario_creo as id_usuario_creo,
	[gen_moneda].fechaModificacion as fechaModificacion,
	[gen_moneda].fechaCreacion as fechaCreacion,
	[gen_moneda].active as active,
	[gen_moneda].[moneda] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gen_moneda]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_moneda].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_moneda].[id_usuario_creo]
	where ' + @p_filtro)
END
