		[gen_notificacion].[datos] AS [datos],
		[gen_notificacion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_notificacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_notificacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_notificacion].[id_usuario_creo]
	INNER JOIN [gen_tipoNotificacion] ON [gen_tipoNotificacion].id=[gen_notificacion].[id_tipoNotificacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_origen] ON [seg_usuario_origen].id=[gen_notificacion].[id_usuario_origen]
	INNER JOIN [seg_usuario] AS [seg_usuario_destino] ON [seg_usuario_destino].id=[gen_notificacion].[id_usuario_destino]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_notificacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_notificacion].active=1
