GO
CREATE PROCEDURE [upd_gen_notificacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_notificacion varchar(300) = null,
		@p_notificacion_codigo varchar(100) = null,
		@p_id_tipoNotificacion int = null,
		@p_id_usuario_origen int = null,
		@p_id_usuario_destino int = null,
		@p_datos nvarchar(-1) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_notificacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[notificacion] = isnull(@p_notificacion,[notificacion]),
			[notificacion_codigo] = isnull(@p_notificacion_codigo,[notificacion_codigo]),
			[id_tipoNotificacion] = isnull(@p_id_tipoNotificacion,[id_tipoNotificacion]),
			[id_usuario_origen] = isnull(@p_id_usuario_origen,[id_usuario_origen]),
			[id_usuario_destino] = isnull(@p_id_usuario_destino,[id_usuario_destino]),
			[datos] = isnull(@p_datos,[datos]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
