IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_notificacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_notificacion]
GO
CREATE PROCEDURE [ins_gen_notificacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_notificacion varchar(300),
		@p_notificacion_codigo varchar(100),
		@p_id_tipoNotificacion int,
		@p_id_usuario_origen int,
		@p_id_usuario_destino int,
		@p_datos nvarchar(-1),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_notificacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[notificacion],
			[notificacion_codigo],
			[id_tipoNotificacion],
			[id_usuario_origen],
			[id_usuario_destino],
			[datos],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_notificacion,
			@p_notificacion_codigo,
			@p_id_tipoNotificacion,
			@p_id_usuario_origen,
			@p_id_usuario_destino,
			@p_datos,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_notificacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
