CREATE PROCEDURE [aud_gen_notificacion]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gen_notificacion].id as id_tabla,
	[gen_notificacion].id_usuario_modifico as id_usuario_modifico,
	[gen_notificacion].id_usuario_creo as id_usuario_creo,
	[gen_notificacion].fechaModificacion as fechaModificacion,
	[gen_notificacion].fechaCreacion as fechaCreacion,
	[gen_notificacion].active as active,
	[gen_notificacion].[notificacion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gen_notificacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_notificacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_notificacion].[id_usuario_creo]
	where ' + @p_filtro)
END
