IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_presupuestoEmpresa]')) DROP VIEW [dbo].[view_gen_presupuestoEmpresa]
GO
CREATE  VIEW [view_gen_presupuestoEmpresa] AS
SELECT 	[gen_presupuestoEmpresa].[id] AS [id],
		[gen_presupuestoEmpresa].[uid] AS [uid],
		[gen_presupuestoEmpresa].[eid] AS [eid],
		[gen_presupuestoEmpresa].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_presupuestoEmpresa].[id_usuario_creo] AS [id_usuario_creo],
		[gen_presupuestoEmpresa].[fechaModificacion] AS [fechaModificacion],
		[gen_presupuestoEmpresa].[fechaCreacion] AS [fechaCreacion],
		[gen_presupuestoEmpresa].[active] AS [active],
		[gen_presupuestoEmpresa].[presupuestoEmpresa] AS [presupuestoEmpresa],
		[gen_presupuestoEmpresa].[presupuestoEmpresa_codigo] AS [presupuestoEmpresa_codigo],
		[gen_presupuestoEmpresa].[fechaInicio_ff] AS [fechaInicio_ff],
		[gen_presupuestoEmpresa].[fechaFin_ff] AS [fechaFin_ff],
		[gen_presupuestoEmpresa].[Valor] AS [Valor],
		[gen_presupuestoEmpresa].[id_empresa] AS [id_empresa],
[gen_empresa].[empresa] as [gen_empresa_empresa],
[gen_empresa].[empresa_codigo] as [gen_empresa_empresa_codigo],
[gen_empresa].[codigo] as [gen_empresa_codigo],
[gen_empresa].[costoAdministrativoMes] as [gen_empresa_costoAdministrativoMes],
[gen_empresa].[id_empresa] as [gen_empresa_id_empresa],
[gen_empresa].[cmm] as [gen_empresa_cmm],
		[gen_presupuestoEmpresa].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_presupuestoEmpresa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_presupuestoEmpresa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_presupuestoEmpresa].[id_usuario_creo]
	INNER JOIN [gen_empresa] ON [gen_empresa].id=[gen_presupuestoEmpresa].[id_empresa]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_presupuestoEmpresa].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_presupuestoEmpresa].active=1
GO
