CREATE PROCEDURE [aud_gen_presupuestoEmpresa]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gen_presupuestoEmpresa].id as id_tabla,
	[gen_presupuestoEmpresa].id_usuario_modifico as id_usuario_modifico,
	[gen_presupuestoEmpresa].id_usuario_creo as id_usuario_creo,
	[gen_presupuestoEmpresa].fechaModificacion as fechaModificacion,
	[gen_presupuestoEmpresa].fechaCreacion as fechaCreacion,
	[gen_presupuestoEmpresa].active as active,
	[gen_presupuestoEmpresa].[presupuestoEmpresa] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gen_presupuestoEmpresa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_presupuestoEmpresa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_presupuestoEmpresa].[id_usuario_creo]
	where ' + @p_filtro)
END
