IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_recurso]')) DROP VIEW [dbo].[view_gen_recurso]
GO
CREATE  VIEW [view_gen_recurso] AS
SELECT 	[gen_recurso].[id] AS [id],
		[gen_recurso].[uid] AS [uid],
		[gen_recurso].[eid] AS [eid],
		[gen_recurso].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_recurso].[id_usuario_creo] AS [id_usuario_creo],
		[gen_recurso].[fechaModificacion] AS [fechaModificacion],
		[gen_recurso].[fechaCreacion] AS [fechaCreacion],
		[gen_recurso].[active] AS [active],
		[gen_recurso].[recurso] AS [recurso],
		[gen_recurso].[recurso_codigo] AS [recurso_codigo],
		[gen_recurso].[grupoRecurso] AS [grupoRecurso],
		[gen_recurso].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_recurso]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_recurso].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_recurso].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_recurso].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_recurso].active=1
GO
