CREATE  VIEW [view_gen_registroEnvio] AS
SELECT 	[gen_registroEnvio].[id] AS [id],
		[gen_registroEnvio].[uid] AS [uid],
		[gen_registroEnvio].[eid] AS [eid],
		[gen_registroEnvio].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_registroEnvio].[id_usuario_creo] AS [id_usuario_creo],
		[gen_registroEnvio].[fechaModificacion] AS [fechaModificacion],
		[gen_registroEnvio].[fechaCreacion] AS [fechaCreacion],
		[gen_registroEnvio].[active] AS [active],
		[gen_registroEnvio].[registroEnvio] AS [registroEnvio],
		[gen_registroEnvio].[registroEnvio_codigo] AS [registroEnvio_codigo],
		[gen_registroEnvio].[tabla] AS [tabla],
		[gen_registroEnvio].[reintentar] AS [reintentar],
		[gen_registroEnvio].[id_envioCorreo] AS [id_envioCorreo],
[gen_envioCorreo].[envioCorreo] as [gen_envioCorreo_envioCorreo],
[gen_envioCorreo].[envioCorreo_codigo] as [gen_envioCorreo_envioCorreo_codigo],
[gen_envioCorreo].[estrategia] as [gen_envioCorreo_estrategia],
[gen_envioCorreo].[tabla] as [gen_envioCorreo_tabla],
[gen_envioCorreo].[id_reporte] as [gen_envioCorreo_id_reporte],
[gen_envioCorreo].[correoAdicional] as [gen_envioCorreo_correoAdicional],
[gen_envioCorreo].[plantillaAdjunto] as [gen_envioCorreo_plantillaAdjunto],
[gen_envioCorreo].[id_subtipoDocumento] as [gen_envioCorreo_id_subtipoDocumento],
[gen_envioCorreo].[id_estadoTipoDocumento] as [gen_envioCorreo_id_estadoTipoDocumento],
[gen_envioCorreo].[cantidadMensajes] as [gen_envioCorreo_cantidadMensajes],
[gen_envioCorreo].[tiempo_por_mensajes] as [gen_envioCorreo_tiempo_por_mensajes],
[gen_envioCorreo].[cantidadReintento] as [gen_envioCorreo_cantidadReintento],
[gen_envioCorreo].[adjuntarArchivo] as [gen_envioCorreo_adjuntarArchivo],
[gen_envioCorreo].[id_remitenteCorreo] as [gen_envioCorreo_id_remitenteCorreo],
[gen_envioCorreo].[cmm] as [gen_envioCorreo_cmm],
		[gen_registroEnvio].[id_registroEnvio] AS [id_registroEnvio],
[gen_registroEnvio_padre].[registroEnvio] as [gen_registroEnvio_padre_registroEnvio],
[gen_registroEnvio_padre].[registroEnvio_codigo] as [gen_registroEnvio_padre_registroEnvio_codigo],
[gen_registroEnvio_padre].[tabla] as [gen_registroEnvio_padre_tabla],
[gen_registroEnvio_padre].[reintentar] as [gen_registroEnvio_padre_reintentar],
[gen_registroEnvio_padre].[id_envioCorreo] as [gen_registroEnvio_padre_id_envioCorreo],
[gen_registroEnvio_padre].[id_registroEnvio] as [gen_registroEnvio_padre_id_registroEnvio],
[gen_registroEnvio_padre].[cmm] as [gen_registroEnvio_padre_cmm],
		[gen_registroEnvio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_registroEnvio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_registroEnvio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_registroEnvio].[id_usuario_creo]
	INNER JOIN [gen_envioCorreo] ON [gen_envioCorreo].id=[gen_registroEnvio].[id_envioCorreo]
	INNER JOIN [gen_registroEnvio] AS [gen_registroEnvio_padre] ON [gen_registroEnvio_padre].id=[gen_registroEnvio].[id_registroEnvio]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_registroEnvio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_registroEnvio].active=1
