GO
CREATE PROCEDURE [upd_gen_registroEnvio]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_registroEnvio varchar(300) = null,
		@p_registroEnvio_codigo varchar(100) = null,
		@p_tabla varchar(200) = null,
		@p_reintentar bit = null,
		@p_id_envioCorreo int = null,
		@p_id_registroEnvio int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_registroEnvio]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[registroEnvio] = isnull(@p_registroEnvio,[registroEnvio]),
			[registroEnvio_codigo] = isnull(@p_registroEnvio_codigo,[registroEnvio_codigo]),
			[tabla] = isnull(@p_tabla,[tabla]),
			[reintentar] = isnull(@p_reintentar,[reintentar]),
			[id_envioCorreo] = isnull(@p_id_envioCorreo,[id_envioCorreo]),
			[id_registroEnvio] = isnull(@p_id_registroEnvio,[id_registroEnvio]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
