IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_registroEnvio]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_registroEnvio]
GO
CREATE PROCEDURE [ins_gen_registroEnvio]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_registroEnvio varchar(300),
		@p_registroEnvio_codigo varchar(100),
		@p_tabla varchar(200),
		@p_reintentar bit,
		@p_id_envioCorreo int,
		@p_id_registroEnvio int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_registroEnvio]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[registroEnvio],
			[registroEnvio_codigo],
			[tabla],
			[reintentar],
			[id_envioCorreo],
			[id_registroEnvio],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_registroEnvio,
			@p_registroEnvio_codigo,
			@p_tabla,
			@p_reintentar,
			@p_id_envioCorreo,
			@p_id_registroEnvio,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_registroEnvio] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
