IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_remitenteCorreo]')) DROP VIEW [dbo].[view_gen_remitenteCorreo]
GO
CREATE  VIEW [view_gen_remitenteCorreo] AS
SELECT 	[gen_remitenteCorreo].[id] AS [id],
		[gen_remitenteCorreo].[uid] AS [uid],
		[gen_remitenteCorreo].[eid] AS [eid],
		[gen_remitenteCorreo].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_remitenteCorreo].[id_usuario_creo] AS [id_usuario_creo],
		[gen_remitenteCorreo].[fechaModificacion] AS [fechaModificacion],
		[gen_remitenteCorreo].[fechaCreacion] AS [fechaCreacion],
		[gen_remitenteCorreo].[active] AS [active],
		[gen_remitenteCorreo].[remitenteCorreo] AS [remitenteCorreo],
		[gen_remitenteCorreo].[remitenteCorreo_codigo] AS [remitenteCorreo_codigo],
		[gen_remitenteCorreo].[servidor] AS [servidor],
		[gen_remitenteCorreo].[certificado] AS [certificado],
		[gen_remitenteCorreo].[puerto] AS [puerto],
		[gen_remitenteCorreo].[credenciales] AS [credenciales],
		[gen_remitenteCorreo].[esGSuite] AS [esGSuite],
		[gen_remitenteCorreo].[cuentaCertificado] AS [cuentaCertificado],
		[gen_remitenteCorreo].[archivoCertificado] AS [archivoCertificado],
		[gen_remitenteCorreo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_remitenteCorreo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_remitenteCorreo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_remitenteCorreo].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_remitenteCorreo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_remitenteCorreo].active=1
GO
