GO
CREATE PROCEDURE [upd_gen_remitenteCorreo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_remitenteCorreo varchar(300) = null,
		@p_remitenteCorreo_codigo varchar(100) = null,
		@p_servidor varchar(200) = null,
		@p_certificado bit = null,
		@p_puerto varchar(100) = null,
		@p_credenciales varchar(200) = null,
		@p_esGSuite bit = null,
		@p_cuentaCertificado varchar(200) = null,
		@p_archivoCertificado varchar(800) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_remitenteCorreo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[remitenteCorreo] = isnull(@p_remitenteCorreo,[remitenteCorreo]),
			[remitenteCorreo_codigo] = isnull(@p_remitenteCorreo_codigo,[remitenteCorreo_codigo]),
			[servidor] = isnull(@p_servidor,[servidor]),
			[certificado] = isnull(@p_certificado,[certificado]),
			[puerto] = isnull(@p_puerto,[puerto]),
			[credenciales] = isnull(@p_credenciales,[credenciales]),
			[esGSuite] = isnull(@p_esGSuite,[esGSuite]),
			[cuentaCertificado] = isnull(@p_cuentaCertificado,[cuentaCertificado]),
			[archivoCertificado] = isnull(@p_archivoCertificado,[archivoCertificado]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
