IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gen_remitenteCorreo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gen_remitenteCorreo]
GO
CREATE PROCEDURE [ins_gen_remitenteCorreo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_remitenteCorreo varchar(300),
		@p_remitenteCorreo_codigo varchar(100),
		@p_servidor varchar(200),
		@p_certificado bit,
		@p_puerto varchar(100),
		@p_credenciales varchar(200),
		@p_esGSuite bit,
		@p_cuentaCertificado varchar(200),
		@p_archivoCertificado varchar(800),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_remitenteCorreo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[remitenteCorreo],
			[remitenteCorreo_codigo],
			[servidor],
			[certificado],
			[puerto],
			[credenciales],
			[esGSuite],
			[cuentaCertificado],
			[archivoCertificado],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_remitenteCorreo,
			@p_remitenteCorreo_codigo,
			@p_servidor,
			@p_certificado,
			@p_puerto,
			@p_credenciales,
			@p_esGSuite,
			@p_cuentaCertificado,
			@p_archivoCertificado,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_remitenteCorreo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
