CREATE  VIEW [view_gen_seccionFormulario] AS
SELECT 	[gen_seccionFormulario].[id] AS [id],
		[gen_seccionFormulario].[uid] AS [uid],
		[gen_seccionFormulario].[eid] AS [eid],
		[gen_seccionFormulario].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_seccionFormulario].[id_usuario_creo] AS [id_usuario_creo],
		[gen_seccionFormulario].[fechaModificacion] AS [fechaModificacion],
		[gen_seccionFormulario].[fechaCreacion] AS [fechaCreacion],
		[gen_seccionFormulario].[active] AS [active],
		[gen_seccionFormulario].[seccionFormulario] AS [seccionFormulario],
		[gen_seccionFormulario].[seccionFormulario_codigo] AS [seccionFormulario_codigo],
		[gen_seccionFormulario].[orden] AS [orden],
		[gen_seccionFormulario].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_seccionFormulario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_seccionFormulario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_seccionFormulario].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_seccionFormulario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_seccionFormulario].active=1
