GO
CREATE PROCEDURE [ins_gen_seccionFormulario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_seccionFormulario varchar(300),
		@p_seccionFormulario_codigo varchar(100),
		@p_orden int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_seccionFormulario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[seccionFormulario],
			[seccionFormulario_codigo],
			[orden],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_seccionFormulario,
			@p_seccionFormulario_codigo,
			@p_orden,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_seccionFormulario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
