CREATE  VIEW [view_gen_tipoNotificacion] AS
SELECT 	[gen_tipoNotificacion].[id] AS [id],
		[gen_tipoNotificacion].[uid] AS [uid],
		[gen_tipoNotificacion].[eid] AS [eid],
		[gen_tipoNotificacion].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_tipoNotificacion].[id_usuario_creo] AS [id_usuario_creo],
		[gen_tipoNotificacion].[fechaModificacion] AS [fechaModificacion],
		[gen_tipoNotificacion].[fechaCreacion] AS [fechaCreacion],
		[gen_tipoNotificacion].[active] AS [active],
		[gen_tipoNotificacion].[tipoNotificacion] AS [tipoNotificacion],
		[gen_tipoNotificacion].[tipoNotificacion_codigo] AS [tipoNotificacion_codigo],
		[gen_tipoNotificacion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_tipoNotificacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_tipoNotificacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_tipoNotificacion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_tipoNotificacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_tipoNotificacion].active=1
