			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tipoNotificacion] = isnull(@p_tipoNotificacion,[tipoNotificacion]),
			[tipoNotificacion_codigo] = isnull(@p_tipoNotificacion_codigo,[tipoNotificacion_codigo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
