CREATE  VIEW [view_gen_tipoServicio] AS
SELECT 	[gen_tipoServicio].[id] AS [id],
		[gen_tipoServicio].[uid] AS [uid],
		[gen_tipoServicio].[eid] AS [eid],
		[gen_tipoServicio].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_tipoServicio].[id_usuario_creo] AS [id_usuario_creo],
		[gen_tipoServicio].[fechaModificacion] AS [fechaModificacion],
		[gen_tipoServicio].[fechaCreacion] AS [fechaCreacion],
		[gen_tipoServicio].[active] AS [active],
		[gen_tipoServicio].[tipoServicio] AS [tipoServicio],
		[gen_tipoServicio].[tipoServicio_codigo] AS [tipoServicio_codigo],
		[gen_tipoServicio].[tieneGarantia] AS [tieneGarantia],
		[gen_tipoServicio].[diasGarantia] AS [diasGarantia],
		[gen_tipoServicio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_tipoServicio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_tipoServicio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_tipoServicio].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_tipoServicio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_tipoServicio].active=1
