GO
CREATE PROCEDURE [ins_gen_tipoServicio]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoServicio varchar(300),
		@p_tipoServicio_codigo varchar(100),
		@p_tieneGarantia bit,
		@p_diasGarantia int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_tipoServicio]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoServicio],
			[tipoServicio_codigo],
			[tieneGarantia],
			[diasGarantia],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoServicio,
			@p_tipoServicio_codigo,
			@p_tieneGarantia,
			@p_diasGarantia,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_tipoServicio] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
