	[gen_unidad].id_usuario_modifico as id_usuario_modifico,
	[gen_unidad].id_usuario_creo as id_usuario_creo,
	[gen_unidad].fechaModificacion as fechaModificacion,
	[gen_unidad].fechaCreacion as fechaCreacion,
	[gen_unidad].active as active,
	[gen_unidad].[unidad] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gen_unidad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_unidad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_unidad].[id_usuario_creo]
	where ' + @p_filtro)
END
