IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gen_zona]')) DROP VIEW [dbo].[view_gen_zona]
GO
CREATE  VIEW [view_gen_zona] AS
SELECT 	[gen_zona].[id] AS [id],
		[gen_zona].[uid] AS [uid],
		[gen_zona].[eid] AS [eid],
		[gen_zona].[id_usuario_modifico] AS [id_usuario_modifico],
		[gen_zona].[id_usuario_creo] AS [id_usuario_creo],
		[gen_zona].[fechaModificacion] AS [fechaModificacion],
		[gen_zona].[fechaCreacion] AS [fechaCreacion],
		[gen_zona].[active] AS [active],
		[gen_zona].[zona] AS [zona],
		[gen_zona].[zona_codigo] AS [zona_codigo],
		[gen_zona].[tiempoDesplazamiento] AS [tiempoDesplazamiento],
		[gen_zona].[nivel] AS [nivel],
		[gen_zona].[id_zona] AS [id_zona],
[gen_zona_padre].[zona] as [gen_zona_padre_zona],
[gen_zona_padre].[zona_codigo] as [gen_zona_padre_zona_codigo],
[gen_zona_padre].[tiempoDesplazamiento] as [gen_zona_padre_tiempoDesplazamiento],
[gen_zona_padre].[nivel] as [gen_zona_padre_nivel],
[gen_zona_padre].[id_zona] as [gen_zona_padre_id_zona],
[gen_zona_padre].[codigoExterno] as [gen_zona_padre_codigoExterno],
[gen_zona_padre].[cmm] as [gen_zona_padre_cmm],
		[gen_zona].[codigoExterno] AS [codigoExterno],
		[gen_zona].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gen_zona]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_zona].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_zona].[id_usuario_creo]
	INNER JOIN [gen_zona] AS [gen_zona_padre] ON [gen_zona_padre].id=[gen_zona].[id_zona]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gen_zona].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gen_zona].active=1
GO
