CREATE PROCEDURE [upd_gen_zona]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_zona varchar(300) = null,
		@p_zona_codigo varchar(100) = null,
		@p_tiempoDesplazamiento float = null,
		@p_nivel int = null,
		@p_id_zona int = null,
		@p_codigoExterno varchar(50) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gen_zona]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[zona] = isnull(@p_zona,[zona]),
			[zona_codigo] = isnull(@p_zona_codigo,[zona_codigo]),
			[tiempoDesplazamiento] = isnull(@p_tiempoDesplazamiento,[tiempoDesplazamiento]),
			[nivel] = isnull(@p_nivel,[nivel]),
			[id_zona] = isnull(@p_id_zona,[id_zona]),
			[codigoExterno] = isnull(@p_codigoExterno,[codigoExterno]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
