CREATE PROCEDURE [ins_gen_zona]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_zona varchar(300),
		@p_zona_codigo varchar(100),
		@p_tiempoDesplazamiento float,
		@p_nivel int,
		@p_id_zona int,
		@p_codigoExterno varchar(50),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_zona]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[zona],
			[zona_codigo],
			[tiempoDesplazamiento],
			[nivel],
			[id_zona],
			[codigoExterno],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_zona,
			@p_zona_codigo,
			@p_tiempoDesplazamiento,
			@p_nivel,
			@p_id_zona,
			@p_codigoExterno,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_zona] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
