CREATE PROCEDURE [aud_gen_zona]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gen_zona].id as id_tabla,
	[gen_zona].id_usuario_modifico as id_usuario_modifico,
	[gen_zona].id_usuario_creo as id_usuario_creo,
	[gen_zona].fechaModificacion as fechaModificacion,
	[gen_zona].fechaCreacion as fechaCreacion,
	[gen_zona].active as active,
	[gen_zona].[zona] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gen_zona]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gen_zona].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gen_zona].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
