GO
CREATE  VIEW [view_geo_ubicacion] AS
SELECT 	[geo_ubicacion].[id] AS [id],
		[geo_ubicacion].[uid] AS [uid],
		[geo_ubicacion].[eid] AS [eid],
		[geo_ubicacion].[id_usuario_modifico] AS [id_usuario_modifico],
		[geo_ubicacion].[id_usuario_creo] AS [id_usuario_creo],
		[geo_ubicacion].[fechaModificacion] AS [fechaModificacion],
		[geo_ubicacion].[fechaCreacion] AS [fechaCreacion],
		[geo_ubicacion].[active] AS [active],
		[geo_ubicacion].[ubicacion] AS [ubicacion],
		[geo_ubicacion].[ubicacion_codigo] AS [ubicacion_codigo],
		[geo_ubicacion].[tabla] AS [tabla],
		[geo_ubicacion].[idObjeto] AS [idObjeto],
		[geo_ubicacion].[longitud] AS [longitud],
		[geo_ubicacion].[latitud] AS [latitud],
		[geo_ubicacion].[fecha_fh] AS [fecha_fh],
		[geo_ubicacion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [geo_ubicacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[geo_ubicacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[geo_ubicacion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [geo_ubicacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [geo_ubicacion].active=1
GO
