IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_geo_ubicacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_geo_ubicacion]
GO
CREATE PROCEDURE [upd_geo_ubicacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_ubicacion varchar(300) = null,
		@p_ubicacion_codigo varchar(300) = null,
		@p_tabla varchar(100) = null,
		@p_idObjeto int = null,
		@p_longitud float = null,
		@p_latitud float = null,
		@p_fecha_fh smalldatetime = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [geo_ubicacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[ubicacion] = isnull(@p_ubicacion,[ubicacion]),
			[ubicacion_codigo] = isnull(@p_ubicacion_codigo,[ubicacion_codigo]),
			[tabla] = isnull(@p_tabla,[tabla]),
			[idObjeto] = isnull(@p_idObjeto,[idObjeto]),
			[longitud] = isnull(@p_longitud,[longitud]),
			[latitud] = isnull(@p_latitud,[latitud]),
			[fecha_fh] = isnull(@p_fecha_fh,[fecha_fh]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
