IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_geo_ubicacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_geo_ubicacion]
GO
CREATE PROCEDURE [ins_geo_ubicacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_ubicacion varchar(300),
		@p_ubicacion_codigo varchar(300),
		@p_tabla varchar(100),
		@p_idObjeto int,
		@p_longitud float,
		@p_latitud float,
		@p_fecha_fh smalldatetime,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [geo_ubicacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[ubicacion],
			[ubicacion_codigo],
			[tabla],
			[idObjeto],
			[longitud],
			[latitud],
			[fecha_fh],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_ubicacion,
			@p_ubicacion_codigo,
			@p_tabla,
			@p_idObjeto,
			@p_longitud,
			@p_latitud,
			@p_fecha_fh,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [geo_ubicacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
