[gui_ayuda_padre].[ayuda] as [gui_ayuda_padre_ayuda],
[gui_ayuda_padre].[ayuda_codigo] as [gui_ayuda_padre_ayuda_codigo],
[gui_ayuda_padre].[id_ayuda] as [gui_ayuda_padre_id_ayuda],
[gui_ayuda_padre].[cmm] as [gui_ayuda_padre_cmm],
		[gui_ayuda].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gui_ayuda]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_ayuda].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_ayuda].[id_usuario_creo]
	INNER JOIN [gui_ayuda] AS [gui_ayuda_padre] ON [gui_ayuda_padre].id=[gui_ayuda].[id_ayuda]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gui_ayuda].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gui_ayuda].active=1
