IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gui_ayuda]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gui_ayuda]
GO
CREATE PROCEDURE [ins_gui_ayuda]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_ayuda varchar(300),
		@p_ayuda_codigo varchar(100),
		@p_id_ayuda int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gui_ayuda]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[ayuda],
			[ayuda_codigo],
			[id_ayuda],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_ayuda,
			@p_ayuda_codigo,
			@p_id_ayuda,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gui_ayuda] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
