CREATE PROCEDURE [aud_gui_ayuda]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gui_ayuda].id as id_tabla,
	[gui_ayuda].id_usuario_modifico as id_usuario_modifico,
	[gui_ayuda].id_usuario_creo as id_usuario_creo,
	[gui_ayuda].fechaModificacion as fechaModificacion,
	[gui_ayuda].fechaCreacion as fechaCreacion,
	[gui_ayuda].active as active,
	[gui_ayuda].[ayuda] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gui_ayuda]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_ayuda].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_ayuda].[id_usuario_creo]
	where ' + @p_filtro)
END
