IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gui_bloqueHome]')) DROP VIEW [dbo].[view_gui_bloqueHome]
GO
CREATE  VIEW [view_gui_bloqueHome] AS
SELECT 	[gui_bloqueHome].[id] AS [id],
		[gui_bloqueHome].[uid] AS [uid],
		[gui_bloqueHome].[eid] AS [eid],
		[gui_bloqueHome].[id_usuario_modifico] AS [id_usuario_modifico],
		[gui_bloqueHome].[id_usuario_creo] AS [id_usuario_creo],
		[gui_bloqueHome].[fechaModificacion] AS [fechaModificacion],
		[gui_bloqueHome].[fechaCreacion] AS [fechaCreacion],
		[gui_bloqueHome].[active] AS [active],
		[gui_bloqueHome].[bloqueHome] AS [bloqueHome],
		[gui_bloqueHome].[bloqueHome_codigo] AS [bloqueHome_codigo],
		[gui_bloqueHome].[nombreControl] AS [nombreControl],
		[gui_bloqueHome].[urlBusqueda] AS [urlBusqueda],
		[gui_bloqueHome].[urlNuevo] AS [urlNuevo],
		[gui_bloqueHome].[orden] AS [orden],
		[gui_bloqueHome].[colorModulo] AS [colorModulo],
		[gui_bloqueHome].[esGenerico] AS [esGenerico],
		[gui_bloqueHome].[filtro] AS [filtro],
		[gui_bloqueHome].[actualizacion] AS [actualizacion],
		[gui_bloqueHome].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gui_bloqueHome]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_bloqueHome].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_bloqueHome].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gui_bloqueHome].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gui_bloqueHome].active=1
GO
