GO
CREATE  VIEW [view_gui_campoTexto] AS
SELECT 	[gui_campoTexto].[id] AS [id],
		[gui_campoTexto].[uid] AS [uid],
		[gui_campoTexto].[eid] AS [eid],
		[gui_campoTexto].[id_usuario_modifico] AS [id_usuario_modifico],
		[gui_campoTexto].[id_usuario_creo] AS [id_usuario_creo],
		[gui_campoTexto].[fechaModificacion] AS [fechaModificacion],
		[gui_campoTexto].[fechaCreacion] AS [fechaCreacion],
		[gui_campoTexto].[active] AS [active],
		[gui_campoTexto].[campoTexto] AS [campoTexto],
		[gui_campoTexto].[campoTexto_codigo] AS [campoTexto_codigo],
		[gui_campoTexto].[esHTML] AS [esHTML],
		[gui_campoTexto].[id_funcionalidad] AS [id_funcionalidad],
[gui_funcionalidad].[funcionalidad] as [gui_funcionalidad_funcionalidad],
[gui_funcionalidad].[funcionalidad_codigo] as [gui_funcionalidad_funcionalidad_codigo],
[gui_funcionalidad].[orden] as [gui_funcionalidad_orden],
[gui_funcionalidad].[id_funcionalidad] as [gui_funcionalidad_id_funcionalidad],
[gui_funcionalidad].[id_tipoFuncionalidad] as [gui_funcionalidad_id_tipoFuncionalidad],
[gui_funcionalidad].[id_aplicacion] as [gui_funcionalidad_id_aplicacion],
[gui_funcionalidad].[id_formulario] as [gui_funcionalidad_id_formulario],
[gui_funcionalidad].[cmm] as [gui_funcionalidad_cmm],
[gui_funcionalidad].[icono] as [gui_funcionalidad_icono],
[gui_funcionalidad].[valorDefecto] as [gui_funcionalidad_valorDefecto],
		[gui_campoTexto].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gui_campoTexto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_campoTexto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_campoTexto].[id_usuario_creo]
	INNER JOIN [gui_funcionalidad] ON [gui_funcionalidad].id=[gui_campoTexto].[id_funcionalidad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gui_campoTexto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gui_campoTexto].active=1
