CREATE  VIEW [view_gui_detalleBloqueHome] AS
SELECT 	[gui_detalleBloqueHome].[id] AS [id],
		[gui_detalleBloqueHome].[uid] AS [uid],
		[gui_detalleBloqueHome].[eid] AS [eid],
		[gui_detalleBloqueHome].[id_usuario_modifico] AS [id_usuario_modifico],
		[gui_detalleBloqueHome].[id_usuario_creo] AS [id_usuario_creo],
		[gui_detalleBloqueHome].[fechaModificacion] AS [fechaModificacion],
		[gui_detalleBloqueHome].[fechaCreacion] AS [fechaCreacion],
		[gui_detalleBloqueHome].[active] AS [active],
		[gui_detalleBloqueHome].[detalleBloqueHome] AS [detalleBloqueHome],
		[gui_detalleBloqueHome].[detalleBloqueHome_codigo] AS [detalleBloqueHome_codigo],
		[gui_detalleBloqueHome].[id_bloqueHome] AS [id_bloqueHome],
[gui_bloqueHome].[bloqueHome] as [gui_bloqueHome_bloqueHome],
[gui_bloqueHome].[bloqueHome_codigo] as [gui_bloqueHome_bloqueHome_codigo],
[gui_bloqueHome].[nombreControl] as [gui_bloqueHome_nombreControl],
[gui_bloqueHome].[urlBusqueda] as [gui_bloqueHome_urlBusqueda],
[gui_bloqueHome].[urlNuevo] as [gui_bloqueHome_urlNuevo],
[gui_bloqueHome].[orden] as [gui_bloqueHome_orden],
[gui_bloqueHome].[colorModulo] as [gui_bloqueHome_colorModulo],
[gui_bloqueHome].[esGenerico] as [gui_bloqueHome_esGenerico],
[gui_bloqueHome].[filtro] as [gui_bloqueHome_filtro],
[gui_bloqueHome].[actualizacion] as [gui_bloqueHome_actualizacion],
[gui_bloqueHome].[cmm] as [gui_bloqueHome_cmm],
		[gui_detalleBloqueHome].[tipoCampo] AS [tipoCampo],
		[gui_detalleBloqueHome].[orden] AS [orden],
		[gui_detalleBloqueHome].[tipoBloqueHome] AS [tipoBloqueHome],
		[gui_detalleBloqueHome].[estrategiaFecha] AS [estrategiaFecha],
		[gui_detalleBloqueHome].[itemsTab] AS [itemsTab],
		[gui_detalleBloqueHome].[posicionTab] AS [posicionTab],
		[gui_detalleBloqueHome].[ordenResultados] AS [ordenResultados],
		[gui_detalleBloqueHome].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gui_detalleBloqueHome]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_detalleBloqueHome].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_detalleBloqueHome].[id_usuario_creo]
	INNER JOIN [gui_bloqueHome] ON [gui_bloqueHome].id=[gui_detalleBloqueHome].[id_bloqueHome]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gui_detalleBloqueHome].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gui_detalleBloqueHome].active=1
