CREATE PROCEDURE [upd_gui_detalleBloqueHome]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_detalleBloqueHome varchar(300) = null,
		@p_detalleBloqueHome_codigo varchar(100) = null,
		@p_id_bloqueHome int = null,
		@p_tipoCampo int = null,
		@p_orden int = null,
		@p_tipoBloqueHome int = null,
		@p_estrategiaFecha int = null,
		@p_itemsTab int = null,
		@p_posicionTab int = null,
		@p_ordenResultados int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [gui_detalleBloqueHome]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[detalleBloqueHome] = isnull(@p_detalleBloqueHome,[detalleBloqueHome]),
			[detalleBloqueHome_codigo] = isnull(@p_detalleBloqueHome_codigo,[detalleBloqueHome_codigo]),
			[id_bloqueHome] = isnull(@p_id_bloqueHome,[id_bloqueHome]),
			[tipoCampo] = isnull(@p_tipoCampo,[tipoCampo]),
			[orden] = isnull(@p_orden,[orden]),
			[tipoBloqueHome] = isnull(@p_tipoBloqueHome,[tipoBloqueHome]),
			[estrategiaFecha] = isnull(@p_estrategiaFecha,[estrategiaFecha]),
			[itemsTab] = isnull(@p_itemsTab,[itemsTab]),
			[posicionTab] = isnull(@p_posicionTab,[posicionTab]),
			[ordenResultados] = isnull(@p_ordenResultados,[ordenResultados]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
