GO
CREATE PROCEDURE [ins_gui_detalleBloqueHome]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_detalleBloqueHome varchar(300),
		@p_detalleBloqueHome_codigo varchar(100),
		@p_id_bloqueHome int,
		@p_tipoCampo int,
		@p_orden int,
		@p_tipoBloqueHome int,
		@p_estrategiaFecha int,
		@p_itemsTab int,
		@p_posicionTab int,
		@p_ordenResultados int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gui_detalleBloqueHome]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[detalleBloqueHome],
			[detalleBloqueHome_codigo],
			[id_bloqueHome],
			[tipoCampo],
			[orden],
			[tipoBloqueHome],
			[estrategiaFecha],
			[itemsTab],
			[posicionTab],
			[ordenResultados],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_detalleBloqueHome,
			@p_detalleBloqueHome_codigo,
			@p_id_bloqueHome,
			@p_tipoCampo,
			@p_orden,
			@p_tipoBloqueHome,
			@p_estrategiaFecha,
			@p_itemsTab,
			@p_posicionTab,
			@p_ordenResultados,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gui_detalleBloqueHome] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
