[gen_formulario].[id_formulario] as [gen_formulario_id_formulario],
[gen_formulario].[condicion] as [gen_formulario_condicion],
[gen_formulario].[valorDefecto] as [gen_formulario_valorDefecto],
		[gui_funcionalidad].[cmm] AS [cmm],
		[gui_funcionalidad].[icono] AS [icono],
		[gui_funcionalidad].[valorDefecto] AS [valorDefecto],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gui_funcionalidad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_funcionalidad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_funcionalidad].[id_usuario_creo]
	INNER JOIN [gui_funcionalidad] AS [gui_funcionalidad_padre] ON [gui_funcionalidad_padre].id=[gui_funcionalidad].[id_funcionalidad]
	INNER JOIN [gui_tipoFuncionalidad] ON [gui_tipoFuncionalidad].id=[gui_funcionalidad].[id_tipoFuncionalidad]
	INNER JOIN [_aplicacion] ON [_aplicacion].id=[gui_funcionalidad].[id_aplicacion]
	INNER JOIN [gen_formulario] ON [gen_formulario].id=[gui_funcionalidad].[id_formulario]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gui_funcionalidad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gui_funcionalidad].active=1
GO
