GO
CREATE PROCEDURE [upd_gui_funcionalidad]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_funcionalidad varchar(300) = null,
		@p_funcionalidad_codigo varchar(100) = null,
		@p_orden int = null,
		@p_id_funcionalidad int = null,
		@p_id_tipoFuncionalidad int = null,
		@p_id_aplicacion int = null,
		@p_id_formulario int = null,
		@p_cmm varchar(300) = null,
		@p_icono varchar(100) = null,
		@p_valorDefecto varchar(300) = null
AS
BEGIN
		UPDATE [gui_funcionalidad]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[funcionalidad] = isnull(@p_funcionalidad,[funcionalidad]),
			[funcionalidad_codigo] = isnull(@p_funcionalidad_codigo,[funcionalidad_codigo]),
			[orden] = isnull(@p_orden,[orden]),
			[id_funcionalidad] = isnull(@p_id_funcionalidad,[id_funcionalidad]),
			[id_tipoFuncionalidad] = isnull(@p_id_tipoFuncionalidad,[id_tipoFuncionalidad]),
			[id_aplicacion] = isnull(@p_id_aplicacion,[id_aplicacion]),
			[id_formulario] = isnull(@p_id_formulario,[id_formulario]),
			[cmm] = isnull(@p_cmm,[cmm]),
			[icono] = isnull(@p_icono,[icono]),
			[valorDefecto] = isnull(@p_valorDefecto,[valorDefecto])
		WHERE (id = @p_id)
END
