IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gui_funcionalidad]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gui_funcionalidad]
GO
CREATE PROCEDURE [ins_gui_funcionalidad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_funcionalidad varchar(300),
		@p_funcionalidad_codigo varchar(100),
		@p_orden int,
		@p_id_funcionalidad int,
		@p_id_tipoFuncionalidad int,
		@p_id_aplicacion int,
		@p_id_formulario int,
		@p_cmm varchar(300),
		@p_icono varchar(100),
		@p_valorDefecto varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gui_funcionalidad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[funcionalidad],
			[funcionalidad_codigo],
			[orden],
			[id_funcionalidad],
			[id_tipoFuncionalidad],
			[id_aplicacion],
			[id_formulario],
			[cmm],
			[icono],
			[valorDefecto])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_funcionalidad,
			@p_funcionalidad_codigo,
			@p_orden,
			@p_id_funcionalidad,
			@p_id_tipoFuncionalidad,
			@p_id_aplicacion,
			@p_id_formulario,
			@p_cmm,
			@p_icono,
			@p_valorDefecto)
		SET @v_id = scope_identity()
UPDATE [gui_funcionalidad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
