CREATE PROCEDURE [aud_gui_funcionalidad]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [gui_funcionalidad].id as id_tabla,
	[gui_funcionalidad].id_usuario_modifico as id_usuario_modifico,
	[gui_funcionalidad].id_usuario_creo as id_usuario_creo,
	[gui_funcionalidad].fechaModificacion as fechaModificacion,
	[gui_funcionalidad].fechaCreacion as fechaCreacion,
	[gui_funcionalidad].active as active,
	[gui_funcionalidad].[funcionalidad] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [gui_funcionalidad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_funcionalidad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_funcionalidad].[id_usuario_creo]
	where ' + @p_filtro)
END
