IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_gui_textoDefecto]')) DROP VIEW [dbo].[view_gui_textoDefecto]
GO
CREATE  VIEW [view_gui_textoDefecto] AS
SELECT 	[gui_textoDefecto].[id] AS [id],
		[gui_textoDefecto].[uid] AS [uid],
		[gui_textoDefecto].[eid] AS [eid],
		[gui_textoDefecto].[id_usuario_modifico] AS [id_usuario_modifico],
		[gui_textoDefecto].[id_usuario_creo] AS [id_usuario_creo],
		[gui_textoDefecto].[fechaModificacion] AS [fechaModificacion],
		[gui_textoDefecto].[fechaCreacion] AS [fechaCreacion],
		[gui_textoDefecto].[active] AS [active],
		[gui_textoDefecto].[textoDefecto] AS [textoDefecto],
		[gui_textoDefecto].[textoDefecto_codigo] AS [textoDefecto_codigo],
		[gui_textoDefecto].[Texto] AS [Texto],
		[gui_textoDefecto].[id_campoTexto] AS [id_campoTexto],
[gui_campoTexto].[campoTexto] as [gui_campoTexto_campoTexto],
[gui_campoTexto].[campoTexto_codigo] as [gui_campoTexto_campoTexto_codigo],
[gui_campoTexto].[esHTML] as [gui_campoTexto_esHTML],
[gui_campoTexto].[id_funcionalidad] as [gui_campoTexto_id_funcionalidad],
[gui_campoTexto].[cmm] as [gui_campoTexto_cmm],
		[gui_textoDefecto].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [gui_textoDefecto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[gui_textoDefecto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[gui_textoDefecto].[id_usuario_creo]
	INNER JOIN [gui_campoTexto] ON [gui_campoTexto].id=[gui_textoDefecto].[id_campoTexto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [gui_textoDefecto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [gui_textoDefecto].active=1
