IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_gui_textoDefecto]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_gui_textoDefecto]
GO
CREATE PROCEDURE [ins_gui_textoDefecto]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_textoDefecto varchar(300),
		@p_textoDefecto_codigo varchar(100),
		@p_Texto varchar(8000),
		@p_id_campoTexto int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gui_textoDefecto]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[textoDefecto],
			[textoDefecto_codigo],
			[Texto],
			[id_campoTexto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_textoDefecto,
			@p_textoDefecto_codigo,
			@p_Texto,
			@p_id_campoTexto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gui_textoDefecto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
