IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_lic_catalogo_parametro]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_lic_catalogo_parametro]
GO
CREATE PROCEDURE [ins_lic_catalogo_parametro]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_catalogo_parametro varchar(300),
		@p_id_catalogo int,
		@p_id_parametro int,
		@p_valorXdefecto varchar(1),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [lic_catalogo_parametro]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[catalogo_parametro],
			[id_catalogo],
			[id_parametro],
			[valorXdefecto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_catalogo_parametro,
			@p_id_catalogo,
			@p_id_parametro,
			@p_valorXdefecto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [lic_catalogo_parametro] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
