AS
BEGIN
exec(	'SELECT [lic_catalogo_parametro].id as id_tabla,
	[lic_catalogo_parametro].id_usuario_modifico as id_usuario_modifico,
	[lic_catalogo_parametro].id_usuario_creo as id_usuario_creo,
	[lic_catalogo_parametro].fechaModificacion as fechaModificacion,
	[lic_catalogo_parametro].fechaCreacion as fechaCreacion,
	[lic_catalogo_parametro].active as active,
	[lic_catalogo_parametro].[catalogo_parametro] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [lic_catalogo_parametro]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[lic_catalogo_parametro].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[lic_catalogo_parametro].[id_usuario_creo]
	where ' + @p_filtro)
END
