IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_lic_licencia]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_lic_licencia]
GO
CREATE PROCEDURE [upd_lic_licencia]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_licencia varchar(300) = null,
		@p_licencia_codigo varchar(100) = null,
		@p_serial varchar(500) = null,
		@p_clave varchar(100) = null,
		@p_fechaInicio_ff smalldatetime = null,
		@p_fechaFin_ff smalldatetime = null,
		@p_id_tercero int = null,
		@p_id_catalogo int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [lic_licencia]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[licencia] = isnull(@p_licencia,[licencia]),
			[licencia_codigo] = isnull(@p_licencia_codigo,[licencia_codigo]),
			[serial] = isnull(@p_serial,[serial]),
			[clave] = isnull(@p_clave,[clave]),
			[fechaInicio_ff] = isnull(@p_fechaInicio_ff,[fechaInicio_ff]),
			[fechaFin_ff] = isnull(@p_fechaFin_ff,[fechaFin_ff]),
			[id_tercero] = isnull(@p_id_tercero,[id_tercero]),
			[id_catalogo] = isnull(@p_id_catalogo,[id_catalogo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
