IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_lic_licencia]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_lic_licencia]
GO
CREATE PROCEDURE [ins_lic_licencia]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_licencia varchar(300),
		@p_licencia_codigo varchar(100),
		@p_serial varchar(500),
		@p_clave varchar(100),
		@p_fechaInicio_ff smalldatetime,
		@p_fechaFin_ff smalldatetime,
		@p_id_tercero int,
		@p_id_catalogo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [lic_licencia]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[licencia],
			[licencia_codigo],
			[serial],
			[clave],
			[fechaInicio_ff],
			[fechaFin_ff],
			[id_tercero],
			[id_catalogo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_licencia,
			@p_licencia_codigo,
			@p_serial,
			@p_clave,
			@p_fechaInicio_ff,
			@p_fechaFin_ff,
			@p_id_tercero,
			@p_id_catalogo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [lic_licencia] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
