GO
CREATE  VIEW [view_lic_licencia_parametro] AS
SELECT 	[lic_licencia_parametro].[id] AS [id],
		[lic_licencia_parametro].[uid] AS [uid],
		[lic_licencia_parametro].[eid] AS [eid],
		[lic_licencia_parametro].[id_usuario_modifico] AS [id_usuario_modifico],
		[lic_licencia_parametro].[id_usuario_creo] AS [id_usuario_creo],
		[lic_licencia_parametro].[fechaModificacion] AS [fechaModificacion],
		[lic_licencia_parametro].[fechaCreacion] AS [fechaCreacion],
		[lic_licencia_parametro].[active] AS [active],
		[lic_licencia_parametro].[licencia_parametro] AS [licencia_parametro],
		[lic_licencia_parametro].[id_licencia] AS [id_licencia],
[lic_licencia].[licencia] as [lic_licencia_licencia],
[lic_licencia].[licencia_codigo] as [lic_licencia_licencia_codigo],
[lic_licencia].[serial] as [lic_licencia_serial],
[lic_licencia].[clave] as [lic_licencia_clave],
[lic_licencia].[fechaInicio_ff] as [lic_licencia_fechaInicio_ff],
[lic_licencia].[fechaFin_ff] as [lic_licencia_fechaFin_ff],
[lic_licencia].[id_tercero] as [lic_licencia_id_tercero],
[lic_licencia].[id_catalogo] as [lic_licencia_id_catalogo],
[lic_licencia].[cmm] as [lic_licencia_cmm],
		[lic_licencia_parametro].[id_parametro] AS [id_parametro],
[lic_parametro].[parametro] as [lic_parametro_parametro],
[lic_parametro].[parametro_codigo] as [lic_parametro_parametro_codigo],
[lic_parametro].[descripcion] as [lic_parametro_descripcion],
[lic_parametro].[cmm] as [lic_parametro_cmm],
		[lic_licencia_parametro].[valor] AS [valor],
		[lic_licencia_parametro].[esParteSerial] AS [esParteSerial],
		[lic_licencia_parametro].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [lic_licencia_parametro]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[lic_licencia_parametro].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[lic_licencia_parametro].[id_usuario_creo]
	INNER JOIN [lic_licencia] ON [lic_licencia].id=[lic_licencia_parametro].[id_licencia]
	INNER JOIN [lic_parametro] ON [lic_parametro].id=[lic_licencia_parametro].[id_parametro]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [lic_licencia_parametro].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
