CREATE PROCEDURE [aud_lic_licencia_parametro]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [lic_licencia_parametro].id as id_tabla,
	[lic_licencia_parametro].id_usuario_modifico as id_usuario_modifico,
	[lic_licencia_parametro].id_usuario_creo as id_usuario_creo,
	[lic_licencia_parametro].fechaModificacion as fechaModificacion,
	[lic_licencia_parametro].fechaCreacion as fechaCreacion,
	[lic_licencia_parametro].active as active,
	[lic_licencia_parametro].[licencia_parametro] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [lic_licencia_parametro]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[lic_licencia_parametro].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[lic_licencia_parametro].[id_usuario_creo]
	where ' + @p_filtro)
END
