IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_lic_parametro]')) DROP VIEW [dbo].[view_lic_parametro]
GO
CREATE  VIEW [view_lic_parametro] AS
SELECT 	[lic_parametro].[id] AS [id],
		[lic_parametro].[uid] AS [uid],
		[lic_parametro].[eid] AS [eid],
		[lic_parametro].[id_usuario_modifico] AS [id_usuario_modifico],
		[lic_parametro].[id_usuario_creo] AS [id_usuario_creo],
		[lic_parametro].[fechaModificacion] AS [fechaModificacion],
		[lic_parametro].[fechaCreacion] AS [fechaCreacion],
		[lic_parametro].[active] AS [active],
		[lic_parametro].[parametro] AS [parametro],
		[lic_parametro].[parametro_codigo] AS [parametro_codigo],
		[lic_parametro].[descripcion] AS [descripcion],
		[lic_parametro].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [lic_parametro]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[lic_parametro].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[lic_parametro].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [lic_parametro].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [lic_parametro].active=1
GO
