IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_ort_canalAtencion]')) DROP VIEW [dbo].[view_ort_canalAtencion]
GO
CREATE  VIEW [view_ort_canalAtencion] AS
SELECT 	[ort_canalAtencion].[id] AS [id],
		[ort_canalAtencion].[uid] AS [uid],
		[ort_canalAtencion].[eid] AS [eid],
		[ort_canalAtencion].[id_usuario_modifico] AS [id_usuario_modifico],
		[ort_canalAtencion].[id_usuario_creo] AS [id_usuario_creo],
		[ort_canalAtencion].[fechaModificacion] AS [fechaModificacion],
		[ort_canalAtencion].[fechaCreacion] AS [fechaCreacion],
		[ort_canalAtencion].[active] AS [active],
		[ort_canalAtencion].[canalAtencion] AS [canalAtencion],
		[ort_canalAtencion].[canalAtencion_codigo] AS [canalAtencion_codigo],
		[ort_canalAtencion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ort_canalAtencion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_canalAtencion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_canalAtencion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ort_canalAtencion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ort_canalAtencion].active=1
