IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_ort_departamentoSolicitud]')) DROP VIEW [dbo].[view_ort_departamentoSolicitud]
GO
CREATE  VIEW [view_ort_departamentoSolicitud] AS
SELECT 	[ort_departamentoSolicitud].[id] AS [id],
		[ort_departamentoSolicitud].[uid] AS [uid],
		[ort_departamentoSolicitud].[eid] AS [eid],
		[ort_departamentoSolicitud].[id_usuario_modifico] AS [id_usuario_modifico],
		[ort_departamentoSolicitud].[id_usuario_creo] AS [id_usuario_creo],
		[ort_departamentoSolicitud].[fechaModificacion] AS [fechaModificacion],
		[ort_departamentoSolicitud].[fechaCreacion] AS [fechaCreacion],
		[ort_departamentoSolicitud].[active] AS [active],
		[ort_departamentoSolicitud].[departamentoSolicitud] AS [departamentoSolicitud],
		[ort_departamentoSolicitud].[departamentoSolicitud_codigo] AS [departamentoSolicitud_codigo],
		[ort_departamentoSolicitud].[recibeSolicitudes] AS [recibeSolicitudes],
		[ort_departamentoSolicitud].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ort_departamentoSolicitud]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_departamentoSolicitud].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_departamentoSolicitud].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ort_departamentoSolicitud].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ort_departamentoSolicitud].active=1
GO
