IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_ort_departamentoSolicitud]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_ort_departamentoSolicitud]
GO
CREATE PROCEDURE [upd_ort_departamentoSolicitud]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_departamentoSolicitud varchar(300) = null,
		@p_departamentoSolicitud_codigo varchar(100) = null,
		@p_recibeSolicitudes bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [ort_departamentoSolicitud]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[departamentoSolicitud] = isnull(@p_departamentoSolicitud,[departamentoSolicitud]),
			[departamentoSolicitud_codigo] = isnull(@p_departamentoSolicitud_codigo,[departamentoSolicitud_codigo]),
			[recibeSolicitudes] = isnull(@p_recibeSolicitudes,[recibeSolicitudes]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
