IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ort_departamentoSolicitud]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ort_departamentoSolicitud]
GO
CREATE PROCEDURE [ins_ort_departamentoSolicitud]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_departamentoSolicitud varchar(300),
		@p_departamentoSolicitud_codigo varchar(100),
		@p_recibeSolicitudes bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_departamentoSolicitud]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[departamentoSolicitud],
			[departamentoSolicitud_codigo],
			[recibeSolicitudes],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_departamentoSolicitud,
			@p_departamentoSolicitud_codigo,
			@p_recibeSolicitudes,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ort_departamentoSolicitud] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
