		[ort_motivoCancelacion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ort_motivoCancelacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_motivoCancelacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_motivoCancelacion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ort_motivoCancelacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ort_motivoCancelacion].active=1
