GO
CREATE PROCEDURE [upd_ort_motivoCancelacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_motivoCancelacion varchar(300) = null,
		@p_motivoCancelacion_codigo varchar(100) = null,
		@p_responsableServicio bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [ort_motivoCancelacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[motivoCancelacion] = isnull(@p_motivoCancelacion,[motivoCancelacion]),
			[motivoCancelacion_codigo] = isnull(@p_motivoCancelacion_codigo,[motivoCancelacion_codigo]),
			[responsableServicio] = isnull(@p_responsableServicio,[responsableServicio]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
