[cat_catalogo.actividad].[dias_garantia] as [cat_catalogo.actividad_dias_garantia],
[cat_catalogo.actividad].[cmm] as [cat_catalogo.actividad_cmm],
		[cat_catalogo_actividad].[catalogo_codigo] AS [cat_catalogo_actividad_catalogo_codigo],
		[cat_catalogo_actividad].[codigoInventario] AS [cat_catalogo_actividad_codigoInventario],
		[cat_catalogo_actividad].[precioVenta] AS [cat_catalogo_actividad_precioVenta],
