		[cat_catalogo_actividad].[id_familia] AS [cat_catalogo_actividad_id_familia],
		[cat_catalogo_actividad].[id_subtipoCatalogo] AS [cat_catalogo_actividad_id_subtipoCatalogo],
		[cat_catalogo_actividad].[id_unidad] AS [cat_catalogo_actividad_id_unidad],
		[cat_catalogo_actividad].[id_impuesto] AS [cat_catalogo_actividad_id_impuesto],
		[cat_catalogo_actividad].[descripcion] AS [cat_catalogo_actividad_descripcion],
		[cat_catalogo_actividad].[bloquearCostear] AS [cat_catalogo_actividad_bloquearCostear],
		[cat_catalogo_actividad].[cmm] AS [cat_catalogo_actividad_cmm],
		[ort_programacion].[costo] AS [costo],
		[ort_programacion].[id_soporteItemDocumento] AS [id_soporteItemDocumento],
[doc_soporteItemDocumento].[soporteItemDocumento] as [doc_soporteItemDocumento_soporteItemDocumento],
[doc_soporteItemDocumento].[soporteItemDocumento_codigo] as [doc_soporteItemDocumento_soporteItemDocumento_codigo],
[doc_soporteItemDocumento].[duracionPlaneada] as [doc_soporteItemDocumento_duracionPlaneada],
[doc_soporteItemDocumento].[Valor] as [doc_soporteItemDocumento_Valor],
[doc_soporteItemDocumento].[Costo] as [doc_soporteItemDocumento_Costo],
[doc_soporteItemDocumento].[id_itemDocumento] as [doc_soporteItemDocumento_id_itemDocumento],
[doc_soporteItemDocumento].[id_usuario] as [doc_soporteItemDocumento_id_usuario],
[doc_soporteItemDocumento].[duracionEjecutada] as [doc_soporteItemDocumento_duracionEjecutada],
[doc_soporteItemDocumento].[horasOrdinales] as [doc_soporteItemDocumento_horasOrdinales],
[doc_soporteItemDocumento].[horasFestivas] as [doc_soporteItemDocumento_horasFestivas],
[doc_soporteItemDocumento].[horasNocturnas] as [doc_soporteItemDocumento_horasNocturnas],
[doc_soporteItemDocumento].[periodo] as [doc_soporteItemDocumento_periodo],
[doc_soporteItemDocumento].[cmm] as [doc_soporteItemDocumento_cmm],
		[ort_programacion].[cmm] AS [cmm],
		[ort_programacion].[id_programacion_grupo] AS [id_programacion_grupo],
[ort_programacion_grupo].[programacion] as [ort_programacion_grupo_programacion],
[ort_programacion_grupo].[programacion_codigo] as [ort_programacion_grupo_programacion_codigo],
[ort_programacion_grupo].[desde_fh] as [ort_programacion_grupo_desde_fh],
[ort_programacion_grupo].[duracion] as [ort_programacion_grupo_duracion],
[ort_programacion_grupo].[comentario] as [ort_programacion_grupo_comentario],
[ort_programacion_grupo].[id_usuario] as [ort_programacion_grupo_id_usuario],
[ort_programacion_grupo].[id_tipoProgramacion] as [ort_programacion_grupo_id_tipoProgramacion],
[ort_programacion_grupo].[id_motivoCancelacion] as [ort_programacion_grupo_id_motivoCancelacion],
[ort_programacion_grupo].[id_programacion] as [ort_programacion_grupo_id_programacion],
[ort_programacion_grupo].[id_reporteTecnico] as [ort_programacion_grupo_id_reporteTecnico],
[ort_programacion_grupo].[id_catalogo.actividad] as [ort_programacion_grupo_id_catalogo.actividad],
[ort_programacion_grupo].[costo] as [ort_programacion_grupo_costo],
[ort_programacion_grupo].[id_soporteItemDocumento] as [ort_programacion_grupo_id_soporteItemDocumento],
[ort_programacion_grupo].[cmm] as [ort_programacion_grupo_cmm],
[ort_programacion_grupo].[id_programacion_grupo] as [ort_programacion_grupo_id_programacion_grupo],
[ort_programacion_grupo].[id_tabla] as [ort_programacion_grupo_id_tabla],
[ort_programacion_grupo].[idObjeto] as [ort_programacion_grupo_idObjeto],
[ort_programacion_grupo].[diasLaborables] as [ort_programacion_grupo_diasLaborables],
[ort_programacion_grupo].[horaInicioJornada] as [ort_programacion_grupo_horaInicioJornada],
[ort_programacion_grupo].[horaFinJornada] as [ort_programacion_grupo_horaFinJornada],
[ort_programacion_grupo].[diaHabil] as [ort_programacion_grupo_diaHabil],
		[ort_programacion].[id_tabla] AS [id_tabla],
		[_tablas].[tabla] AS [_tablas_tabla],
		[_tablas].[id_tabla_padre] AS [_tablas_id_tabla_padre],
		[ort_programacion].[idObjeto] AS [idObjeto],
		[ort_programacion].[diasLaborables] AS [diasLaborables],
		[ort_programacion].[horaInicioJornada] AS [horaInicioJornada],
		[ort_programacion].[horaFinJornada] AS [horaFinJornada],
		[ort_programacion].[diaHabil] AS [diaHabil],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ort_programacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_programacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_programacion].[id_usuario_creo]
	INNER JOIN [seg_usuario] ON [seg_usuario].id=[ort_programacion].[id_usuario]
	INNER JOIN [ort_tipoProgramacion] ON [ort_tipoProgramacion].id=[ort_programacion].[id_tipoProgramacion]
	INNER JOIN [ort_motivoCancelacion] ON [ort_motivoCancelacion].id=[ort_programacion].[id_motivoCancelacion]
	INNER JOIN [ort_programacion] AS [ort_programacion_padre] ON [ort_programacion_padre].id=[ort_programacion].[id_programacion]
	INNER JOIN [ort_reporteTecnico] ON [ort_reporteTecnico].id=[ort_programacion].[id_reporteTecnico]
	INNER JOIN [cat_catalogo.actividad] ON [cat_catalogo.actividad].id=[ort_programacion].[id_catalogo.actividad]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_actividad] ON [cat_catalogo.actividad].id = [cat_catalogo_actividad].id
	INNER JOIN [doc_soporteItemDocumento] ON [doc_soporteItemDocumento].id=[ort_programacion].[id_soporteItemDocumento]
	INNER JOIN [ort_programacion] AS [ort_programacion_grupo] ON [ort_programacion_grupo].id=[ort_programacion].[id_programacion_grupo]
	INNER JOIN [_tablas] ON [_tablas].id=[ort_programacion].[id_tabla]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ort_programacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ort_programacion].active=1
