IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_ort_programacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_ort_programacion]
GO
CREATE PROCEDURE [upd_ort_programacion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_programacion varchar(300) = null,
		@p_programacion_codigo varchar(100) = null,
		@p_desde_fh smalldatetime = null,
		@p_duracion int = null,
		@p_comentario varchar(300) = null,
		@p_id_usuario int = null,
		@p_id_tipoProgramacion int = null,
		@p_id_motivoCancelacion int = null,
		@p_id_programacion int = null,
		@p_id_reporteTecnico int = null,
		@p_id_catalogo_actividad int = null,
		@p_costo float = null,
		@p_id_soporteItemDocumento int = null,
		@p_cmm varchar(300) = null,
		@p_id_programacion_grupo int = null,
		@p_id_tabla int = null,
		@p_idObjeto int = null,
		@p_diasLaborables int = null,
		@p_horaInicioJornada time = null,
		@p_horaFinJornada time = null,
		@p_diaHabil int = null
AS
BEGIN
		UPDATE [ort_programacion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[programacion] = isnull(@p_programacion,[programacion]),
			[programacion_codigo] = isnull(@p_programacion_codigo,[programacion_codigo]),
			[desde_fh] = isnull(@p_desde_fh,[desde_fh]),
			[duracion] = isnull(@p_duracion,[duracion]),
			[comentario] = isnull(@p_comentario,[comentario]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[id_tipoProgramacion] = isnull(@p_id_tipoProgramacion,[id_tipoProgramacion]),
			[id_motivoCancelacion] = isnull(@p_id_motivoCancelacion,[id_motivoCancelacion]),
			[id_programacion] = isnull(@p_id_programacion,[id_programacion]),
			[id_reporteTecnico] = isnull(@p_id_reporteTecnico,[id_reporteTecnico]),
			[id_catalogo.actividad] = isnull(@p_id_catalogo_actividad,[id_catalogo.actividad]),
			[costo] = isnull(@p_costo,[costo]),
			[id_soporteItemDocumento] = isnull(@p_id_soporteItemDocumento,[id_soporteItemDocumento]),
			[cmm] = isnull(@p_cmm,[cmm]),
			[id_programacion_grupo] = isnull(@p_id_programacion_grupo,[id_programacion_grupo]),
			[id_tabla] = isnull(@p_id_tabla,[id_tabla]),
			[idObjeto] = isnull(@p_idObjeto,[idObjeto]),
			[diasLaborables] = isnull(@p_diasLaborables,[diasLaborables]),
			[horaInicioJornada] = isnull(@p_horaInicioJornada,[horaInicioJornada]),
			[horaFinJornada] = isnull(@p_horaFinJornada,[horaFinJornada]),
			[diaHabil] = isnull(@p_diaHabil,[diaHabil])
		WHERE (id = @p_id)
END
GO
