IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ort_programacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ort_programacion]
GO
CREATE PROCEDURE [ins_ort_programacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_programacion varchar(300),
		@p_programacion_codigo varchar(100),
		@p_desde_fh smalldatetime,
		@p_duracion int,
		@p_comentario varchar(300),
		@p_id_usuario int,
		@p_id_tipoProgramacion int,
		@p_id_motivoCancelacion int,
		@p_id_programacion int,
		@p_id_reporteTecnico int,
		@p_id_catalogo_actividad int,
		@p_costo float,
		@p_id_soporteItemDocumento int,
		@p_cmm varchar(300),
		@p_id_programacion_grupo int,
		@p_id_tabla int,
		@p_idObjeto int,
		@p_diasLaborables int,
		@p_horaInicioJornada time,
		@p_horaFinJornada time,
		@p_diaHabil int
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_programacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[programacion],
			[programacion_codigo],
			[desde_fh],
			[duracion],
			[comentario],
			[id_usuario],
			[id_tipoProgramacion],
			[id_motivoCancelacion],
			[id_programacion],
			[id_reporteTecnico],
			[id_catalogo.actividad],
			[costo],
			[id_soporteItemDocumento],
			[cmm],
			[id_programacion_grupo],
			[id_tabla],
			[idObjeto],
			[diasLaborables],
			[horaInicioJornada],
			[horaFinJornada],
			[diaHabil])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_programacion,
			@p_programacion_codigo,
			@p_desde_fh,
			@p_duracion,
			@p_comentario,
			@p_id_usuario,
			@p_id_tipoProgramacion,
			@p_id_motivoCancelacion,
			@p_id_programacion,
			@p_id_reporteTecnico,
			@p_id_catalogo_actividad,
			@p_costo,
			@p_id_soporteItemDocumento,
			@p_cmm,
			@p_id_programacion_grupo,
			@p_id_tabla,
			@p_idObjeto,
			@p_diasLaborables,
			@p_horaInicioJornada,
			@p_horaFinJornada,
			@p_diaHabil)
		SET @v_id = scope_identity()
UPDATE [ort_programacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
