GO
CREATE PROCEDURE [aud_ort_programacion]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [ort_programacion].id as id_tabla,
	[ort_programacion].id_usuario_modifico as id_usuario_modifico,
	[ort_programacion].id_usuario_creo as id_usuario_creo,
	[ort_programacion].fechaModificacion as fechaModificacion,
	[ort_programacion].fechaCreacion as fechaCreacion,
	[ort_programacion].active as active,
	[ort_programacion].[programacion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [ort_programacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_programacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_programacion].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
