CREATE PROCEDURE [upd_ort_reporteTecnico]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_reporteTecnico varchar(300) = null,
		@p_reporteTecnico_codigo varchar(100) = null,
		@p_numero varchar(100) = null,
		@p_trabajos varchar(4000) = null,
		@p_recomendaciones varchar(4000) = null,
		@p_compromisos varchar(4000) = null,
		@p_id_canalAtencion int = null,
		@p_diagnostico varchar(8000) = null,
		@p_id_documento_gasto int = null,
		@p_cmm varchar(300) = null,
		@p_desde_fh smalldatetime = null,
		@p_duracion int = null,
		@p_id_reporteTecnico int = null
AS
BEGIN
		UPDATE [ort_reporteTecnico]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[reporteTecnico] = isnull(@p_reporteTecnico,[reporteTecnico]),
			[reporteTecnico_codigo] = isnull(@p_reporteTecnico_codigo,[reporteTecnico_codigo]),
			[numero] = isnull(@p_numero,[numero]),
			[trabajos] = isnull(@p_trabajos,[trabajos]),
			[recomendaciones] = isnull(@p_recomendaciones,[recomendaciones]),
			[compromisos] = isnull(@p_compromisos,[compromisos]),
			[id_canalAtencion] = isnull(@p_id_canalAtencion,[id_canalAtencion]),
			[diagnostico] = isnull(@p_diagnostico,[diagnostico]),
			[id_documento.gasto] = isnull(@p_id_documento_gasto,[id_documento.gasto]),
			[cmm] = isnull(@p_cmm,[cmm]),
			[desde_fh] = isnull(@p_desde_fh,[desde_fh]),
			[duracion] = isnull(@p_duracion,[duracion]),
			[id_reporteTecnico] = isnull(@p_id_reporteTecnico,[id_reporteTecnico])
		WHERE (id = @p_id)
END
