GO
CREATE PROCEDURE [ins_ort_reporteTecnico]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_reporteTecnico varchar(300),
		@p_reporteTecnico_codigo varchar(100),
		@p_numero varchar(100),
		@p_trabajos varchar(4000),
		@p_recomendaciones varchar(4000),
		@p_compromisos varchar(4000),
		@p_id_canalAtencion int,
		@p_diagnostico varchar(8000),
		@p_id_documento_gasto int,
		@p_cmm varchar(300),
		@p_desde_fh smalldatetime,
		@p_duracion int,
		@p_id_reporteTecnico int
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_reporteTecnico]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[reporteTecnico],
			[reporteTecnico_codigo],
			[numero],
			[trabajos],
			[recomendaciones],
			[compromisos],
			[id_canalAtencion],
			[diagnostico],
			[id_documento.gasto],
			[cmm],
			[desde_fh],
			[duracion],
			[id_reporteTecnico])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_reporteTecnico,
			@p_reporteTecnico_codigo,
			@p_numero,
			@p_trabajos,
			@p_recomendaciones,
			@p_compromisos,
			@p_id_canalAtencion,
			@p_diagnostico,
			@p_id_documento_gasto,
			@p_cmm,
			@p_desde_fh,
			@p_duracion,
			@p_id_reporteTecnico)
		SET @v_id = scope_identity()
UPDATE [ort_reporteTecnico] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
