CREATE PROCEDURE [aud_ort_reporteTecnico]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [ort_reporteTecnico].id as id_tabla,
	[ort_reporteTecnico].id_usuario_modifico as id_usuario_modifico,
	[ort_reporteTecnico].id_usuario_creo as id_usuario_creo,
	[ort_reporteTecnico].fechaModificacion as fechaModificacion,
	[ort_reporteTecnico].fechaCreacion as fechaCreacion,
	[ort_reporteTecnico].active as active,
	[ort_reporteTecnico].[reporteTecnico] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [ort_reporteTecnico]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_reporteTecnico].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_reporteTecnico].[id_usuario_creo]
	where ' + @p_filtro)
END
