SELECT 	[ort_reporteTecnico_falla].[id] AS [id],
		[ort_reporteTecnico_falla].[uid] AS [uid],
		[ort_reporteTecnico_falla].[eid] AS [eid],
		[ort_reporteTecnico_falla].[id_usuario_modifico] AS [id_usuario_modifico],
		[ort_reporteTecnico_falla].[id_usuario_creo] AS [id_usuario_creo],
		[ort_reporteTecnico_falla].[fechaModificacion] AS [fechaModificacion],
		[ort_reporteTecnico_falla].[fechaCreacion] AS [fechaCreacion],
		[ort_reporteTecnico_falla].[active] AS [active],
		[ort_reporteTecnico_falla].[reporteTecnico_falla] AS [reporteTecnico_falla],
		[ort_reporteTecnico_falla].[id_reporteTecnico] AS [id_reporteTecnico],
[ort_reporteTecnico].[reporteTecnico] as [ort_reporteTecnico_reporteTecnico],
[ort_reporteTecnico].[reporteTecnico_codigo] as [ort_reporteTecnico_reporteTecnico_codigo],
[ort_reporteTecnico].[numero] as [ort_reporteTecnico_numero],
[ort_reporteTecnico].[trabajos] as [ort_reporteTecnico_trabajos],
[ort_reporteTecnico].[recomendaciones] as [ort_reporteTecnico_recomendaciones],
[ort_reporteTecnico].[compromisos] as [ort_reporteTecnico_compromisos],
[ort_reporteTecnico].[id_canalAtencion] as [ort_reporteTecnico_id_canalAtencion],
[ort_reporteTecnico].[diagnostico] as [ort_reporteTecnico_diagnostico],
[ort_reporteTecnico].[id_documento.gasto] as [ort_reporteTecnico_id_documento.gasto],
[ort_reporteTecnico].[cmm] as [ort_reporteTecnico_cmm],
[ort_reporteTecnico].[desde_fh] as [ort_reporteTecnico_desde_fh],
[ort_reporteTecnico].[duracion] as [ort_reporteTecnico_duracion],
[ort_reporteTecnico].[id_reporteTecnico] as [ort_reporteTecnico_id_reporteTecnico],
		[ort_reporteTecnico_falla].[id_falla] AS [id_falla],
[equ_falla].[falla] as [equ_falla_falla],
[equ_falla].[falla_codigo] as [equ_falla_falla_codigo],
[equ_falla].[procedimiento] as [equ_falla_procedimiento],
[equ_falla].[id_tipoFalla] as [equ_falla_id_tipoFalla],
[equ_falla].[id_falla] as [equ_falla_id_falla],
[equ_falla].[cmm] as [equ_falla_cmm],
		[ort_reporteTecnico_falla].[id_falla_causa] AS [id_falla_causa],
[equ_falla_causa].[falla] as [equ_falla_causa_falla],
[equ_falla_causa].[falla_codigo] as [equ_falla_causa_falla_codigo],
[equ_falla_causa].[procedimiento] as [equ_falla_causa_procedimiento],
[equ_falla_causa].[id_tipoFalla] as [equ_falla_causa_id_tipoFalla],
[equ_falla_causa].[id_falla] as [equ_falla_causa_id_falla],
[equ_falla_causa].[cmm] as [equ_falla_causa_cmm],
		[ort_reporteTecnico_falla].[id_falla_efecto] AS [id_falla_efecto],
[equ_falla_efecto].[falla] as [equ_falla_efecto_falla],
[equ_falla_efecto].[falla_codigo] as [equ_falla_efecto_falla_codigo],
[equ_falla_efecto].[procedimiento] as [equ_falla_efecto_procedimiento],
[equ_falla_efecto].[id_tipoFalla] as [equ_falla_efecto_id_tipoFalla],
[equ_falla_efecto].[id_falla] as [equ_falla_efecto_id_falla],
[equ_falla_efecto].[cmm] as [equ_falla_efecto_cmm],
		[ort_reporteTecnico_falla].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ort_reporteTecnico_falla]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_reporteTecnico_falla].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_reporteTecnico_falla].[id_usuario_creo]
	INNER JOIN [ort_reporteTecnico] ON [ort_reporteTecnico].id=[ort_reporteTecnico_falla].[id_reporteTecnico]
	INNER JOIN [equ_falla] ON [equ_falla].id=[ort_reporteTecnico_falla].[id_falla]
	INNER JOIN [equ_falla] AS [equ_falla_causa] ON [equ_falla_causa].id=[ort_reporteTecnico_falla].[id_falla_causa]
	INNER JOIN [equ_falla] AS [equ_falla_efecto] ON [equ_falla_efecto].id=[ort_reporteTecnico_falla].[id_falla_efecto]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ort_reporteTecnico_falla].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
