IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ort_reporteTecnico_falla]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ort_reporteTecnico_falla]
GO
CREATE PROCEDURE [ins_ort_reporteTecnico_falla]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_reporteTecnico_falla varchar(300),
		@p_id_reporteTecnico int,
		@p_id_falla int,
		@p_id_falla_causa int,
		@p_id_falla_efecto int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_reporteTecnico_falla]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[reporteTecnico_falla],
			[id_reporteTecnico],
			[id_falla],
			[id_falla_causa],
			[id_falla_efecto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_reporteTecnico_falla,
			@p_id_reporteTecnico,
			@p_id_falla,
			@p_id_falla_causa,
			@p_id_falla_efecto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ort_reporteTecnico_falla] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
