CREATE PROCEDURE [reg_ort_reporteTecnico_falla_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[reporteTecnico_falla] AS [reporteTecnico_falla],
		[id_reporteTecnico] AS [id_reporteTecnico],
		[id_falla] AS [id_falla],
		[id_falla_causa] AS [id_falla_causa],
		[id_falla_efecto] AS [id_falla_efecto],
		[cmm] AS [cmm]
	FROM [ort_reporteTecnico_falla]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
