IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ort_reporteTecnico_ot]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ort_reporteTecnico_ot]
GO
CREATE PROCEDURE [ins_ort_reporteTecnico_ot]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_id_reporteTecnico int,
		@p_id_documento_ot int,
		@p_observaciones varchar(2000),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_reporteTecnico_ot]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[id_reporteTecnico],
			[id_documento.ot],
			[observaciones],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_id_reporteTecnico,
			@p_id_documento_ot,
			@p_observaciones,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ort_reporteTecnico_ot] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
