		[ort_reporteTecnicoAtributo].[reporteTecnicoAtributo] AS [reporteTecnicoAtributo],
		[ort_reporteTecnicoAtributo].[reporteTecnicoAtributo_codigo] AS [reporteTecnicoAtributo_codigo],
		[ort_reporteTecnicoAtributo].[id_reporteTecnico] AS [id_reporteTecnico],
[ort_reporteTecnico].[reporteTecnico] as [ort_reporteTecnico_reporteTecnico],
[ort_reporteTecnico].[reporteTecnico_codigo] as [ort_reporteTecnico_reporteTecnico_codigo],
[ort_reporteTecnico].[numero] as [ort_reporteTecnico_numero],
[ort_reporteTecnico].[trabajos] as [ort_reporteTecnico_trabajos],
[ort_reporteTecnico].[recomendaciones] as [ort_reporteTecnico_recomendaciones],
[ort_reporteTecnico].[compromisos] as [ort_reporteTecnico_compromisos],
[ort_reporteTecnico].[id_canalAtencion] as [ort_reporteTecnico_id_canalAtencion],
[ort_reporteTecnico].[diagnostico] as [ort_reporteTecnico_diagnostico],
[ort_reporteTecnico].[id_documento.gasto] as [ort_reporteTecnico_id_documento.gasto],
[ort_reporteTecnico].[cmm] as [ort_reporteTecnico_cmm],
[ort_reporteTecnico].[desde_fh] as [ort_reporteTecnico_desde_fh],
[ort_reporteTecnico].[duracion] as [ort_reporteTecnico_duracion],
[ort_reporteTecnico].[id_reporteTecnico] as [ort_reporteTecnico_id_reporteTecnico],
		[ort_reporteTecnicoAtributo].[id_atributo] AS [id_atributo],
[cat_atributo].[atributo] as [cat_atributo_atributo],
[cat_atributo].[atributo_codigo] as [cat_atributo_atributo_codigo],
[cat_atributo].[id_unidad] as [cat_atributo_id_unidad],
[cat_atributo].[cmm] as [cat_atributo_cmm],
		[ort_reporteTecnicoAtributo].[id_opcionAtributo] AS [id_opcionAtributo],
[equ_opcionAtributo].[opcionAtributo] as [equ_opcionAtributo_opcionAtributo],
[equ_opcionAtributo].[opcionAtributo_codigo] as [equ_opcionAtributo_opcionAtributo_codigo],
[equ_opcionAtributo].[orden] as [equ_opcionAtributo_orden],
[equ_opcionAtributo].[id_atributo] as [equ_opcionAtributo_id_atributo],
[equ_opcionAtributo].[cmm] as [equ_opcionAtributo_cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ort_reporteTecnicoAtributo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_reporteTecnicoAtributo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_reporteTecnicoAtributo].[id_usuario_creo]
	INNER JOIN [ort_reporteTecnico] ON [ort_reporteTecnico].id=[ort_reporteTecnicoAtributo].[id_reporteTecnico]
	INNER JOIN [cat_atributo] ON [cat_atributo].id=[ort_reporteTecnicoAtributo].[id_atributo]
	INNER JOIN [equ_opcionAtributo] ON [equ_opcionAtributo].id=[ort_reporteTecnicoAtributo].[id_opcionAtributo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ort_reporteTecnicoAtributo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ort_reporteTecnicoAtributo].active=1
