GO
CREATE PROCEDURE [upd_ort_reporteTecnicoAtributo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_reporteTecnicoAtributo nvarchar(-1) = null,
		@p_reporteTecnicoAtributo_codigo varchar(500) = null,
		@p_id_reporteTecnico int = null,
		@p_id_atributo int = null,
		@p_id_opcionAtributo int = null
AS
BEGIN
		UPDATE [ort_reporteTecnicoAtributo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[reporteTecnicoAtributo] = isnull(@p_reporteTecnicoAtributo,[reporteTecnicoAtributo]),
			[reporteTecnicoAtributo_codigo] = isnull(@p_reporteTecnicoAtributo_codigo,[reporteTecnicoAtributo_codigo]),
			[id_reporteTecnico] = isnull(@p_id_reporteTecnico,[id_reporteTecnico]),
			[id_atributo] = isnull(@p_id_atributo,[id_atributo]),
			[id_opcionAtributo] = isnull(@p_id_opcionAtributo,[id_opcionAtributo])
		WHERE (id = @p_id)
END
GO
