IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ort_reporteTecnicoAtributo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ort_reporteTecnicoAtributo]
GO
CREATE PROCEDURE [ins_ort_reporteTecnicoAtributo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_reporteTecnicoAtributo nvarchar(-1),
		@p_reporteTecnicoAtributo_codigo varchar(500),
		@p_id_reporteTecnico int,
		@p_id_atributo int,
		@p_id_opcionAtributo int
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_reporteTecnicoAtributo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[reporteTecnicoAtributo],
			[reporteTecnicoAtributo_codigo],
			[id_reporteTecnico],
			[id_atributo],
			[id_opcionAtributo])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_reporteTecnicoAtributo,
			@p_reporteTecnicoAtributo_codigo,
			@p_id_reporteTecnico,
			@p_id_atributo,
			@p_id_opcionAtributo)
		SET @v_id = scope_identity()
UPDATE [ort_reporteTecnicoAtributo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
