IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_ort_tipoProgramacion]')) DROP VIEW [dbo].[view_ort_tipoProgramacion]
GO
CREATE  VIEW [view_ort_tipoProgramacion] AS
SELECT 	[ort_tipoProgramacion].[id] AS [id],
		[ort_tipoProgramacion].[uid] AS [uid],
		[ort_tipoProgramacion].[eid] AS [eid],
		[ort_tipoProgramacion].[id_usuario_modifico] AS [id_usuario_modifico],
		[ort_tipoProgramacion].[id_usuario_creo] AS [id_usuario_creo],
		[ort_tipoProgramacion].[fechaModificacion] AS [fechaModificacion],
		[ort_tipoProgramacion].[fechaCreacion] AS [fechaCreacion],
		[ort_tipoProgramacion].[active] AS [active],
		[ort_tipoProgramacion].[tipoProgramacion] AS [tipoProgramacion],
		[ort_tipoProgramacion].[tipoProgramacion_codigo] AS [tipoProgramacion_codigo],
		[ort_tipoProgramacion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ort_tipoProgramacion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ort_tipoProgramacion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ort_tipoProgramacion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ort_tipoProgramacion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ort_tipoProgramacion].active=1
GO
