IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ort_tipoProgramacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ort_tipoProgramacion]
GO
CREATE PROCEDURE [ins_ort_tipoProgramacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoProgramacion varchar(300),
		@p_tipoProgramacion_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_tipoProgramacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoProgramacion],
			[tipoProgramacion_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoProgramacion,
			@p_tipoProgramacion_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ort_tipoProgramacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
