IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_ort_vale]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_ort_vale]
GO
CREATE PROCEDURE [upd_ort_vale]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_vale varchar(300) = null,
		@p_vale_codigo varchar(100) = null,
		@p_id_documento_ot int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [ort_vale]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[vale] = isnull(@p_vale,[vale]),
			[vale_codigo] = isnull(@p_vale_codigo,[vale_codigo]),
			[id_documento.ot] = isnull(@p_id_documento_ot,[id_documento.ot]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
