IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ort_vale]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ort_vale]
GO
CREATE PROCEDURE [ins_ort_vale]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_vale varchar(300),
		@p_vale_codigo varchar(100),
		@p_id_documento_ot int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ort_vale]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[vale],
			[vale_codigo],
			[id_documento.ot],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_vale,
			@p_vale_codigo,
			@p_id_documento_ot,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ort_vale] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
