		[pro_actividad].[id_usuario_creo] AS [id_usuario_creo],
		[pro_actividad].[fechaModificacion] AS [fechaModificacion],
		[pro_actividad].[fechaCreacion] AS [fechaCreacion],
		[pro_actividad].[active] AS [active],
		[pro_actividad].[actividad] AS [actividad],
		[pro_actividad].[actividad_codigo] AS [actividad_codigo],
		[pro_actividad].[descripcionDetallada] AS [descripcionDetallada],
		[pro_actividad].[fechainicioPlaneada] AS [fechainicioPlaneada],
		[pro_actividad].[fechainicioProyectada] AS [fechainicioProyectada],
		[pro_actividad].[fechaInicioReal] AS [fechaInicioReal],
		[pro_actividad].[duracion] AS [duracion],
		[pro_actividad].[fechaTerminacionPlaneada] AS [fechaTerminacionPlaneada],
		[pro_actividad].[fechaTerminacionProyectada] AS [fechaTerminacionProyectada],
		[pro_actividad].[fechaTerminacionReal] AS [fechaTerminacionReal],
		[pro_actividad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_actividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_actividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_actividad].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_actividad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_actividad].active=1
GO
