		@p_fechaTerminacionReal smalldatetime = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [pro_actividad]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[actividad] = isnull(@p_actividad,[actividad]),
			[actividad_codigo] = isnull(@p_actividad_codigo,[actividad_codigo]),
			[descripcionDetallada] = isnull(@p_descripcionDetallada,[descripcionDetallada]),
			[fechainicioPlaneada] = isnull(@p_fechainicioPlaneada,[fechainicioPlaneada]),
			[fechainicioProyectada] = isnull(@p_fechainicioProyectada,[fechainicioProyectada]),
			[fechaInicioReal] = isnull(@p_fechaInicioReal,[fechaInicioReal]),
			[duracion] = isnull(@p_duracion,[duracion]),
			[fechaTerminacionPlaneada] = isnull(@p_fechaTerminacionPlaneada,[fechaTerminacionPlaneada]),
			[fechaTerminacionProyectada] = isnull(@p_fechaTerminacionProyectada,[fechaTerminacionProyectada]),
			[fechaTerminacionReal] = isnull(@p_fechaTerminacionReal,[fechaTerminacionReal]),
