		@p_fechaTerminacionProyectada smalldatetime,
		@p_fechaTerminacionReal smalldatetime,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_actividad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[actividad],
			[actividad_codigo],
			[descripcionDetallada],
			[fechainicioPlaneada],
			[fechainicioProyectada],
			[fechaInicioReal],
			[duracion],
			[fechaTerminacionPlaneada],
			[fechaTerminacionProyectada],
			[fechaTerminacionReal],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_actividad,
