		[pro_actividad_ejecutor].[eid] AS [eid],
		[pro_actividad_ejecutor].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_actividad_ejecutor].[id_usuario_creo] AS [id_usuario_creo],
		[pro_actividad_ejecutor].[fechaModificacion] AS [fechaModificacion],
		[pro_actividad_ejecutor].[fechaCreacion] AS [fechaCreacion],
		[pro_actividad_ejecutor].[active] AS [active],
		[pro_actividad_ejecutor].[actividad_ejecutor] AS [actividad_ejecutor],
		[pro_actividad_ejecutor].[id_ejecutores] AS [id_ejecutores],
[pro_ejecutores].[ejecutores] as [pro_ejecutores_ejecutores],
[pro_ejecutores].[ejecutores_codigo] as [pro_ejecutores_ejecutores_codigo],
[pro_ejecutores].[costo] as [pro_ejecutores_costo],
[pro_ejecutores].[unidadTiempo] as [pro_ejecutores_unidadTiempo],
[pro_ejecutores].[id_horarioTrabajo] as [pro_ejecutores_id_horarioTrabajo],
[pro_ejecutores].[id_usuario] as [pro_ejecutores_id_usuario],
[pro_ejecutores].[id_horarioEjecutores] as [pro_ejecutores_id_horarioEjecutores],
[pro_ejecutores].[cmm] as [pro_ejecutores_cmm],
		[pro_actividad_ejecutor].[id_actividad] AS [id_actividad],
[pro_actividad].[actividad] as [pro_actividad_actividad],
[pro_actividad].[actividad_codigo] as [pro_actividad_actividad_codigo],
[pro_actividad].[descripcionDetallada] as [pro_actividad_descripcionDetallada],
[pro_actividad].[fechainicioPlaneada] as [pro_actividad_fechainicioPlaneada],
[pro_actividad].[fechainicioProyectada] as [pro_actividad_fechainicioProyectada],
[pro_actividad].[fechaInicioReal] as [pro_actividad_fechaInicioReal],
[pro_actividad].[duracion] as [pro_actividad_duracion],
[pro_actividad].[fechaTerminacionPlaneada] as [pro_actividad_fechaTerminacionPlaneada],
[pro_actividad].[fechaTerminacionProyectada] as [pro_actividad_fechaTerminacionProyectada],
[pro_actividad].[fechaTerminacionReal] as [pro_actividad_fechaTerminacionReal],
[pro_actividad].[cmm] as [pro_actividad_cmm],
		[pro_actividad_ejecutor].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_actividad_ejecutor]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_actividad_ejecutor].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_actividad_ejecutor].[id_usuario_creo]
	INNER JOIN [pro_ejecutores] ON [pro_ejecutores].id=[pro_actividad_ejecutor].[id_ejecutores]
	INNER JOIN [pro_actividad] ON [pro_actividad].id=[pro_actividad_ejecutor].[id_actividad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_actividad_ejecutor].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
