IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_pro_actividad_ejecutor]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_pro_actividad_ejecutor]
GO
CREATE PROCEDURE [ins_pro_actividad_ejecutor]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_actividad_ejecutor varchar(300),
		@p_id_ejecutores int,
		@p_id_actividad int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_actividad_ejecutor]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[actividad_ejecutor],
			[id_ejecutores],
			[id_actividad],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_actividad_ejecutor,
			@p_id_ejecutores,
			@p_id_actividad,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_actividad_ejecutor] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
