[pro_etapa].[fechaInicioPlaneada] as [pro_etapa_fechaInicioPlaneada],
[pro_etapa].[fechaInicioProyectada] as [pro_etapa_fechaInicioProyectada],
[pro_etapa].[fechaInicioReal] as [pro_etapa_fechaInicioReal],
[pro_etapa].[fechaFinPlaneada] as [pro_etapa_fechaFinPlaneada],
[pro_etapa].[fechaFinProyectada] as [pro_etapa_fechaFinProyectada],
[pro_etapa].[fechaFinReal] as [pro_etapa_fechaFinReal],
[pro_etapa].[cmm] as [pro_etapa_cmm],
		[pro_actividad_etapa].[id_actividad] AS [id_actividad],
[pro_actividad].[actividad] as [pro_actividad_actividad],
[pro_actividad].[actividad_codigo] as [pro_actividad_actividad_codigo],
[pro_actividad].[descripcionDetallada] as [pro_actividad_descripcionDetallada],
[pro_actividad].[fechainicioPlaneada] as [pro_actividad_fechainicioPlaneada],
[pro_actividad].[fechainicioProyectada] as [pro_actividad_fechainicioProyectada],
[pro_actividad].[fechaInicioReal] as [pro_actividad_fechaInicioReal],
[pro_actividad].[duracion] as [pro_actividad_duracion],
[pro_actividad].[fechaTerminacionPlaneada] as [pro_actividad_fechaTerminacionPlaneada],
[pro_actividad].[fechaTerminacionProyectada] as [pro_actividad_fechaTerminacionProyectada],
[pro_actividad].[fechaTerminacionReal] as [pro_actividad_fechaTerminacionReal],
[pro_actividad].[cmm] as [pro_actividad_cmm],
		[pro_actividad_etapa].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_actividad_etapa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_actividad_etapa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_actividad_etapa].[id_usuario_creo]
	INNER JOIN [pro_etapa] ON [pro_etapa].id=[pro_actividad_etapa].[id_etapa]
	INNER JOIN [pro_actividad] ON [pro_actividad].id=[pro_actividad_etapa].[id_actividad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_actividad_etapa].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
