IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_pro_actividad_etapa]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_pro_actividad_etapa]
GO
CREATE PROCEDURE [ins_pro_actividad_etapa]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_actividad_etapa varchar(300),
		@p_id_etapa int,
		@p_id_actividad int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_actividad_etapa]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[actividad_etapa],
			[id_etapa],
			[id_actividad],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_actividad_etapa,
			@p_id_etapa,
			@p_id_actividad,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_actividad_etapa] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
