	INNER JOIN [pro_actividad] ON [pro_actividad].id=[pro_actividad_hito].[id_actividad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_actividad_hito].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
