CREATE PROCEDURE [aud_pro_actividad_hito]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [pro_actividad_hito].id as id_tabla,
	[pro_actividad_hito].id_usuario_modifico as id_usuario_modifico,
	[pro_actividad_hito].id_usuario_creo as id_usuario_creo,
	[pro_actividad_hito].fechaModificacion as fechaModificacion,
	[pro_actividad_hito].fechaCreacion as fechaCreacion,
	[pro_actividad_hito].active as active,
	[pro_actividad_hito].[actividad_hito] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [pro_actividad_hito]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_actividad_hito].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_actividad_hito].[id_usuario_creo]
	where ' + @p_filtro)
END
