GO
CREATE  VIEW [view_pro_actividad_recursoFisico] AS
SELECT 	[pro_actividad_recursoFisico].[id] AS [id],
		[pro_actividad_recursoFisico].[uid] AS [uid],
		[pro_actividad_recursoFisico].[eid] AS [eid],
		[pro_actividad_recursoFisico].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_actividad_recursoFisico].[id_usuario_creo] AS [id_usuario_creo],
		[pro_actividad_recursoFisico].[fechaModificacion] AS [fechaModificacion],
		[pro_actividad_recursoFisico].[fechaCreacion] AS [fechaCreacion],
		[pro_actividad_recursoFisico].[active] AS [active],
		[pro_actividad_recursoFisico].[actividad_recursoFisico] AS [actividad_recursoFisico],
		[pro_actividad_recursoFisico].[duracion] AS [duracion],
		[pro_actividad_recursoFisico].[cantidad] AS [cantidad],
		[pro_actividad_recursoFisico].[id_recursoFisico] AS [id_recursoFisico],
[pro_recursoFisico].[recursoFisico] as [pro_recursoFisico_recursoFisico],
[pro_recursoFisico].[recursoFisico_codigo] as [pro_recursoFisico_recursoFisico_codigo],
[pro_recursoFisico].[costo] as [pro_recursoFisico_costo],
[pro_recursoFisico].[unidadTiempo] as [pro_recursoFisico_unidadTiempo],
[pro_recursoFisico].[esPropio] as [pro_recursoFisico_esPropio],
[pro_recursoFisico].[id_equipo] as [pro_recursoFisico_id_equipo],
[pro_recursoFisico].[id_catalogo] as [pro_recursoFisico_id_catalogo],
[pro_recursoFisico].[cmm] as [pro_recursoFisico_cmm],
		[pro_actividad_recursoFisico].[id_actividad] AS [id_actividad],
[pro_actividad].[actividad] as [pro_actividad_actividad],
[pro_actividad].[actividad_codigo] as [pro_actividad_actividad_codigo],
[pro_actividad].[descripcionDetallada] as [pro_actividad_descripcionDetallada],
[pro_actividad].[fechainicioPlaneada] as [pro_actividad_fechainicioPlaneada],
[pro_actividad].[fechainicioProyectada] as [pro_actividad_fechainicioProyectada],
[pro_actividad].[fechaInicioReal] as [pro_actividad_fechaInicioReal],
[pro_actividad].[duracion] as [pro_actividad_duracion],
[pro_actividad].[fechaTerminacionPlaneada] as [pro_actividad_fechaTerminacionPlaneada],
[pro_actividad].[fechaTerminacionProyectada] as [pro_actividad_fechaTerminacionProyectada],
[pro_actividad].[fechaTerminacionReal] as [pro_actividad_fechaTerminacionReal],
[pro_actividad].[cmm] as [pro_actividad_cmm],
		[pro_actividad_recursoFisico].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_actividad_recursoFisico]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_actividad_recursoFisico].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_actividad_recursoFisico].[id_usuario_creo]
	INNER JOIN [pro_recursoFisico] ON [pro_recursoFisico].id=[pro_actividad_recursoFisico].[id_recursoFisico]
	INNER JOIN [pro_actividad] ON [pro_actividad].id=[pro_actividad_recursoFisico].[id_actividad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_actividad_recursoFisico].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
