CREATE PROCEDURE [aud_pro_actividad_recursoFisico]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [pro_actividad_recursoFisico].id as id_tabla,
	[pro_actividad_recursoFisico].id_usuario_modifico as id_usuario_modifico,
	[pro_actividad_recursoFisico].id_usuario_creo as id_usuario_creo,
	[pro_actividad_recursoFisico].fechaModificacion as fechaModificacion,
	[pro_actividad_recursoFisico].fechaCreacion as fechaCreacion,
	[pro_actividad_recursoFisico].active as active,
	[pro_actividad_recursoFisico].[actividad_recursoFisico] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [pro_actividad_recursoFisico]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_actividad_recursoFisico].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_actividad_recursoFisico].[id_usuario_creo]
	where ' + @p_filtro)
END
