GO
CREATE  VIEW [view_pro_actividadPredecesora] AS
SELECT 	[pro_actividadPredecesora].[id] AS [id],
		[pro_actividadPredecesora].[uid] AS [uid],
		[pro_actividadPredecesora].[eid] AS [eid],
		[pro_actividadPredecesora].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_actividadPredecesora].[id_usuario_creo] AS [id_usuario_creo],
		[pro_actividadPredecesora].[fechaModificacion] AS [fechaModificacion],
		[pro_actividadPredecesora].[fechaCreacion] AS [fechaCreacion],
		[pro_actividadPredecesora].[active] AS [active],
		[pro_actividadPredecesora].[actividadPredecesora] AS [actividadPredecesora],
		[pro_actividadPredecesora].[actividadPredecesora_codigo] AS [actividadPredecesora_codigo],
		[pro_actividadPredecesora].[id_actividad_origen] AS [id_actividad_origen],
[pro_actividad_origen].[actividad] as [pro_actividad_origen_actividad],
[pro_actividad_origen].[actividad_codigo] as [pro_actividad_origen_actividad_codigo],
[pro_actividad_origen].[descripcionDetallada] as [pro_actividad_origen_descripcionDetallada],
[pro_actividad_origen].[fechainicioPlaneada] as [pro_actividad_origen_fechainicioPlaneada],
[pro_actividad_origen].[fechainicioProyectada] as [pro_actividad_origen_fechainicioProyectada],
[pro_actividad_origen].[fechaInicioReal] as [pro_actividad_origen_fechaInicioReal],
[pro_actividad_origen].[duracion] as [pro_actividad_origen_duracion],
[pro_actividad_origen].[fechaTerminacionPlaneada] as [pro_actividad_origen_fechaTerminacionPlaneada],
[pro_actividad_origen].[fechaTerminacionProyectada] as [pro_actividad_origen_fechaTerminacionProyectada],
[pro_actividad_origen].[fechaTerminacionReal] as [pro_actividad_origen_fechaTerminacionReal],
[pro_actividad_origen].[cmm] as [pro_actividad_origen_cmm],
		[pro_actividadPredecesora].[id_actividad_destino] AS [id_actividad_destino],
[pro_actividad_destino].[actividad] as [pro_actividad_destino_actividad],
[pro_actividad_destino].[actividad_codigo] as [pro_actividad_destino_actividad_codigo],
[pro_actividad_destino].[descripcionDetallada] as [pro_actividad_destino_descripcionDetallada],
[pro_actividad_destino].[fechainicioPlaneada] as [pro_actividad_destino_fechainicioPlaneada],
[pro_actividad_destino].[fechainicioProyectada] as [pro_actividad_destino_fechainicioProyectada],
[pro_actividad_destino].[fechaInicioReal] as [pro_actividad_destino_fechaInicioReal],
[pro_actividad_destino].[duracion] as [pro_actividad_destino_duracion],
[pro_actividad_destino].[fechaTerminacionPlaneada] as [pro_actividad_destino_fechaTerminacionPlaneada],
[pro_actividad_destino].[fechaTerminacionProyectada] as [pro_actividad_destino_fechaTerminacionProyectada],
[pro_actividad_destino].[fechaTerminacionReal] as [pro_actividad_destino_fechaTerminacionReal],
[pro_actividad_destino].[cmm] as [pro_actividad_destino_cmm],
		[pro_actividadPredecesora].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_actividadPredecesora]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_actividadPredecesora].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_actividadPredecesora].[id_usuario_creo]
	INNER JOIN [pro_actividad] AS [pro_actividad_origen] ON [pro_actividad_origen].id=[pro_actividadPredecesora].[id_actividad_origen]
	INNER JOIN [pro_actividad] AS [pro_actividad_destino] ON [pro_actividad_destino].id=[pro_actividadPredecesora].[id_actividad_destino]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_actividadPredecesora].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_actividadPredecesora].active=1
