CREATE PROCEDURE [ins_pro_actividadPredecesora]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_actividadPredecesora varchar(300),
		@p_actividadPredecesora_codigo varchar(100),
		@p_id_actividad_origen int,
		@p_id_actividad_destino int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_actividadPredecesora]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[actividadPredecesora],
			[actividadPredecesora_codigo],
			[id_actividad_origen],
			[id_actividad_destino],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_actividadPredecesora,
			@p_actividadPredecesora_codigo,
			@p_id_actividad_origen,
			@p_id_actividad_destino,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_actividadPredecesora] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
