IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_pro_calidad]')) DROP VIEW [dbo].[view_pro_calidad]
GO
CREATE  VIEW [view_pro_calidad] AS
SELECT 	[pro_calidad].[id] AS [id],
		[pro_calidad].[uid] AS [uid],
		[pro_calidad].[eid] AS [eid],
		[pro_calidad].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_calidad].[id_usuario_creo] AS [id_usuario_creo],
		[pro_calidad].[fechaModificacion] AS [fechaModificacion],
		[pro_calidad].[fechaCreacion] AS [fechaCreacion],
		[pro_calidad].[active] AS [active],
		[pro_calidad].[calidad] AS [calidad],
		[pro_calidad].[calidad_codigo] AS [calidad_codigo],
		[pro_calidad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_calidad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_calidad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_calidad].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_calidad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_calidad].active=1
GO
