CREATE PROCEDURE [sel_doc_documento_proyectosXcalidad]
	@p_id_pro_calidad INT
AS
BEGIN
	SELECT 	[doc_documento.proyecto_calidad].[id] AS [I_id],
		[doc_documento.proyecto_calidad].[uid] AS [I_uid],
		[doc_documento.proyecto_calidad].[eid] AS [I_eid],
		[doc_documento.proyecto_calidad].[fechaModificacion] AS [I_fechaModificacion],
		[doc_documento.proyecto_calidad].[fechaCreacion] AS [I_fechaCreacion],
		[doc_documento.proyecto_calidad].[active] AS [I_active],
		[doc_documento.proyecto_calidad].[documento.proyecto_calidad] AS [I_documento.proyecto_calidad],
		[doc_documento.proyecto_calidad].[cmm] AS [I_cmm]
	FROM doc_documento.proyecto_calidad INNER JOIN doc_documento.proyecto
	 ON [doc_documento.proyecto_calidad].[id_documento.proyecto] = [doc_documento.proyecto].id
	WHERE	([doc_documento.proyecto_calidad].[id_calidad]= @p_id_pro_calidad)
END
