GO
CREATE  VIEW [view_pro_ejecutores] AS
SELECT 	[pro_ejecutores].[id] AS [id],
		[pro_ejecutores].[uid] AS [uid],
		[pro_ejecutores].[eid] AS [eid],
		[pro_ejecutores].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_ejecutores].[id_usuario_creo] AS [id_usuario_creo],
		[pro_ejecutores].[fechaModificacion] AS [fechaModificacion],
		[pro_ejecutores].[fechaCreacion] AS [fechaCreacion],
		[pro_ejecutores].[active] AS [active],
		[pro_ejecutores].[ejecutores] AS [ejecutores],
		[pro_ejecutores].[ejecutores_codigo] AS [ejecutores_codigo],
		[pro_ejecutores].[costo] AS [costo],
		[pro_ejecutores].[unidadTiempo] AS [unidadTiempo],
		[pro_ejecutores].[id_horarioTrabajo] AS [id_horarioTrabajo],
[pro_horarioTrabajo].[horarioTrabajo] as [pro_horarioTrabajo_horarioTrabajo],
[pro_horarioTrabajo].[horarioTrabajo_codigo] as [pro_horarioTrabajo_horarioTrabajo_codigo],
[pro_horarioTrabajo].[cmm] as [pro_horarioTrabajo_cmm],
		[pro_ejecutores].[id_usuario] AS [id_usuario],
[seg_usuario].[usuario] as [seg_usuario_usuario],
[seg_usuario].[usuario_codigo] as [seg_usuario_usuario_codigo],
[seg_usuario].[intentosFallidos] as [seg_usuario_intentosFallidos],
[seg_usuario].[numeroIngresos] as [seg_usuario_numeroIngresos],
[seg_usuario].[fechaUltimoIngreso_fh] as [seg_usuario_fechaUltimoIngreso_fh],
[seg_usuario].[fechaIntentoFallido_fh] as [seg_usuario_fechaIntentoFallido_fh],
[seg_usuario].[clave] as [seg_usuario_clave],
[seg_usuario].[nombre] as [seg_usuario_nombre],
[seg_usuario].[profesion] as [seg_usuario_profesion],
[seg_usuario].[email] as [seg_usuario_email],
[seg_usuario].[direccion] as [seg_usuario_direccion],
[seg_usuario].[telefono] as [seg_usuario_telefono],
[seg_usuario].[costoHora] as [seg_usuario_costoHora],
[seg_usuario].[porcentajeComision] as [seg_usuario_porcentajeComision],
[seg_usuario].[accesoActivo] as [seg_usuario_accesoActivo],
[seg_usuario].[cambiarClave] as [seg_usuario_cambiarClave],
[seg_usuario].[fechaUltimoCambioClave_fh] as [seg_usuario_fechaUltimoCambioClave_fh],
[seg_usuario].[aplicaRecargo] as [seg_usuario_aplicaRecargo],
[seg_usuario].[sexo] as [seg_usuario_sexo],
[seg_usuario].[id_perfil] as [seg_usuario_id_perfil],
[seg_usuario].[id_cargo] as [seg_usuario_id_cargo],
[seg_usuario].[id_grupo] as [seg_usuario_id_grupo],
[seg_usuario].[id_zona] as [seg_usuario_id_zona],
[seg_usuario].[identificacion] as [seg_usuario_identificacion],
[seg_usuario].[id_usuario] as [seg_usuario_id_usuario],
[seg_usuario].[habilitado] as [seg_usuario_habilitado],
[seg_usuario].[idDispositivo] as [seg_usuario_idDispositivo],
[seg_usuario].[cmm] as [seg_usuario_cmm],
		[pro_ejecutores].[id_horarioEjecutores] AS [id_horarioEjecutores],
[pro_horarioEjecutores].[horarioEjecutores] as [pro_horarioEjecutores_horarioEjecutores],
[pro_horarioEjecutores].[horarioEjecutores_codigo] as [pro_horarioEjecutores_horarioEjecutores_codigo],
[pro_horarioEjecutores].[cmm] as [pro_horarioEjecutores_cmm],
		[pro_ejecutores].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_ejecutores]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_ejecutores].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_ejecutores].[id_usuario_creo]
	INNER JOIN [pro_horarioTrabajo] ON [pro_horarioTrabajo].id=[pro_ejecutores].[id_horarioTrabajo]
	INNER JOIN [seg_usuario] ON [seg_usuario].id=[pro_ejecutores].[id_usuario]
	INNER JOIN [pro_horarioEjecutores] ON [pro_horarioEjecutores].id=[pro_ejecutores].[id_horarioEjecutores]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_ejecutores].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_ejecutores].active=1
