CREATE PROCEDURE [upd_pro_ejecutores]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_ejecutores varchar(300) = null,
		@p_ejecutores_codigo varchar(100) = null,
		@p_costo float = null,
		@p_unidadTiempo varchar(1) = null,
		@p_id_horarioTrabajo int = null,
		@p_id_usuario int = null,
		@p_id_horarioEjecutores int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [pro_ejecutores]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[ejecutores] = isnull(@p_ejecutores,[ejecutores]),
			[ejecutores_codigo] = isnull(@p_ejecutores_codigo,[ejecutores_codigo]),
			[costo] = isnull(@p_costo,[costo]),
			[unidadTiempo] = isnull(@p_unidadTiempo,[unidadTiempo]),
			[id_horarioTrabajo] = isnull(@p_id_horarioTrabajo,[id_horarioTrabajo]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[id_horarioEjecutores] = isnull(@p_id_horarioEjecutores,[id_horarioEjecutores]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
