IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_pro_ejecutores]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_pro_ejecutores]
GO
CREATE PROCEDURE [ins_pro_ejecutores]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_ejecutores varchar(300),
		@p_ejecutores_codigo varchar(100),
		@p_costo float,
		@p_unidadTiempo varchar(1),
		@p_id_horarioTrabajo int,
		@p_id_usuario int,
		@p_id_horarioEjecutores int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_ejecutores]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[ejecutores],
			[ejecutores_codigo],
			[costo],
			[unidadTiempo],
			[id_horarioTrabajo],
			[id_usuario],
			[id_horarioEjecutores],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_ejecutores,
			@p_ejecutores_codigo,
			@p_costo,
			@p_unidadTiempo,
			@p_id_horarioTrabajo,
			@p_id_usuario,
			@p_id_horarioEjecutores,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_ejecutores] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
