CREATE PROCEDURE [reg_pro_ejecutores_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[ejecutores] AS [ejecutores],
		[ejecutores_codigo] AS [ejecutores_codigo],
		[costo] AS [costo],
		[unidadTiempo] AS [unidadTiempo],
		[id_horarioTrabajo] AS [id_horarioTrabajo],
		[id_usuario] AS [id_usuario],
		[id_horarioEjecutores] AS [id_horarioEjecutores],
		[cmm] AS [cmm]
	FROM [pro_ejecutores]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
