GO
CREATE PROCEDURE [aud_pro_ejecutores]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [pro_ejecutores].id as id_tabla,
	[pro_ejecutores].id_usuario_modifico as id_usuario_modifico,
	[pro_ejecutores].id_usuario_creo as id_usuario_creo,
	[pro_ejecutores].fechaModificacion as fechaModificacion,
	[pro_ejecutores].fechaCreacion as fechaCreacion,
	[pro_ejecutores].active as active,
	[pro_ejecutores].[ejecutores] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [pro_ejecutores]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_ejecutores].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_ejecutores].[id_usuario_creo]
	where ' + @p_filtro)
END
