CREATE PROCEDURE [sel_doc_documento_proyectosXejecutores]
	@p_id_pro_ejecutores INT
AS
BEGIN
	SELECT 	[doc_documento.proyecto_ejecutores].[id] AS [I_id],
		[doc_documento.proyecto_ejecutores].[uid] AS [I_uid],
		[doc_documento.proyecto_ejecutores].[eid] AS [I_eid],
		[doc_documento.proyecto_ejecutores].[fechaModificacion] AS [I_fechaModificacion],
		[doc_documento.proyecto_ejecutores].[fechaCreacion] AS [I_fechaCreacion],
		[doc_documento.proyecto_ejecutores].[active] AS [I_active],
		[doc_documento.proyecto_ejecutores].[documento.proyecto_ejecutores] AS [I_documento.proyecto_ejecutores],
		[doc_documento.proyecto_ejecutores].[cmm] AS [I_cmm]
	FROM doc_documento.proyecto_ejecutores INNER JOIN doc_documento.proyecto
	 ON [doc_documento.proyecto_ejecutores].[id_documento.proyecto] = [doc_documento.proyecto].id
	WHERE	([doc_documento.proyecto_ejecutores].[id_ejecutores]= @p_id_pro_ejecutores)
END
