		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_ejecutores_archivo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_ejecutores_archivo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_ejecutores_archivo].[id_usuario_creo]
	INNER JOIN [gen_archivo] ON [gen_archivo].id=[pro_ejecutores_archivo].[id_archivo]
	INNER JOIN [pro_ejecutores] ON [pro_ejecutores].id=[pro_ejecutores_archivo].[id_ejecutores]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_ejecutores_archivo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
