GO
CREATE PROCEDURE [upd_pro_ejecutores_archivo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_ejecutores_archivo varchar(300) = null,
		@p_revisado bit = null,
		@p_aprobado bit = null,
		@p_fecha_revision datetime = null,
		@p_fecha_aprobacion datetime = null,
		@p_id_archivo int = null,
		@p_id_ejecutores int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [pro_ejecutores_archivo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[ejecutores_archivo] = isnull(@p_ejecutores_archivo,[ejecutores_archivo]),
			[revisado] = isnull(@p_revisado,[revisado]),
			[aprobado] = isnull(@p_aprobado,[aprobado]),
			[fecha_revision] = isnull(@p_fecha_revision,[fecha_revision]),
			[fecha_aprobacion] = isnull(@p_fecha_aprobacion,[fecha_aprobacion]),
			[id_archivo] = isnull(@p_id_archivo,[id_archivo]),
			[id_ejecutores] = isnull(@p_id_ejecutores,[id_ejecutores]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
