IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_pro_ejecutores_archivo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_pro_ejecutores_archivo]
GO
CREATE PROCEDURE [ins_pro_ejecutores_archivo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_ejecutores_archivo varchar(300),
		@p_revisado bit,
		@p_aprobado bit,
		@p_fecha_revision datetime,
		@p_fecha_aprobacion datetime,
		@p_id_archivo int,
		@p_id_ejecutores int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_ejecutores_archivo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[ejecutores_archivo],
			[revisado],
			[aprobado],
			[fecha_revision],
			[fecha_aprobacion],
			[id_archivo],
			[id_ejecutores],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_ejecutores_archivo,
			@p_revisado,
			@p_aprobado,
			@p_fecha_revision,
			@p_fecha_aprobacion,
			@p_id_archivo,
			@p_id_ejecutores,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_ejecutores_archivo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
