IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_pro_entregable]')) DROP VIEW [dbo].[view_pro_entregable]
GO
CREATE  VIEW [view_pro_entregable] AS
SELECT 	[pro_entregable].[id] AS [id],
		[pro_entregable].[uid] AS [uid],
		[pro_entregable].[eid] AS [eid],
		[pro_entregable].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_entregable].[id_usuario_creo] AS [id_usuario_creo],
		[pro_entregable].[fechaModificacion] AS [fechaModificacion],
		[pro_entregable].[fechaCreacion] AS [fechaCreacion],
		[pro_entregable].[active] AS [active],
		[pro_entregable].[entregable] AS [entregable],
		[pro_entregable].[entregable_codigo] AS [entregable_codigo],
		[pro_entregable].[nombre] AS [nombre],
		[pro_entregable].[producto] AS [producto],
		[pro_entregable].[fechaPlaneada] AS [fechaPlaneada],
		[pro_entregable].[fechaProyectada] AS [fechaProyectada],
		[pro_entregable].[fechaReal] AS [fechaReal],
		[pro_entregable].[esExterno] AS [esExterno],
		[pro_entregable].[porcentajePlaneado] AS [porcentajePlaneado],
		[pro_entregable].[valorPlaneado] AS [valorPlaneado],
		[pro_entregable].[porcentajeReal] AS [porcentajeReal],
		[pro_entregable].[valorReal] AS [valorReal],
		[pro_entregable].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_entregable]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_entregable].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_entregable].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_entregable].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_entregable].active=1
GO
