		@p_valorPlaneado int,
		@p_porcentajeReal float,
		@p_valorReal int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_entregable]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[entregable],
			[entregable_codigo],
			[nombre],
			[producto],
			[fechaPlaneada],
