			[porcentajePlaneado],
			[valorPlaneado],
			[porcentajeReal],
			[valorReal],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_entregable,
