		[pro_etapa].[fechaFinReal] AS [fechaFinReal],
		[pro_etapa].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_etapa]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_etapa].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_etapa].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_etapa].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_etapa].active=1
GO
