CREATE PROCEDURE [upd_pro_etapa]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_etapa varchar(300) = null,
		@p_etapa_codigo varchar(100) = null,
		@p_descripcion varchar(500) = null,
		@p_fechaInicioPlaneada_ff smalldatetime = null,
		@p_fechaInicioProyectada_ff smalldatetime = null,
		@p_fechaInicioReal_ff smalldatetime = null,
		@p_fechaFinPlaneada_ff smalldatetime = null,
		@p_fechaFinProyectada_ff smalldatetime = null,
		@p_fechaFinReal_ff smalldatetime = null,
		@p_orden int = null,
		@p_completado int = null,
		@p_porcentajePresupuesto float = null,
		@p_valorPresupuesto money = null,
		@p_fechaInicioPlaneada datetime = null,
		@p_fechaInicioProyectada datetime = null,
		@p_fechaInicioReal datetime = null,
		@p_fechaFinPlaneada datetime = null,
		@p_fechaFinProyectada datetime = null,
		@p_fechaFinReal datetime = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [pro_etapa]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[etapa] = isnull(@p_etapa,[etapa]),
			[etapa_codigo] = isnull(@p_etapa_codigo,[etapa_codigo]),
			[descripcion] = isnull(@p_descripcion,[descripcion]),
			[fechaInicioPlaneada_ff] = isnull(@p_fechaInicioPlaneada_ff,[fechaInicioPlaneada_ff]),
			[fechaInicioProyectada_ff] = isnull(@p_fechaInicioProyectada_ff,[fechaInicioProyectada_ff]),
			[fechaInicioReal_ff] = isnull(@p_fechaInicioReal_ff,[fechaInicioReal_ff]),
			[fechaFinPlaneada_ff] = isnull(@p_fechaFinPlaneada_ff,[fechaFinPlaneada_ff]),
			[fechaFinProyectada_ff] = isnull(@p_fechaFinProyectada_ff,[fechaFinProyectada_ff]),
			[fechaFinReal_ff] = isnull(@p_fechaFinReal_ff,[fechaFinReal_ff]),
			[orden] = isnull(@p_orden,[orden]),
			[completado] = isnull(@p_completado,[completado]),
			[porcentajePresupuesto] = isnull(@p_porcentajePresupuesto,[porcentajePresupuesto]),
			[valorPresupuesto] = isnull(@p_valorPresupuesto,[valorPresupuesto]),
			[fechaInicioPlaneada] = isnull(@p_fechaInicioPlaneada,[fechaInicioPlaneada]),
			[fechaInicioProyectada] = isnull(@p_fechaInicioProyectada,[fechaInicioProyectada]),
			[fechaInicioReal] = isnull(@p_fechaInicioReal,[fechaInicioReal]),
			[fechaFinPlaneada] = isnull(@p_fechaFinPlaneada,[fechaFinPlaneada]),
			[fechaFinProyectada] = isnull(@p_fechaFinProyectada,[fechaFinProyectada]),
			[fechaFinReal] = isnull(@p_fechaFinReal,[fechaFinReal]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
