	[pro_etapa].id_usuario_modifico as id_usuario_modifico,
	[pro_etapa].id_usuario_creo as id_usuario_creo,
	[pro_etapa].fechaModificacion as fechaModificacion,
	[pro_etapa].fechaCreacion as fechaCreacion,
