GO
CREATE  VIEW [view_pro_GrupoSesion] AS
SELECT 	[pro_GrupoSesion].[id] AS [id],
		[pro_GrupoSesion].[uid] AS [uid],
		[pro_GrupoSesion].[eid] AS [eid],
		[pro_GrupoSesion].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_GrupoSesion].[id_usuario_creo] AS [id_usuario_creo],
		[pro_GrupoSesion].[fechaModificacion] AS [fechaModificacion],
		[pro_GrupoSesion].[fechaCreacion] AS [fechaCreacion],
		[pro_GrupoSesion].[active] AS [active],
		[pro_GrupoSesion].[GrupoSesion] AS [GrupoSesion],
		[pro_GrupoSesion].[GrupoSesion_codigo] AS [GrupoSesion_codigo],
		[pro_GrupoSesion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_GrupoSesion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_GrupoSesion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_GrupoSesion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_GrupoSesion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_GrupoSesion].active=1
GO
