CREATE  VIEW [view_pro_horarioEjecutores] AS
SELECT 	[pro_horarioEjecutores].[id] AS [id],
		[pro_horarioEjecutores].[uid] AS [uid],
		[pro_horarioEjecutores].[eid] AS [eid],
		[pro_horarioEjecutores].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_horarioEjecutores].[id_usuario_creo] AS [id_usuario_creo],
		[pro_horarioEjecutores].[fechaModificacion] AS [fechaModificacion],
		[pro_horarioEjecutores].[fechaCreacion] AS [fechaCreacion],
		[pro_horarioEjecutores].[active] AS [active],
		[pro_horarioEjecutores].[horarioEjecutores] AS [horarioEjecutores],
		[pro_horarioEjecutores].[horarioEjecutores_codigo] AS [horarioEjecutores_codigo],
		[pro_horarioEjecutores].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_horarioEjecutores]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_horarioEjecutores].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_horarioEjecutores].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_horarioEjecutores].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_horarioEjecutores].active=1
GO
