GO
CREATE PROCEDURE [upd_pro_horarioProyecto]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_horarioProyecto varchar(300) = null,
		@p_horarioProyecto_codigo varchar(100) = null,
		@p_id_documento_proyecto int = null,
		@p_lunes varchar(200) = null,
		@p_martes varchar(200) = null,
		@p_miercoles varchar(200) = null,
		@p_jueves varchar(200) = null,
		@p_viernes varchar(200) = null,
		@p_sabado varchar(200) = null,
		@p_domingo varchar(200) = null,
		@p_festivos varchar(200) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [pro_horarioProyecto]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[horarioProyecto] = isnull(@p_horarioProyecto,[horarioProyecto]),
			[horarioProyecto_codigo] = isnull(@p_horarioProyecto_codigo,[horarioProyecto_codigo]),
			[id_documento.proyecto] = isnull(@p_id_documento_proyecto,[id_documento.proyecto]),
			[lunes] = isnull(@p_lunes,[lunes]),
			[martes] = isnull(@p_martes,[martes]),
			[miercoles] = isnull(@p_miercoles,[miercoles]),
			[jueves] = isnull(@p_jueves,[jueves]),
			[viernes] = isnull(@p_viernes,[viernes]),
			[sabado] = isnull(@p_sabado,[sabado]),
			[domingo] = isnull(@p_domingo,[domingo]),
			[festivos] = isnull(@p_festivos,[festivos]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
