IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_pro_horarioProyecto]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_pro_horarioProyecto]
GO
CREATE PROCEDURE [ins_pro_horarioProyecto]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_horarioProyecto varchar(300),
		@p_horarioProyecto_codigo varchar(100),
		@p_id_documento_proyecto int,
		@p_lunes varchar(200),
		@p_martes varchar(200),
		@p_miercoles varchar(200),
		@p_jueves varchar(200),
		@p_viernes varchar(200),
		@p_sabado varchar(200),
		@p_domingo varchar(200),
		@p_festivos varchar(200),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_horarioProyecto]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[horarioProyecto],
			[horarioProyecto_codigo],
			[id_documento.proyecto],
			[lunes],
			[martes],
			[miercoles],
			[jueves],
			[viernes],
			[sabado],
			[domingo],
			[festivos],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_horarioProyecto,
			@p_horarioProyecto_codigo,
			@p_id_documento_proyecto,
			@p_lunes,
			@p_martes,
			@p_miercoles,
			@p_jueves,
			@p_viernes,
			@p_sabado,
			@p_domingo,
			@p_festivos,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_horarioProyecto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
