	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [pro_horarioProyecto].id as id_tabla,
	[pro_horarioProyecto].id_usuario_modifico as id_usuario_modifico,
	[pro_horarioProyecto].id_usuario_creo as id_usuario_creo,
	[pro_horarioProyecto].fechaModificacion as fechaModificacion,
	[pro_horarioProyecto].fechaCreacion as fechaCreacion,
	[pro_horarioProyecto].active as active,
	[pro_horarioProyecto].[horarioProyecto] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [pro_horarioProyecto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_horarioProyecto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_horarioProyecto].[id_usuario_creo]
	where ' + @p_filtro)
