CREATE  VIEW [view_pro_horarioTrabajo] AS
SELECT 	[pro_horarioTrabajo].[id] AS [id],
		[pro_horarioTrabajo].[uid] AS [uid],
		[pro_horarioTrabajo].[eid] AS [eid],
		[pro_horarioTrabajo].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_horarioTrabajo].[id_usuario_creo] AS [id_usuario_creo],
		[pro_horarioTrabajo].[fechaModificacion] AS [fechaModificacion],
		[pro_horarioTrabajo].[fechaCreacion] AS [fechaCreacion],
		[pro_horarioTrabajo].[active] AS [active],
		[pro_horarioTrabajo].[horarioTrabajo] AS [horarioTrabajo],
		[pro_horarioTrabajo].[horarioTrabajo_codigo] AS [horarioTrabajo_codigo],
		[pro_horarioTrabajo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_horarioTrabajo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_horarioTrabajo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_horarioTrabajo].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_horarioTrabajo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_horarioTrabajo].active=1
