CREATE PROCEDURE [ins_pro_horarioTrabajo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_horarioTrabajo varchar(300),
		@p_horarioTrabajo_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_horarioTrabajo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[horarioTrabajo],
			[horarioTrabajo_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_horarioTrabajo,
			@p_horarioTrabajo_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_horarioTrabajo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
