[cat_catalogo].[id_subtipoCatalogo] as [cat_catalogo_id_subtipoCatalogo],
[cat_catalogo].[id_unidad] as [cat_catalogo_id_unidad],
[cat_catalogo].[id_impuesto] as [cat_catalogo_id_impuesto],
[cat_catalogo].[descripcion] as [cat_catalogo_descripcion],
[cat_catalogo].[bloquearCostear] as [cat_catalogo_bloquearCostear],
[cat_catalogo].[cmm] as [cat_catalogo_cmm],
		[pro_recursoFisico].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_recursoFisico]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_recursoFisico].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_recursoFisico].[id_usuario_creo]
	INNER JOIN [equ_equipo] ON [equ_equipo].id=[pro_recursoFisico].[id_equipo]
	INNER JOIN [cat_catalogo] ON [cat_catalogo].id=[pro_recursoFisico].[id_catalogo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_recursoFisico].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_recursoFisico].active=1
