		@p_id_usuario_creo int,
		@p_recursoFisico varchar(300),
		@p_recursoFisico_codigo varchar(100),
		@p_costo float,
		@p_unidadTiempo varchar(1),
		@p_esPropio bit,
		@p_id_equipo int,
		@p_id_catalogo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_recursoFisico]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[recursoFisico],
			[recursoFisico_codigo],
			[costo],
			[unidadTiempo],
			[esPropio],
			[id_equipo],
			[id_catalogo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_recursoFisico,
			@p_recursoFisico_codigo,
			@p_costo,
			@p_unidadTiempo,
			@p_esPropio,
			@p_id_equipo,
			@p_id_catalogo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_recursoFisico] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
