[ter_sucursal].[cargo] as [ter_sucursal_cargo],
[ter_sucursal].[cmm] as [ter_sucursal_cmm],
		[pro_reporteActividad].[fecha_inicio] AS [fecha_inicio],
		[pro_reporteActividad].[duracion] AS [duracion],
		[pro_reporteActividad].[texto] AS [texto],
		[pro_reporteActividad].[porcentaje_avance] AS [porcentaje_avance],
		[pro_reporteActividad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_reporteActividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_reporteActividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_reporteActividad].[id_usuario_creo]
	INNER JOIN [pro_actividad] ON [pro_actividad].id=[pro_reporteActividad].[id_actividad]
	INNER JOIN [pro_SesionActividad] ON [pro_SesionActividad].id=[pro_reporteActividad].[id_SesionActividad]
	INNER JOIN [pro_ejecutores] ON [pro_ejecutores].id=[pro_reporteActividad].[id_ejecutores]
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[pro_reporteActividad].[id_sucursal]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_reporteActividad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_reporteActividad].active=1
