GO
CREATE PROCEDURE [upd_pro_reporteActividad]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_reporteActividad varchar(300) = null,
		@p_reporteActividad_codigo varchar(100) = null,
		@p_id_actividad int = null,
		@p_id_SesionActividad int = null,
		@p_id_ejecutores int = null,
		@p_id_sucursal int = null,
		@p_fecha_inicio smalldatetime = null,
		@p_duracion float = null,
		@p_texto varchar(3000) = null,
		@p_porcentaje_avance float = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [pro_reporteActividad]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[reporteActividad] = isnull(@p_reporteActividad,[reporteActividad]),
			[reporteActividad_codigo] = isnull(@p_reporteActividad_codigo,[reporteActividad_codigo]),
			[id_actividad] = isnull(@p_id_actividad,[id_actividad]),
			[id_SesionActividad] = isnull(@p_id_SesionActividad,[id_SesionActividad]),
			[id_ejecutores] = isnull(@p_id_ejecutores,[id_ejecutores]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[fecha_inicio] = isnull(@p_fecha_inicio,[fecha_inicio]),
			[duracion] = isnull(@p_duracion,[duracion]),
			[texto] = isnull(@p_texto,[texto]),
			[porcentaje_avance] = isnull(@p_porcentaje_avance,[porcentaje_avance]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
