IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_pro_reporteActividad]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_pro_reporteActividad]
GO
CREATE PROCEDURE [ins_pro_reporteActividad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_reporteActividad varchar(300),
		@p_reporteActividad_codigo varchar(100),
		@p_id_actividad int,
		@p_id_SesionActividad int,
		@p_id_ejecutores int,
		@p_id_sucursal int,
		@p_fecha_inicio smalldatetime,
		@p_duracion float,
		@p_texto varchar(3000),
		@p_porcentaje_avance float,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_reporteActividad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[reporteActividad],
			[reporteActividad_codigo],
			[id_actividad],
			[id_SesionActividad],
			[id_ejecutores],
			[id_sucursal],
			[fecha_inicio],
			[duracion],
			[texto],
			[porcentaje_avance],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_reporteActividad,
			@p_reporteActividad_codigo,
			@p_id_actividad,
			@p_id_SesionActividad,
			@p_id_ejecutores,
			@p_id_sucursal,
			@p_fecha_inicio,
			@p_duracion,
			@p_texto,
			@p_porcentaje_avance,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_reporteActividad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
