CREATE PROCEDURE [aud_pro_reporteActividad]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [pro_reporteActividad].id as id_tabla,
	[pro_reporteActividad].id_usuario_modifico as id_usuario_modifico,
	[pro_reporteActividad].id_usuario_creo as id_usuario_creo,
	[pro_reporteActividad].fechaModificacion as fechaModificacion,
	[pro_reporteActividad].fechaCreacion as fechaCreacion,
	[pro_reporteActividad].active as active,
	[pro_reporteActividad].[reporteActividad] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [pro_reporteActividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_reporteActividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_reporteActividad].[id_usuario_creo]
	where ' + @p_filtro)
END
