CREATE  VIEW [view_pro_rol] AS
SELECT 	[pro_rol].[id] AS [id],
		[pro_rol].[uid] AS [uid],
		[pro_rol].[eid] AS [eid],
		[pro_rol].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_rol].[id_usuario_creo] AS [id_usuario_creo],
		[pro_rol].[fechaModificacion] AS [fechaModificacion],
		[pro_rol].[fechaCreacion] AS [fechaCreacion],
		[pro_rol].[active] AS [active],
		[pro_rol].[rol] AS [rol],
		[pro_rol].[rol_codigo] AS [rol_codigo],
		[pro_rol].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_rol]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_rol].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_rol].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_rol].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_rol].active=1
