		[pro_rol_contacto].[fechaModificacion] AS [fechaModificacion],
		[pro_rol_contacto].[fechaCreacion] AS [fechaCreacion],
		[pro_rol_contacto].[active] AS [active],
		[pro_rol_contacto].[rol_contacto] AS [rol_contacto],
		[pro_rol_contacto].[id_rol] AS [id_rol],
[pro_rol].[rol] as [pro_rol_rol],
[pro_rol].[rol_codigo] as [pro_rol_rol_codigo],
[pro_rol].[cmm] as [pro_rol_cmm],
