GO
CREATE PROCEDURE [aud_pro_rol_contacto]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [pro_rol_contacto].id as id_tabla,
	[pro_rol_contacto].id_usuario_modifico as id_usuario_modifico,
	[pro_rol_contacto].id_usuario_creo as id_usuario_creo,
	[pro_rol_contacto].fechaModificacion as fechaModificacion,
	[pro_rol_contacto].fechaCreacion as fechaCreacion,
	[pro_rol_contacto].active as active,
	[pro_rol_contacto].[rol_contacto] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [pro_rol_contacto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_rol_contacto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_rol_contacto].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
