GO
CREATE  VIEW [view_pro_SesionActividad] AS
SELECT 	[pro_SesionActividad].[id] AS [id],
		[pro_SesionActividad].[uid] AS [uid],
		[pro_SesionActividad].[eid] AS [eid],
		[pro_SesionActividad].[id_usuario_modifico] AS [id_usuario_modifico],
		[pro_SesionActividad].[id_usuario_creo] AS [id_usuario_creo],
		[pro_SesionActividad].[fechaModificacion] AS [fechaModificacion],
		[pro_SesionActividad].[fechaCreacion] AS [fechaCreacion],
		[pro_SesionActividad].[active] AS [active],
		[pro_SesionActividad].[SesionActividad] AS [SesionActividad],
		[pro_SesionActividad].[SesionActividad_codigo] AS [SesionActividad_codigo],
		[pro_SesionActividad].[id_actividad] AS [id_actividad],
[pro_actividad].[actividad] as [pro_actividad_actividad],
[pro_actividad].[actividad_codigo] as [pro_actividad_actividad_codigo],
[pro_actividad].[descripcionDetallada] as [pro_actividad_descripcionDetallada],
[pro_actividad].[fechainicioPlaneada] as [pro_actividad_fechainicioPlaneada],
[pro_actividad].[fechainicioProyectada] as [pro_actividad_fechainicioProyectada],
[pro_actividad].[fechaInicioReal] as [pro_actividad_fechaInicioReal],
[pro_actividad].[duracion] as [pro_actividad_duracion],
[pro_actividad].[fechaTerminacionPlaneada] as [pro_actividad_fechaTerminacionPlaneada],
[pro_actividad].[fechaTerminacionProyectada] as [pro_actividad_fechaTerminacionProyectada],
[pro_actividad].[fechaTerminacionReal] as [pro_actividad_fechaTerminacionReal],
[pro_actividad].[cmm] as [pro_actividad_cmm],
		[pro_SesionActividad].[id_ejecutores] AS [id_ejecutores],
[pro_ejecutores].[ejecutores] as [pro_ejecutores_ejecutores],
[pro_ejecutores].[ejecutores_codigo] as [pro_ejecutores_ejecutores_codigo],
[pro_ejecutores].[costo] as [pro_ejecutores_costo],
[pro_ejecutores].[unidadTiempo] as [pro_ejecutores_unidadTiempo],
[pro_ejecutores].[id_horarioTrabajo] as [pro_ejecutores_id_horarioTrabajo],
[pro_ejecutores].[id_usuario] as [pro_ejecutores_id_usuario],
[pro_ejecutores].[id_horarioEjecutores] as [pro_ejecutores_id_horarioEjecutores],
[pro_ejecutores].[cmm] as [pro_ejecutores_cmm],
		[pro_SesionActividad].[id_GrupoSesion] AS [id_GrupoSesion],
[pro_GrupoSesion].[GrupoSesion] as [pro_GrupoSesion_GrupoSesion],
[pro_GrupoSesion].[GrupoSesion_codigo] as [pro_GrupoSesion_GrupoSesion_codigo],
[pro_GrupoSesion].[cmm] as [pro_GrupoSesion_cmm],
		[pro_SesionActividad].[duracion] AS [duracion],
		[pro_SesionActividad].[descripcion] AS [descripcion],
		[pro_SesionActividad].[fecha_inicio] AS [fecha_inicio],
		[pro_SesionActividad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [pro_SesionActividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[pro_SesionActividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[pro_SesionActividad].[id_usuario_creo]
	INNER JOIN [pro_actividad] ON [pro_actividad].id=[pro_SesionActividad].[id_actividad]
	INNER JOIN [pro_ejecutores] ON [pro_ejecutores].id=[pro_SesionActividad].[id_ejecutores]
	INNER JOIN [pro_GrupoSesion] ON [pro_GrupoSesion].id=[pro_SesionActividad].[id_GrupoSesion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [pro_SesionActividad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [pro_SesionActividad].active=1
GO
