GO
CREATE PROCEDURE [ins_pro_SesionActividad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_SesionActividad varchar(300),
		@p_SesionActividad_codigo varchar(100),
		@p_id_actividad int,
		@p_id_ejecutores int,
		@p_id_GrupoSesion int,
		@p_duracion float,
		@p_descripcion varchar(3000),
		@p_fecha_inicio smalldatetime,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_SesionActividad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[SesionActividad],
			[SesionActividad_codigo],
			[id_actividad],
			[id_ejecutores],
			[id_GrupoSesion],
			[duracion],
			[descripcion],
			[fecha_inicio],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_SesionActividad,
			@p_SesionActividad_codigo,
			@p_id_actividad,
			@p_id_ejecutores,
			@p_id_GrupoSesion,
			@p_duracion,
			@p_descripcion,
			@p_fecha_inicio,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_SesionActividad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
