IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_rep_campoReporte]')) DROP VIEW [dbo].[view_rep_campoReporte]
GO
CREATE  VIEW [view_rep_campoReporte] AS
SELECT 	[rep_campoReporte].[id] AS [id],
		[rep_campoReporte].[uid] AS [uid],
		[rep_campoReporte].[eid] AS [eid],
		[rep_campoReporte].[id_usuario_modifico] AS [id_usuario_modifico],
		[rep_campoReporte].[id_usuario_creo] AS [id_usuario_creo],
		[rep_campoReporte].[fechaModificacion] AS [fechaModificacion],
		[rep_campoReporte].[fechaCreacion] AS [fechaCreacion],
		[rep_campoReporte].[active] AS [active],
		[rep_campoReporte].[campoReporte] AS [campoReporte],
		[rep_campoReporte].[campoReporte_codigo] AS [campoReporte_codigo],
		[rep_campoReporte].[id_reporte] AS [id_reporte],
[rep_reporte].[reporte] as [rep_reporte_reporte],
[rep_reporte].[reporte_codigo] as [rep_reporte_reporte_codigo],
[rep_reporte].[id_funcionalidad] as [rep_reporte_id_funcionalidad],
[rep_reporte].[esFormato] as [rep_reporte_esFormato],
[rep_reporte].[tieneGraficos] as [rep_reporte_tieneGraficos],
[rep_reporte].[cabecera] as [rep_reporte_cabecera],
[rep_reporte].[orden] as [rep_reporte_orden],
[rep_reporte].[basica] as [rep_reporte_basica],
[rep_reporte].[cmm] as [rep_reporte_cmm],
		[rep_campoReporte].[id_tipoCampoReporte] AS [id_tipoCampoReporte],
[rep_tipoCampoReporte].[tipoCampoReporte] as [rep_tipoCampoReporte_tipoCampoReporte],
[rep_tipoCampoReporte].[tipoCampoReporte_codigo] as [rep_tipoCampoReporte_tipoCampoReporte_codigo],
[rep_tipoCampoReporte].[cmm] as [rep_tipoCampoReporte_cmm],
		[rep_campoReporte].[tabla] AS [tabla],
		[rep_campoReporte].[valorDefecto] AS [valorDefecto],
		[rep_campoReporte].[esParametro] AS [esParametro],
		[rep_campoReporte].[esSerie] AS [esSerie],
		[rep_campoReporte].[parametroTotal] AS [parametroTotal],
		[rep_campoReporte].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_campoReporte]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_campoReporte].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_campoReporte].[id_usuario_creo]
	INNER JOIN [rep_reporte] ON [rep_reporte].id=[rep_campoReporte].[id_reporte]
	INNER JOIN [rep_tipoCampoReporte] ON [rep_tipoCampoReporte].id=[rep_campoReporte].[id_tipoCampoReporte]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_campoReporte].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [rep_campoReporte].active=1
GO
