			@p_parametroTotal,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [rep_campoReporte] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
