CREATE PROCEDURE [aud_rep_campoReporte]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [rep_campoReporte].id as id_tabla,
	[rep_campoReporte].id_usuario_modifico as id_usuario_modifico,
	[rep_campoReporte].id_usuario_creo as id_usuario_creo,
	[rep_campoReporte].fechaModificacion as fechaModificacion,
	[rep_campoReporte].fechaCreacion as fechaCreacion,
	[rep_campoReporte].active as active,
	[rep_campoReporte].[campoReporte] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [rep_campoReporte]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_campoReporte].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_campoReporte].[id_usuario_creo]
	where ' + @p_filtro)
END
