IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_rep_categoria]')) DROP VIEW [dbo].[view_rep_categoria]
GO
CREATE  VIEW [view_rep_categoria] AS
SELECT 	[rep_categoria].[id] AS [id],
		[rep_categoria].[uid] AS [uid],
		[rep_categoria].[eid] AS [eid],
		[rep_categoria].[id_usuario_modifico] AS [id_usuario_modifico],
		[rep_categoria].[id_usuario_creo] AS [id_usuario_creo],
		[rep_categoria].[fechaModificacion] AS [fechaModificacion],
		[rep_categoria].[fechaCreacion] AS [fechaCreacion],
		[rep_categoria].[active] AS [active],
		[rep_categoria].[categoria] AS [categoria],
		[rep_categoria].[categoria_codigo] AS [categoria_codigo],
		[rep_categoria].[id_categoria] AS [id_categoria],
[rep_categoria_padre].[categoria] as [rep_categoria_padre_categoria],
[rep_categoria_padre].[categoria_codigo] as [rep_categoria_padre_categoria_codigo],
[rep_categoria_padre].[id_categoria] as [rep_categoria_padre_id_categoria],
[rep_categoria_padre].[cmm] as [rep_categoria_padre_cmm],
		[rep_categoria].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_categoria]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_categoria].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_categoria].[id_usuario_creo]
	INNER JOIN [rep_categoria] AS [rep_categoria_padre] ON [rep_categoria_padre].id=[rep_categoria].[id_categoria]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_categoria].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [rep_categoria].active=1
GO
