CREATE PROCEDURE [ins_rep_reporte_categoria]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_reporte_categoria varchar(300),
		@p_id_categoria int,
		@p_id_reporte int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [rep_reporte_categoria]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[reporte_categoria],
			[id_categoria],
			[id_reporte],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_reporte_categoria,
			@p_id_categoria,
			@p_id_reporte,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [rep_reporte_categoria] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
