IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_rep_indicador]')) DROP VIEW [dbo].[view_rep_indicador]
GO
CREATE  VIEW [view_rep_indicador] AS
SELECT 	[rep_indicador].[id] AS [id],
		[rep_indicador].[uid] AS [uid],
		[rep_indicador].[eid] AS [eid],
		[rep_indicador].[id_usuario_modifico] AS [id_usuario_modifico],
		[rep_indicador].[id_usuario_creo] AS [id_usuario_creo],
		[rep_indicador].[fechaModificacion] AS [fechaModificacion],
		[rep_indicador].[fechaCreacion] AS [fechaCreacion],
		[rep_indicador].[active] AS [active],
		[rep_indicador].[indicador] AS [indicador],
		[rep_indicador].[indicador_codigo] AS [indicador_codigo],
		[rep_indicador].[id_reporte] AS [id_reporte],
[rep_reporte].[reporte] as [rep_reporte_reporte],
[rep_reporte].[reporte_codigo] as [rep_reporte_reporte_codigo],
[rep_reporte].[id_funcionalidad] as [rep_reporte_id_funcionalidad],
[rep_reporte].[esFormato] as [rep_reporte_esFormato],
[rep_reporte].[tieneGraficos] as [rep_reporte_tieneGraficos],
[rep_reporte].[cabecera] as [rep_reporte_cabecera],
[rep_reporte].[orden] as [rep_reporte_orden],
[rep_reporte].[basica] as [rep_reporte_basica],
[rep_reporte].[cmm] as [rep_reporte_cmm],
		[rep_indicador].[titulo] AS [titulo],
		[rep_indicador].[descripcion] AS [descripcion],
		[rep_indicador].[cabecera] AS [cabecera],
		[rep_indicador].[seccion1] AS [seccion1],
		[rep_indicador].[seccion2] AS [seccion2],
		[rep_indicador].[seccion3] AS [seccion3],
		[rep_indicador].[seccion4] AS [seccion4],
		[rep_indicador].[seccion5] AS [seccion5],
		[rep_indicador].[seccion6] AS [seccion6],
		[rep_indicador].[seccion7] AS [seccion7],
		[rep_indicador].[seccion8] AS [seccion8],
		[rep_indicador].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_indicador]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_indicador].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_indicador].[id_usuario_creo]
	INNER JOIN [rep_reporte] ON [rep_reporte].id=[rep_indicador].[id_reporte]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_indicador].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [rep_indicador].active=1
GO
