IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_rep_opcionReporte]')) DROP VIEW [dbo].[view_rep_opcionReporte]
GO
CREATE  VIEW [view_rep_opcionReporte] AS
SELECT 	[rep_opcionReporte].[id] AS [id],
		[rep_opcionReporte].[uid] AS [uid],
		[rep_opcionReporte].[eid] AS [eid],
		[rep_opcionReporte].[id_usuario_modifico] AS [id_usuario_modifico],
		[rep_opcionReporte].[id_usuario_creo] AS [id_usuario_creo],
		[rep_opcionReporte].[fechaModificacion] AS [fechaModificacion],
		[rep_opcionReporte].[fechaCreacion] AS [fechaCreacion],
		[rep_opcionReporte].[active] AS [active],
		[rep_opcionReporte].[opcionReporte] AS [opcionReporte],
		[rep_opcionReporte].[opcionReporte_codigo] AS [opcionReporte_codigo],
		[rep_opcionReporte].[id_reporte] AS [id_reporte],
[rep_reporte].[reporte] as [rep_reporte_reporte],
[rep_reporte].[reporte_codigo] as [rep_reporte_reporte_codigo],
[rep_reporte].[id_funcionalidad] as [rep_reporte_id_funcionalidad],
[rep_reporte].[esFormato] as [rep_reporte_esFormato],
[rep_reporte].[tieneGraficos] as [rep_reporte_tieneGraficos],
[rep_reporte].[cabecera] as [rep_reporte_cabecera],
[rep_reporte].[orden] as [rep_reporte_orden],
[rep_reporte].[basica] as [rep_reporte_basica],
[rep_reporte].[cmm] as [rep_reporte_cmm],
		[rep_opcionReporte].[defecto] AS [defecto],
		[rep_opcionReporte].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_opcionReporte]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_opcionReporte].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_opcionReporte].[id_usuario_creo]
	INNER JOIN [rep_reporte] ON [rep_reporte].id=[rep_opcionReporte].[id_reporte]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_opcionReporte].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [rep_opcionReporte].active=1
GO
