IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_rep_opcionReporte]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_rep_opcionReporte]
GO
CREATE PROCEDURE [ins_rep_opcionReporte]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_opcionReporte varchar(300),
		@p_opcionReporte_codigo varchar(100),
		@p_id_reporte int,
		@p_defecto bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [rep_opcionReporte]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[opcionReporte],
			[opcionReporte_codigo],
			[id_reporte],
			[defecto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_opcionReporte,
			@p_opcionReporte_codigo,
			@p_id_reporte,
			@p_defecto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [rep_opcionReporte] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
