GO
CREATE  VIEW [view_rep_origenDato] AS
SELECT 	[rep_origenDato].[id] AS [id],
		[rep_origenDato].[uid] AS [uid],
		[rep_origenDato].[eid] AS [eid],
		[rep_origenDato].[id_usuario_modifico] AS [id_usuario_modifico],
		[rep_origenDato].[id_usuario_creo] AS [id_usuario_creo],
		[rep_origenDato].[fechaModificacion] AS [fechaModificacion],
		[rep_origenDato].[fechaCreacion] AS [fechaCreacion],
		[rep_origenDato].[active] AS [active],
		[rep_origenDato].[origenDato] AS [origenDato],
		[rep_origenDato].[origenDato_codigo] AS [origenDato_codigo],
		[rep_origenDato].[id_reporte] AS [id_reporte],
[rep_reporte].[reporte] as [rep_reporte_reporte],
[rep_reporte].[reporte_codigo] as [rep_reporte_reporte_codigo],
[rep_reporte].[id_funcionalidad] as [rep_reporte_id_funcionalidad],
[rep_reporte].[esFormato] as [rep_reporte_esFormato],
[rep_reporte].[tieneGraficos] as [rep_reporte_tieneGraficos],
[rep_reporte].[cabecera] as [rep_reporte_cabecera],
[rep_reporte].[orden] as [rep_reporte_orden],
[rep_reporte].[basica] as [rep_reporte_basica],
[rep_reporte].[cmm] as [rep_reporte_cmm],
		[rep_origenDato].[duracion] AS [duracion],
		[rep_origenDato].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_origenDato]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_origenDato].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_origenDato].[id_usuario_creo]
	INNER JOIN [rep_reporte] ON [rep_reporte].id=[rep_origenDato].[id_reporte]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_origenDato].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [rep_origenDato].active=1
GO
