IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_rep_origenDato]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_rep_origenDato]
GO
CREATE PROCEDURE [ins_rep_origenDato]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_origenDato varchar(300),
		@p_origenDato_codigo varchar(100),
		@p_id_reporte int,
		@p_duracion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [rep_origenDato]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[origenDato],
			[origenDato_codigo],
			[id_reporte],
			[duracion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_origenDato,
			@p_origenDato_codigo,
			@p_id_reporte,
			@p_duracion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [rep_origenDato] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
