		[rep_reporte].[orden] AS [orden],
		[rep_reporte].[basica] AS [basica],
		[rep_reporte].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_reporte]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_reporte].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_reporte].[id_usuario_creo]
	INNER JOIN [gui_funcionalidad] ON [gui_funcionalidad].id=[rep_reporte].[id_funcionalidad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_reporte].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [rep_reporte].active=1
GO
