CREATE  VIEW [view_rep_reporte_categoria] AS
SELECT 	[rep_reporte_categoria].[id] AS [id],
		[rep_reporte_categoria].[uid] AS [uid],
		[rep_reporte_categoria].[eid] AS [eid],
		[rep_reporte_categoria].[id_usuario_modifico] AS [id_usuario_modifico],
		[rep_reporte_categoria].[id_usuario_creo] AS [id_usuario_creo],
		[rep_reporte_categoria].[fechaModificacion] AS [fechaModificacion],
		[rep_reporte_categoria].[fechaCreacion] AS [fechaCreacion],
		[rep_reporte_categoria].[active] AS [active],
		[rep_reporte_categoria].[reporte_categoria] AS [reporte_categoria],
		[rep_reporte_categoria].[id_categoria] AS [id_categoria],
[rep_categoria].[categoria] as [rep_categoria_categoria],
[rep_categoria].[categoria_codigo] as [rep_categoria_categoria_codigo],
[rep_categoria].[id_categoria] as [rep_categoria_id_categoria],
[rep_categoria].[cmm] as [rep_categoria_cmm],
		[rep_reporte_categoria].[id_reporte] AS [id_reporte],
[rep_reporte].[reporte] as [rep_reporte_reporte],
[rep_reporte].[reporte_codigo] as [rep_reporte_reporte_codigo],
[rep_reporte].[id_funcionalidad] as [rep_reporte_id_funcionalidad],
[rep_reporte].[esFormato] as [rep_reporte_esFormato],
[rep_reporte].[tieneGraficos] as [rep_reporte_tieneGraficos],
[rep_reporte].[cabecera] as [rep_reporte_cabecera],
[rep_reporte].[orden] as [rep_reporte_orden],
[rep_reporte].[basica] as [rep_reporte_basica],
[rep_reporte].[cmm] as [rep_reporte_cmm],
		[rep_reporte_categoria].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_reporte_categoria]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_reporte_categoria].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_reporte_categoria].[id_usuario_creo]
	INNER JOIN [rep_categoria] ON [rep_categoria].id=[rep_reporte_categoria].[id_categoria]
	INNER JOIN [rep_reporte] ON [rep_reporte].id=[rep_reporte_categoria].[id_reporte]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_reporte_categoria].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
