IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_rep_tipoCampoReporte]')) DROP VIEW [dbo].[view_rep_tipoCampoReporte]
GO
CREATE  VIEW [view_rep_tipoCampoReporte] AS
SELECT 	[rep_tipoCampoReporte].[id] AS [id],
		[rep_tipoCampoReporte].[uid] AS [uid],
		[rep_tipoCampoReporte].[eid] AS [eid],
		[rep_tipoCampoReporte].[id_usuario_modifico] AS [id_usuario_modifico],
		[rep_tipoCampoReporte].[id_usuario_creo] AS [id_usuario_creo],
		[rep_tipoCampoReporte].[fechaModificacion] AS [fechaModificacion],
		[rep_tipoCampoReporte].[fechaCreacion] AS [fechaCreacion],
		[rep_tipoCampoReporte].[active] AS [active],
		[rep_tipoCampoReporte].[tipoCampoReporte] AS [tipoCampoReporte],
		[rep_tipoCampoReporte].[tipoCampoReporte_codigo] AS [tipoCampoReporte_codigo],
		[rep_tipoCampoReporte].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [rep_tipoCampoReporte]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[rep_tipoCampoReporte].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[rep_tipoCampoReporte].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [rep_tipoCampoReporte].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [rep_tipoCampoReporte].active=1
GO
