IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_seg_cargo]')) DROP VIEW [dbo].[view_seg_cargo]
GO
CREATE  VIEW [view_seg_cargo] AS
SELECT 	[seg_cargo].[id] AS [id],
		[seg_cargo].[uid] AS [uid],
		[seg_cargo].[eid] AS [eid],
		[seg_cargo].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_cargo].[id_usuario_creo] AS [id_usuario_creo],
		[seg_cargo].[fechaModificacion] AS [fechaModificacion],
		[seg_cargo].[fechaCreacion] AS [fechaCreacion],
		[seg_cargo].[active] AS [active],
		[seg_cargo].[cargo] AS [cargo],
		[seg_cargo].[cargo_codigo] AS [cargo_codigo],
		[seg_cargo].[esTecnico] AS [esTecnico],
		[seg_cargo].[esComercial] AS [esComercial],
		[seg_cargo].[esCoordinador] AS [esCoordinador],
		[seg_cargo].[valorHora] AS [valorHora],
		[seg_cargo].[esAdministrativo] AS [esAdministrativo],
		[seg_cargo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_cargo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_cargo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_cargo].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_cargo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [seg_cargo].active=1
GO
