GO
CREATE PROCEDURE [upd_seg_cargo]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_cargo varchar(300) = null,
		@p_cargo_codigo varchar(100) = null,
		@p_esTecnico bit = null,
		@p_esComercial bit = null,
		@p_esCoordinador bit = null,
		@p_valorHora money = null,
		@p_esAdministrativo bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [seg_cargo]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[cargo] = isnull(@p_cargo,[cargo]),
			[cargo_codigo] = isnull(@p_cargo_codigo,[cargo_codigo]),
			[esTecnico] = isnull(@p_esTecnico,[esTecnico]),
			[esComercial] = isnull(@p_esComercial,[esComercial]),
			[esCoordinador] = isnull(@p_esCoordinador,[esCoordinador]),
			[valorHora] = isnull(@p_valorHora,[valorHora]),
			[esAdministrativo] = isnull(@p_esAdministrativo,[esAdministrativo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
