IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_cargo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_cargo]
GO
CREATE PROCEDURE [ins_seg_cargo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_cargo varchar(300),
		@p_cargo_codigo varchar(100),
		@p_esTecnico bit,
		@p_esComercial bit,
		@p_esCoordinador bit,
		@p_valorHora money,
		@p_esAdministrativo bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_cargo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[cargo],
			[cargo_codigo],
			[esTecnico],
			[esComercial],
			[esCoordinador],
			[valorHora],
			[esAdministrativo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_cargo,
			@p_cargo_codigo,
			@p_esTecnico,
			@p_esComercial,
			@p_esCoordinador,
			@p_valorHora,
			@p_esAdministrativo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_cargo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
