		[seg_cargo_actividad].[uid] AS [uid],
		[seg_cargo_actividad].[eid] AS [eid],
		[seg_cargo_actividad].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_cargo_actividad].[id_usuario_creo] AS [id_usuario_creo],
		[seg_cargo_actividad].[fechaModificacion] AS [fechaModificacion],
		[seg_cargo_actividad].[fechaCreacion] AS [fechaCreacion],
		[seg_cargo_actividad].[active] AS [active],
		[seg_cargo_actividad].[cargo_actividad] AS [cargo_actividad],
		[seg_cargo_actividad].[id_cargo] AS [id_cargo],
[seg_cargo].[cargo] as [seg_cargo_cargo],
[seg_cargo].[cargo_codigo] as [seg_cargo_cargo_codigo],
[seg_cargo].[esTecnico] as [seg_cargo_esTecnico],
[seg_cargo].[esComercial] as [seg_cargo_esComercial],
[seg_cargo].[esCoordinador] as [seg_cargo_esCoordinador],
[seg_cargo].[valorHora] as [seg_cargo_valorHora],
[seg_cargo].[esAdministrativo] as [seg_cargo_esAdministrativo],
[seg_cargo].[cmm] as [seg_cargo_cmm],
		[seg_cargo_actividad].[id_catalogo.actividad] AS [id_catalogo.actividad],
[cat_catalogo.actividad].[catalogo.actividad] as [cat_catalogo.actividad_catalogo.actividad],
[cat_catalogo.actividad].[esProductiva] as [cat_catalogo.actividad_esProductiva],
[cat_catalogo.actividad].[duracionEstimada] as [cat_catalogo.actividad_duracionEstimada],
[cat_catalogo.actividad].[procedimiento] as [cat_catalogo.actividad_procedimiento],
[cat_catalogo.actividad].[dias_garantia] as [cat_catalogo.actividad_dias_garantia],
[cat_catalogo.actividad].[cmm] as [cat_catalogo.actividad_cmm],
		[cat_catalogo_actividad].[catalogo_codigo] AS [cat_catalogo_actividad_catalogo_codigo],
		[cat_catalogo_actividad].[codigoInventario] AS [cat_catalogo_actividad_codigoInventario],
		[cat_catalogo_actividad].[precioVenta] AS [cat_catalogo_actividad_precioVenta],
		[cat_catalogo_actividad].[tiempoConsecucion] AS [cat_catalogo_actividad_tiempoConsecucion],
		[cat_catalogo_actividad].[esNacional] AS [cat_catalogo_actividad_esNacional],
		[cat_catalogo_actividad].[id_familia] AS [cat_catalogo_actividad_id_familia],
		[cat_catalogo_actividad].[id_subtipoCatalogo] AS [cat_catalogo_actividad_id_subtipoCatalogo],
		[cat_catalogo_actividad].[id_unidad] AS [cat_catalogo_actividad_id_unidad],
		[cat_catalogo_actividad].[id_impuesto] AS [cat_catalogo_actividad_id_impuesto],
		[cat_catalogo_actividad].[descripcion] AS [cat_catalogo_actividad_descripcion],
		[cat_catalogo_actividad].[bloquearCostear] AS [cat_catalogo_actividad_bloquearCostear],
		[cat_catalogo_actividad].[cmm] AS [cat_catalogo_actividad_cmm],
		[seg_cargo_actividad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_cargo_actividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_cargo_actividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_cargo_actividad].[id_usuario_creo]
	INNER JOIN [seg_cargo] ON [seg_cargo].id=[seg_cargo_actividad].[id_cargo]
	INNER JOIN [cat_catalogo.actividad] ON [cat_catalogo.actividad].id=[seg_cargo_actividad].[id_catalogo.actividad]
	INNER JOIN [cat_catalogo] aS [cat_catalogo_actividad] ON [cat_catalogo.actividad].id = [cat_catalogo_actividad].id
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_cargo_actividad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
