IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_cargo_actividad]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_cargo_actividad]
GO
CREATE PROCEDURE [ins_seg_cargo_actividad]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_cargo_actividad varchar(300),
		@p_id_cargo int,
		@p_id_catalogo_actividad int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_cargo_actividad]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[cargo_actividad],
			[id_cargo],
			[id_catalogo.actividad],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_cargo_actividad,
			@p_id_cargo,
			@p_id_catalogo_actividad,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_cargo_actividad] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
