CREATE PROCEDURE [aud_seg_cargo_actividad]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [seg_cargo_actividad].id as id_tabla,
	[seg_cargo_actividad].id_usuario_modifico as id_usuario_modifico,
	[seg_cargo_actividad].id_usuario_creo as id_usuario_creo,
	[seg_cargo_actividad].fechaModificacion as fechaModificacion,
	[seg_cargo_actividad].fechaCreacion as fechaCreacion,
	[seg_cargo_actividad].active as active,
	[seg_cargo_actividad].[cargo_actividad] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [seg_cargo_actividad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_cargo_actividad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_cargo_actividad].[id_usuario_creo]
	where ' + @p_filtro)
END
