[seg_cargo].[cmm] as [seg_cargo_cmm],
		[seg_cargo_envioCorreo].[id_envioCorreo] AS [id_envioCorreo],
[gen_envioCorreo].[envioCorreo] as [gen_envioCorreo_envioCorreo],
[gen_envioCorreo].[envioCorreo_codigo] as [gen_envioCorreo_envioCorreo_codigo],
[gen_envioCorreo].[estrategia] as [gen_envioCorreo_estrategia],
[gen_envioCorreo].[tabla] as [gen_envioCorreo_tabla],
[gen_envioCorreo].[id_reporte] as [gen_envioCorreo_id_reporte],
[gen_envioCorreo].[correoAdicional] as [gen_envioCorreo_correoAdicional],
[gen_envioCorreo].[plantillaAdjunto] as [gen_envioCorreo_plantillaAdjunto],
[gen_envioCorreo].[id_subtipoDocumento] as [gen_envioCorreo_id_subtipoDocumento],
[gen_envioCorreo].[id_estadoTipoDocumento] as [gen_envioCorreo_id_estadoTipoDocumento],
[gen_envioCorreo].[cantidadMensajes] as [gen_envioCorreo_cantidadMensajes],
[gen_envioCorreo].[tiempo_por_mensajes] as [gen_envioCorreo_tiempo_por_mensajes],
[gen_envioCorreo].[cantidadReintento] as [gen_envioCorreo_cantidadReintento],
[gen_envioCorreo].[adjuntarArchivo] as [gen_envioCorreo_adjuntarArchivo],
[gen_envioCorreo].[id_remitenteCorreo] as [gen_envioCorreo_id_remitenteCorreo],
[gen_envioCorreo].[cmm] as [gen_envioCorreo_cmm],
		[seg_cargo_envioCorreo].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_cargo_envioCorreo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_cargo_envioCorreo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_cargo_envioCorreo].[id_usuario_creo]
	INNER JOIN [seg_cargo] ON [seg_cargo].id=[seg_cargo_envioCorreo].[id_cargo]
	INNER JOIN [gen_envioCorreo] ON [gen_envioCorreo].id=[seg_cargo_envioCorreo].[id_envioCorreo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_cargo_envioCorreo].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
