IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_cargo_envioCorreo]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_cargo_envioCorreo]
GO
CREATE PROCEDURE [ins_seg_cargo_envioCorreo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_cargo_envioCorreo varchar(300),
		@p_id_cargo int,
		@p_id_envioCorreo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_cargo_envioCorreo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[cargo_envioCorreo],
			[id_cargo],
			[id_envioCorreo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_cargo_envioCorreo,
			@p_id_cargo,
			@p_id_envioCorreo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_cargo_envioCorreo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
