CREATE PROCEDURE [ins_seg_grupo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_grupo varchar(300),
		@p_grupo_codigo varchar(100),
		@p_activo bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_grupo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[grupo],
			[grupo_codigo],
			[activo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_grupo,
			@p_grupo_codigo,
			@p_activo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_grupo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
