CREATE PROCEDURE [aud_seg_grupo]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [seg_grupo].id as id_tabla,
	[seg_grupo].id_usuario_modifico as id_usuario_modifico,
	[seg_grupo].id_usuario_creo as id_usuario_creo,
	[seg_grupo].fechaModificacion as fechaModificacion,
	[seg_grupo].fechaCreacion as fechaCreacion,
	[seg_grupo].active as active,
	[seg_grupo].[grupo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [seg_grupo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_grupo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_grupo].[id_usuario_creo]
	where ' + @p_filtro)
END
