CREATE  VIEW [view_seg_perfil_bloqueHome] AS
SELECT 	[seg_perfil_bloqueHome].[id] AS [id],
		[seg_perfil_bloqueHome].[uid] AS [uid],
		[seg_perfil_bloqueHome].[eid] AS [eid],
		[seg_perfil_bloqueHome].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_perfil_bloqueHome].[id_usuario_creo] AS [id_usuario_creo],
		[seg_perfil_bloqueHome].[fechaModificacion] AS [fechaModificacion],
		[seg_perfil_bloqueHome].[fechaCreacion] AS [fechaCreacion],
		[seg_perfil_bloqueHome].[active] AS [active],
		[seg_perfil_bloqueHome].[perfil_bloqueHome] AS [perfil_bloqueHome],
		[seg_perfil_bloqueHome].[id_perfil] AS [id_perfil],
[seg_perfil].[perfil] as [seg_perfil_perfil],
[seg_perfil].[perfil_codigo] as [seg_perfil_perfil_codigo],
[seg_perfil].[descripcion] as [seg_perfil_descripcion],
[seg_perfil].[mostrarBotones] as [seg_perfil_mostrarBotones],
[seg_perfil].[paraCliente] as [seg_perfil_paraCliente],
[seg_perfil].[paraProveedor] as [seg_perfil_paraProveedor],
[seg_perfil].[cmm] as [seg_perfil_cmm],
		[seg_perfil_bloqueHome].[id_bloqueHome] AS [id_bloqueHome],
[gui_bloqueHome].[bloqueHome] as [gui_bloqueHome_bloqueHome],
[gui_bloqueHome].[bloqueHome_codigo] as [gui_bloqueHome_bloqueHome_codigo],
[gui_bloqueHome].[nombreControl] as [gui_bloqueHome_nombreControl],
[gui_bloqueHome].[urlBusqueda] as [gui_bloqueHome_urlBusqueda],
[gui_bloqueHome].[urlNuevo] as [gui_bloqueHome_urlNuevo],
[gui_bloqueHome].[orden] as [gui_bloqueHome_orden],
[gui_bloqueHome].[colorModulo] as [gui_bloqueHome_colorModulo],
[gui_bloqueHome].[esGenerico] as [gui_bloqueHome_esGenerico],
[gui_bloqueHome].[filtro] as [gui_bloqueHome_filtro],
[gui_bloqueHome].[actualizacion] as [gui_bloqueHome_actualizacion],
[gui_bloqueHome].[cmm] as [gui_bloqueHome_cmm],
		[seg_perfil_bloqueHome].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_perfil_bloqueHome]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_perfil_bloqueHome].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_perfil_bloqueHome].[id_usuario_creo]
	INNER JOIN [seg_perfil] ON [seg_perfil].id=[seg_perfil_bloqueHome].[id_perfil]
	INNER JOIN [gui_bloqueHome] ON [gui_bloqueHome].id=[seg_perfil_bloqueHome].[id_bloqueHome]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_perfil_bloqueHome].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
