	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [seg_perfil_bloqueHome].id as id_tabla,
	[seg_perfil_bloqueHome].id_usuario_modifico as id_usuario_modifico,
	[seg_perfil_bloqueHome].id_usuario_creo as id_usuario_creo,
	[seg_perfil_bloqueHome].fechaModificacion as fechaModificacion,
	[seg_perfil_bloqueHome].fechaCreacion as fechaCreacion,
	[seg_perfil_bloqueHome].active as active,
	[seg_perfil_bloqueHome].[perfil_bloqueHome] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [seg_perfil_bloqueHome]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_perfil_bloqueHome].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_perfil_bloqueHome].[id_usuario_creo]
	where ' + @p_filtro)
END
