IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_seg_perfil_formulario]')) DROP VIEW [dbo].[view_seg_perfil_formulario]
GO
CREATE  VIEW [view_seg_perfil_formulario] AS
SELECT 	[seg_perfil_formulario].[id] AS [id],
		[seg_perfil_formulario].[uid] AS [uid],
		[seg_perfil_formulario].[eid] AS [eid],
		[seg_perfil_formulario].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_perfil_formulario].[id_usuario_creo] AS [id_usuario_creo],
		[seg_perfil_formulario].[fechaModificacion] AS [fechaModificacion],
		[seg_perfil_formulario].[fechaCreacion] AS [fechaCreacion],
		[seg_perfil_formulario].[active] AS [active],
		[seg_perfil_formulario].[perfil_formulario] AS [perfil_formulario],
		[seg_perfil_formulario].[id_perfil] AS [id_perfil],
[seg_perfil].[perfil] as [seg_perfil_perfil],
[seg_perfil].[perfil_codigo] as [seg_perfil_perfil_codigo],
[seg_perfil].[descripcion] as [seg_perfil_descripcion],
[seg_perfil].[mostrarBotones] as [seg_perfil_mostrarBotones],
[seg_perfil].[paraCliente] as [seg_perfil_paraCliente],
[seg_perfil].[paraProveedor] as [seg_perfil_paraProveedor],
[seg_perfil].[cmm] as [seg_perfil_cmm],
		[seg_perfil_formulario].[id_formulario] AS [id_formulario],
[gen_formulario].[formulario] as [gen_formulario_formulario],
[gen_formulario].[formulario_codigo] as [gen_formulario_formulario_codigo],
[gen_formulario].[duplicar] as [gen_formulario_duplicar],
[gen_formulario].[eliminarIntermedias] as [gen_formulario_eliminarIntermedias],
[gen_formulario].[id_configuracionAtributos] as [gen_formulario_id_configuracionAtributos],
[gen_formulario].[id_tabla_destino] as [gen_formulario_id_tabla_destino],
[gen_formulario].[cmm] as [gen_formulario_cmm],
[gen_formulario].[id_formulario] as [gen_formulario_id_formulario],
[gen_formulario].[condicion] as [gen_formulario_condicion],
[gen_formulario].[valorDefecto] as [gen_formulario_valorDefecto],
		[seg_perfil_formulario].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_perfil_formulario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_perfil_formulario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_perfil_formulario].[id_usuario_creo]
	INNER JOIN [seg_perfil] ON [seg_perfil].id=[seg_perfil_formulario].[id_perfil]
	INNER JOIN [gen_formulario] ON [gen_formulario].id=[seg_perfil_formulario].[id_formulario]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_perfil_formulario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
