GO
CREATE  VIEW [view_seg_perfil_funcionalidad] AS
SELECT 	[seg_perfil_funcionalidad].[id] AS [id],
		[seg_perfil_funcionalidad].[uid] AS [uid],
		[seg_perfil_funcionalidad].[eid] AS [eid],
		[seg_perfil_funcionalidad].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_perfil_funcionalidad].[id_usuario_creo] AS [id_usuario_creo],
		[seg_perfil_funcionalidad].[fechaModificacion] AS [fechaModificacion],
		[seg_perfil_funcionalidad].[fechaCreacion] AS [fechaCreacion],
		[seg_perfil_funcionalidad].[active] AS [active],
		[seg_perfil_funcionalidad].[perfil_funcionalidad] AS [perfil_funcionalidad],
		[seg_perfil_funcionalidad].[id_perfil] AS [id_perfil],
[seg_perfil].[perfil] as [seg_perfil_perfil],
[seg_perfil].[perfil_codigo] as [seg_perfil_perfil_codigo],
[seg_perfil].[descripcion] as [seg_perfil_descripcion],
[seg_perfil].[mostrarBotones] as [seg_perfil_mostrarBotones],
[seg_perfil].[paraCliente] as [seg_perfil_paraCliente],
[seg_perfil].[paraProveedor] as [seg_perfil_paraProveedor],
[seg_perfil].[cmm] as [seg_perfil_cmm],
		[seg_perfil_funcionalidad].[id_funcionalidad] AS [id_funcionalidad],
[gui_funcionalidad].[funcionalidad] as [gui_funcionalidad_funcionalidad],
[gui_funcionalidad].[funcionalidad_codigo] as [gui_funcionalidad_funcionalidad_codigo],
[gui_funcionalidad].[orden] as [gui_funcionalidad_orden],
[gui_funcionalidad].[id_funcionalidad] as [gui_funcionalidad_id_funcionalidad],
[gui_funcionalidad].[id_tipoFuncionalidad] as [gui_funcionalidad_id_tipoFuncionalidad],
[gui_funcionalidad].[id_aplicacion] as [gui_funcionalidad_id_aplicacion],
[gui_funcionalidad].[id_formulario] as [gui_funcionalidad_id_formulario],
[gui_funcionalidad].[cmm] as [gui_funcionalidad_cmm],
[gui_funcionalidad].[icono] as [gui_funcionalidad_icono],
[gui_funcionalidad].[valorDefecto] as [gui_funcionalidad_valorDefecto],
		[seg_perfil_funcionalidad].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_perfil_funcionalidad]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_perfil_funcionalidad].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_perfil_funcionalidad].[id_usuario_creo]
	INNER JOIN [seg_perfil] ON [seg_perfil].id=[seg_perfil_funcionalidad].[id_perfil]
	INNER JOIN [gui_funcionalidad] ON [gui_funcionalidad].id=[seg_perfil_funcionalidad].[id_funcionalidad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_perfil_funcionalidad].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
