IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_perfil_subtipoDocumento]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_perfil_subtipoDocumento]
GO
CREATE PROCEDURE [ins_seg_perfil_subtipoDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_perfil_subtipoDocumento varchar(300),
		@p_id_perfil int,
		@p_id_subtipoDocumento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_perfil_subtipoDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[perfil_subtipoDocumento],
			[id_perfil],
			[id_subtipoDocumento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_perfil_subtipoDocumento,
			@p_id_perfil,
			@p_id_subtipoDocumento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_perfil_subtipoDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
