SELECT 	[seg_perfil_tercero].[id] AS [id],
		[seg_perfil_tercero].[uid] AS [uid],
		[seg_perfil_tercero].[eid] AS [eid],
		[seg_perfil_tercero].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_perfil_tercero].[id_usuario_creo] AS [id_usuario_creo],
		[seg_perfil_tercero].[fechaModificacion] AS [fechaModificacion],
		[seg_perfil_tercero].[fechaCreacion] AS [fechaCreacion],
		[seg_perfil_tercero].[active] AS [active],
		[seg_perfil_tercero].[perfil_tercero] AS [perfil_tercero],
		[seg_perfil_tercero].[id_perfil] AS [id_perfil],
[seg_perfil].[perfil] as [seg_perfil_perfil],
[seg_perfil].[perfil_codigo] as [seg_perfil_perfil_codigo],
[seg_perfil].[descripcion] as [seg_perfil_descripcion],
[seg_perfil].[mostrarBotones] as [seg_perfil_mostrarBotones],
[seg_perfil].[paraCliente] as [seg_perfil_paraCliente],
[seg_perfil].[paraProveedor] as [seg_perfil_paraProveedor],
[seg_perfil].[cmm] as [seg_perfil_cmm],
		[seg_perfil_tercero].[id_tercero] AS [id_tercero],
[ter_tercero].[tercero] as [ter_tercero_tercero],
[ter_tercero].[tercero_codigo] as [ter_tercero_tercero_codigo],
[ter_tercero].[tercero_nit] as [ter_tercero_tercero_nit],
[ter_tercero].[direccion] as [ter_tercero_direccion],
[ter_tercero].[contacto] as [ter_tercero_contacto],
[ter_tercero].[telefono] as [ter_tercero_telefono],
[ter_tercero].[fax] as [ter_tercero_fax],
[ter_tercero].[email] as [ter_tercero_email],
[ter_tercero].[website] as [ter_tercero_website],
[ter_tercero].[representante] as [ter_tercero_representante],
[ter_tercero].[notas] as [ter_tercero_notas],
[ter_tercero].[tercero_nombreCorto] as [ter_tercero_tercero_nombreCorto],
[ter_tercero].[esCliente] as [ter_tercero_esCliente],
[ter_tercero].[esProveedor] as [ter_tercero_esProveedor],
[ter_tercero].[esTransportador] as [ter_tercero_esTransportador],
[ter_tercero].[esFabricante] as [ter_tercero_esFabricante],
[ter_tercero].[esEmpresaPropia] as [ter_tercero_esEmpresaPropia],
[ter_tercero].[clasificacion] as [ter_tercero_clasificacion],
[ter_tercero].[id_zona] as [ter_tercero_id_zona],
[ter_tercero].[id_estadoTercero] as [ter_tercero_id_estadoTercero],
[ter_tercero].[id_naturalezaTercero] as [ter_tercero_id_naturalezaTercero],
[ter_tercero].[esProspecto] as [ter_tercero_esProspecto],
[ter_tercero].[id_formaPago] as [ter_tercero_id_formaPago],
[ter_tercero].[tiempoEntrega] as [ter_tercero_tiempoEntrega],
[ter_tercero].[cmm] as [ter_tercero_cmm],
		[seg_perfil_tercero].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_perfil_tercero]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_perfil_tercero].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_perfil_tercero].[id_usuario_creo]
	INNER JOIN [seg_perfil] ON [seg_perfil].id=[seg_perfil_tercero].[id_perfil]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[seg_perfil_tercero].[id_tercero]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_perfil_tercero].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
