IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_perfil_tercero]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_perfil_tercero]
GO
CREATE PROCEDURE [ins_seg_perfil_tercero]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_perfil_tercero varchar(300),
		@p_id_perfil int,
		@p_id_tercero int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_perfil_tercero]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[perfil_tercero],
			[id_perfil],
			[id_tercero],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_perfil_tercero,
			@p_id_perfil,
			@p_id_tercero,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_perfil_tercero] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
