[seg_usuario].[porcentajeComision] as [seg_usuario_porcentajeComision],
[seg_usuario].[accesoActivo] as [seg_usuario_accesoActivo],
[seg_usuario].[cambiarClave] as [seg_usuario_cambiarClave],
[seg_usuario].[fechaUltimoCambioClave_fh] as [seg_usuario_fechaUltimoCambioClave_fh],
[seg_usuario].[aplicaRecargo] as [seg_usuario_aplicaRecargo],
[seg_usuario].[sexo] as [seg_usuario_sexo],
[seg_usuario].[id_perfil] as [seg_usuario_id_perfil],
[seg_usuario].[id_cargo] as [seg_usuario_id_cargo],
[seg_usuario].[id_grupo] as [seg_usuario_id_grupo],
[seg_usuario].[id_zona] as [seg_usuario_id_zona],
[seg_usuario].[identificacion] as [seg_usuario_identificacion],
[seg_usuario].[id_usuario] as [seg_usuario_id_usuario],
[seg_usuario].[habilitado] as [seg_usuario_habilitado],
[seg_usuario].[idDispositivo] as [seg_usuario_idDispositivo],
[seg_usuario].[cmm] as [seg_usuario_cmm],
		[seg_preferencia].[id_funcionalidad] AS [id_funcionalidad],
[gui_funcionalidad].[funcionalidad] as [gui_funcionalidad_funcionalidad],
[gui_funcionalidad].[funcionalidad_codigo] as [gui_funcionalidad_funcionalidad_codigo],
[gui_funcionalidad].[orden] as [gui_funcionalidad_orden],
[gui_funcionalidad].[id_funcionalidad] as [gui_funcionalidad_id_funcionalidad],
[gui_funcionalidad].[id_tipoFuncionalidad] as [gui_funcionalidad_id_tipoFuncionalidad],
[gui_funcionalidad].[id_aplicacion] as [gui_funcionalidad_id_aplicacion],
[gui_funcionalidad].[id_formulario] as [gui_funcionalidad_id_formulario],
[gui_funcionalidad].[cmm] as [gui_funcionalidad_cmm],
[gui_funcionalidad].[icono] as [gui_funcionalidad_icono],
[gui_funcionalidad].[valorDefecto] as [gui_funcionalidad_valorDefecto],
		[seg_preferencia].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_preferencia]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_preferencia].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_preferencia].[id_usuario_creo]
	INNER JOIN [seg_usuario] ON [seg_usuario].id=[seg_preferencia].[id_usuario]
	INNER JOIN [gui_funcionalidad] ON [gui_funcionalidad].id=[seg_preferencia].[id_funcionalidad]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_preferencia].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [seg_preferencia].active=1
