IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_preferencia]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_preferencia]
GO
CREATE PROCEDURE [ins_seg_preferencia]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_preferencia varchar(300),
		@p_preferencia_codigo varchar(100),
		@p_valor varbinary,
		@p_id_usuario int,
		@p_id_funcionalidad int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_preferencia]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[preferencia],
			[preferencia_codigo],
			[valor],
			[id_usuario],
			[id_funcionalidad],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_preferencia,
			@p_preferencia_codigo,
			@p_valor,
			@p_id_usuario,
			@p_id_funcionalidad,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_preferencia] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
