		[seg_registroIntegracion].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_registroIntegracion].[id_usuario_creo] AS [id_usuario_creo],
		[seg_registroIntegracion].[fechaModificacion] AS [fechaModificacion],
		[seg_registroIntegracion].[fechaCreacion] AS [fechaCreacion],
