		[seg_registroIntegracion].[registroIntegracion] AS [registroIntegracion],
		[seg_registroIntegracion].[registroIntegracion_codigo] AS [registroIntegracion_codigo],
		[seg_registroIntegracion].[mensaje] AS [mensaje],
		[seg_registroIntegracion].[respuesta] AS [respuesta],
		[seg_registroIntegracion].[codigoRespuesta] AS [codigoRespuesta],
		[seg_registroIntegracion].[idObjeto] AS [idObjeto],
		[seg_registroIntegracion].[id_puntoIntegracion] AS [id_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion] as [syn_puntoIntegracion_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion_codigo] as [syn_puntoIntegracion_puntoIntegracion_codigo],
[syn_puntoIntegracion].[tablaLocal] as [syn_puntoIntegracion_tablaLocal],
[syn_puntoIntegracion].[condicion] as [syn_puntoIntegracion_condicion],
[syn_puntoIntegracion].[urlConsumir] as [syn_puntoIntegracion_urlConsumir],
[syn_puntoIntegracion].[id_puntoIntegracion] as [syn_puntoIntegracion_id_puntoIntegracion],
[syn_puntoIntegracion].[id_sistemaIntegrar] as [syn_puntoIntegracion_id_sistemaIntegrar],
[syn_puntoIntegracion].[metodo] as [syn_puntoIntegracion_metodo],
[syn_puntoIntegracion].[cantidadReintentos] as [syn_puntoIntegracion_cantidadReintentos],
[syn_puntoIntegracion].[intervaloReintentos] as [syn_puntoIntegracion_intervaloReintentos],
[syn_puntoIntegracion].[codigosReintentos] as [syn_puntoIntegracion_codigosReintentos],
[syn_puntoIntegracion].[cmm] as [syn_puntoIntegracion_cmm],
		[seg_registroIntegracion].[numeroReintento] AS [numeroReintento],
		[seg_registroIntegracion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_registroIntegracion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_registroIntegracion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_registroIntegracion].[id_usuario_creo]
	INNER JOIN [syn_puntoIntegracion] ON [syn_puntoIntegracion].id=[seg_registroIntegracion].[id_puntoIntegracion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_registroIntegracion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [seg_registroIntegracion].active=1
