GO
CREATE PROCEDURE [upd_seg_registroIntegracion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_registroIntegracion varchar(300) = null,
		@p_registroIntegracion_codigo varchar(100) = null,
		@p_mensaje varchar(8000) = null,
		@p_respuesta varchar(8000) = null,
		@p_codigoRespuesta varchar(20) = null,
		@p_idObjeto int = null,
		@p_id_puntoIntegracion int = null,
		@p_numeroReintento int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [seg_registroIntegracion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[registroIntegracion] = isnull(@p_registroIntegracion,[registroIntegracion]),
			[registroIntegracion_codigo] = isnull(@p_registroIntegracion_codigo,[registroIntegracion_codigo]),
			[mensaje] = isnull(@p_mensaje,[mensaje]),
			[respuesta] = isnull(@p_respuesta,[respuesta]),
			[codigoRespuesta] = isnull(@p_codigoRespuesta,[codigoRespuesta]),
			[idObjeto] = isnull(@p_idObjeto,[idObjeto]),
			[id_puntoIntegracion] = isnull(@p_id_puntoIntegracion,[id_puntoIntegracion]),
			[numeroReintento] = isnull(@p_numeroReintento,[numeroReintento]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
