IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_registroIntegracion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_registroIntegracion]
GO
CREATE PROCEDURE [ins_seg_registroIntegracion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_registroIntegracion varchar(300),
		@p_registroIntegracion_codigo varchar(100),
		@p_mensaje varchar(8000),
		@p_respuesta varchar(8000),
		@p_codigoRespuesta varchar(20),
		@p_idObjeto int,
		@p_id_puntoIntegracion int,
		@p_numeroReintento int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_registroIntegracion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[registroIntegracion],
			[registroIntegracion_codigo],
			[mensaje],
			[respuesta],
			[codigoRespuesta],
			[idObjeto],
			[id_puntoIntegracion],
			[numeroReintento],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_registroIntegracion,
			@p_registroIntegracion_codigo,
			@p_mensaje,
			@p_respuesta,
			@p_codigoRespuesta,
			@p_idObjeto,
			@p_id_puntoIntegracion,
			@p_numeroReintento,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_registroIntegracion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
