CREATE PROCEDURE [upd_seg_registroPeticion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_registroPeticion varchar(300) = null,
		@p_registroPeticion_codigo varchar(100) = null,
		@p_urlServicio varchar(1000) = null,
		@p_modulo varchar(100) = null,
		@p_aplicacion varchar(100) = null,
		@p_esExitosa bit = null,
		@p_mensajeRespuesta varchar(2000) = null,
		@p_id_usuario int = null,
		@p_tamanoPeticion float = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [seg_registroPeticion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[registroPeticion] = isnull(@p_registroPeticion,[registroPeticion]),
			[registroPeticion_codigo] = isnull(@p_registroPeticion_codigo,[registroPeticion_codigo]),
			[urlServicio] = isnull(@p_urlServicio,[urlServicio]),
			[modulo] = isnull(@p_modulo,[modulo]),
			[aplicacion] = isnull(@p_aplicacion,[aplicacion]),
			[esExitosa] = isnull(@p_esExitosa,[esExitosa]),
			[mensajeRespuesta] = isnull(@p_mensajeRespuesta,[mensajeRespuesta]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[tamanoPeticion] = isnull(@p_tamanoPeticion,[tamanoPeticion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
