	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [seg_registroPeticion].id as id_tabla,
	[seg_registroPeticion].id_usuario_modifico as id_usuario_modifico,
	[seg_registroPeticion].id_usuario_creo as id_usuario_creo,
	[seg_registroPeticion].fechaModificacion as fechaModificacion,
	[seg_registroPeticion].fechaCreacion as fechaCreacion,
	[seg_registroPeticion].active as active,
	[seg_registroPeticion].[registroPeticion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [seg_registroPeticion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_registroPeticion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_registroPeticion].[id_usuario_creo]
	where ' + @p_filtro)
END
