GO
CREATE  VIEW [view_seg_sesion] AS
SELECT 	[seg_sesion].[id] AS [id],
		[seg_sesion].[uid] AS [uid],
		[seg_sesion].[eid] AS [eid],
		[seg_sesion].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_sesion].[id_usuario_creo] AS [id_usuario_creo],
		[seg_sesion].[fechaModificacion] AS [fechaModificacion],
		[seg_sesion].[fechaCreacion] AS [fechaCreacion],
		[seg_sesion].[active] AS [active],
		[seg_sesion].[sesion] AS [sesion],
		[seg_sesion].[sesion_codigo] AS [sesion_codigo],
		[seg_sesion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_sesion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_sesion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_sesion].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_sesion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [seg_sesion].active=1
GO
