CREATE  VIEW [view_seg_sesionHistorico] AS
SELECT 	[seg_sesionHistorico].[id] AS [id],
		[seg_sesionHistorico].[uid] AS [uid],
		[seg_sesionHistorico].[eid] AS [eid],
		[seg_sesionHistorico].[id_usuario_modifico] AS [id_usuario_modifico],
		[seg_sesionHistorico].[id_usuario_creo] AS [id_usuario_creo],
		[seg_sesionHistorico].[fechaModificacion] AS [fechaModificacion],
		[seg_sesionHistorico].[fechaCreacion] AS [fechaCreacion],
		[seg_sesionHistorico].[active] AS [active],
		[seg_sesionHistorico].[sesion] AS [sesion],
		[seg_sesionHistorico].[sesion_codigo] AS [sesion_codigo],
		[seg_sesionHistorico].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_sesionHistorico]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_sesionHistorico].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_sesionHistorico].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_sesionHistorico].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [seg_sesionHistorico].active=1
