[seg_usuario_padre].[intentosFallidos] as [seg_usuario_padre_intentosFallidos],
[seg_usuario_padre].[numeroIngresos] as [seg_usuario_padre_numeroIngresos],
[seg_usuario_padre].[fechaUltimoIngreso_fh] as [seg_usuario_padre_fechaUltimoIngreso_fh],
[seg_usuario_padre].[fechaIntentoFallido_fh] as [seg_usuario_padre_fechaIntentoFallido_fh],
[seg_usuario_padre].[clave] as [seg_usuario_padre_clave],
[seg_usuario_padre].[nombre] as [seg_usuario_padre_nombre],
[seg_usuario_padre].[profesion] as [seg_usuario_padre_profesion],
[seg_usuario_padre].[email] as [seg_usuario_padre_email],
[seg_usuario_padre].[direccion] as [seg_usuario_padre_direccion],
[seg_usuario_padre].[telefono] as [seg_usuario_padre_telefono],
[seg_usuario_padre].[costoHora] as [seg_usuario_padre_costoHora],
[seg_usuario_padre].[porcentajeComision] as [seg_usuario_padre_porcentajeComision],
[seg_usuario_padre].[accesoActivo] as [seg_usuario_padre_accesoActivo],
[seg_usuario_padre].[cambiarClave] as [seg_usuario_padre_cambiarClave],
[seg_usuario_padre].[fechaUltimoCambioClave_fh] as [seg_usuario_padre_fechaUltimoCambioClave_fh],
[seg_usuario_padre].[aplicaRecargo] as [seg_usuario_padre_aplicaRecargo],
[seg_usuario_padre].[sexo] as [seg_usuario_padre_sexo],
[seg_usuario_padre].[id_perfil] as [seg_usuario_padre_id_perfil],
[seg_usuario_padre].[id_cargo] as [seg_usuario_padre_id_cargo],
[seg_usuario_padre].[id_grupo] as [seg_usuario_padre_id_grupo],
[seg_usuario_padre].[id_zona] as [seg_usuario_padre_id_zona],
[seg_usuario_padre].[identificacion] as [seg_usuario_padre_identificacion],
[seg_usuario_padre].[id_usuario] as [seg_usuario_padre_id_usuario],
[seg_usuario_padre].[habilitado] as [seg_usuario_padre_habilitado],
[seg_usuario_padre].[idDispositivo] as [seg_usuario_padre_idDispositivo],
[seg_usuario_padre].[cmm] as [seg_usuario_padre_cmm],
		[seg_usuario].[habilitado] AS [habilitado],
		[seg_usuario].[idDispositivo] AS [idDispositivo],
		[seg_usuario].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [seg_usuario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_usuario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_usuario].[id_usuario_creo]
	INNER JOIN [seg_perfil] ON [seg_perfil].id=[seg_usuario].[id_perfil]
	INNER JOIN [seg_cargo] ON [seg_cargo].id=[seg_usuario].[id_cargo]
	INNER JOIN [seg_grupo] ON [seg_grupo].id=[seg_usuario].[id_grupo]
	INNER JOIN [gen_zona] ON [gen_zona].id=[seg_usuario].[id_zona]
	INNER JOIN [seg_usuario] AS [seg_usuario_padre] ON [seg_usuario_padre].id=[seg_usuario].[id_usuario]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [seg_usuario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [seg_usuario].active=1
