IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[upd_seg_usuario]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[upd_seg_usuario]
GO
CREATE PROCEDURE [upd_seg_usuario]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_usuario varchar(300) = null,
		@p_usuario_codigo varchar(100) = null,
		@p_intentosFallidos int = null,
		@p_numeroIngresos int = null,
		@p_fechaUltimoIngreso_fh smalldatetime = null,
		@p_fechaIntentoFallido_fh smalldatetime = null,
		@p_clave varchar(64) = null,
		@p_nombre varchar(100) = null,
		@p_profesion varchar(100) = null,
		@p_email varchar(100) = null,
		@p_direccion varchar(300) = null,
		@p_telefono varchar(100) = null,
		@p_costoHora money = null,
		@p_porcentajeComision float = null,
		@p_accesoActivo bit = null,
		@p_cambiarClave bit = null,
		@p_fechaUltimoCambioClave_fh smalldatetime = null,
		@p_aplicaRecargo bit = null,
		@p_sexo bit = null,
		@p_id_perfil int = null,
		@p_id_cargo int = null,
		@p_id_grupo int = null,
		@p_id_zona int = null,
		@p_identificacion varchar(100) = null,
		@p_id_usuario int = null,
		@p_habilitado bit = null,
		@p_idDispositivo varchar(500) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [seg_usuario]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[usuario] = isnull(@p_usuario,[usuario]),
			[usuario_codigo] = isnull(@p_usuario_codigo,[usuario_codigo]),
			[intentosFallidos] = isnull(@p_intentosFallidos,[intentosFallidos]),
			[numeroIngresos] = isnull(@p_numeroIngresos,[numeroIngresos]),
			[fechaUltimoIngreso_fh] = isnull(@p_fechaUltimoIngreso_fh,[fechaUltimoIngreso_fh]),
			[fechaIntentoFallido_fh] = isnull(@p_fechaIntentoFallido_fh,[fechaIntentoFallido_fh]),
			[clave] = isnull(@p_clave,[clave]),
			[nombre] = isnull(@p_nombre,[nombre]),
			[profesion] = isnull(@p_profesion,[profesion]),
			[email] = isnull(@p_email,[email]),
			[direccion] = isnull(@p_direccion,[direccion]),
			[telefono] = isnull(@p_telefono,[telefono]),
			[costoHora] = isnull(@p_costoHora,[costoHora]),
			[porcentajeComision] = isnull(@p_porcentajeComision,[porcentajeComision]),
			[accesoActivo] = isnull(@p_accesoActivo,[accesoActivo]),
			[cambiarClave] = isnull(@p_cambiarClave,[cambiarClave]),
			[fechaUltimoCambioClave_fh] = isnull(@p_fechaUltimoCambioClave_fh,[fechaUltimoCambioClave_fh]),
			[aplicaRecargo] = isnull(@p_aplicaRecargo,[aplicaRecargo]),
			[sexo] = isnull(@p_sexo,[sexo]),
			[id_perfil] = isnull(@p_id_perfil,[id_perfil]),
			[id_cargo] = isnull(@p_id_cargo,[id_cargo]),
			[id_grupo] = isnull(@p_id_grupo,[id_grupo]),
			[id_zona] = isnull(@p_id_zona,[id_zona]),
			[identificacion] = isnull(@p_identificacion,[identificacion]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[habilitado] = isnull(@p_habilitado,[habilitado]),
			[idDispositivo] = isnull(@p_idDispositivo,[idDispositivo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
