IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_seg_usuario]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_seg_usuario]
GO
CREATE PROCEDURE [ins_seg_usuario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_usuario varchar(300),
		@p_usuario_codigo varchar(100),
		@p_intentosFallidos int,
		@p_numeroIngresos int,
		@p_fechaUltimoIngreso_fh smalldatetime,
		@p_fechaIntentoFallido_fh smalldatetime,
		@p_clave varchar(64),
		@p_nombre varchar(100),
		@p_profesion varchar(100),
		@p_email varchar(100),
		@p_direccion varchar(300),
		@p_telefono varchar(100),
		@p_costoHora money,
		@p_porcentajeComision float,
		@p_accesoActivo bit,
		@p_cambiarClave bit,
		@p_fechaUltimoCambioClave_fh smalldatetime,
		@p_aplicaRecargo bit,
		@p_sexo bit,
		@p_id_perfil int,
		@p_id_cargo int,
		@p_id_grupo int,
		@p_id_zona int,
		@p_identificacion varchar(100),
		@p_id_usuario int,
		@p_habilitado bit,
		@p_idDispositivo varchar(500),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_usuario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[usuario],
			[usuario_codigo],
			[intentosFallidos],
			[numeroIngresos],
			[fechaUltimoIngreso_fh],
			[fechaIntentoFallido_fh],
			[clave],
			[nombre],
			[profesion],
			[email],
			[direccion],
			[telefono],
			[costoHora],
			[porcentajeComision],
			[accesoActivo],
			[cambiarClave],
			[fechaUltimoCambioClave_fh],
			[aplicaRecargo],
			[sexo],
			[id_perfil],
			[id_cargo],
			[id_grupo],
			[id_zona],
			[identificacion],
			[id_usuario],
			[habilitado],
			[idDispositivo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_usuario,
			@p_usuario_codigo,
			@p_intentosFallidos,
			@p_numeroIngresos,
			@p_fechaUltimoIngreso_fh,
			@p_fechaIntentoFallido_fh,
			@p_clave,
			@p_nombre,
			@p_profesion,
			@p_email,
			@p_direccion,
			@p_telefono,
			@p_costoHora,
			@p_porcentajeComision,
			@p_accesoActivo,
			@p_cambiarClave,
			@p_fechaUltimoCambioClave_fh,
			@p_aplicaRecargo,
			@p_sexo,
			@p_id_perfil,
			@p_id_cargo,
			@p_id_grupo,
			@p_id_zona,
			@p_identificacion,
			@p_id_usuario,
			@p_habilitado,
			@p_idDispositivo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_usuario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
