GO
CREATE PROCEDURE [reg_seg_usuario_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[usuario] AS [usuario],
		[usuario_codigo] AS [usuario_codigo],
		[intentosFallidos] AS [intentosFallidos],
		[numeroIngresos] AS [numeroIngresos],
		[fechaUltimoIngreso_fh] AS [fechaUltimoIngreso_fh],
		[fechaIntentoFallido_fh] AS [fechaIntentoFallido_fh],
		[clave] AS [clave],
		[nombre] AS [nombre],
		[profesion] AS [profesion],
		[email] AS [email],
		[direccion] AS [direccion],
		[telefono] AS [telefono],
		[costoHora] AS [costoHora],
		[porcentajeComision] AS [porcentajeComision],
		[accesoActivo] AS [accesoActivo],
		[cambiarClave] AS [cambiarClave],
		[fechaUltimoCambioClave_fh] AS [fechaUltimoCambioClave_fh],
		[aplicaRecargo] AS [aplicaRecargo],
		[sexo] AS [sexo],
		[id_perfil] AS [id_perfil],
		[id_cargo] AS [id_cargo],
		[id_grupo] AS [id_grupo],
		[id_zona] AS [id_zona],
		[identificacion] AS [identificacion],
		[id_usuario] AS [id_usuario],
		[habilitado] AS [habilitado],
		[idDispositivo] AS [idDispositivo],
		[cmm] AS [cmm]
	FROM [seg_usuario]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
