GO
CREATE PROCEDURE [aud_seg_usuario]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [seg_usuario].id as id_tabla,
	[seg_usuario].id_usuario_modifico as id_usuario_modifico,
	[seg_usuario].id_usuario_creo as id_usuario_creo,
	[seg_usuario].fechaModificacion as fechaModificacion,
	[seg_usuario].fechaCreacion as fechaCreacion,
	[seg_usuario].active as active,
	[seg_usuario].[usuario] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [seg_usuario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_usuario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_usuario].[id_usuario_creo]
	where ' + @p_filtro)
END
GO
