CREATE PROCEDURE [ins_gen_bodega_usuario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_bodega_usuario varchar(300),
		@p_id_usuario int,
		@p_id_bodega int,
		@p_sugerir bit,
		@p_ocultar bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [gen_bodega_usuario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[bodega_usuario],
			[id_usuario],
			[id_bodega],
			[sugerir],
			[ocultar],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_bodega_usuario,
			@p_id_usuario,
			@p_id_bodega,
			@p_sugerir,
			@p_ocultar,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [gen_bodega_usuario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
