CREATE PROCEDURE [ins_seg_usuario_catalogo_equipo]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_usuario_catalogo_equipo varchar(300),
		@p_id_usuario int,
		@p_id_tipoServicio int,
		@p_id_catalogo_equipo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [seg_usuario_catalogo.equipo]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
