			[id_usuario],
			[id_tipoServicio],
			[id_catalogo.equipo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_usuario_catalogo_equipo,
			@p_id_usuario,
			@p_id_tipoServicio,
			@p_id_catalogo_equipo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [seg_usuario_catalogo.equipo] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
