	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [seg_usuario_catalogo.equipo].id as id_tabla,
	[seg_usuario_catalogo.equipo].id_usuario_modifico as id_usuario_modifico,
	[seg_usuario_catalogo.equipo].id_usuario_creo as id_usuario_creo,
	[seg_usuario_catalogo.equipo].fechaModificacion as fechaModificacion,
	[seg_usuario_catalogo.equipo].fechaCreacion as fechaCreacion,
	[seg_usuario_catalogo.equipo].active as active,
	[seg_usuario_catalogo.equipo].[usuario_catalogo.equipo] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [seg_usuario_catalogo.equipo]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[seg_usuario_catalogo.equipo].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[seg_usuario_catalogo.equipo].[id_usuario_creo]
	where ' + @p_filtro)
