CREATE  VIEW [view_syn_campoIntegracion] AS
SELECT 	[syn_campoIntegracion].[id] AS [id],
		[syn_campoIntegracion].[uid] AS [uid],
		[syn_campoIntegracion].[eid] AS [eid],
		[syn_campoIntegracion].[id_usuario_modifico] AS [id_usuario_modifico],
		[syn_campoIntegracion].[id_usuario_creo] AS [id_usuario_creo],
		[syn_campoIntegracion].[fechaModificacion] AS [fechaModificacion],
		[syn_campoIntegracion].[fechaCreacion] AS [fechaCreacion],
		[syn_campoIntegracion].[active] AS [active],
		[syn_campoIntegracion].[campoIntegracion] AS [campoIntegracion],
		[syn_campoIntegracion].[campoIntegracion_codigo] AS [campoIntegracion_codigo],
		[syn_campoIntegracion].[campoLocal] AS [campoLocal],
		[syn_campoIntegracion].[tablaAuxiliar] AS [tablaAuxiliar],
		[syn_campoIntegracion].[campoEnlace] AS [campoEnlace],
		[syn_campoIntegracion].[valorXDefecto] AS [valorXDefecto],
		[syn_campoIntegracion].[tipoDato] AS [tipoDato],
		[syn_campoIntegracion].[longitud] AS [longitud],
		[syn_campoIntegracion].[esLlave] AS [esLlave],
		[syn_campoIntegracion].[orden] AS [orden],
		[syn_campoIntegracion].[id_puntoIntegracion] AS [id_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion] as [syn_puntoIntegracion_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion_codigo] as [syn_puntoIntegracion_puntoIntegracion_codigo],
[syn_puntoIntegracion].[tablaLocal] as [syn_puntoIntegracion_tablaLocal],
[syn_puntoIntegracion].[condicion] as [syn_puntoIntegracion_condicion],
[syn_puntoIntegracion].[urlConsumir] as [syn_puntoIntegracion_urlConsumir],
[syn_puntoIntegracion].[id_puntoIntegracion] as [syn_puntoIntegracion_id_puntoIntegracion],
[syn_puntoIntegracion].[id_sistemaIntegrar] as [syn_puntoIntegracion_id_sistemaIntegrar],
[syn_puntoIntegracion].[metodo] as [syn_puntoIntegracion_metodo],
[syn_puntoIntegracion].[cantidadReintentos] as [syn_puntoIntegracion_cantidadReintentos],
[syn_puntoIntegracion].[intervaloReintentos] as [syn_puntoIntegracion_intervaloReintentos],
[syn_puntoIntegracion].[codigosReintentos] as [syn_puntoIntegracion_codigosReintentos],
[syn_puntoIntegracion].[cmm] as [syn_puntoIntegracion_cmm],
		[syn_campoIntegracion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [syn_campoIntegracion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[syn_campoIntegracion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[syn_campoIntegracion].[id_usuario_creo]
	INNER JOIN [syn_puntoIntegracion] ON [syn_puntoIntegracion].id=[syn_campoIntegracion].[id_puntoIntegracion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [syn_campoIntegracion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [syn_campoIntegracion].active=1
