CREATE PROCEDURE [upd_syn_campoIntegracion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_campoIntegracion varchar(300) = null,
		@p_campoIntegracion_codigo varchar(100) = null,
		@p_campoLocal varchar(200) = null,
		@p_tablaAuxiliar varchar(200) = null,
		@p_campoEnlace varchar(300) = null,
		@p_valorXDefecto varchar(200) = null,
		@p_tipoDato int = null,
		@p_longitud int = null,
		@p_esLlave bit = null,
		@p_orden int = null,
		@p_id_puntoIntegracion int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [syn_campoIntegracion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[campoIntegracion] = isnull(@p_campoIntegracion,[campoIntegracion]),
			[campoIntegracion_codigo] = isnull(@p_campoIntegracion_codigo,[campoIntegracion_codigo]),
			[campoLocal] = isnull(@p_campoLocal,[campoLocal]),
			[tablaAuxiliar] = isnull(@p_tablaAuxiliar,[tablaAuxiliar]),
			[campoEnlace] = isnull(@p_campoEnlace,[campoEnlace]),
			[valorXDefecto] = isnull(@p_valorXDefecto,[valorXDefecto]),
			[tipoDato] = isnull(@p_tipoDato,[tipoDato]),
			[longitud] = isnull(@p_longitud,[longitud]),
			[esLlave] = isnull(@p_esLlave,[esLlave]),
			[orden] = isnull(@p_orden,[orden]),
			[id_puntoIntegracion] = isnull(@p_id_puntoIntegracion,[id_puntoIntegracion]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
