GO
CREATE PROCEDURE [ins_syn_campoIntegracion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_campoIntegracion varchar(300),
		@p_campoIntegracion_codigo varchar(100),
		@p_campoLocal varchar(200),
		@p_tablaAuxiliar varchar(200),
		@p_campoEnlace varchar(300),
		@p_valorXDefecto varchar(200),
		@p_tipoDato int,
		@p_longitud int,
		@p_esLlave bit,
		@p_orden int,
		@p_id_puntoIntegracion int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [syn_campoIntegracion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[campoIntegracion],
			[campoIntegracion_codigo],
			[campoLocal],
			[tablaAuxiliar],
			[campoEnlace],
			[valorXDefecto],
			[tipoDato],
			[longitud],
			[esLlave],
			[orden],
			[id_puntoIntegracion],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_campoIntegracion,
			@p_campoIntegracion_codigo,
			@p_campoLocal,
			@p_tablaAuxiliar,
			@p_campoEnlace,
			@p_valorXDefecto,
			@p_tipoDato,
			@p_longitud,
			@p_esLlave,
			@p_orden,
			@p_id_puntoIntegracion,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [syn_campoIntegracion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
