SELECT 	[syn_puntoIntegracion].[id] AS [id],
		[syn_puntoIntegracion].[uid] AS [uid],
		[syn_puntoIntegracion].[eid] AS [eid],
		[syn_puntoIntegracion].[id_usuario_modifico] AS [id_usuario_modifico],
