		[syn_puntoIntegracion].[puntoIntegracion_codigo] AS [puntoIntegracion_codigo],
		[syn_puntoIntegracion].[tablaLocal] AS [tablaLocal],
		[syn_puntoIntegracion].[condicion] AS [condicion],
		[syn_puntoIntegracion].[urlConsumir] AS [urlConsumir],
		[syn_puntoIntegracion].[id_puntoIntegracion] AS [id_puntoIntegracion],
[syn_puntoIntegracion_padre].[puntoIntegracion] as [syn_puntoIntegracion_padre_puntoIntegracion],
[syn_puntoIntegracion_padre].[puntoIntegracion_codigo] as [syn_puntoIntegracion_padre_puntoIntegracion_codigo],
[syn_puntoIntegracion_padre].[tablaLocal] as [syn_puntoIntegracion_padre_tablaLocal],
[syn_puntoIntegracion_padre].[condicion] as [syn_puntoIntegracion_padre_condicion],
[syn_puntoIntegracion_padre].[urlConsumir] as [syn_puntoIntegracion_padre_urlConsumir],
[syn_puntoIntegracion_padre].[id_puntoIntegracion] as [syn_puntoIntegracion_padre_id_puntoIntegracion],
[syn_puntoIntegracion_padre].[id_sistemaIntegrar] as [syn_puntoIntegracion_padre_id_sistemaIntegrar],
[syn_puntoIntegracion_padre].[metodo] as [syn_puntoIntegracion_padre_metodo],
[syn_puntoIntegracion_padre].[cantidadReintentos] as [syn_puntoIntegracion_padre_cantidadReintentos],
[syn_puntoIntegracion_padre].[intervaloReintentos] as [syn_puntoIntegracion_padre_intervaloReintentos],
[syn_puntoIntegracion_padre].[codigosReintentos] as [syn_puntoIntegracion_padre_codigosReintentos],
[syn_puntoIntegracion_padre].[cmm] as [syn_puntoIntegracion_padre_cmm],
		[syn_puntoIntegracion].[id_sistemaIntegrar] AS [id_sistemaIntegrar],
[syn_sistemaIntegrar].[sistemaIntegrar] as [syn_sistemaIntegrar_sistemaIntegrar],
[syn_sistemaIntegrar].[sistemaIntegrar_codigo] as [syn_sistemaIntegrar_sistemaIntegrar_codigo],
[syn_sistemaIntegrar].[usuario] as [syn_sistemaIntegrar_usuario],
[syn_sistemaIntegrar].[clave] as [syn_sistemaIntegrar_clave],
[syn_sistemaIntegrar].[urlAutenticar] as [syn_sistemaIntegrar_urlAutenticar],
[syn_sistemaIntegrar].[id_tipoAutenticacion] as [syn_sistemaIntegrar_id_tipoAutenticacion],
[syn_sistemaIntegrar].[token] as [syn_sistemaIntegrar_token],
[syn_sistemaIntegrar].[metodoAutenticar] as [syn_sistemaIntegrar_metodoAutenticar],
[syn_sistemaIntegrar].[estructuraResponseAutenticar] as [syn_sistemaIntegrar_estructuraResponseAutenticar],
[syn_sistemaIntegrar].[cmm] as [syn_sistemaIntegrar_cmm],
		[syn_puntoIntegracion].[metodo] AS [metodo],
		[syn_puntoIntegracion].[cantidadReintentos] AS [cantidadReintentos],
		[syn_puntoIntegracion].[intervaloReintentos] AS [intervaloReintentos],
		[syn_puntoIntegracion].[codigosReintentos] AS [codigosReintentos],
		[syn_puntoIntegracion].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [syn_puntoIntegracion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[syn_puntoIntegracion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[syn_puntoIntegracion].[id_usuario_creo]
	INNER JOIN [syn_puntoIntegracion] AS [syn_puntoIntegracion_padre] ON [syn_puntoIntegracion_padre].id=[syn_puntoIntegracion].[id_puntoIntegracion]
	INNER JOIN [syn_sistemaIntegrar] ON [syn_sistemaIntegrar].id=[syn_puntoIntegracion].[id_sistemaIntegrar]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [syn_puntoIntegracion].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [syn_puntoIntegracion].active=1
