GO
CREATE PROCEDURE [upd_syn_puntoIntegracion]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_puntoIntegracion varchar(300) = null,
		@p_puntoIntegracion_codigo varchar(100) = null,
		@p_tablaLocal varchar(200) = null,
		@p_condicion varchar(200) = null,
		@p_urlConsumir varchar(500) = null,
		@p_id_puntoIntegracion int = null,
		@p_id_sistemaIntegrar int = null,
		@p_metodo varchar(100) = null,
		@p_cantidadReintentos int = null,
		@p_intervaloReintentos int = null,
		@p_codigosReintentos varchar(200) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [syn_puntoIntegracion]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[puntoIntegracion] = isnull(@p_puntoIntegracion,[puntoIntegracion]),
			[puntoIntegracion_codigo] = isnull(@p_puntoIntegracion_codigo,[puntoIntegracion_codigo]),
			[tablaLocal] = isnull(@p_tablaLocal,[tablaLocal]),
			[condicion] = isnull(@p_condicion,[condicion]),
			[urlConsumir] = isnull(@p_urlConsumir,[urlConsumir]),
			[id_puntoIntegracion] = isnull(@p_id_puntoIntegracion,[id_puntoIntegracion]),
			[id_sistemaIntegrar] = isnull(@p_id_sistemaIntegrar,[id_sistemaIntegrar]),
			[metodo] = isnull(@p_metodo,[metodo]),
			[cantidadReintentos] = isnull(@p_cantidadReintentos,[cantidadReintentos]),
			[intervaloReintentos] = isnull(@p_intervaloReintentos,[intervaloReintentos]),
			[codigosReintentos] = isnull(@p_codigosReintentos,[codigosReintentos]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
