GO
CREATE PROCEDURE [ins_syn_puntoIntegracion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_puntoIntegracion varchar(300),
		@p_puntoIntegracion_codigo varchar(100),
		@p_tablaLocal varchar(200),
		@p_condicion varchar(200),
		@p_urlConsumir varchar(500),
		@p_id_puntoIntegracion int,
		@p_id_sistemaIntegrar int,
		@p_metodo varchar(100),
		@p_cantidadReintentos int,
		@p_intervaloReintentos int,
		@p_codigosReintentos varchar(200),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [syn_puntoIntegracion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[puntoIntegracion],
			[puntoIntegracion_codigo],
			[tablaLocal],
			[condicion],
			[urlConsumir],
			[id_puntoIntegracion],
			[id_sistemaIntegrar],
			[metodo],
			[cantidadReintentos],
			[intervaloReintentos],
			[codigosReintentos],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_puntoIntegracion,
			@p_puntoIntegracion_codigo,
			@p_tablaLocal,
			@p_condicion,
			@p_urlConsumir,
			@p_id_puntoIntegracion,
			@p_id_sistemaIntegrar,
			@p_metodo,
			@p_cantidadReintentos,
			@p_intervaloReintentos,
			@p_codigosReintentos,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [syn_puntoIntegracion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
