	[syn_puntoIntegracion].id_usuario_modifico as id_usuario_modifico,
	[syn_puntoIntegracion].id_usuario_creo as id_usuario_creo,
	[syn_puntoIntegracion].fechaModificacion as fechaModificacion,
	[syn_puntoIntegracion].fechaCreacion as fechaCreacion,
	[syn_puntoIntegracion].active as active,
	[syn_puntoIntegracion].[puntoIntegracion] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [syn_puntoIntegracion]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[syn_puntoIntegracion].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[syn_puntoIntegracion].[id_usuario_creo]
	where ' + @p_filtro)
END
