[syn_puntoIntegracion].[id_sistemaIntegrar] as [syn_puntoIntegracion_id_sistemaIntegrar],
[syn_puntoIntegracion].[metodo] as [syn_puntoIntegracion_metodo],
[syn_puntoIntegracion].[cantidadReintentos] as [syn_puntoIntegracion_cantidadReintentos],
