GO
CREATE PROCEDURE [upd_syn_puntoIntegracion_estadoTipoDocumento]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_puntoIntegracion_estadoTipoDocumento varchar(300) = null,
		@p_id_puntoIntegracion int = null,
		@p_id_estadoTipoDocumento int = null,
		@p_idRolEstado int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [syn_puntoIntegracion_estadoTipoDocumento]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[puntoIntegracion_estadoTipoDocumento] = isnull(@p_puntoIntegracion_estadoTipoDocumento,[puntoIntegracion_estadoTipoDocumento]),
			[id_puntoIntegracion] = isnull(@p_id_puntoIntegracion,[id_puntoIntegracion]),
			[id_estadoTipoDocumento] = isnull(@p_id_estadoTipoDocumento,[id_estadoTipoDocumento]),
			[idRolEstado] = isnull(@p_idRolEstado,[idRolEstado]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
