GO
CREATE PROCEDURE [ins_syn_puntoIntegracion_estadoTipoDocumento]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_puntoIntegracion_estadoTipoDocumento varchar(300),
		@p_id_puntoIntegracion int,
		@p_id_estadoTipoDocumento int,
		@p_idRolEstado int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [syn_puntoIntegracion_estadoTipoDocumento]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[puntoIntegracion_estadoTipoDocumento],
			[id_puntoIntegracion],
			[id_estadoTipoDocumento],
			[idRolEstado],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_puntoIntegracion_estadoTipoDocumento,
			@p_id_puntoIntegracion,
			@p_id_estadoTipoDocumento,
			@p_idRolEstado,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [syn_puntoIntegracion_estadoTipoDocumento] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
