IF  EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'[dbo].[view_syn_puntoIntegracionTabla]')) DROP VIEW [dbo].[view_syn_puntoIntegracionTabla]
GO
CREATE  VIEW [view_syn_puntoIntegracionTabla] AS
SELECT 	[syn_puntoIntegracionTabla].[id] AS [id],
		[syn_puntoIntegracionTabla].[uid] AS [uid],
		[syn_puntoIntegracionTabla].[eid] AS [eid],
		[syn_puntoIntegracionTabla].[id_usuario_modifico] AS [id_usuario_modifico],
		[syn_puntoIntegracionTabla].[id_usuario_creo] AS [id_usuario_creo],
		[syn_puntoIntegracionTabla].[fechaModificacion] AS [fechaModificacion],
		[syn_puntoIntegracionTabla].[fechaCreacion] AS [fechaCreacion],
		[syn_puntoIntegracionTabla].[active] AS [active],
		[syn_puntoIntegracionTabla].[puntoIntegracionTabla] AS [puntoIntegracionTabla],
		[syn_puntoIntegracionTabla].[puntoIntegracionTabla_codigo] AS [puntoIntegracionTabla_codigo],
		[syn_puntoIntegracionTabla].[id_puntoIntegracion] AS [id_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion] as [syn_puntoIntegracion_puntoIntegracion],
[syn_puntoIntegracion].[puntoIntegracion_codigo] as [syn_puntoIntegracion_puntoIntegracion_codigo],
[syn_puntoIntegracion].[tablaLocal] as [syn_puntoIntegracion_tablaLocal],
[syn_puntoIntegracion].[condicion] as [syn_puntoIntegracion_condicion],
[syn_puntoIntegracion].[urlConsumir] as [syn_puntoIntegracion_urlConsumir],
[syn_puntoIntegracion].[id_puntoIntegracion] as [syn_puntoIntegracion_id_puntoIntegracion],
[syn_puntoIntegracion].[id_sistemaIntegrar] as [syn_puntoIntegracion_id_sistemaIntegrar],
[syn_puntoIntegracion].[metodo] as [syn_puntoIntegracion_metodo],
[syn_puntoIntegracion].[cantidadReintentos] as [syn_puntoIntegracion_cantidadReintentos],
[syn_puntoIntegracion].[intervaloReintentos] as [syn_puntoIntegracion_intervaloReintentos],
[syn_puntoIntegracion].[codigosReintentos] as [syn_puntoIntegracion_codigosReintentos],
[syn_puntoIntegracion].[cmm] as [syn_puntoIntegracion_cmm],
		[syn_puntoIntegracionTabla].[tabla] AS [tabla],
		[syn_puntoIntegracionTabla].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [syn_puntoIntegracionTabla]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[syn_puntoIntegracionTabla].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[syn_puntoIntegracionTabla].[id_usuario_creo]
	INNER JOIN [syn_puntoIntegracion] ON [syn_puntoIntegracion].id=[syn_puntoIntegracionTabla].[id_puntoIntegracion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [syn_puntoIntegracionTabla].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [syn_puntoIntegracionTabla].active=1
GO
