IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_syn_puntoIntegracionTabla]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_syn_puntoIntegracionTabla]
GO
CREATE PROCEDURE [ins_syn_puntoIntegracionTabla]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_puntoIntegracionTabla varchar(300),
		@p_puntoIntegracionTabla_codigo varchar(100),
		@p_id_puntoIntegracion int,
		@p_tabla varchar(200),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [syn_puntoIntegracionTabla]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[puntoIntegracionTabla],
			[puntoIntegracionTabla_codigo],
			[id_puntoIntegracion],
			[tabla],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_puntoIntegracionTabla,
			@p_puntoIntegracionTabla_codigo,
			@p_id_puntoIntegracion,
			@p_tabla,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [syn_puntoIntegracionTabla] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
