GO
CREATE  VIEW [view_syn_sistemaIntegrar] AS
SELECT 	[syn_sistemaIntegrar].[id] AS [id],
		[syn_sistemaIntegrar].[uid] AS [uid],
		[syn_sistemaIntegrar].[eid] AS [eid],
		[syn_sistemaIntegrar].[id_usuario_modifico] AS [id_usuario_modifico],
		[syn_sistemaIntegrar].[id_usuario_creo] AS [id_usuario_creo],
		[syn_sistemaIntegrar].[fechaModificacion] AS [fechaModificacion],
		[syn_sistemaIntegrar].[fechaCreacion] AS [fechaCreacion],
		[syn_sistemaIntegrar].[active] AS [active],
		[syn_sistemaIntegrar].[sistemaIntegrar] AS [sistemaIntegrar],
		[syn_sistemaIntegrar].[sistemaIntegrar_codigo] AS [sistemaIntegrar_codigo],
		[syn_sistemaIntegrar].[usuario] AS [usuario],
		[syn_sistemaIntegrar].[clave] AS [clave],
		[syn_sistemaIntegrar].[urlAutenticar] AS [urlAutenticar],
		[syn_sistemaIntegrar].[id_tipoAutenticacion] AS [id_tipoAutenticacion],
[syn_tipoAutenticacion].[tipoAutenticacion] as [syn_tipoAutenticacion_tipoAutenticacion],
[syn_tipoAutenticacion].[tipoAutenticacion_codigo] as [syn_tipoAutenticacion_tipoAutenticacion_codigo],
[syn_tipoAutenticacion].[cmm] as [syn_tipoAutenticacion_cmm],
		[syn_sistemaIntegrar].[token] AS [token],
		[syn_sistemaIntegrar].[metodoAutenticar] AS [metodoAutenticar],
		[syn_sistemaIntegrar].[estructuraResponseAutenticar] AS [estructuraResponseAutenticar],
		[syn_sistemaIntegrar].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [syn_sistemaIntegrar]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[syn_sistemaIntegrar].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[syn_sistemaIntegrar].[id_usuario_creo]
	INNER JOIN [syn_tipoAutenticacion] ON [syn_tipoAutenticacion].id=[syn_sistemaIntegrar].[id_tipoAutenticacion]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [syn_sistemaIntegrar].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [syn_sistemaIntegrar].active=1
