GO
CREATE PROCEDURE [upd_syn_sistemaIntegrar]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_sistemaIntegrar varchar(300) = null,
		@p_sistemaIntegrar_codigo varchar(100) = null,
		@p_usuario varchar(200) = null,
		@p_clave varchar(200) = null,
		@p_urlAutenticar varchar(800) = null,
		@p_id_tipoAutenticacion int = null,
		@p_token varchar(8000) = null,
		@p_metodoAutenticar varchar(100) = null,
		@p_estructuraResponseAutenticar varchar(-1) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [syn_sistemaIntegrar]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[sistemaIntegrar] = isnull(@p_sistemaIntegrar,[sistemaIntegrar]),
			[sistemaIntegrar_codigo] = isnull(@p_sistemaIntegrar_codigo,[sistemaIntegrar_codigo]),
			[usuario] = isnull(@p_usuario,[usuario]),
			[clave] = isnull(@p_clave,[clave]),
			[urlAutenticar] = isnull(@p_urlAutenticar,[urlAutenticar]),
			[id_tipoAutenticacion] = isnull(@p_id_tipoAutenticacion,[id_tipoAutenticacion]),
			[token] = isnull(@p_token,[token]),
			[metodoAutenticar] = isnull(@p_metodoAutenticar,[metodoAutenticar]),
			[estructuraResponseAutenticar] = isnull(@p_estructuraResponseAutenticar,[estructuraResponseAutenticar]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
