IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_syn_sistemaIntegrar]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_syn_sistemaIntegrar]
GO
CREATE PROCEDURE [ins_syn_sistemaIntegrar]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_sistemaIntegrar varchar(300),
		@p_sistemaIntegrar_codigo varchar(100),
		@p_usuario varchar(200),
		@p_clave varchar(200),
		@p_urlAutenticar varchar(800),
		@p_id_tipoAutenticacion int,
		@p_token varchar(8000),
		@p_metodoAutenticar varchar(100),
		@p_estructuraResponseAutenticar varchar(-1),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [syn_sistemaIntegrar]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[sistemaIntegrar],
			[sistemaIntegrar_codigo],
			[usuario],
			[clave],
			[urlAutenticar],
			[id_tipoAutenticacion],
			[token],
			[metodoAutenticar],
			[estructuraResponseAutenticar],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_sistemaIntegrar,
			@p_sistemaIntegrar_codigo,
			@p_usuario,
			@p_clave,
			@p_urlAutenticar,
			@p_id_tipoAutenticacion,
			@p_token,
			@p_metodoAutenticar,
			@p_estructuraResponseAutenticar,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [syn_sistemaIntegrar] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
