IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_syn_tipoAutenticacion]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_syn_tipoAutenticacion]
GO
CREATE PROCEDURE [ins_syn_tipoAutenticacion]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tipoAutenticacion varchar(300),
		@p_tipoAutenticacion_codigo varchar(100),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [syn_tipoAutenticacion]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tipoAutenticacion],
			[tipoAutenticacion_codigo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tipoAutenticacion,
			@p_tipoAutenticacion_codigo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [syn_tipoAutenticacion] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
