		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_nivelTax varchar(300) = null,
		@p_nivelTax_codigo varchar(100) = null,
		@p_id_nivelTax int = null,
		@p_tabla varchar(300) = null,
		@p_filtro varchar(300) = null,
		@p_columnaPrincipal varchar(300) = null,
		@p_esEquipo bit = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [tax_nivelTax]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[nivelTax] = isnull(@p_nivelTax,[nivelTax]),
			[nivelTax_codigo] = isnull(@p_nivelTax_codigo,[nivelTax_codigo]),
			[id_nivelTax] = isnull(@p_id_nivelTax,[id_nivelTax]),
