GO
CREATE PROCEDURE [ins_tax_nivelTax]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_nivelTax varchar(300),
		@p_nivelTax_codigo varchar(100),
		@p_id_nivelTax int,
		@p_tabla varchar(300),
		@p_filtro varchar(300),
		@p_columnaPrincipal varchar(300),
		@p_esEquipo bit,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [tax_nivelTax]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[nivelTax],
			[nivelTax_codigo],
			[id_nivelTax],
			[tabla],
			[filtro],
			[columnaPrincipal],
			[esEquipo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_nivelTax,
			@p_nivelTax_codigo,
			@p_id_nivelTax,
			@p_tabla,
			@p_filtro,
			@p_columnaPrincipal,
			@p_esEquipo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [tax_nivelTax] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
