GO
CREATE PROCEDURE [ins_tax_objetoTax]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_objetoTax varchar(300),
		@p_objetoTax_codigo varchar(100),
		@p_tabla varchar(300),
		@p_id_tablaTax int,
		@p_id_objTax int,
		@p_id_nivelTax int,
		@p_orden int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [tax_objetoTax]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[objetoTax],
			[objetoTax_codigo],
			[tabla],
			[id_tablaTax],
			[id_objTax],
			[id_nivelTax],
			[orden],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
