GO
CREATE  VIEW [view_ter_cargoContacto] AS
SELECT 	[ter_cargoContacto].[id] AS [id],
		[ter_cargoContacto].[uid] AS [uid],
		[ter_cargoContacto].[eid] AS [eid],
		[ter_cargoContacto].[id_usuario_modifico] AS [id_usuario_modifico],
		[ter_cargoContacto].[id_usuario_creo] AS [id_usuario_creo],
		[ter_cargoContacto].[fechaModificacion] AS [fechaModificacion],
		[ter_cargoContacto].[fechaCreacion] AS [fechaCreacion],
		[ter_cargoContacto].[active] AS [active],
		[ter_cargoContacto].[cargoContacto] AS [cargoContacto],
		[ter_cargoContacto].[cargoContacto_codigo] AS [cargoContacto_codigo],
		[ter_cargoContacto].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ter_cargoContacto]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_cargoContacto].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_cargoContacto].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ter_cargoContacto].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ter_cargoContacto].active=1
GO
