			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[cargoContacto] = isnull(@p_cargoContacto,[cargoContacto]),
			[cargoContacto_codigo] = isnull(@p_cargoContacto_codigo,[cargoContacto_codigo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
