GO
CREATE PROCEDURE [upd_ter_contacto]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_contacto varchar(300) = null,
		@p_contacto_codigo varchar(100) = null,
		@p_telefono varchar(100) = null,
		@p_Fax varchar(100) = null,
		@p_Email varchar(100) = null,
		@p_Direccion varchar(300) = null,
		@p_telefonoMovil varchar(100) = null,
		@p_id_usuario int = null,
		@p_cargo nvarchar(100) = null,
		@p_codigoAcceso varchar(300) = null,
		@p_id_cargoContacto int = null,
		@p_accesoActivo bit = null,
		@p_ter_cargoContacto_id_usuario_Modifico int = null,
		@p_ter_cargoContacto_id_usuario_Creo int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [ter_contacto]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[contacto] = isnull(@p_contacto,[contacto]),
			[contacto_codigo] = isnull(@p_contacto_codigo,[contacto_codigo]),
			[telefono] = isnull(@p_telefono,[telefono]),
			[Fax] = isnull(@p_Fax,[Fax]),
			[Email] = isnull(@p_Email,[Email]),
			[Direccion] = isnull(@p_Direccion,[Direccion]),
			[telefonoMovil] = isnull(@p_telefonoMovil,[telefonoMovil]),
			[id_usuario] = isnull(@p_id_usuario,[id_usuario]),
			[cargo] = isnull(@p_cargo,[cargo]),
			[codigoAcceso] = isnull(@p_codigoAcceso,[codigoAcceso]),
			[id_cargoContacto] = isnull(@p_id_cargoContacto,[id_cargoContacto]),
			[accesoActivo] = isnull(@p_accesoActivo,[accesoActivo]),
			[ter_cargoContacto_id_usuario_Modifico] = isnull(@p_ter_cargoContacto_id_usuario_Modifico,[ter_cargoContacto_id_usuario_Modifico]),
			[ter_cargoContacto_id_usuario_Creo] = isnull(@p_ter_cargoContacto_id_usuario_Creo,[ter_cargoContacto_id_usuario_Creo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
