IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ter_contacto]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ter_contacto]
GO
CREATE PROCEDURE [ins_ter_contacto]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_contacto varchar(300),
		@p_contacto_codigo varchar(100),
		@p_telefono varchar(100),
		@p_Fax varchar(100),
		@p_Email varchar(100),
		@p_Direccion varchar(300),
		@p_telefonoMovil varchar(100),
		@p_id_usuario int,
		@p_cargo nvarchar(100),
		@p_codigoAcceso varchar(300),
		@p_id_cargoContacto int,
		@p_accesoActivo bit,
		@p_ter_cargoContacto_id_usuario_Modifico int,
		@p_ter_cargoContacto_id_usuario_Creo int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ter_contacto]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[contacto],
			[contacto_codigo],
			[telefono],
			[Fax],
			[Email],
			[Direccion],
			[telefonoMovil],
			[id_usuario],
			[cargo],
			[codigoAcceso],
			[id_cargoContacto],
			[accesoActivo],
			[ter_cargoContacto_id_usuario_Modifico],
			[ter_cargoContacto_id_usuario_Creo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_contacto,
			@p_contacto_codigo,
			@p_telefono,
			@p_Fax,
			@p_Email,
			@p_Direccion,
			@p_telefonoMovil,
			@p_id_usuario,
			@p_cargo,
			@p_codigoAcceso,
			@p_id_cargoContacto,
			@p_accesoActivo,
			@p_ter_cargoContacto_id_usuario_Modifico,
			@p_ter_cargoContacto_id_usuario_Creo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ter_contacto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
