GO
CREATE PROCEDURE [ins_pro_rol_contacto]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_rol_contacto varchar(300),
		@p_id_rol int,
		@p_id_contacto int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [pro_rol_contacto]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[rol_contacto],
			[id_rol],
			[id_contacto],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_rol_contacto,
			@p_id_rol,
			@p_id_contacto,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [pro_rol_contacto] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
