GO
CREATE  VIEW [view_ter_estadoTercero] AS
SELECT 	[ter_estadoTercero].[id] AS [id],
		[ter_estadoTercero].[uid] AS [uid],
		[ter_estadoTercero].[eid] AS [eid],
		[ter_estadoTercero].[id_usuario_modifico] AS [id_usuario_modifico],
		[ter_estadoTercero].[id_usuario_creo] AS [id_usuario_creo],
		[ter_estadoTercero].[fechaModificacion] AS [fechaModificacion],
		[ter_estadoTercero].[fechaCreacion] AS [fechaCreacion],
		[ter_estadoTercero].[active] AS [active],
		[ter_estadoTercero].[estadoTercero] AS [estadoTercero],
		[ter_estadoTercero].[estadoTercero_codigo] AS [estadoTercero_codigo],
		[ter_estadoTercero].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ter_estadoTercero]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_estadoTercero].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_estadoTercero].[id_usuario_creo]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ter_estadoTercero].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ter_estadoTercero].active=1
GO
