CREATE PROCEDURE [aud_ter_sector]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [ter_sector].id as id_tabla,
	[ter_sector].id_usuario_modifico as id_usuario_modifico,
	[ter_sector].id_usuario_creo as id_usuario_creo,
	[ter_sector].fechaModificacion as fechaModificacion,
	[ter_sector].fechaCreacion as fechaCreacion,
	[ter_sector].active as active,
	[ter_sector].[sector] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [ter_sector]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_sector].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_sector].[id_usuario_creo]
	where ' + @p_filtro)
END
