IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ter_tercero_sector]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ter_tercero_sector]
GO
CREATE PROCEDURE [ins_ter_tercero_sector]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tercero_sector varchar(300),
		@p_id_tercero int,
		@p_id_sector int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ter_tercero_sector]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tercero_sector],
			[id_tercero],
			[id_sector],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tercero_sector,
			@p_id_tercero,
			@p_id_sector,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ter_tercero_sector] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
