[ter_sucursal_padre].[cmm] as [ter_sucursal_padre_cmm],
		[ter_sucursal].[id_estadoTercero] AS [id_estadoTercero],
[ter_estadoTercero].[estadoTercero] as [ter_estadoTercero_estadoTercero],
[ter_estadoTercero].[estadoTercero_codigo] as [ter_estadoTercero_estadoTercero_codigo],
[ter_estadoTercero].[cmm] as [ter_estadoTercero_cmm],
		[ter_sucursal].[codigorecursiva] AS [codigorecursiva],
		[ter_sucursal].[cargo] AS [cargo],
		[ter_sucursal].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ter_sucursal]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_sucursal].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_sucursal].[id_usuario_creo]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[ter_sucursal].[id_tercero]
	INNER JOIN [gen_zona] ON [gen_zona].id=[ter_sucursal].[id_zona]
	INNER JOIN [seg_usuario] AS [seg_usuario_asesor] ON [seg_usuario_asesor].id=[ter_sucursal].[id_usuario_asesor]
	INNER JOIN [seg_usuario] AS [seg_usuario_tecnico] ON [seg_usuario_tecnico].id=[ter_sucursal].[id_usuario_tecnico]
	INNER JOIN [ter_sucursal] AS [ter_sucursal_padre] ON [ter_sucursal_padre].id=[ter_sucursal].[id_sucursal]
	INNER JOIN [ter_estadoTercero] ON [ter_estadoTercero].id=[ter_sucursal].[id_estadoTercero]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ter_sucursal].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
WHERE [ter_sucursal].active=1
GO
