GO
CREATE PROCEDURE [upd_ter_sucursal]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_sucursal varchar(300) = null,
		@p_sucursal_codigo varchar(100) = null,
		@p_contacto varchar(100) = null,
		@p_telefono varchar(100) = null,
		@p_Fax varchar(100) = null,
		@p_Email varchar(100) = null,
		@p_Direccion varchar(300) = null,
		@p_paraVenta bit = null,
		@p_paraSoporte bit = null,
		@p_paraAlquiler bit = null,
		@p_id_tercero int = null,
		@p_id_zona int = null,
		@p_id_usuario_asesor int = null,
		@p_id_usuario_tecnico int = null,
		@p_id_sucursal int = null,
		@p_id_estadoTercero int = null,
		@p_codigorecursiva varchar(5000) = null,
		@p_cargo varchar(300) = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [ter_sucursal]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[sucursal] = isnull(@p_sucursal,[sucursal]),
			[sucursal_codigo] = isnull(@p_sucursal_codigo,[sucursal_codigo]),
			[contacto] = isnull(@p_contacto,[contacto]),
			[telefono] = isnull(@p_telefono,[telefono]),
			[Fax] = isnull(@p_Fax,[Fax]),
			[Email] = isnull(@p_Email,[Email]),
			[Direccion] = isnull(@p_Direccion,[Direccion]),
			[paraVenta] = isnull(@p_paraVenta,[paraVenta]),
			[paraSoporte] = isnull(@p_paraSoporte,[paraSoporte]),
			[paraAlquiler] = isnull(@p_paraAlquiler,[paraAlquiler]),
			[id_tercero] = isnull(@p_id_tercero,[id_tercero]),
			[id_zona] = isnull(@p_id_zona,[id_zona]),
			[id_usuario_asesor] = isnull(@p_id_usuario_asesor,[id_usuario_asesor]),
			[id_usuario_tecnico] = isnull(@p_id_usuario_tecnico,[id_usuario_tecnico]),
			[id_sucursal] = isnull(@p_id_sucursal,[id_sucursal]),
			[id_estadoTercero] = isnull(@p_id_estadoTercero,[id_estadoTercero]),
			[codigorecursiva] = isnull(@p_codigorecursiva,[codigorecursiva]),
			[cargo] = isnull(@p_cargo,[cargo]),
			[cmm] = isnull(@p_cmm,[cmm])
		WHERE (id = @p_id)
END
GO
