IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ter_sucursal]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ter_sucursal]
GO
CREATE PROCEDURE [ins_ter_sucursal]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_sucursal varchar(300),
		@p_sucursal_codigo varchar(100),
		@p_contacto varchar(100),
		@p_telefono varchar(100),
		@p_Fax varchar(100),
		@p_Email varchar(100),
		@p_Direccion varchar(300),
		@p_paraVenta bit,
		@p_paraSoporte bit,
		@p_paraAlquiler bit,
		@p_id_tercero int,
		@p_id_zona int,
		@p_id_usuario_asesor int,
		@p_id_usuario_tecnico int,
		@p_id_sucursal int,
		@p_id_estadoTercero int,
		@p_codigorecursiva varchar(5000),
		@p_cargo varchar(300),
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ter_sucursal]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[sucursal],
			[sucursal_codigo],
			[contacto],
			[telefono],
			[Fax],
			[Email],
			[Direccion],
			[paraVenta],
			[paraSoporte],
			[paraAlquiler],
			[id_tercero],
			[id_zona],
			[id_usuario_asesor],
			[id_usuario_tecnico],
			[id_sucursal],
			[id_estadoTercero],
			[codigorecursiva],
			[cargo],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_sucursal,
			@p_sucursal_codigo,
			@p_contacto,
			@p_telefono,
			@p_Fax,
			@p_Email,
			@p_Direccion,
			@p_paraVenta,
			@p_paraSoporte,
			@p_paraAlquiler,
			@p_id_tercero,
			@p_id_zona,
			@p_id_usuario_asesor,
			@p_id_usuario_tecnico,
			@p_id_sucursal,
			@p_id_estadoTercero,
			@p_codigorecursiva,
			@p_cargo,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ter_sucursal] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
GO
