CREATE PROCEDURE [reg_ter_sucursal_m]
	@p_id INT,
	@p_eid as varchar(50) = ''
AS
BEGIN
	SELECT 	[id] AS [id],
		[uid] AS [uid],
		[eid] AS [eid],
		[id_usuario_modifico] AS [id_usuario_modifico],
		[id_usuario_creo] AS [id_usuario_creo],
		[fechaModificacion] AS [fechaModificacion],
		[fechaCreacion] AS [fechaCreacion],
		[active] AS [active],
		[sucursal] AS [sucursal],
		[sucursal_codigo] AS [sucursal_codigo],
		[contacto] AS [contacto],
		[telefono] AS [telefono],
		[Fax] AS [Fax],
		[Email] AS [Email],
		[Direccion] AS [Direccion],
		[paraVenta] AS [paraVenta],
		[paraSoporte] AS [paraSoporte],
		[paraAlquiler] AS [paraAlquiler],
		[id_tercero] AS [id_tercero],
		[id_zona] AS [id_zona],
		[id_usuario_asesor] AS [id_usuario_asesor],
		[id_usuario_tecnico] AS [id_usuario_tecnico],
		[id_sucursal] AS [id_sucursal],
		[id_estadoTercero] AS [id_estadoTercero],
		[codigorecursiva] AS [codigorecursiva],
		[cargo] AS [cargo],
		[cmm] AS [cmm]
	FROM [ter_sucursal]
	WHERE	(id = @p_id)
	AND	(eid LIKE @p_eid+'%')

END
