CREATE PROCEDURE [ins_doc_documento_proyecto_sucursal]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_documento_proyecto_sucursal varchar(300),
		@p_id_documento_proyecto int,
		@p_id_sucursal int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [doc_documento.proyecto_sucursal]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[documento.proyecto_sucursal],
			[id_documento.proyecto],
			[id_sucursal],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_documento_proyecto_sucursal,
			@p_id_documento_proyecto,
			@p_id_sucursal,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [doc_documento.proyecto_sucursal] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
