CREATE  VIEW [view_ter_sucursal_listaprecio] AS
SELECT 	[ter_sucursal_listaprecio].[id] AS [id],
		[ter_sucursal_listaprecio].[uid] AS [uid],
		[ter_sucursal_listaprecio].[eid] AS [eid],
		[ter_sucursal_listaprecio].[id_usuario_modifico] AS [id_usuario_modifico],
		[ter_sucursal_listaprecio].[id_usuario_creo] AS [id_usuario_creo],
		[ter_sucursal_listaprecio].[fechaModificacion] AS [fechaModificacion],
		[ter_sucursal_listaprecio].[fechaCreacion] AS [fechaCreacion],
		[ter_sucursal_listaprecio].[active] AS [active],
		[ter_sucursal_listaprecio].[sucursal_listaprecio] AS [sucursal_listaprecio],
		[ter_sucursal_listaprecio].[id_sucursal] AS [id_sucursal],
[ter_sucursal].[sucursal] as [ter_sucursal_sucursal],
[ter_sucursal].[sucursal_codigo] as [ter_sucursal_sucursal_codigo],
[ter_sucursal].[contacto] as [ter_sucursal_contacto],
[ter_sucursal].[telefono] as [ter_sucursal_telefono],
[ter_sucursal].[Fax] as [ter_sucursal_Fax],
[ter_sucursal].[Email] as [ter_sucursal_Email],
[ter_sucursal].[Direccion] as [ter_sucursal_Direccion],
[ter_sucursal].[paraVenta] as [ter_sucursal_paraVenta],
[ter_sucursal].[paraSoporte] as [ter_sucursal_paraSoporte],
[ter_sucursal].[paraAlquiler] as [ter_sucursal_paraAlquiler],
[ter_sucursal].[id_tercero] as [ter_sucursal_id_tercero],
[ter_sucursal].[id_zona] as [ter_sucursal_id_zona],
[ter_sucursal].[id_usuario_asesor] as [ter_sucursal_id_usuario_asesor],
[ter_sucursal].[id_usuario_tecnico] as [ter_sucursal_id_usuario_tecnico],
[ter_sucursal].[id_sucursal] as [ter_sucursal_id_sucursal],
[ter_sucursal].[id_estadoTercero] as [ter_sucursal_id_estadoTercero],
[ter_sucursal].[codigorecursiva] as [ter_sucursal_codigorecursiva],
[ter_sucursal].[cargo] as [ter_sucursal_cargo],
[ter_sucursal].[cmm] as [ter_sucursal_cmm],
		[ter_sucursal_listaprecio].[id_listaprecio] AS [id_listaprecio],
[cat_listaPrecio].[listaPrecio] as [cat_listaPrecio_listaPrecio],
[cat_listaPrecio].[listaPrecio_codigo] as [cat_listaPrecio_listaPrecio_codigo],
[cat_listaPrecio].[porcentajeDescuento] as [cat_listaPrecio_porcentajeDescuento],
[cat_listaPrecio].[esPrivado] as [cat_listaPrecio_esPrivado],
[cat_listaPrecio].[id_moneda] as [cat_listaPrecio_id_moneda],
[cat_listaPrecio].[paraCompra] as [cat_listaPrecio_paraCompra],
[cat_listaPrecio].[cmm] as [cat_listaPrecio_cmm],
		[ter_sucursal_listaprecio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ter_sucursal_listaprecio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_sucursal_listaprecio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_sucursal_listaprecio].[id_usuario_creo]
	INNER JOIN [ter_sucursal] ON [ter_sucursal].id=[ter_sucursal_listaprecio].[id_sucursal]
	INNER JOIN [cat_listaPrecio] ON [cat_listaPrecio].id=[ter_sucursal_listaprecio].[id_listaprecio]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ter_sucursal_listaprecio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
