	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [ter_sucursal_usuario].id as id_tabla,
	[ter_sucursal_usuario].id_usuario_modifico as id_usuario_modifico,
	[ter_sucursal_usuario].id_usuario_creo as id_usuario_creo,
	[ter_sucursal_usuario].fechaModificacion as fechaModificacion,
	[ter_sucursal_usuario].fechaCreacion as fechaCreacion,
	[ter_sucursal_usuario].active as active,
	[ter_sucursal_usuario].[sucursal_usuario] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [ter_sucursal_usuario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_sucursal_usuario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_sucursal_usuario].[id_usuario_creo]
	where ' + @p_filtro)
END
