GO
CREATE PROCEDURE [upd_ter_tercero]
	@p_id int = null,
		@p_uid varchar(500) = null,
		@p_eid varchar(50) = null,
		@p_id_usuario_modifico int = null,
		@p_id_usuario_creo int = null,
		@p_fechaCreacion smalldatetime = null,
		@p_tercero varchar(300) = null,
		@p_tercero_codigo varchar(100) = null,
		@p_tercero_nit varchar(100) = null,
		@p_direccion varchar(300) = null,
		@p_contacto varchar(100) = null,
		@p_telefono varchar(100) = null,
		@p_fax varchar(100) = null,
		@p_email varchar(100) = null,
		@p_website varchar(100) = null,
		@p_representante varchar(100) = null,
		@p_notas varchar(8000) = null,
		@p_tercero_nombreCorto varchar(100) = null,
		@p_esCliente bit = null,
		@p_esProveedor bit = null,
		@p_esTransportador bit = null,
		@p_esFabricante bit = null,
		@p_esEmpresaPropia bit = null,
		@p_clasificacion varchar(50) = null,
		@p_id_zona int = null,
		@p_id_estadoTercero int = null,
		@p_id_naturalezaTercero int = null,
		@p_esProspecto bit = null,
		@p_id_formaPago int = null,
		@p_tiempoEntrega int = null,
		@p_cmm varchar(300) = null
AS
BEGIN
		UPDATE [ter_tercero]
		SET	[uid] = isnull(@p_uid,[uid]),
			[eid] = isnull(@p_eid,[eid]),
			[id_usuario_modifico] = isnull(@p_id_usuario_modifico,[id_usuario_modifico]),
			[id_usuario_creo] = isnull(@p_id_usuario_creo,[id_usuario_creo]),
			[fechaModificacion] = GETDATE(),
			[tercero] = isnull(@p_tercero,[tercero]),
			[tercero_codigo] = isnull(@p_tercero_codigo,[tercero_codigo]),
			[tercero_nit] = isnull(@p_tercero_nit,[tercero_nit]),
			[direccion] = isnull(@p_direccion,[direccion]),
			[contacto] = isnull(@p_contacto,[contacto]),
			[telefono] = isnull(@p_telefono,[telefono]),
			[fax] = isnull(@p_fax,[fax]),
			[email] = isnull(@p_email,[email]),
			[website] = isnull(@p_website,[website]),
			[representante] = isnull(@p_representante,[representante]),
			[notas] = isnull(@p_notas,[notas]),
			[tercero_nombreCorto] = isnull(@p_tercero_nombreCorto,[tercero_nombreCorto]),
			[esCliente] = isnull(@p_esCliente,[esCliente]),
			[esProveedor] = isnull(@p_esProveedor,[esProveedor]),
			[esTransportador] = isnull(@p_esTransportador,[esTransportador]),
			[esFabricante] = isnull(@p_esFabricante,[esFabricante]),
			[esEmpresaPropia] = isnull(@p_esEmpresaPropia,[esEmpresaPropia]),
