GO
CREATE PROCEDURE [ins_ter_tercero]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tercero varchar(300),
		@p_tercero_codigo varchar(100),
		@p_tercero_nit varchar(100),
		@p_direccion varchar(300),
		@p_contacto varchar(100),
		@p_telefono varchar(100),
		@p_fax varchar(100),
		@p_email varchar(100),
		@p_website varchar(100),
		@p_representante varchar(100),
		@p_notas varchar(8000),
		@p_tercero_nombreCorto varchar(100),
		@p_esCliente bit,
		@p_esProveedor bit,
		@p_esTransportador bit,
		@p_esFabricante bit,
		@p_esEmpresaPropia bit,
		@p_clasificacion varchar(50),
		@p_id_zona int,
		@p_id_estadoTercero int,
		@p_id_naturalezaTercero int,
		@p_esProspecto bit,
		@p_id_formaPago int,
		@p_tiempoEntrega int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ter_tercero]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tercero],
			[tercero_codigo],
			[tercero_nit],
			[direccion],
			[contacto],
			[telefono],
			[fax],
			[email],
			[website],
			[representante],
			[notas],
			[tercero_nombreCorto],
			[esCliente],
			[esProveedor],
			[esTransportador],
			[esFabricante],
			[esEmpresaPropia],
			[clasificacion],
			[id_zona],
			[id_estadoTercero],
			[id_naturalezaTercero],
			[esProspecto],
			[id_formaPago],
			[tiempoEntrega],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tercero,
			@p_tercero_codigo,
			@p_tercero_nit,
			@p_direccion,
			@p_contacto,
			@p_telefono,
			@p_fax,
			@p_email,
			@p_website,
			@p_representante,
			@p_notas,
			@p_tercero_nombreCorto,
			@p_esCliente,
			@p_esProveedor,
			@p_esTransportador,
			@p_esFabricante,
			@p_esEmpresaPropia,
			@p_clasificacion,
			@p_id_zona,
			@p_id_estadoTercero,
			@p_id_naturalezaTercero,
			@p_esProspecto,
			@p_id_formaPago,
			@p_tiempoEntrega,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ter_tercero] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
