[ter_tercero].[esProveedor] as [ter_tercero_esProveedor],
[ter_tercero].[esTransportador] as [ter_tercero_esTransportador],
[ter_tercero].[esFabricante] as [ter_tercero_esFabricante],
[ter_tercero].[esEmpresaPropia] as [ter_tercero_esEmpresaPropia],
[ter_tercero].[clasificacion] as [ter_tercero_clasificacion],
[ter_tercero].[id_zona] as [ter_tercero_id_zona],
[ter_tercero].[id_estadoTercero] as [ter_tercero_id_estadoTercero],
[ter_tercero].[id_naturalezaTercero] as [ter_tercero_id_naturalezaTercero],
[ter_tercero].[esProspecto] as [ter_tercero_esProspecto],
[ter_tercero].[id_formaPago] as [ter_tercero_id_formaPago],
[ter_tercero].[tiempoEntrega] as [ter_tercero_tiempoEntrega],
[ter_tercero].[cmm] as [ter_tercero_cmm],
		[ter_tercero_listaprecio].[id_listaprecio] AS [id_listaprecio],
[cat_listaPrecio].[listaPrecio] as [cat_listaPrecio_listaPrecio],
[cat_listaPrecio].[listaPrecio_codigo] as [cat_listaPrecio_listaPrecio_codigo],
[cat_listaPrecio].[porcentajeDescuento] as [cat_listaPrecio_porcentajeDescuento],
[cat_listaPrecio].[esPrivado] as [cat_listaPrecio_esPrivado],
[cat_listaPrecio].[id_moneda] as [cat_listaPrecio_id_moneda],
[cat_listaPrecio].[paraCompra] as [cat_listaPrecio_paraCompra],
[cat_listaPrecio].[cmm] as [cat_listaPrecio_cmm],
		[ter_tercero_listaprecio].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ter_tercero_listaprecio]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_tercero_listaprecio].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_tercero_listaprecio].[id_usuario_creo]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[ter_tercero_listaprecio].[id_tercero]
	INNER JOIN [cat_listaPrecio] ON [cat_listaPrecio].id=[ter_tercero_listaprecio].[id_listaprecio]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ter_tercero_listaprecio].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
