BEGIN
exec(	'SELECT [ter_tercero_listaprecio].id as id_tabla,
	[ter_tercero_listaprecio].id_usuario_modifico as id_usuario_modifico,
	[ter_tercero_listaprecio].id_usuario_creo as id_usuario_creo,
