[ter_tercero].[cmm] as [ter_tercero_cmm],
		[ter_tercero_sector].[id_sector] AS [id_sector],
[ter_sector].[sector] as [ter_sector_sector],
[ter_sector].[sector_codigo] as [ter_sector_sector_codigo],
[ter_sector].[cmm] as [ter_sector_cmm],
		[ter_tercero_sector].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ter_tercero_sector]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_tercero_sector].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_tercero_sector].[id_usuario_creo]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[ter_tercero_sector].[id_tercero]
	INNER JOIN [ter_sector] ON [ter_sector].id=[ter_tercero_sector].[id_sector]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ter_tercero_sector].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
