[seg_usuario].[idDispositivo] as [seg_usuario_idDispositivo],
[seg_usuario].[cmm] as [seg_usuario_cmm],
		[ter_tercero_usuario].[cmm] AS [cmm],
		[empresaCodigo].[empresa] As [multiempresa]
FROM [ter_tercero_usuario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_tercero_usuario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_tercero_usuario].[id_usuario_creo]
	INNER JOIN [ter_tercero] ON [ter_tercero].id=[ter_tercero_usuario].[id_tercero]
	INNER JOIN [seg_usuario] ON [seg_usuario].id=[ter_tercero_usuario].[id_usuario]
	INNER JOIN [gen_empresa] AS empresaCodigo ON [ter_tercero_usuario].eid = [empresaCodigo].[codigo] and empresaCodigo.active=1
GO
