IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ins_ter_tercero_usuario]') AND type in (N'P', N'PC'))DROP PROCEDURE [dbo].[ins_ter_tercero_usuario]
GO
CREATE PROCEDURE [ins_ter_tercero_usuario]
	@p_uid varchar(500),
		@p_eid varchar(50),
		@p_id_usuario_modifico int,
		@p_id_usuario_creo int,
		@p_tercero_usuario varchar(300),
		@p_id_tercero int,
		@p_id_usuario int,
		@p_cmm varchar(300)
AS
BEGIN
	DECLARE @v_id int
		INSERT INTO [ter_tercero_usuario]
			([uid],
			[eid],
			[id_usuario_modifico],
			[id_usuario_creo],
			[fechaModificacion],
			[fechaCreacion],
			[tercero_usuario],
			[id_tercero],
			[id_usuario],
			[cmm])
		VALUES(	@p_uid,
			@p_eid,
			@p_id_usuario_modifico,
			@p_id_usuario_creo,
			GETDATE(),
			GETDATE(),
			@p_tercero_usuario,
			@p_id_tercero,
			@p_id_usuario,
			@p_cmm)
		SET @v_id = scope_identity()
UPDATE [ter_tercero_usuario] set [uid] = [uid] + '_' + convert(varchar(20),@v_id) where [id]=@v_id
SELECT @v_id as id
RETURN @v_id
END
