GO
CREATE PROCEDURE [aud_ter_tercero_usuario]
	@p_filtro as varchar (8000) = '1=1'
AS
BEGIN
exec(	'SELECT [ter_tercero_usuario].id as id_tabla,
	[ter_tercero_usuario].id_usuario_modifico as id_usuario_modifico,
	[ter_tercero_usuario].id_usuario_creo as id_usuario_creo,
	[ter_tercero_usuario].fechaModificacion as fechaModificacion,
	[ter_tercero_usuario].fechaCreacion as fechaCreacion,
	[ter_tercero_usuario].active as active,
	[ter_tercero_usuario].[tercero_usuario] as campoPrincipal,
	[seg_usuario_creo].usuario as usuarioCreo,
	[seg_usuario_modifico].usuario as usuarioModifico

	FROM [ter_tercero_usuario]
	INNER JOIN [seg_usuario] AS [seg_usuario_modifico] ON [seg_usuario_modifico].id=[ter_tercero_usuario].[id_usuario_modifico]
	INNER JOIN [seg_usuario] AS [seg_usuario_creo] ON [seg_usuario_creo].id=[ter_tercero_usuario].[id_usuario_creo]
	where ' + @p_filtro)
END
